#!/usr/bin/env python
"""Drive the FEM workflow one validated answer at a time, on an idle GPU.

This runs the same graph, checkpoints and tools as the interactive CLI
(``run_workflow.py``), which is written for a person at a prompt, and adds what
an agent driving it needs:

* every answer is merged with what the card shows and linted against the
  workflow's own models before it is sent, so a mistake costs neither an API
  call nor a GPU step, and the merge is reported;
* a step that raises is rolled back (``graph.reopen_card``), so the card comes
  back clean and can simply be answered again;
* every GPU step first picks an idle GPU (``CUDA_VISIBLE_DEVICES``, which every
  tool and worker inherits), moves any resident worker that sits elsewhere, and
  records the VRAM it used;
* every step is logged under the session's ``operator/`` folder.

Run it with the ``mechfoundry-agents`` interpreter.  Each call prints one JSON
object and exits; long steps (generation, segmentation, the solve) are meant to
be run in the background and watched with ``status``.

    drive.py gpu
    drive.py start --instruction "<the user's instruction>" [--provider deepseek] [--compute-env mechfoundry-warp117]
    drive.py run SID --plan plan.json        # answer cards from a plan up to the next look
    drive.py show SID
    drive.py answer SID --json '{"description": "..."}'
    drive.py status SID
    drive.py history SID
    drive.py rewind SID --kind bc_input
    drive.py retry SID
    drive.py solve-backend SID --backend pyamgx
"""

from __future__ import annotations

import argparse
import contextlib
import copy
import fcntl
import functools
import json
import math
import os
import re
import shutil
import sys
import time
import traceback
import uuid
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterator

sys.path.insert(0, os.fspath(Path(__file__).resolve().parent))
import sessionlib as lib  # noqa: E402

sys.path.insert(0, os.fspath(lib.REPO_ROOT))


def gate_refusal(name: str, shape: str = "text"):
    """A gate that raises refuses instead, naming the error: a value of the wrong type in the
    brief's JSON lines or the plan (a "run" written as a list, 2026-10-10 review) used to end the
    command with a traceback.  ``shape``: "text" (str | None), "list" (list[str]) or "pair"
    ((str | None, dict))."""
    import functools

    def wrap(fn):
        @functools.wraps(fn)
        def inner(*args, record: bool = True, **kwargs):
            try:
                out = fn(*args, **kwargs)
            except Exception as exc:          # a refusal, never a traceback
                said = (f"{name} could not read the case ({type(exc).__name__}: {str(exc)[:200]}): a value in the "
                        "brief's JSON lines or the plan has the wrong form; correct it to the form the brief's "
                        "references give and run again")
                out = [said] if shape == "list" else (said, {}) if shape == "pair" else said
            # Every refusal of a gate on the case is a blocker `judge` takes "could not be run" on: a
            # refusal the agent cannot clear left one run with no verdict at all.
            refused = out if shape == "text" else "; ".join(out) if shape == "list" else None
            where = args[0] if args and isinstance(args[0], Path) else None
            if where is not None and shape != "pair" and record:
                session = where.parent if where.name == "operator" else where
                try:
                    if refused:
                        record_blocker(session, name, refused)
                    else:
                        clear_blockers(session, name)      # a gate that passes leaves no blocker
                except OSError:
                    pass
            return out
        return inner
    return wrap

BLOCKERS = "blockers.json"      # beside the snapshots: what kept a case from running, written by the runner


def record_blocker(session: Path, kind: str, text: str) -> None:
    """What kept the case from being run, as the runner met it: a body G4 refused, a run limit, a
    failed workflow step.  `judge` takes "could not be run" without a solve only on one of these."""
    path = session / "brief_snapshots" / BLOCKERS
    path.parent.mkdir(parents=True, exist_ok=True)
    found = lib.read_json(path, []) or []
    entry = {"time": time.time(), "kind": kind, "text": str(text)[:400]}
    if not found or {k: found[-1].get(k) for k in ("kind", "text")} != {"kind": kind, "text": entry["text"]}:
        lib.write_json(path, found + [entry])


def clear_blockers(session: Path, kind: str) -> None:
    path = session / "brief_snapshots" / BLOCKERS
    found = lib.read_json(path, []) if path.exists() else []
    kept = [b for b in found or [] if b.get("kind") != kind]
    if found and len(kept) != len(found):
        lib.write_json(path, kept)


def blockers(session: Path) -> list[dict[str, Any]]:
    return lib.read_json(session / "brief_snapshots" / BLOCKERS, []) or []


def solve_recorded(session: Path) -> bool:
    """Whether a solve ran in this session: a prediction history entry or the solve stop's record."""
    operator = lib.operator_dir(session)
    return bool(lib.read_json(operator / "prediction_history.json", []) or []) or (operator / "stop_solve.json").exists()


CARD_ACTIONS = {
    "geometry_input": None,  # no action key, except draw_image (SDXL draws an image input)
    "geometry_texture": ("texture_surface", "use_texture", "skip_texture"),
    "geometry_physics": ("apply_scaling", "infer_scale"),
    "bc_input": ("preview_segmentation", "preview_regions", "revise_prompt", "revise_regions",
                 "approve_regions"),
    "bc_values": ("infer_values", "apply_values"),
    "material_input": ("texture_surface", "infer_material", "infer_parts", "apply_parts",
                       "infer_vomp", "apply_material"),
    "shape_opt_settings": ("run", "finish"),
}
DEFAULT_ACTION = {
    "geometry_texture": "skip_texture", "geometry_physics": "apply_scaling",
    "bc_values": "apply_values", "material_input": "apply_material",
}
GENERATOR_WORKER = {"triposg": "triposg", "text2cad": "text2cad",
                    "cadcoder": "cadcoder", "hunyuan3d": "hunyuan3d"}
SOLVE_LOG_LINES = 25


# ------------------------------------------------------------ preparation --

@dataclass
class Prepared:
    answer: Any
    notes: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)
    errors: list[str] = field(default_factory=list)
    gpu: bool = False
    workers: list[str] = field(default_factory=list)
    need_mib: int = 0          # free VRAM the step needs on the GPU it runs on (EXTRACTION_MIB)

    @property
    def action(self) -> str | None:
        return self.answer.get("action") if isinstance(self.answer, dict) else None


def _vector(value: Any, name: str, errors: list[str]) -> list[float] | None:
    if (not isinstance(value, (list, tuple)) or len(value) != 3
            or not all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in value)):
        errors.append(f"{name} must be three numbers, got {value!r}")
        return None
    return [float(v) for v in value]


def _existing_path(value: Any, name: str, errors: list[str]) -> str | None:
    path = Path(str(value)).expanduser()
    if not path.is_absolute():
        # Relative to the repository root, as the runner prints paths (no absolute paths).
        path = lib.REPO_ROOT / path if (lib.REPO_ROOT / path).exists() else Path.cwd() / path
    path = path.resolve()
    if not path.is_file():
        errors.append(f"{name} does not exist: {path}")
        return None
    return str(path)


def prepare_answer(card: dict[str, Any], workflow: dict[str, Any], answer: Any,
                   merge: bool = True, force: bool = False) -> Prepared:
    """Complete ``answer`` from the card and check it the way the graph will.

    Everything the graph would reject is reported here instead, before the
    answer is sent and before it can start an API call or a GPU step.  Merging
    fills only what the card itself shows -- the values the workflow keeps for
    an omitted field -- and every field it fills is named in ``notes``.
    """
    from src.agents_wrapper.fem_workflow.models import (
        FIELD_MODES, GeometryGenerationSettings, PartMaterial, SegmentationSettings,
        ShapeOptSettings, UNIT_SYSTEMS,
    )
    from src.agents_wrapper.fem_workflow.graph import needs_cad_revision, _implausible_part

    kind = card.get("kind")
    prepared = Prepared(answer=answer)
    errors, notes, warnings = prepared.errors, prepared.notes, prepared.warnings
    if kind not in CARD_ACTIONS:
        errors.append(f"unknown card kind {kind!r}")
        return prepared
    if not isinstance(answer, dict):
        errors.append("answers are JSON objects (a bare string is only accepted by bc_input, "
                      "and is ambiguous there)")
        return prepared
    answer = dict(answer)
    prepared.answer = answer
    actions = CARD_ACTIONS[kind]
    action = answer.get("action", DEFAULT_ACTION.get(kind))
    if actions and kind != "shape_opt_settings" and action not in actions:
        errors.append(f"{kind} action must be one of {', '.join(actions)}; got {action!r}")
        return prepared
    if kind in DEFAULT_ACTION and "action" not in answer:
        answer["action"] = action

    def validate(model, value, label):
        try:
            return model.model_validate(value)
        except Exception as exc:  # pydantic.ValidationError, ValueError
            errors.append(f"{label}: {str(exc).splitlines()[0]}"
                          + ("; " + "; ".join(str(exc).splitlines()[1:3]) if "\n" in str(exc) else ""))
            return None

    if (kind == "geometry_input" and merge and "description" not in answer
            and str(card.get("description") or "").strip()):
        # The one description says what the object is and is what SDXL draws;
        # an answer that leaves it out means the one the card shows.
        answer["description"] = card["description"]
        notes.append(f"description taken from the card: {card['description']!r}")

    if kind == "geometry_input" and action == "draw_image":
        # SDXL draws the description as an image input, and the card comes back with it.
        sdxl = card.get("sdxl") or {}
        if not sdxl.get("ready"):
            errors.append(f"SDXL is not available here: {sdxl.get('summary', 'unknown')}")
        if "image_prompt" in answer:
            errors.append("draw_image draws the description; there is no image_prompt")
        if not str(answer.get("description") or card.get("description") or "").strip():
            errors.append("draw_image needs a description: SDXL draws it")
        seed = answer.get("image_seed", 0)
        if not isinstance(seed, int) or isinstance(seed, bool) or seed < 0:
            errors.append("image_seed must be a whole number >= 0")
        prepared.gpu, prepared.workers = True, []

    elif kind == "geometry_input":
        if action not in (None, ""):
            errors.append(f"the geometry card's only action is draw_image; got {action!r}")
        generator = answer.get("generator") or (answer.get("generation_settings") or {}).get(
            "generator") or "triposg"
        asset_kind = answer.get("asset_kind")
        if answer.get("use_drawn_image"):
            if not card.get("drawn_image"):
                errors.append("use_drawn_image needs a drawing: send "
                              '{"action": "draw_image", "description": ...} first')
            if answer.get("asset_path") is not None or asset_kind not in (None, "image"):
                errors.append("use_drawn_image takes the drawing as the image input; "
                              "leave asset_path and asset_kind out")
            asset_kind = "image"
        elif answer.get("asset_path") is not None:
            answer["asset_path"] = _existing_path(answer["asset_path"], "asset_path", errors)
            if asset_kind not in ("image", "scribble", "surface"):
                errors.append("asset_kind must be image, scribble or surface when asset_path is set")
        elif asset_kind:
            errors.append("asset_kind given without asset_path")
        if asset_kind != "surface" and not str(answer.get("description", "")).strip():
            errors.append("description is required (even for an image or scribble)")
        if generator not in GENERATOR_WORKER:
            errors.append(f"generator must be one of {', '.join(GENERATOR_WORKER)}")
        elif generator != "triposg" and asset_kind != "surface":
            status = card.get(generator) or {}
            if not status.get("ready"):
                errors.append(f"{generator} is not ready here: {status.get('summary', 'unknown')}")
        if generator in ("text2cad", "cadcoder") and answer.get("asset_path") and asset_kind != "surface":
            errors.append(f"{generator} generates from text only; drop asset_path")
        if generator == "hunyuan3d" and asset_kind != "image":
            errors.append("hunyuan3d needs asset_kind 'image' and an asset_path")
        if asset_kind == "scribble" and generator != "triposg":
            errors.append("only triposg takes a scribble")
        settings = answer.get("generation_settings")
        if settings is not None:
            parsed = validate(GeometryGenerationSettings, {**settings, "generator": generator},
                              "generation_settings")
            depths = (parsed.init_octree_depth, parsed.octree_depth) if parsed is not None else (4, 7)
            image = asset_kind in ("image", "scribble")
            if generator == "triposg" and depths != (4, 7) and (not image or depths not in REFINED_DEPTHS):
                # REFINED_DEPTHS: init 4 under depth 8 collapsed bodies, and text mode degenerates finer
                errors.append(f"TripoSG init_octree_depth/octree_depth {depths[0]}/{depths[1]}: text stays at "
                              "4/7; a body made poorly from a passed image is refined at 6/9, then 5/8 "
                              "(geometry.md, Writing the description)")
            prepared.need_mib = EXTRACTION_MIB.get(depths[1], 0) if generator == "triposg" else 0
            if (generator == "triposg" and depths[1] >= 8 and parsed is not None and parsed.faces == -1
                    and not errors):
                # a finer extraction is capped (the generator keeps it one watertight body): 1.4 M faces ran
                # the segmentation out of GPU memory three times in one run
                answer["generation_settings"] = {**settings, "faces": FINE_FACES}
                prepared.notes.append(f"a depth-{depths[1]} extraction is capped at {FINE_FACES} faces, kept watertight")
            if parsed is not None and parsed.erosion_radius > 0:
                warnings.append(f"erosion_radius {parsed.erosion_radius} drops members thinner "
                                f"than {2 * parsed.erosion_radius} voxels and whatever hangs "
                                "from them; keep 0 unless junk is attached by threads")
        if (not answer.get("revise_prompt") and asset_kind != "surface"
                and needs_cad_revision(generator, str(answer.get("description", "")),
                                       card.get("cad_revision"))):
            message = (f"{generator} needs its own revised prompt: send the description with "
                       '"revise_prompt": true first and use the text it returns')
            (warnings if force else errors).append(message)
        prepared.gpu = not answer.get("revise_prompt") and asset_kind != "surface"
        prepared.workers = [GENERATOR_WORKER.get(generator, "triposg")] if prepared.gpu else []

    elif kind == "geometry_texture":
        if action == "texture_surface":
            if answer.get("texture_image"):
                answer["texture_image"] = _existing_path(answer["texture_image"], "texture_image", errors)
            elif not str(answer.get("texture_prompt", card.get("texture_prompt") or "")).strip():
                errors.append("texture_surface needs texture_prompt or texture_image")
            elif "texture_prompt" not in answer and merge:
                answer["texture_prompt"] = card.get("texture_prompt")
                notes.append("texture_prompt taken from the card")
            if not (card.get("texture_status") or {}).get("ready") and not answer.get("texture_image"):
                warnings.append("the painter reports not ready for text prompts: "
                                + str((card.get("texture_status") or {}).get("summary")))
            prepared.gpu, prepared.workers = True, ["hunyuan3d"]
        elif action == "use_texture" and not card.get("textured_surface"):
            errors.append("use_texture needs a painted surface; texture_surface first")

    elif kind == "geometry_physics":
        if merge:
            for key in ("unit_system", "up_axis", "physical_extent"):
                if answer.get(key) in (None, "") and card.get(key) not in (None, ""):
                    answer[key] = card[key]
                    notes.append(f"{key}={card[key]!r} taken from the card")
        if answer.get("unit_system") not in UNIT_SYSTEMS:
            errors.append(f"unit_system must be one of {list(UNIT_SYSTEMS)} (sent with every answer)")
        if action == "apply_scaling":
            if answer.get("up_axis") not in ("x", "y", "z"):
                errors.append("up_axis must be x, y or z (it is the axis physical_extent is measured along)")
            extent = answer.get("physical_extent")
            if not isinstance(extent, (int, float)) or isinstance(extent, bool) or extent <= 0:
                errors.append("physical_extent must be a positive number in the unit system's length unit")

    elif kind == "bc_input":
        segmentation = dict(card.get("segmentation") or {})
        if "segmentation" in answer:
            if merge:
                missing = sorted(set(segmentation) - set(answer["segmentation"] or {}))
                if missing:
                    notes.append("segmentation " + ", ".join(missing) + " taken from the card")
                segmentation.update(answer["segmentation"] or {})
            else:
                segmentation = answer["segmentation"]
            answer["segmentation"] = segmentation
        parsed = validate(SegmentationSettings, segmentation, "segmentation") if segmentation else None
        if parsed is not None:
            if parsed.method == "cad_faces" and not card.get("cad_faces"):
                errors.append("cad_faces segmentation needs a surface from a CAD generator")
            if parsed.method == "partfield" and not (card.get("partfield") or {}).get("ready"):
                errors.append("PartField is not ready here; use shape_diameter")
        if action == "approve_regions" and not card.get("has_regions"):
            errors.append("preview_regions (and check them) before approve_regions")
        if action == "revise_regions":
            if not card.get("can_revise"):
                errors.append("revise_regions edits regions synthesized from the current words: "
                              "preview_regions first")
            prepared.gpu, prepared.workers = True, ["tools"]
        if action in ("preview_regions", "revise_prompt") and not (
                str(answer.get("description", "")).strip() or str(card.get("description") or "").strip()):
            errors.append(f"{action} needs a description of the supports and loads")
        if action in ("preview_segmentation", "preview_regions"):
            prepared.gpu = True
            method = parsed.method if parsed is not None else segmentation.get("method")
            prepared.workers = ["tools"] + (["partfield"] if method == "partfield" else [])

    elif kind == "bc_values":
        dirichlet = {item["name"]: {"components": item.get("components") or [0, 1, 2],
                                    "value": item.get("value", 0.0)}
                     for item in card.get("dirichlet") or []}
        neumann = {item["name"]: item.get("traction") for item in card.get("neumann") or []}
        areas = {item["name"]: item.get("area") for item in card.get("neumann") or []}
        loaded_areas = {item["name"]: item.get("loaded_area") for item in card.get("neumann") or []}
        if action == "infer_values":
            if not str(answer.get("value_description", "")).strip():
                errors.append("infer_values needs value_description")
        else:
            # The graph reads these keys only and ignores the rest, so a region
            # keyed at the top level would silently leave the card's traction.
            stray = sorted(set(answer) - {"action", "dirichlet_values", "neumann_values",
                                          "body_force", "acceleration", "value_description"})
            for key in stray:
                if key in neumann:
                    errors.append(f"{key!r} is a load region: put it under neumann_values")
                elif key in dirichlet:
                    errors.append(f"{key!r} is a support region: put it under dirichlet_values")
                else:
                    errors.append(f"unknown key {key!r}: the workflow would ignore it")
            supplied_d = answer.get("dirichlet_values") or {}
            supplied_n = answer.get("neumann_values") or {}
            for label, supplied, names in (("dirichlet_values", supplied_d, dirichlet),
                                           ("neumann_values", supplied_n, neumann)):
                if not isinstance(supplied, dict):
                    errors.append(f"{label} must be an object keyed by region name")
                    continue
                unknown = sorted(set(supplied) - set(names))
                if unknown:
                    errors.append(f"{label} names unknown regions {unknown}; the regions are {sorted(names)}")
            if errors:
                return prepared
            merged_d = {**dirichlet, **supplied_d} if merge else dict(supplied_d)
            merged_n = {**neumann, **supplied_n} if merge else dict(supplied_n)
            for name in set(dirichlet) - set(supplied_d):
                if merge:
                    notes.append(f"Dirichlet {name!r} kept as shown: {dirichlet[name]}")
            loaded_forces = []
            for name, value in list(merged_n.items()):
                if isinstance(value, dict) and "force" in value:
                    force_vec = _vector(value["force"], f"{name}.force", errors)
                    # The workflow divides a force by the region's loaded area
                    # (the cosine-weighted one resolve-bcs records), so it is
                    # sent as a force and the total reaches the part as given.
                    area = loaded_areas.get(name) or areas.get(name)
                    if force_vec is None:
                        continue
                    if not area:
                        errors.append(f"cannot spread a force over {name!r}: its area is unknown")
                        continue
                    merged_n[name] = {"force": force_vec}
                    loaded_forces.append(force_vec)
                    notes.append(f"{name}: total force {force_vec} sent as a force; the "
                                 f"workflow divides it by the loaded area {area:.6g} "
                                 f"= traction {[round(f / area, 6) for f in force_vec]}")
                    nominal = areas.get(name)
                    if nominal and area < 0.8 * nominal:
                        warnings.append(
                            f"{name!r} faces many ways: only {area / nominal:.0%} "
                            "of it is loaded; consider narrowing it to one facing")
                elif value is None:
                    errors.append(f"Neumann region {name!r} has no traction; every load needs a value")
                else:
                    merged_n[name] = _vector(value, f"neumann_values.{name}", errors)
                    if merged_n[name] is not None and not any(merged_n[name]):
                        warnings.append(f"load region {name!r} has zero traction: it is a free "
                                        "surface; give it its load")
            for name, value in merged_d.items():
                if not isinstance(value, dict):
                    errors.append(f"Dirichlet {name!r} must be {{'components': [...], 'value': v}}")
                    continue
                components = value.get("components")
                if (not isinstance(components, list) or not components
                        or any(c not in (0, 1, 2) for c in components)
                        or len(set(components)) != len(components)):
                    errors.append(f"Dirichlet {name!r} components must be distinct integers "
                                  f"0/1/2 (x/y/z); got {components!r}")
                if not isinstance(value.get("value", 0.0), (int, float)):
                    errors.append(f"Dirichlet {name!r} value must be one number")
            answer["dirichlet_values"] = merged_d
            answer["neumann_values"] = merged_n
            for key in ("body_force", "acceleration"):
                if key in answer:
                    answer[key] = _vector(answer[key], key, errors)
            if not dirichlet:
                errors.append("no support region: a static solve needs at least one held region")
            loads = [v for v in merged_n.values() if isinstance(v, list) and any(v)]
            loads += [v for v in loaded_forces if any(v)]
            # An omitted body load keeps the card's, as every omitted field does.
            body = [answer.get(key, card.get(key)) for key in ("body_force", "acceleration")]
            if not loads and not any(any(v or []) for v in body):
                warnings.append("no nonzero load: the solve would return zero displacement")

    elif kind == "material_input":
        if action == "texture_surface" and answer.get("per_part_colours"):
            # a flat colour per part: no painter, PartField only when the regions' parts are not its
            prepared.gpu, prepared.workers = True, ["partfield", "tools"]
        elif action == "texture_surface":
            if answer.get("texture_image"):
                answer["texture_image"] = _existing_path(answer["texture_image"], "texture_image", errors)
            elif not str(answer.get("texture_prompt", "")).strip():
                errors.append("texture_surface needs texture_prompt or texture_image")
            prepared.gpu, prepared.workers = True, ["hunyuan3d"]
        elif action == "infer_parts":
            if card.get("surface_has_colour") is False and not card.get("textured_surface"):
                errors.append("the surface has no colour; texture_surface first (or use uniform)")
            prepared.gpu, prepared.workers = True, ["partfield", "tools"]
        elif action == "infer_vomp":
            if card.get("surface_has_colour") is False and not card.get("textured_surface"):
                errors.append("the surface has no colour; texture_surface first")
            prepared.gpu, prepared.workers = True, ["vomp"]
        elif action == "infer_material":
            # Only a 'vomp' reading runs a model, but that cannot be known in advance.
            prepared.gpu, prepared.workers = True, ["vomp"]
        elif action == "apply_parts":
            current = {int(p["id"]): p for p in card.get("material_parts") or []}
            if not current:
                errors.append("infer_parts before apply_parts")
            edits = answer.get("parts") or []
            merged = dict(current)
            for part in edits:
                if not isinstance(part, dict) or "id" not in part:
                    errors.append(f"each part edit needs an id: {part!r}")
                    continue
                if int(part["id"]) not in current:
                    errors.append(f"part {part['id']} is not one of {sorted(current)}")
                    continue
                merged[int(part["id"])] = {**current[int(part["id"])], **part}
            parts = [{k: v for k, v in merged[i].items()
                      if k in ("id", "youngs_modulus", "poisson_ratio", "density")}
                     for i in sorted(merged)]
            for part in parts:
                validate(PartMaterial, part, f"part {part.get('id')}")
            if not errors:
                slip = _implausible_part(parts, workflow.get("unit_system") or "SI (m-kg-s)")
                if slip:
                    errors.append(f"implausible part values (would break the card): {slip}")
            if merge and len(edits) < len(parts):
                notes.append(f"{len(parts) - len(edits)} unedited part(s) kept as shown")
            answer["parts"] = parts
        else:  # apply_material
            mode = answer.get("material_mode")
            if mode is None and merge:
                mode = card.get("material_mode") or "uniform"
                answer["material_mode"] = mode
                notes.append(f"material_mode={mode!r} taken from the card")
            mode = mode or "uniform"
            if mode not in ("uniform", "parts", "vomp"):
                errors.append("material_mode must be uniform, parts or vomp")
            if mode == "uniform":
                for key in ("youngs_modulus", "poisson_ratio", "density"):
                    if answer.get(key) in (None, "") and merge and card.get(key) not in (None, ""):
                        answer[key] = card[key]
                        notes.append(f"{key}={card[key]!r} taken from the card")
                e, nu, rho = (answer.get(k) for k in ("youngs_modulus", "poisson_ratio", "density"))
                if not isinstance(e, (int, float)) or e <= 0:
                    errors.append("youngs_modulus must be a positive number in the modulus unit")
                if not isinstance(nu, (int, float)) or not -1 < nu < 0.5:
                    errors.append("poisson_ratio must be in (-1, 0.5)")
                if rho is not None and (not isinstance(rho, (int, float)) or rho <= 0):
                    errors.append("density must be positive")
                if any(workflow.get("acceleration") or []) and rho in (None, ""):
                    errors.append("density is required: the load case has a nonzero acceleration")
                if not errors:
                    slip = _implausible_part(
                        [{"id": 0, "youngs_modulus": e, "poisson_ratio": nu,
                          "density": rho if rho else _typical_density(workflow)}],
                        workflow.get("unit_system") or "SI (m-kg-s)")
                    if slip:
                        (warnings if force else errors).append(
                            f"implausible uniform material, likely a unit slip: {slip}")
                    if nu > 0.49:
                        warnings.append("poisson_ratio above 0.49 is nearly incompressible: "
                                        "expect poor conditioning (volumetric locking)")
            elif mode == "parts" and not card.get("parts_artifact"):
                errors.append("material_mode parts needs infer_parts first")
            elif mode == "vomp" and not card.get("material_artifact"):
                errors.append("material_mode vomp needs infer_vomp first")

    elif kind == "shape_opt_settings":
        if answer.get("action") == "finish":
            return prepared
        answer.pop("action", None)
        if merge:
            changed = sorted(k for k in answer if (card.get("defaults") or {}).get(k) != answer[k])
            answer = {**(card.get("defaults") or {}), **answer}
            notes.append("settings = the card's current settings"
                         + (f" with {', '.join(changed)} changed" if changed else ", unchanged"))
        answer["preset_version"] = 2
        prepared.answer = answer
        parsed = validate(ShapeOptSettings, answer, "settings")
        material = (workflow.get("material") or {}).get("mode")
        if parsed is not None:
            if parsed.run_mode != "forward" and material in FIELD_MODES:
                errors.append(f"shape optimization needs a uniform material; this case uses {material}")
            estimate, floor = card.get("strain_estimate"), card.get("strain_floor")
            if (estimate is not None and floor is not None and estimate < floor
                    and not parsed.use_mixed_precision):
                warnings.append(f"estimated strain {estimate:.3g} is below the float32 floor "
                                f"{floor:.3g}: set use_mixed_precision true")
            if parsed.remesh_octree_depth >= 8:
                warnings.append("remesh_octree_depth >= 8: several times the time and about 3x "
                                "the VRAM of depth 7")
            if parsed.remesh_init_octree_depth > parsed.remesh_octree_depth:
                errors.append("remesh_init_octree_depth cannot exceed remesh_octree_depth")
        prepared.gpu, prepared.workers = True, ["solver"]
    return prepared


def _typical_density(workflow: dict[str, Any]) -> float:
    """A placeholder density in the session's units, only for the plausibility check."""
    unit = workflow.get("unit_system") or "SI (m-kg-s)"
    return {"SI (m-kg-s)": 1000.0, "SI-mm (mm-tonne-s)": 1e-9,
            "US-inch (in-lbf-s)": 9.357254e-5}.get(unit, 1000.0)


# ----------------------------------------------------------------- graph --

# The folder each open session was opened from.  The graph rebases a state
# recorded elsewhere onto the folder named in its config, so a copied or moved
# session reads and writes where it now is.
_SESSION_FOLDERS: dict[str, str] = {}


@contextlib.contextmanager
def open_graph(session: Path) -> Iterator[Any]:
    from src.agents_wrapper.fem_workflow.graph import open_session_graph

    _SESSION_FOLDERS[session.name] = str(session.resolve())
    with open_session_graph(session) as graph:      # as the app's controller opens a session
        yield graph


def _thread(session_id: str) -> dict[str, Any]:
    if session_id in _SESSION_FOLDERS:
        from src.agents_wrapper.fem_workflow.graph import session_thread
        return session_thread(session_id, _SESSION_FOLDERS[session_id])
    return {"configurable": {"thread_id": session_id}}


def pending(graph: Any, session_id: str) -> dict[str, Any]:
    snapshot = graph.get_state(_thread(session_id))
    interrupts = [item.value for task in snapshot.tasks for item in task.interrupts]
    return {
        "checkpoint_id": snapshot.config.get("configurable", {}).get("checkpoint_id"),
        "card": interrupts[0] if interrupts else None,
        "next": list(snapshot.next or ()),
        "workflow": (snapshot.values or {}).get("workflow") or {},
    }


def fork(graph: Any, session_id: str, checkpoint_id: str) -> Any:
    """Make ``checkpoint_id`` the head again, with its card waiting afresh.

    Used for a rewind and after a failed answer, whose resume value LangGraph
    would otherwise replay on the next attempt (``graph.reopen_card``).
    """
    from src.agents_wrapper.fem_workflow.graph import reopen_card
    return reopen_card(graph, _thread(session_id), checkpoint_id)


def event_from(graph: Any, session_id: str, result: Any, session: Path) -> dict[str, Any]:
    state = pending(graph, session_id)
    interrupts = (result or {}).get("__interrupt__", ()) if isinstance(result, dict) else ()
    card = interrupts[0].value if interrupts else state["card"]
    workflow = ((result or {}).get("workflow") if isinstance(result, dict) else None) \
        or state["workflow"] or lib.read_json(session / "session.json", {})
    return {"checkpoint_id": state["checkpoint_id"], "card": card,
            "next": state["next"], "workflow": workflow}


# ------------------------------------------------------------ GPU guard --

def _stop_worker(pid: int, kind: str, pid_file: Path) -> None:
    """Stop one resident worker, found by its pid file (see sessionlib.worker_files)."""
    lib.stop_worker_file(pid, kind, pid_file)


def warm_gpus(output_root: Path, needed_workers: list[str]) -> set[int]:
    """The GPUs already holding (or loading) a resident worker this step needs."""
    if not needed_workers:
        return set()
    try:
        apps, gpus = lib.query_apps(), lib.query_gpus()
        return {index for pid, kind, _ in lib.worker_files(output_root) if kind in needed_workers
                for index in lib.worker_gpu(pid, apps, gpus)}
    except Exception:
        return set()


def select_gpu(args: argparse.Namespace, output_root: Path, gpu_step: bool,
               needed_workers: list[str], compute_env: str, need_mib: int = 0) -> dict[str, Any]:
    """Pin this process (and so every tool and worker it starts) to one GPU.

    Returns ``{"index", "verdicts", "moved", "override"}`` or raises
    ``NoIdleGPU`` when the rules forbid running now.  ``need_mib``: the free memory the step
    needs, our own workers' counted as room (a finer TripoSG extraction, EXTRACTION_MIB); an idle
    GPU with less is waited on as a busy one.
    """
    if not lib.nvidia_smi_available():
        return {"index": None, "note": "nvidia-smi not found; GPU not pinned"}
    # Three samples a second apart for a GPU step, one when a GPU was found idle (nobody else on
    # it) within the last minute: a fresh command re-sampled for 2.2 s before every GPU step.
    count = 3 if gpu_step and not lib.recent_idle(output_root) else 1
    started = time.time()
    while True:
        verdicts = lib.gpu_table(output_root, count=count, interval=1.0,
                                 max_foreign_mib=args.max_foreign_mib, max_util=args.max_util)
        if args.gpu not in (None, "auto"):
            chosen = next((v for v in verdicts if v.index == int(args.gpu)), None)
            if chosen is None:
                raise NoIdleGPU(f"GPU {args.gpu} does not exist", verdicts)
            override = "user-specified GPU" + ("" if chosen.idle else f" (busy: {chosen.reason})")
            break
        warm = (warm_gpus(output_root, needed_workers)
                if gpu_step and any(v.idle for v in verdicts) else set())
        roomy = [v for v in verdicts if v.free_mib + v.ours_mib >= need_mib]
        chosen = lib.choose_gpu(roomy, warm)
        override = None
        if chosen is not None and gpu_step:
            lib.note_verdicts(output_root, verdicts)
        if chosen is not None:
            break
        if not gpu_step or args.allow_busy_gpu:
            chosen = min(verdicts, key=lambda v: (v.foreign_mib, v.util))
            override = ("--allow-busy-gpu: running on the least-loaded busy GPU"
                        if gpu_step else "CPU step; pinned to the least-loaded GPU")
            break
        if count == 1:
            # One sample cannot tell a process starting from another user's (sessionlib.classify):
            # look again with three before waiting.
            count = 3
            continue
        if time.time() - started >= args.gpu_wait:
            raise NoIdleGPU(f"no idle GPU{f' with {need_mib} MiB free' if need_mib else ''} after waiting "
                            f"{args.gpu_wait:.0f} s", verdicts)
        print(json.dumps({"waiting_for_idle_gpu": [v.as_dict() for v in verdicts]}),
              file=sys.stderr, flush=True)
        # Another user's job (our own load no longer counts, sessionlib.classify): check again.
        count = 3
        time.sleep(10)
    os.environ["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
    os.environ["CUDA_VISIBLE_DEVICES"] = str(chosen.index)
    moved = []
    if gpu_step:
        apps, gpus = lib.query_apps(), lib.query_gpus()
        for pid, kind, pid_file in lib.worker_files(output_root):
            if kind not in needed_workers:
                continue
            where = lib.worker_gpu(pid, apps, gpus)
            if chosen.index not in where:
                _stop_worker(pid, kind, pid_file)
                moved.append(f"stopped {kind} worker (pid {pid}) on GPU {where}; "
                             f"it restarts on GPU {chosen.index}")
    return {"index": chosen.index, "name": chosen.name, "override": override,
            "moved": moved, "verdicts": [v.as_dict() for v in verdicts],
            "samples": count, "select_s": round(time.time() - started, 2)}


class NoIdleGPU(RuntimeError):
    def __init__(self, message: str, verdicts: list[Any]):
        super().__init__(message)
        self.verdicts = verdicts


# ------------------------------------------------------------- utilities --

_HELD_LOCKS: set[str] = set()


@contextlib.contextmanager
def session_lock(session: Path) -> Iterator[None]:
    # Re-entrant within one process: a step the runner takes inside its own `run` (the solver
    # fallback) holds the lock the run already holds.
    key = str(Path(session).resolve())
    if key in _HELD_LOCKS:
        yield
        return
    path = lib.operator_dir(session) / "driver.lock"
    handle = path.open("a+")
    try:
        fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        handle.close()
        raise SystemExit(json.dumps({
            "ok": False, "error": "another driver is working on this session; "
                                  "wait for it (drive.py status) instead of starting a second"}))
    handle.seek(0)
    handle.truncate()
    handle.write(str(os.getpid()))
    handle.flush()
    _HELD_LOCKS.add(key)
    try:
        yield
    finally:
        _HELD_LOCKS.discard(key)
        fcntl.flock(handle, fcntl.LOCK_UN)
        handle.close()


def lock_holder(session: Path) -> int | None:
    path = session / "operator" / "driver.lock"
    if not path.exists():
        return None
    with path.open("a+") as handle:
        try:
            fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            handle.seek(0)
            text = handle.read().strip()
            return int(text) if text.isdigit() else -1
        fcntl.flock(handle, fcntl.LOCK_UN)
    return None


def trim_card(card: Any) -> Any:
    """The card as an agent needs to read it: long logs cut to their tail."""
    if not isinstance(card, dict):
        return card
    card = dict(card)
    if isinstance(card.get("solve_log"), str):
        lines = card["solve_log"].splitlines()
        card["solve_log"] = "\n".join(lines[-SOLVE_LOG_LINES:])
    for key in ("text2cad", "cadcoder", "hunyuan3d", "partfield", "texture_status"):
        if isinstance(card.get(key), dict):
            card[key] = {k: card[key].get(k) for k in ("ready", "summary")}
    card.pop("unit_details", None)
    return card


def save_stop(session: Path, name: str, value: Any) -> None:
    """A stop's payload saved under ``operator/`` (``last_run.json``, ``stop_<stop>.json``,
    ``last_event.json``): what the agent may read again, so its paths are relative too."""
    lib.write_json(lib.operator_dir(session) / name, lib.relative_paths(value))


LIST_SHOWN = 20     # a list in a command's output shows this many items and counts the rest


def capped(value: Any) -> Any:
    """Every list longer than LIST_SHOWN cut to its first LIST_SHOWN items and a count of the rest:
    one run printed 122 KB of region pieces, and its agent sent the output to
    /dev/null from then on.  The stop records on disk keep everything."""
    if isinstance(value, dict):
        return {k: capped(v) for k, v in value.items()}
    if isinstance(value, list):
        shown = [capped(v) for v in value[:LIST_SHOWN]]
        return shown + ([f"... {len(value) - LIST_SHOWN} more (the stop's record in operator/ has all)"]
                        if len(value) > LIST_SHOWN else [])
    return value


def emit(value: dict[str, Any], session: Path | None = None) -> None:
    if session is not None and value.get("card") is not None:
        save_stop(session, "last_event.json", value)
    shown = capped(dict(value))
    shown.pop("workflow", None)
    if shown.pop("_compact", False):
        # A stop's compact view (compact_stop): still one JSON object, but one line per key,
        # without the indentation that put every number of a list on its own line.
        if shown.get("card") is not None:
            shown["card"] = trim_card(shown["card"])
        shown = lib.relative_paths(shown)

        def text(ascii_only: bool) -> str:
            return "{\n" + ",\n".join(
                json.dumps(k) + ":" + json.dumps(v, separators=(",", ":"), default=str, ensure_ascii=ascii_only)
                for k, v in shown.items()) + "\n}"
        try:            # a "−" or "ν" is one character, not six; escaped where stdout cannot take it
            print(text(False))
        except UnicodeEncodeError:
            print(text(True))
        return
    shown["card"] = trim_card(value.get("card"))
    print(json.dumps(lib.relative_paths(shown), indent=1, default=str))


def summarize(session_id: str, event: dict[str, Any], **extra: Any) -> dict[str, Any]:
    card = event.get("card")
    workflow = event.get("workflow") or {}
    return {
        "ok": True, "session_id": session_id,
        "checkpoint_id": event.get("checkpoint_id"),
        "stage": workflow.get("stage"),
        "kind": card.get("kind") if isinstance(card, dict) else None,
        "complete": workflow.get("stage") == "complete" and card is None,
        "pending_node": event.get("next") if card is None else None,
        "card": card,
        "workflow": workflow,
        **extra,
    }


def preload(output_root: Path, session: Path, compute_env: str, card: Any, args) -> str | None:
    """Warm the workers the next step will want, the CLI's schedule, on an idle GPU."""
    # (a caller without the CLI's --no-preload flag, such as a test's Namespace, never preloads)
    if getattr(args, "no_preload", True) or not isinstance(card, dict):
        return None
    # The GPU this command's last step was checked idle on, when that check is fresh; else one
    # sample.  Warming takes memory, so it still never lands where another user is.
    pinned = os.environ.get("CUDA_VISIBLE_DEVICES", "")
    if pinned.isdigit() and lib.recent_idle(output_root, int(pinned)):
        index = int(pinned)
    else:
        try:
            verdicts = lib.gpu_table(output_root, count=1, interval=0.0,
                                     max_foreign_mib=args.max_foreign_mib, max_util=args.max_util)
        except Exception:
            return None
        chosen = lib.choose_gpu(verdicts)
        if chosen is None:
            return "no idle GPU: workers not preloaded"
        index = chosen.index
    os.environ["CUDA_DEVICE_ORDER"] = "PCI_BUS_ID"
    os.environ["CUDA_VISIBLE_DEVICES"] = str(index)
    from src.agents_wrapper.fem_workflow.run_workflow import preload_for
    from src.agents_wrapper.fem_workflow.workers import (
        ensure_hunyuan3d_worker, ensure_solver_worker, ensure_tool_worker,
    )
    if paint_ahead_running(session) and card.get("kind") not in ("bc_input", "bc_values", "material_input"):
        join_paint_ahead(session)     # (a rewind past the regions: this card's models would stop it)
    if hunyuan_likely_next(session, card, _plan_of(args)):
        # B2: a TripoSG body from the drawing, with Hunyuan3D the next route the plan lists: its
        # shape stage loads now, beside TripoSG (a retry of the drawing route keeps its worker),
        # while the agent reads the geometry stop.  3 of 4 Hunyuan3D bodies that
        # followed a TripoSG body turned down here loaded cold (92-158 s a call).  Only
        # on the stop's own card: past it (the body accepted) preload_for below frees the worker.
        try:
            ensure_tool_worker(output_root, compute_env, "cuda")
            free = _gpu_free_mib()
            if free is not None and free >= HUNYUAN_SHAPE_MIB:
                ensure_hunyuan3d_worker(output_root, compute_env, shape_only=True, keep_triposg=True)
                return f"workers for the next step warming on GPU {index} (Hunyuan3D's shape stage, ahead)"
            return f"workers for the next step warming on GPU {index} ({free} MiB free: Hunyuan3D not warmed)"
        except Exception as exc:  # warm-up is an optimization only
            return f"preload skipped: {type(exc).__name__}: {exc}"
    plan = _plan_of(args)
    if card.get("kind") == "geometry_input" and hunyuan_kept_for_route(output_root, session, card, plan):
        # B3: a drawing card on the way to Hunyuan3D (the plan's routes list it after the
        # drawing): the Hunyuan3D worker warmed at the last geometry stop stays beside TripoSG
        # and the drawing, room allowing.  One run lost it at the redrawn
        # drawing's card and loaded it again cold (58 s) for the generation that followed.
        try:
            from src.agents_wrapper.fem_workflow.workers import ensure_geometry_worker
            ensure_geometry_worker(output_root, session, compute_env, keep_hunyuan3d=True)
            ensure_tool_worker(output_root, compute_env, "light")
            return f"workers for the next step warming on GPU {index} (Hunyuan3D kept for the next route)"
        except Exception as exc:  # warm-up is an optimization only
            return f"preload skipped: {type(exc).__name__}: {exc}"
    if paint_coming(session, card, plan):
        # B4: the plan paints this body at the material card.  The paint worker loads from the
        # geometry stop on, while the agent reads it, and PartField beside it, so neither is cold
        # when the body is accepted: segmentation first (5 s warm), then the background paint
        # (start_paint_ahead, 28 s warm).  Run together they took 13.7 and 33.5 s (measured): the
        # paint ends no sooner and the segmentation is three times slower.
        try:
            return warm_for_paint(output_root, session, compute_env, card, plan, index)
        except Exception as exc:  # warm-up is an optimization only
            return f"preload skipped: {type(exc).__name__}: {exc}"
    # A paint running in the background (start_paint_ahead) keeps its worker whatever the card.
    ahead = paint_ahead(session, card, args) or paint_ahead_running(session)
    paint = card_will_paint(card, args)
    plan_generator = ((_plan_of(args) or {}).get("geometry") or {}).get("generator")
    if card.get("kind") == "geometry_input" and plan_generator:
        # The card names the generator of the last answer; a drawing answer names none, so after
        # one it still says TripoSG while the plan generates with Hunyuan3D next.  The plan's is
        # the one to warm (a run's first Hunyuan3D body loaded cold).
        card = {**card, "generator": plan_generator}
    if card.get("kind") == "geometry_texture" and paint is False and (
            (lib.read_json(session / "session.json", {}) or {}).get("generation") or {}).get("generator") == "hunyuan3d":
        # A Hunyuan3D body at the geometry stop: the worker stays for a regeneration, as the app
        # keeps it on this card.  Stopping it here made a run's second Hunyuan3D body load
        # the model again; the next card past the geometry stops it.
        paint = None
    try:
        preload_for(output_root, session, compute_env, card, paint=paint,
                    solver_spare=not card.get("solve_complete"), keep_paint=ahead,
                    # the runner generates Hunyuan3D bodies without colour (hunyuan_shape_only)
                    hunyuan_shape_only=plan_shape_only(_plan_of(args)))
        # The app warms each model when its own card opens, while a person reads it.  A plan
        # answers the cards between two stops at once, so the slow loads start one stop early,
        # while the agent reads: the paint worker (about 20 s) from the regions stop when the
        # plan paints, the solve's spare from the last stop before the solve when it does not.
        if card.get("kind") in ("bc_input", "bc_values", "material_input") and not ahead \
                and not card.get("solve_complete") and card_will_paint(card, args) is not True:
            ensure_solver_worker(output_root, compute_env)
    except Exception as exc:  # warm-up is an optimization only
        return f"preload skipped: {type(exc).__name__}: {exc}"
    return f"workers for the next step warming on GPU {index}"


HUNYUAN_SHAPE_MIB = 16_000      # free VRAM the shape stage's worker needs to be warmed beside TripoSG


def plan_shape_only(plan: dict[str, Any] | None) -> bool:
    """Whether the runner generates Hunyuan3D bodies without colour for this plan: unless its
    geometry.generation_settings sets ``texture`` itself (true: the body is painted as generated)."""
    settings = ((plan or {}).get("geometry") or {}).get("generation_settings") or {}
    return settings.get("texture", False) is False


def hunyuan_shape_only(answer: Any, plan: dict[str, Any]) -> Any:
    """A Hunyuan3D generation the runner sends asks for the shape alone (``texture`` off), unless
    the plan's geometry.generation_settings sets ``texture`` itself.  Painting every body cost
    29-34 s a generation, bodies turned down at the geometry stop included, and the colour it made
    was never the plan's: plan.texture could not repaint a coloured body.  The colour is made when
    the plan needs it (plan.texture, or per-part materials), on the accepted body, in the
    background (start_paint_ahead)."""
    if not isinstance(answer, dict) or answer.get("generator") != "hunyuan3d" \
            or answer.get("action") == "draw_image":
        return answer
    settings = dict(answer.get("generation_settings") or {})
    if "texture" in ((plan.get("geometry") or {}).get("generation_settings") or {}):
        return answer
    return {**answer, "generation_settings": {**settings, "texture": False}}


def _gpu_free_mib() -> int | None:
    from src.agents_wrapper.fem_workflow.monitor import gpu_free_mib
    return gpu_free_mib()


def hunyuan_likely_next(session: Path, card: dict[str, Any], plan: dict[str, Any] | None) -> bool:
    """Whether Hunyuan3D is the likely next generation, seen from a geometry stop: the body is
    TripoSG's from the drawing, and the plan's geometry_routes list hunyuan3d after the drawing.
    The warm-up generates nothing; a body accepted here frees the worker at the next card."""
    # The geometry stop's card for a TripoSG body (bare, so offered to the painter, which is the
    # Hunyuan3D install this needs anyway); geometry_physics comes after the body is accepted.
    if card.get("kind") != "geometry_texture" or not isinstance(plan, dict) or not plan_shape_only(plan):
        return False
    geometry = plan.get("geometry") or {}
    if not geometry.get("draw") or geometry.get("generator") not in (None, "triposg"):
        return False
    routes = plan.get("geometry_routes") or declared_routes(session) or []
    if "drawing" not in routes or "hunyuan3d" not in routes[routes.index("drawing") + 1:]:
        return False
    generation = (lib.read_json(session / "session.json", {}) or {}).get("generation") or {}
    return generation.get("generator") in (None, "triposg") and hunyuan_ready()


def paint_ahead(session: Path, card: dict[str, Any], args) -> bool:
    """Whether the material card a run reaches next will paint, seen from the regions cards
    before it: the plan paints (``texture``, or per-part materials, which read colour) and the
    analysis surface is bare."""
    if card.get("kind") not in ("bc_input", "bc_values"):
        return False
    plan = _plan_of(args)
    if not plan_paints(plan):
        return False
    surface = (lib.read_json(session / "session.json", {}) or {}).get("surface_path")
    try:
        from src.hunyuan3d_wrapper.surface import has_colour
        return bool(surface) and not has_colour(surface)
    except Exception:
        return False


def plan_paints(plan: dict[str, Any] | None) -> bool:
    """Whether the plan paints the body with the painter at the material card: ``texture``, or
    per-part materials with their own texture_prompt; not a body coloured flat by part
    (per_part_colours, and per-part materials without a texture_prompt), which needs no painter."""
    material = (plan.get("material") or {}) if isinstance(plan, dict) else {}
    return (isinstance(plan, dict) and not per_part_colours(plan)
            and bool(plan.get("texture") or (material.get("mode") == "parts" and material.get("texture_prompt"))))


def per_part_colours(plan: dict[str, Any] | None) -> Any:
    """plan.texture.per_part_colours: true, or {"<part id>": "<colour words>"}; None when not asked."""
    texture = plan.get("texture") if isinstance(plan, dict) else None
    return texture.get("per_part_colours") or None if isinstance(texture, dict) else None


# The paint worker's resident memory (17.1-17.8 GB measured: the paint stage and SDXL's reference
# models), with a margin: what a card needs free to warm it ahead of the paint.
PAINT_WORKER_MIB = 18_500
# A PartField segmentation beside it (monitor.PARTFIELD_RUN_MIB: 5.2 GB above its worker).
PARTFIELD_BESIDE_MIB = 6_000


def paint_coming(session: Path, card: dict[str, Any], plan: dict[str, Any] | None) -> bool:
    """Whether this card lies between the geometry stop and the material card of a body the plan
    paints: the geometry stop (its skipped texture card), the scaling, the regions and values
    cards, with the analysis surface still bare."""
    if card.get("kind") not in ("geometry_texture", "geometry_physics", "bc_input", "bc_values") \
            or card.get("solve_complete") or not plan_paints(plan):
        return False
    surface = _session_surface(session)
    try:
        from src.hunyuan3d_wrapper.surface import has_colour
        return bool(surface) and has_colour(surface) is False
    except Exception:
        return False


def _hunyuan3d_worker(output_root: Path) -> str | None:
    """The live Hunyuan3D worker's stages: "paint" (the paint stage loaded or loading), "shape"
    (started for a shape-only generation, --no-texture), or None when there is none."""
    from src.agents_wrapper.fem_workflow.runtime_files import worker_paths
    from src.agents_wrapper.fem_workflow.workers import worker_is_serving
    from src.hunyuan3d_wrapper.availability import settings as hunyuan3d_settings
    socket_path, pid_path = worker_paths(output_root, "hunyuan3d", hunyuan3d_settings()[0])
    if not worker_is_serving(socket_path, pid_path):
        return None
    try:
        command = Path(f"/proc/{int(pid_path.read_text(encoding='utf-8'))}/cmdline").read_bytes()
    except (OSError, ValueError):
        return None
    return "shape" if b"--no-texture" in command.split(b"\0") else "paint"


def _partfield_wanted(session: Path, plan: dict[str, Any] | None) -> bool:
    """Whether the segmentation ahead runs PartField: installed, no CAD faces to start from, and
    the plan names no other method."""
    method = ((plan or {}).get("segmentation") or {}).get("method")
    if method not in (None, "partfield"):
        return False
    if (lib.read_json(session / "session.json", {}) or {}).get("cad_faces_path"):
        return False
    try:
        from src.partfield_wrapper.availability import partfield_status
        return bool(partfield_status().ready)
    except Exception:
        return False


def warm_for_paint(output_root: Path, session: Path, compute_env: str, card: dict[str, Any],
                   plan: dict[str, Any] | None, index: int) -> str:
    """Warm the paint worker and PartField side by side for a body the plan paints (paint_coming).

    At the geometry stop TripoSG stays for a regeneration, and a Hunyuan3D body keeps its shape
    worker (its paint stage would not fit beside it with the paint's peak); once the body is
    accepted a shape-only worker gives way to the paint worker.  Each loads only where the card
    has room for it and what runs beside it; the background paint (start_paint_ahead) checks
    again before it starts."""
    from src.agents_wrapper.fem_workflow.workers import (
        ensure_hunyuan3d_worker, ensure_partfield_worker, ensure_tool_worker, stop_hunyuan3d_worker,
    )
    kind = card.get("kind")
    at_stop = kind == "geometry_texture"
    generator = ((lib.read_json(session / "session.json", {}) or {}).get("generation") or {}).get("generator")
    partfield = kind in ("geometry_texture", "geometry_physics", "bc_input") and _partfield_wanted(session, plan)
    ensure_tool_worker(output_root, compute_env, "cuda")
    if at_stop and generator not in (None, "triposg", "hunyuan3d"):
        # a CAD body: its generator's worker stays for a regeneration; both load once accepted
        return f"workers for the next step warming on GPU {index}"
    warmed, state = [], _hunyuan3d_worker(output_root)
    if at_stop and generator == "hunyuan3d":
        pass        # the shape worker stays for a regeneration (the paint stage loads once accepted)
    elif state == "paint":
        warmed.append("the paint worker")
    else:
        if state == "shape":
            stop_hunyuan3d_worker(output_root)      # the body is accepted: no regeneration follows
        free = _gpu_free_mib()
        needed = PAINT_WORKER_MIB + (PARTFIELD_BESIDE_MIB if partfield else 0)
        if free is not None and free >= needed:
            ensure_hunyuan3d_worker(output_root, compute_env, paint=True, keep_triposg=at_stop,
                                    keep_partfield=True)
            warmed.append("the paint worker")
        else:
            warmed.append(f"not the paint worker ({free} MiB free, {needed} needed)")
    if partfield:
        ensure_partfield_worker(output_root, compute_env,
                                keep=("hunyuan3d", "triposg") if at_stop else ("hunyuan3d",))
        warmed.append("PartField")
    return f"workers for the next step warming on GPU {index} ({', '.join(warmed)}, ahead of the paint)"


def hunyuan_kept_for_route(output_root: Path, session: Path, card: dict[str, Any],
                           plan: dict[str, Any] | None) -> bool:
    """Whether a drawing card keeps the Hunyuan3D worker warmed for the next route: the card
    generates with another generator (TripoSG, from the drawing), the plan's routes list Hunyuan3D
    after the drawing, the worker is up, and the card has room for a drawing beside it."""
    if not isinstance(plan, dict) or not plan_shape_only(plan):
        return False
    generator = ((plan.get("geometry") or {}).get("generator")) or card.get("generator")
    if generator not in (None, "triposg") or not (plan.get("geometry") or {}).get("draw"):
        return False
    routes = plan.get("geometry_routes") or declared_routes(session) or []
    if "drawing" not in routes or "hunyuan3d" not in routes[routes.index("drawing") + 1:]:
        return False
    if _hunyuan3d_worker(output_root) is None:
        return False
    from src.agents_wrapper.fem_workflow.monitor import SDXL_RUN_MIB
    free = _gpu_free_mib()
    return free is not None and free >= SDXL_RUN_MIB


def _plan_of(args) -> dict[str, Any] | None:
    try:
        plan = json.loads(Path(args.plan).read_text()) if getattr(args, "plan", None) else None
    except (OSError, ValueError):
        return None
    return plan if isinstance(plan, dict) else None


def card_will_paint(card: dict[str, Any], args) -> bool | None:
    """Whether the runner will paint at this card (so the paint worker is worth loading):
    never at the geometry's texture card (the runner skips it), at the material card only for a
    bare surface the plan paints or values by colour.  None: no plan to tell, keep the default."""
    kind = card.get("kind")
    if kind == "geometry_texture":
        return False
    if kind != "material_input":
        return None
    plan = _plan_of(args)
    if plan is None:
        return None
    if card.get("surface_has_colour") is not False:
        return False
    return plan_paints(plan)


# ------------------------------------------------------- paint ahead --
# The material card's paint (plan.texture, or the parts' colour) started in the background as soon
# as the geometry is final and segmented, so it overlaps the region preview and the agent's reading
# of the regions stop instead of sitting in front of the texture stop (34 and 29 s warm, 2026-10-09).
# paint_ahead.py runs the card's own paint through the tool monitor; the card's texture_surface is
# then served from the same receipts.  Every step that could disturb it -- anything that loads
# another model, changes the surface, or reads the colour -- waits for it first (join_paint_ahead).

PAINT_AHEAD = "paint_ahead.json"
PAINT_AHEAD_WAIT_S = 900.0        # the paint tool's own timeout
# VRAM a paint needs free on the card: the paint worker's peak (30.4 GB on one run's
# card, 17.1 GB of it resident) when it must load, the peak above the resident worker when it is up.
PAINT_AHEAD_COLD_MIB = 31_000
PAINT_AHEAD_WARM_MIB = 14_000


def paint_ahead_answer(session: Path, plan: dict[str, Any] | None) -> dict[str, Any] | None:
    """The ``texture_surface`` answer the material card will send for this plan, if it paints.

    Computed the way the runner computes the card's own answer (plan_answer on a bare surface with
    nothing painted or valued yet, then the lint), so the paint made ahead is the one the card asks
    for.  None when the plan does not paint or the surface already has colour."""
    if not plan_paints(plan):
        return None
    workflow = lib.read_json(session / "session.json", {}) or {}
    surface = _session_surface(session)
    try:
        from src.hunyuan3d_wrapper.surface import has_colour
        if not surface or has_colour(surface):
            return None
    except Exception:
        return None
    card = {"kind": "material_input", "surface_has_colour": False, "textured_surface": None,
            "material_parts": []}
    try:
        answer, _, _ = plan_answer("material_input", card, plan)
    except Exception:
        return None
    if not isinstance(answer, dict) or answer.get("action") != "texture_surface":
        return None
    # the material card adds the same image (with_body_image), so the receipts match
    answer = with_body_image(session, answer)
    prepared = prepare_answer(card, workflow, answer, merge=True, force=False)
    return None if prepared.errors else prepared.answer


def _session_surface(session: Path) -> str | None:
    """The analysis surface session.json names, in this folder (a copied session's snapshot names
    the folder it was recorded in, as graph._state rebases)."""
    workflow = lib.read_json(session / "session.json", {}) or {}
    return _in_session(session, workflow, workflow.get("surface_path"))


def _in_session(session: Path, workflow: dict[str, Any], path: Any) -> str | None:
    """A path session.json records, moved into this folder when it lies under the folder the
    snapshot was recorded in (a copied session)."""
    recorded = workflow.get("session_dir")
    if path and recorded and str(path).startswith(str(recorded).rstrip("/") + "/"):
        return os.fspath(Path(session) / str(path)[len(str(recorded).rstrip("/")) + 1:])
    return str(path) if path else None


def body_image(session: Path) -> str | None:
    """The image the current body was generated from -- the session's input image (a drawing's or a
    web photograph's cut-out) -- or None: a body from text, a CAD generator, a built or uploaded
    body, or one no record ties to that image.

    Tied by the records, not by the card's mode: the body on disk is the generated mesh
    (``body_source``), the last generation receipt that wrote its contents took the input image as
    its input, and the image staged there before that generation is the one on disk now (the
    input asset's file is overwritten by every later image)."""
    workflow = lib.read_json(session / "session.json", {}) or {}
    asset = workflow.get("input_asset") or {}
    if workflow.get("geometry_mode") != "image" or not asset.get("path"):
        return None
    source = body_source(session)
    image = _in_session(session, workflow, asset["path"])
    if source is None or source.name != "generated.glb" or not image or not Path(image).is_file():
        return None
    body, picture = _file_sha256(source), _file_sha256(Path(image))
    if asset.get("sha256") and asset["sha256"] != picture:
        return None
    staged, tied = None, False
    for receipt in workflow.get("tool_receipts") or []:
        tool = str(receipt.get("tool") or "")
        arguments = receipt.get("arguments") or {}
        digests = {_in_session(session, workflow, k): v for k, v in (receipt.get("artifact_digests") or {}).items()}
        if tool == "stage_asset" and _in_session(session, workflow, arguments.get("output")) == image:
            staged = digests.get(image)
        elif tool.startswith("generate") and body in digests.values():
            # the latest generation that wrote this body decides
            tied = _in_session(session, workflow, arguments.get("input")) == image and staged == picture
    return os.fspath(Path(image).resolve()) if tied else None


def with_body_image(session: Path, answer: Any) -> Any:
    """A painting ``texture_surface`` answer for a body generated from an image, painted from that
    image (``texture_image``: the painter's reference in place of one SDXL draws from the words,
    so the body keeps the look it was made from; the words stay, for the record and the painter's
    plain-colour fallback).  Any other answer, a flat colour by part, or one that names its own
    image, is returned as it is.  Both the background paint (paint_ahead_answer) and the material
    card's own answer go through here, so the card is served from the background paint's receipts."""
    if (not isinstance(answer, dict) or answer.get("action") != "texture_surface"
            or answer.get("per_part_colours") or answer.get("texture_image")):
        return answer
    image = body_image(session)
    return {**answer, "texture_image": image} if image else answer


def painted_from_image(session: Path, painted: Any) -> str | None:
    """The image the painted surface ``painted`` was painted from (the paint receipt's input), or
    None for a paint from words: the last paint receipt that wrote this file's contents decides."""
    if not painted or not Path(painted).is_file():
        return None
    workflow = lib.read_json(session / "session.json", {}) or {}
    digest, found = _file_sha256(Path(painted)), None
    for receipt in workflow.get("tool_receipts") or []:
        if receipt.get("tool") == "paint_hunyuan3d_surface" and digest in (receipt.get("artifact_digests") or {}).values():
            found = _in_session(session, workflow, (receipt.get("arguments") or {}).get("input"))
    return found


def _paint_ahead_key(session: Path, answer: dict[str, Any]) -> str:
    import hashlib
    surface = _session_surface(session) or ""
    try:
        from src.agents_wrapper.fem_workflow.monitor import _digest
        contents = _digest(Path(surface)) if surface else ""
    except Exception:
        contents = ""
    return hashlib.sha256(_normalized([surface, contents, answer]).encode()).hexdigest()[:16]


def _paint_ahead_record(session: Path) -> dict[str, Any]:
    """operator/paint_ahead.json, with a paint whose process is gone without saying how it ended
    (killed, crashed) marked failed: it is neither waited for nor started again."""
    path = lib.operator_dir(session) / PAINT_AHEAD
    record = lib.read_json(path, {}) or {}
    pid = record.get("pid")
    if record.get("state") == "running" and (
            (isinstance(pid, int) and not lib._alive(pid))
            or (pid is None and time.time() - float(record.get("started") or 0) > 30)):
        with contextlib.suppress(ChildProcessError, OSError):
            if isinstance(pid, int):
                os.waitpid(pid, os.WNOHANG)
        record = lib.read_json(path, {}) or {}       # it may have written its end meanwhile
        if record.get("state") == "running":
            record.update(state="failed", error="the background paint ended without recording its end")
            lib.write_json(path, record)
    return record


def paint_ahead_running(session: Path) -> bool:
    return _paint_ahead_record(session).get("state") == "running"


def paint_ahead_warning(session: Path) -> str | None:
    """A failed background paint, or another job on its card, said once as a step warning."""
    path = lib.operator_dir(session) / PAINT_AHEAD
    record = _paint_ahead_record(session)
    if record.get("reported") or record.get("state") not in ("failed", "done"):
        return None
    warning = None
    if record.get("state") == "failed":
        warning = (f"the background paint failed ({str(record.get('error'))[:300]}); the material card "
                   "paints for itself")
    elif (record.get("gpu") or {}).get("foreign_appeared"):
        warning = ("another job appeared on the GPU during the background paint; look at the painted "
                   "views before trusting them")
    record["reported"] = True
    lib.write_json(path, record)
    return warning


def _paint_stage_loaded(output_root: Path) -> bool | None:
    """Whether the live Hunyuan3D worker holds the paint stage (None: no worker serving).  One
    started for a shape-only generation (--no-texture) loads it only on its first paint."""
    from src.agents_wrapper.fem_workflow.runtime_files import worker_paths
    from src.hunyuan3d_wrapper.availability import settings as hunyuan3d_settings
    socket_path, pid_path = worker_paths(output_root, "hunyuan3d", hunyuan3d_settings()[0])
    if not socket_path.exists():
        return None
    try:
        pid = int(pid_path.read_text(encoding="utf-8"))
        command = Path(f"/proc/{pid}/cmdline").read_bytes().split(b"\0")
    except (OSError, ValueError):
        return None
    return b"--no-texture" not in command


def _paint_worker_loading_mib(output_root: Path) -> int | None:
    """The memory a paint worker that is still loading has yet to take (its resident size less
    what it holds now), or None when no paint worker is loading."""
    if _hunyuan3d_worker(output_root) != "paint":
        return None
    from src.agents_wrapper.fem_workflow.runtime_files import worker_paths
    from src.hunyuan3d_wrapper.availability import settings as hunyuan3d_settings
    _, pid_path = worker_paths(output_root, "hunyuan3d", hunyuan3d_settings()[0])
    try:
        pid = int(pid_path.read_text(encoding="utf-8"))
        held = sum(a["used_mib"] for a in lib.query_apps() if lib.pgid(a["pid"]) == pid)
    except (OSError, ValueError, RuntimeError):
        return None
    return max(0, int(PAINT_WORKER_MIB - held))


def start_paint_ahead(session: Path, output_root: Path, compute_env: str, card: Any,
                      plan: dict[str, Any] | None) -> str | None:
    """Start the material card's paint in the background, when the plan paints and the geometry is
    final: the card is the regions card with a segmentation, or the values card.  Once per surface
    and answer; on the GPU this command was pinned to, which its step found idle, and only when
    the paint fits beside what is on it.  Returns a note for the stop, or None."""
    if not isinstance(card, dict) or not (
            card.get("kind") == "bc_values"
            or (card.get("kind") == "bc_input" and card.get("has_segmentation"))):
        return None
    answer = paint_ahead_answer(session, plan)
    if answer is None:
        return None
    key = _paint_ahead_key(session, answer)
    path = lib.operator_dir(session) / PAINT_AHEAD
    record = _paint_ahead_record(session)
    if record.get("key") == key:
        return None                 # this paint is under way, made, or failed (the card then paints)
    if paint_ahead_running(session) or (session / "materials" / "texture" / "textured.glb").exists():
        # A repaint (new words, or a new surface after one was painted): the checkpoints record the
        # earlier painting's files, and a rewind's restore could put them back under a paint in
        # progress.  The card paints for itself, as before.
        return None
    pinned = os.environ.get("CUDA_VISIBLE_DEVICES", "")
    if not pinned.isdigit():
        return None
    try:
        from src.agents_wrapper.fem_workflow.monitor import gpu_free_mib
        loaded = _paint_stage_loaded(output_root)
        free = gpu_free_mib()
        # A paint worker still loading (warmed from the geometry stop, warm_for_paint) has the
        # rest of its load to take as well as the paint's peak.
        loading = 0 if loaded else _paint_worker_loading_mib(output_root)
    except Exception:
        return None
    # A paint-stage worker needs room for the paint's peak only; none, or a shape-only one, for
    # the paint stage's load as well.
    needed = PAINT_AHEAD_WARM_MIB if loaded else (
        PAINT_AHEAD_WARM_MIB + loading if loading is not None else PAINT_AHEAD_COLD_MIB)
    if free is None or free < needed:
        return f"paint not started ahead: {free} MiB free on GPU {pinned}, {needed} needed; the material card paints"
    import subprocess
    lib.write_json(path, {"key": key, "state": "running", "pid": None, "started": time.time(),
                          "gpu_index": int(pinned), "answer": answer})
    log = (lib.operator_dir(session) / "paint_ahead.log").open("a", encoding="utf-8")
    try:
        process = subprocess.Popen(
            [sys.executable, "-u", os.fspath(Path(__file__).resolve().with_name("paint_ahead.py")),
             os.fspath(session), os.fspath(output_root), json.dumps(answer), pinned],
            stdout=log, stderr=log, start_new_session=True, cwd=os.fspath(session))
    finally:
        log.close()
    record = lib.read_json(path, {}) or {}
    if record.get("state") == "running":
        record["pid"] = process.pid
        lib.write_json(path, record)
    return f"painting the surface ahead of the material card, in the background on GPU {pinned}"


def join_paint_ahead(session: Path, timeout: float = PAINT_AHEAD_WAIT_S) -> float:
    """Wait for a background paint to end; the seconds waited (0.0 when none was running).

    One still running after ``timeout`` is stopped -- its process group and the paint worker it
    is waiting on, so the card's own paint does not run beside it -- and recorded failed (the next
    step's warning, paint_ahead_warning)."""
    started = time.time()
    while paint_ahead_running(session):
        if time.time() - started >= timeout:
            path = lib.operator_dir(session) / PAINT_AHEAD
            record = lib.read_json(path, {}) or {}
            pid = record.get("pid")
            if isinstance(pid, int):
                with contextlib.suppress(OSError):
                    os.killpg(pid, 15)
            try:
                from src.agents_wrapper.fem_workflow.workers import stop_hunyuan3d_worker
                stop_hunyuan3d_worker(Path(session).parent)
            except Exception:
                pass
            record.update(state="failed", error=f"still painting after {timeout:.0f} s: stopped")
            lib.write_json(path, record)
            break
        time.sleep(0.25)
    return round(time.time() - started, 1) if time.time() - started > 0.3 else 0.0


def release_for_solve(session: Path, compute_env: str) -> None:
    """Before a solve this runner starts itself (outside the graph's card, whose run_forward does
    the same in the monitor): the background paint ends first, then every model worker the solve
    does not use -- the paint worker it used included -- is stopped and waited out."""
    join_paint_ahead(session)
    from src.agents_wrapper.fem_workflow.monitor import ToolMonitor
    ToolMonitor(session, compute_env).release_models_for_solve()


def paint_ahead_conflicts(session: Path, kind: str | None, answer: Any) -> bool:
    """Whether a step must wait for a background paint: everything but the region preview, its
    revision and approval on the segmentation already made, and the values card.  Those load no
    model (the regions' resolve runs in the tools worker) and leave the surface as it is."""
    if kind == "bc_values":
        return False
    if kind != "bc_input" or not isinstance(answer, dict):
        return True
    action = answer.get("action")
    if action in ("approve_regions", "revise_regions", "revise_prompt"):
        return False
    if action != "preview_regions":
        return True
    workflow = lib.read_json(session / "session.json", {}) or {}
    return any(workflow.get(f"segmentation_{name}") != value
               for name, value in (answer.get("segmentation") or {}).items())


def prefetch_fields(session: Path, compute_env: str, scope: str) -> list[str]:
    """Colour the finished solve's surface fields, as the CLI and UI do after a solve."""
    if scope == "none":
        return []
    from src.agents_wrapper.fem_workflow.assets import (
        FIELD_COMPONENTS, load_step_surfaces, newest_surface_vtu, plan_solution_prefetch,
        prefetch_solution_assets, solution_prefetch_requests, surface_point_fields,
    )
    if scope == "all":
        requests = solution_prefetch_requests(session)
    else:
        steps = load_step_surfaces(session / "solve")
        last = steps[-1] if steps else newest_surface_vtu(session / "solve")
        if last is None:
            return []
        requests = plan_solution_prefetch(
            session, [last], surface_point_fields(str(last)), FIELD_COMPONENTS)
    prefetch_solution_assets(str(session), compute_env, requests)
    return [r["output"] for r in requests if Path(r["output"]).exists()]


# --------------------------------------------------------------- commands --

def cmd_gpu(args) -> None:
    output_root = Path(args.output_root).resolve()
    stopped = []
    if args.stop_workers:
        for pid, kind, pid_file in lib.worker_files(output_root):
            _stop_worker(pid, kind, pid_file)
            stopped.append(f"{kind} (pid {pid})")
        time.sleep(3)  # let them release their memory before the table is read
    verdicts = lib.gpu_table(output_root, count=3, interval=1.0,
                             max_foreign_mib=args.max_foreign_mib, max_util=args.max_util)
    chosen = lib.choose_gpu(verdicts)
    apps, gpus = lib.query_apps(), lib.query_gpus()
    workers = {kind: {"pid": pid, "gpus": lib.worker_gpu(pid, apps, gpus)}
               for pid, kind in lib.our_workers(output_root).items()}
    print(json.dumps({"ok": True, "stopped": stopped, "gpus": [v.as_dict() for v in verdicts],
                      "idle_choice": chosen.index if chosen else None,
                      "our_workers": workers,
                      "rule": f"idle = foreign memory < {args.max_foreign_mib:.0f} MiB and "
                              f"utilization < {args.max_util:.0f}% over 3 samples"}, indent=1))




def compute_environment(output_root: Path, name: str):
    """The workflow's ``require_compute_environment`` (it remembers a ready verdict for a day, for
    every output root and front end)."""
    from src.agents_wrapper import require_compute_environment
    return require_compute_environment(name)          # raises when not ready


def cmd_start(args) -> None:
    from src.agents_wrapper import ComputeEnvironmentError
    from src.agents_wrapper.fem_workflow import (
        DEFAULT_TEXT_MODELS, DEFAULT_VISION_MODELS, WorkflowState,
    )
    from src.agents_wrapper.fem_workflow.workers import ensure_tool_worker

    output_root = Path(args.output_root).resolve()
    try:
        gpu = select_gpu(args, output_root, False, [], args.compute_env)
    except NoIdleGPU as exc:
        gpu = {"index": None, "note": str(exc)}
    try:
        environment = compute_environment(output_root, args.compute_env)
    except ComputeEnvironmentError as exc:
        emit({"ok": False, "error": f"compute environment not ready: {exc}"})
        return
    # No API call here: the operator skill makes none of its own (2026-10-11).  The models are the
    # roles' defaults unless named; the workflow's own calls (its graph nodes) meet a bad key or model
    # at the first card that calls, and say so there.  A missing key is said now, for nothing.
    model = args.model or DEFAULT_TEXT_MODELS.get(args.provider)
    vision_provider = args.vision_provider or args.provider
    vision_model = args.vision_model or DEFAULT_VISION_MODELS.get(vision_provider)
    missing = sorted({f"{p.upper()}_API_KEY" for p in (args.provider, vision_provider)
                      if not os.environ.get(f"{p.upper()}_API_KEY")})
    if missing:
        emit({"ok": False, "error": f"no API key for the workflow's calls: {missing} unset "
                                    "(--provider/--vision-provider pick another)"})
        return
    session_id = args.session_id or uuid.uuid4().hex[:12]
    session = lib.session_dir(session_id, output_root)
    if session.exists():
        emit({"ok": False, "error": f"session already exists: {session_id}"})
        return
    state = WorkflowState(
        session_id=session_id, session_dir=str(session), provider=args.provider, model=model,
        vision_provider=vision_provider, vision_model=vision_model,
        compute_env=args.compute_env, octree_depth=args.octree_depth,
    )
    session.mkdir(parents=True)
    link = lib.DEFAULT_OUTPUT_ROOT / session_id
    if output_root != lib.DEFAULT_OUTPUT_ROOT.resolve() and not link.exists():
        link.parent.mkdir(parents=True, exist_ok=True)
        link.symlink_to(session, target_is_directory=True)     # the path the skill names
    with session_lock(session):
        try:
            ensure_tool_worker(output_root, args.compute_env, "light")
        except OSError:
            pass
        with open_graph(session) as graph:
            result = graph.invoke({"workflow": state.model_dump(mode="json")},
                                  config=_thread(session_id))
            event = event_from(graph, session_id, result, session)
        note = preload(output_root, session, args.compute_env, event["card"], args)
        # The user's instruction, stored for the checks (a size it states is "given").
        differs = start_instruction(session, args.instruction)
        note = "; ".join(n for n in (note, differs) if n) or None
        lib.append_jsonl(lib.operator_dir(session) / "driver_log.jsonl", {
            "time": time.time(), "command": "start", "provider": args.provider, "model": model,
            "vision_provider": vision_provider, "vision_model": vision_model,
            "compute_env": environment.name, "gpu": gpu.get("index")})
        print(f"session_id: {session_id}", file=sys.stderr, flush=True)
        reads = read_for("start", [])
        lib.write_json(_shown_path(session), {"notes": [], "read": [[e["file"], e.get("section")] for e in reads]})
        started = summarize(session_id, event, notes=[n for n in (note,) if n],
                            compute_environment=environment.summary, model=model,
                            vision_model=vision_model, read=reads)
        save_stop(session, "last_event.json", started)        # every field, the card's included
        emit(compact_start(started), session)


def start_instruction(session: Path, given: str | None) -> str | None:
    """The instruction at `start`.  A batch passes the user's instruction itself
    (FEM_OPERATOR_INSTRUCTION, the list line): that is stored, the agent's --instruction kept beside
    it, a difference said.  Outside a batch the argument is the instruction."""
    batch = os.environ.get("FEM_OPERATOR_INSTRUCTION")
    record = store_instruction(session, batch or given or "", given if batch else None)
    if record.get("instruction_given") is not None:
        return (f"--instruction {record['instruction_given']!r} differs from the user's instruction "
                f"{record['instruction']!r}: the checks read the user's")
    return None


def _load(args) -> tuple[Path, Path, str]:
    output_root = Path(args.output_root).resolve()
    session = lib.session_dir(args.session_id, output_root)
    if not (session / "checkpoints.sqlite").exists():
        raise SystemExit(json.dumps({"ok": False, "error": f"no such session: {session}"}))
    from src.agents_wrapper.fem_workflow.run_workflow import read_compute_env
    return output_root, session, read_compute_env(session)          # as the CLI's resume reads it


def cmd_show(args) -> None:
    output_root, session, compute_env = _load(args)
    with session_lock(session):
        with open_graph(session) as graph:
            state = pending(graph, args.session_id)
            event = {**state}
        hint = None
        if state["card"] is None and state["next"]:
            hint = ("a step without a card is pending (it failed or was interrupted); "
                    "`drive.py retry SID` runs it again")
        emit(summarize(args.session_id, event, hint=hint), session)


def _run_step(args, session: Path, output_root: Path, compute_env: str, head: str | None,
              kind: str | None, prepared: Prepared | None, send,
              show: bool = True) -> dict[str, Any]:
    """Run one graph step under the GPU guard, rolling back on failure.

    Returns the result it prints (``show``), so a runner can chain steps.
    """
    gpu_step = prepared.gpu if prepared else True
    workers = prepared.workers if prepared else ["tools", "triposg", "partfield", "solver"]
    # A background paint (start_paint_ahead) ends before any step that would load another model,
    # change the surface or read its colour; the material card's paint is then served from it.
    paint_wait = (join_paint_ahead(session) if prepared is None
                  or paint_ahead_conflicts(session, kind, prepared.answer) else 0.0)
    t_select = time.time()
    try:
        gpu = select_gpu(args, output_root, gpu_step, workers, compute_env,
                         prepared.need_mib if prepared else 0)
    except NoIdleGPU as exc:
        summary = {"ok": False, "session_id": args.session_id, "error": str(exc),
                   "gpus": [v.as_dict() for v in exc.verdicts],
                   "hint": "nothing was run; wait and retry, or ask the user before using "
                           "--gpu N or --allow-busy-gpu"}
        if show:
            emit(summary)
        return summary
    action = prepared.action if prepared else None
    lib.write_json(lib.operator_dir(session) / "current_step.json", {
        "pid": os.getpid(), "started": time.time(), "kind": kind, "action": action,
        "gpu": gpu.get("index"), "gpu_step": gpu_step})
    sampler = lib.GPUSampler(output_root, gpu.get("index")) if gpu_step and gpu.get("index") is not None else None
    if sampler:
        sampler.start()
    started = time.time()
    error = None
    if prepared and kind == "geometry_input":
        from src.agents_wrapper.fem_workflow.run_workflow import after_answer
        after_answer(output_root, compute_env, {"kind": kind}, prepared.answer)
    with open_graph(session) as graph:
        try:
            result = send(graph)
            event = event_from(graph, args.session_id, result, session)
        except Exception as exc:
            error = f"{type(exc).__name__}: {str(exc)[:1500]}"
            trace = traceback.format_exc()
            restored = None
            if head:
                try:
                    fork(graph, args.session_id, head)
                    restored = "card restored: answer it again"
                except Exception as fork_exc:
                    restored = f"could not restore the card: {fork_exc}"
            event = event_from(graph, args.session_id, None, session)
    t_end = time.time()
    gpu_report = sampler.finish() if sampler else None
    (lib.operator_dir(session) / "current_step.json").unlink(missing_ok=True)
    elapsed = round(t_end - started, 1)
    extra: dict[str, Any] = {
        "elapsed_s": elapsed,
        "notes": (prepared.notes if prepared else []) + gpu.get("moved", []),
        "warnings": list(prepared.warnings) if prepared else [],
        "gpu": {**(gpu_report or {}), "index": gpu.get("index"), "name": gpu.get("name"),
                "override": gpu.get("override")},
    }
    if paint_wait:
        extra["notes"].append(f"waited {paint_wait} s for the background paint to finish")
    paint_warning = paint_ahead_warning(session)
    if paint_warning:
        extra["warnings"].append(paint_warning)
    if gpu_report and gpu_report.get("foreign_appeared"):
        extra["warnings"].append("another job appeared on this GPU during the step; "
                                 "double-check the result (contention has corrupted runs)")
    if gpu_report and gpu_report.get("suspected_elsewhere"):
        extra["warnings"].append(
            f"the chosen GPU {gpu.get('index')} barely moved while GPU(s) "
            f"{gpu_report['suspected_elsewhere']} (MiB) grew: the step may have run on another "
            "card through a resident worker another front end started (the UI shares "
            f"workers on {lib.UI_OUTPUT_ROOT}). Run `drive.py gpu`, stop stray workers, rerun")
    card = event.get("card")
    if error is None and isinstance(card, dict) and card.get("solve_complete"):
        try:
            extra["field_assets"] = prefetch_fields(session, compute_env, args.prefetch)
        except Exception as exc:
            extra["warnings"].append(f"field export failed: {exc}")
    if error is None and isinstance(card, dict) and card.get("solve_error"):
        extra["warnings"].append("the solve failed: read solve_error / solve_log, "
                                 "fix the settings or the case, and answer again")
    if error is None and isinstance(card, dict) and card.get("api_error"):
        extra["warnings"].append(f"API call failed ({card.get('api_error_source')}): "
                                 f"{card.get('api_error')}; the card is unchanged, retry or rephrase")
    if error is None and isinstance(card, dict) and card.get("preview_error"):
        extra["warnings"].append(f"region preview failed: {card.get('preview_error')}")
    # Every card entered warms its workers, as the app does (controller._preload_for_interrupt):
    # the monitor waits for a worker still starting rather than loading a second copy, so even a
    # card answered at once gains.  Dropping this between chained cards (for a GPU check that
    # met the solver spare's CUDA start, 14.5 s; now sessionlib.classify) left PartField, the
    # paint and the solve to one-shot cold loads.
    note = preload(output_root, session, compute_env, card, args) if error is None else None
    if note:
        extra["notes"].append(note)
    lib.append_jsonl(lib.operator_dir(session) / "driver_log.jsonl", {
        "time": time.time(), "command": args.command, "kind": kind, "action": action,
        "answer": prepared.answer if prepared else None, "ok": error is None, "error": error,
        "elapsed_s": elapsed, "gpu": extra["gpu"], "next_kind": (card or {}).get("kind")
        if isinstance(card, dict) else None,
        # the card's own clock: GPU choice (and any wait) from t_select to t_start, the step to
        # t_end; what follows until "time" is the field export and the preload
        "t_select": round(t_select, 3), "t_start": round(started, 3), "t_end": round(t_end, 3),
        "select_s": gpu.get("select_s"), "gpu_samples": gpu.get("samples"),
        **({"paint_wait_s": paint_wait} if paint_wait else {})})
    if gpu_step and gpu.get("index") is not None:
        lib.append_jsonl(lib.operator_dir(session) / "gpu_log.jsonl", {
            "time": time.time(), "kind": kind, "action": action,
            "workers": workers, "ok": error is None, **extra["gpu"]})
    summary = summarize(args.session_id, event, **extra)
    if error is not None:
        summary.update({"ok": False, "error": error, "restored": restored,
                        "traceback_tail": trace.splitlines()[-6:]})
        note_no_surface(session, kind, prepared.answer if prepared else None, error)
    if show:
        emit(summary, session)
    elif summary.get("card") is not None:
        save_stop(session, "last_event.json", summary)
    return summary


def cmd_answer(args) -> None:
    output_root, session, compute_env = _load(args)
    if args.file:
        raw = Path(args.file).read_text(encoding="utf-8")
    else:
        raw = args.json
    try:
        answer = json.loads(raw)
    except json.JSONDecodeError as exc:
        emit({"ok": False, "error": f"answer is not valid JSON: {exc}"})
        return
    if isinstance(answer, dict) and "inputs/web/" in str(answer.get("asset_path") or "").replace("\\", "/"):
        # As in check_plan: a web photograph comes only from a pick in `run`, counted and credited.
        emit({"ok": False, "session_id": args.session_id, "error": (
            "asset_path cannot name a web photograph: it is used only through plan.geometry.web_image "
            '{"query": ..., "pick": "<id>"} in `run`, which counts and credits it; nothing was sent')})
        return
    with session_lock(session):
        with open_graph(session) as graph:
            state = pending(graph, args.session_id)
        card = state["card"]
        if card is None:
            emit({"ok": False, "session_id": args.session_id, "error": (
                "no card is waiting" + (f"; pending step {state['next']}: use `retry`"
                                        if state["next"] else "; the session is complete"))})
            return
        # Linted as the workflow will read it -- merged over the card, as the
        # workflow does for every field an answer leaves out -- even when the
        # answer is sent as given.
        prepared = prepare_answer(card, state["workflow"], answer,
                                  merge=True, force=args.force)
        if args.no_merge:
            prepared.answer = answer
            prepared.notes = ["sent as given (--no-merge): the workflow keeps the card's value "
                              "for every field the answer leaves out"]
        if args.no_lint and prepared.errors:
            prepared.warnings.extend(f"lint (ignored): {e}" for e in prepared.errors)
            prepared.errors = []
        if prepared.errors or args.dry_run:
            emit({"ok": not prepared.errors, "dry_run": args.dry_run,
                  "session_id": args.session_id, "kind": card.get("kind"),
                  "answer": prepared.answer, "errors": prepared.errors,
                  "notes": prepared.notes, "warnings": prepared.warnings,
                  "gpu_step": prepared.gpu, "workers": prepared.workers,
                  "hint": "nothing was sent" if prepared.errors else "dry run: nothing was sent"})
            return
        # The same limits as `run`: an attempt sent by hand is still an attempt.
        stage = attempt_stage(card.get("kind"), prepared.answer, card)
        try:            # the plan the hand-sent answer is taken under, for the body it leaves
            current = load_plan(lib.operator_dir(session) / "plan.json", session)
        except (PlanError, OSError, ValueError):
            current = None
        order = route_order_problem(session, card.get("kind"), prepared.answer, plan=current) or (
            built_body_problem(session, {**(current or {}), "geometry": prepared.answer})
            if card.get("kind") == "geometry_input" and isinstance(prepared.answer, dict) else None) or (
            body_lock_problem(session, prepared.answer) if card.get("kind") == "bc_input" else None)
        if order:
            emit({"ok": False, "session_id": args.session_id, "kind": card.get("kind"), "error": order,
                  "hint": "nothing was sent"})
            return
        if stage:
            charged = charge_attempt(session, stage, prepared.answer)
            if charged["over"]:
                emit({"ok": False, "session_id": args.session_id, "stop": "limit",
                      "kind": card.get("kind"), "error": limit_message(stage, charged["counts"], declared_routes(session)),
                      "hint": "nothing was sent"})
                return
            if not charged["counted"]:
                prepared.notes.append(f"the same {stage} as an earlier attempt: served from the "
                                      "cache and not counted")
        from src.agents_wrapper.fem_workflow.graph import resume_command

        def send(graph):
            return graph.invoke(resume_command(graph, _thread(args.session_id), prepared.answer),
                                config=_thread(args.session_id))

        result = _run_step(args, session, output_root, compute_env, state["checkpoint_id"],
                           card.get("kind"), prepared, send)
        if result.get("ok"):
            note_revision(session, card.get("kind"), prepared.answer, result.get("card"))
            record_route(session, card.get("kind"), prepared.answer, plan=current)
        elif stage and charged["counted"] and not_run(result):
            refund_attempt(session, stage, prepared.answer)


def cmd_retry(args) -> None:
    """Run a pending step that has no card (one that failed or was interrupted)."""
    output_root, session, compute_env = _load(args)
    with session_lock(session):
        with open_graph(session) as graph:
            state = pending(graph, args.session_id)
        if state["card"] is not None:
            emit({"ok": False, "error": "a card is waiting; answer it instead",
                  "kind": state["card"].get("kind")})
            return

        def send(graph):
            return graph.invoke(None, config=_thread(args.session_id))

        _run_step(args, session, output_root, compute_env, None, None, None, send)


def two_depths_problem(session: Path) -> str | None:
    """``--two-depths`` only once a solve of the session has failed.

    A solve is cheap next to the rest of a run, but a routine second solve at another depth was
    not: run as a second command it cost 0.8-1.8 min per run, re-solving the plan depth and
    rebuilding the whole solve stop (four of five runs).  One solve at the
    plan's depth is the result; two depths are the check for a solve that failed."""
    if (lib.operator_dir(session) / "solve_failed.json").exists():
        return None
    import inspect_session as _inspect_mod
    if any(not _inspect_mod.run_succeeded(run) for run in lib.solve_runs(session)):
        return None
    return ("--two-depths only after a solve of this session failed (a solve_error): one solve at the "
            "plan's depth is the result. Nothing was run; run again without --two-depths")


def cmd_solve_backend(args) -> None:
    """Re-run the session's case with another linear-solver backend, outside the graph.

    For a genuinely ill-conditioned system -- members only a few leaves thick --
    where AMG reaches ||b - Kx||/||b|| of about 1e-2 and JAX-AMG therefore raises
    (known_issues.md #1).  pyamgx keeps its best iterate whatever AMGX reports,
    so the run is inexact Newton and Newton's residual check is what validates
    it; cross-check with ``native``.  The workflow's own run_forward runs the
    session's case/case.json with ``cg_backend_assembled`` swapped, in a run
    folder under the session's solve/.  The graph is not told: its settings card
    still shows the failed solve.
    """
    import subprocess

    output_root, session, compute_env = _load(args)
    import inspect_session as _inspect_mod
    if getattr(args, "two_depths", False) and two_depths_problem(session):
        emit({"ok": False, "session_id": args.session_id, "stop": "error", "error": two_depths_problem(session)})
        return
    converged = lib.read_json(lib.operator_dir(session) / "converged.json", {}) or {}
    cross_check = (args.backend == "native" and converged.get("case") == _inspect_mod.case_digest(session))
    # A fallback solve is a solve: it spends the same limit as the graph's, so a session cannot
    # run nine backends after three failed solves.  The cross-check of a converged result is not
    # an attempt: it cannot turn a sound run into no run.
    charged = ({"counted": False, "over": False, "counts": {}} if cross_check else
               charge_attempt(session, "solve", {"solve_backend": args.backend, "max_iters": args.max_iters}))
    if charged["over"]:
        emit({"ok": False, "session_id": args.session_id, "stop": "limit",
              "error": limit_message("solve", charged["counts"]) + " (solve-backend counts)"})
        return
    case_path = session / "case" / "case.json"
    case = lib.read_json(case_path)
    if not case:
        emit({"ok": False, "error": "no case/case.json yet: answer the settings card once first"})
        return
    snapshot_brief_at_solve(lib.operator_dir(session))
    solve_root = Path(case.get("output", ""))
    if session.resolve() not in solve_root.resolve().parents:
        emit({"ok": False, "error": (f"case.json writes to {solve_root}, outside this session "
                                     "(a copied session's case): answer the settings card here "
                                     "once so the case is rebuilt in this folder")})
        return
    from inspect_session import compute_interpreter
    interpreter = compute_interpreter(compute_env)
    if interpreter is None:
        emit({"ok": False, "error": f"no {compute_env} interpreter found"})
        return
    with session_lock(session):
        try:
            gpu = select_gpu(args, output_root, True, ["solver"], compute_env)
        except NoIdleGPU as exc:
            emit({"ok": False, "error": str(exc), "gpus": [v.as_dict() for v in exc.verdicts],
                  "hint": "nothing was run"})
            return
        # Only once the solve will run (nothing is stopped when no GPU is free).  The workers are
        # this output root's: a batch gives each concurrent slot a root of its own.
        release_for_solve(session, compute_env)
        sampler = lib.GPUSampler(output_root, gpu.get("index")) if gpu.get("index") is not None else None
        if sampler:
            sampler.start()
        cache = output_root / ".runtime_cache"
        (cache / "matplotlib").mkdir(parents=True, exist_ok=True)
        from src.agents_wrapper.fem_workflow.workers import kernel_cache_env
        environment = {**os.environ, **kernel_cache_env(), "XLA_PYTHON_CLIENT_PREALLOCATE": "false",
                       "MPLCONFIGDIR": str(cache / "matplotlib"), "XDG_CACHE_HOME": str(cache)}
        def backend_run(path: Path) -> tuple[int, str]:
            try:
                result = subprocess.run(
                    [interpreter, "-u", str(Path(__file__).resolve().parent / "backend_solve.py"),
                     str(path), args.backend,
                     *(["--jaxamg-max-iters", str(args.max_iters)] if args.max_iters else [])],
                    capture_output=True, text=True, timeout=7200, env=environment, cwd=session)
                return result.returncode, (result.stdout or "") + (result.stderr or "")
            except subprocess.TimeoutExpired as exc:
                return -1, f"timed out after {exc.timeout} s"

        coarse_note = None
        if getattr(args, "two_depths", False) and not cross_check:
            # The same case one depth coarser, the same backend: its run pairs with the next one
            # in checks.depths (the case digest and every logged setting but the depth match).
            coarse_case = dict(case, shape_opt={**case.get("shape_opt", {}), "remesh_octree_depth": int(
                (case.get("shape_opt") or {}).get("remesh_octree_depth", 7)) - 1})
            coarse_path = session / "case" / "case_coarse.json"
            lib.write_json(coarse_path, coarse_case)
            before = time.time()
            code, text = backend_run(coarse_path)
            coarse_runs = [r for r in lib.solve_runs(session) if (r / "log.txt").stat().st_mtime >= before]
            if coarse_runs:
                import inspect_session as _cases
                _cases.record_run_case(session, coarse_runs[-1])
            coarse_note = (f"the coarser solve ({coarse_runs[-1].name if coarse_runs else 'no run'}, not "
                           f"counted): {'finished' if code == 0 else text.strip().splitlines()[-1:] }")
        started = time.time()
        lib.write_json(lib.operator_dir(session) / "current_step.json", {
            "pid": os.getpid(), "started": started, "kind": "solve-backend",
            "action": args.backend, "gpu": gpu.get("index"), "gpu_step": True})
        returncode, output = backend_run(case_path)
        gpu_report = sampler.finish() if sampler else {}
        (lib.operator_dir(session) / "current_step.json").unlink(missing_ok=True)
        log_file = lib.operator_dir(session) / f"backend_{args.backend}_{int(started)}.log"
        log_file.write_text(output, encoding="utf-8")
        runs = [r for r in lib.solve_runs(session) if (r / "log.txt").stat().st_mtime >= started]
        run = runs[-1] if runs else None
        info = lib.parse_solve_log(run / "log.txt") if run else {}
        ok = returncode == 0 and bool(info.get("finalized"))
        extra: dict[str, Any] = {}
        if ok:
            try:
                extra["field_assets"] = prefetch_fields(session, compute_env, args.prefetch)
            except Exception as exc:
                extra["field_export_error"] = str(exc)
            # The same evidence the runner's solve stop gives: the pictures, the
            # checks and the report, so two backends can be compared by their
            # peak displacement and stress without any further command.
            import inspect_session
            rendered = _inspect(session, output_root, "render", args.session_id, "--what", "all")
            # Each backend's pictures under their own names: a later cross-check's render does not
            # overwrite the pictures this result was shown with.
            images, failed = fresh_images(rendered)
            kept = []
            for image in images:
                src = Path(image) if Path(image).is_absolute() else lib.REPO_ROOT / image
                dst = src.with_name(f"{src.stem}_{args.backend}{src.suffix}")
                try:
                    shutil.copyfile(src, dst)
                    kept.append(str(dst))
                except OSError:
                    kept.append(str(src))
            extra["look_at"] = kept
            if failed:
                extra["render_error"] = failed
            summary = inspect_session.summarize(session)
            extra["report"] = str(inspect_session.write_report(session, summary))
            solve = summary.get("solve") or {}
            extra["checks"] = solve.get("checks")
            extra["region_displacement"] = solve.get("region_displacement")
            extra.update(body_and_loads(session, summary))
            extra["material"] = summary.get("material")
            extra["brief"] = brief_status(lib.operator_dir(session))
            declared = lib.read_json(lib.operator_dir(session) / "declared.json", {}) or {}
            extra["relative_to_supports"] = relative_displacement(session, declared)
            extra["prediction_check"] = prediction_check(session, solve, declared.get("prediction"),
                                                         extra["relative_to_supports"])
            history = record_prediction(session, summary, declared, extra["prediction_check"])
            extra["prediction_check"] = {**(extra["prediction_check"] or {}), "agreement": agreement(history)}
            newton = lib.newton_summary(info.get("newton") or [])
            lib.write_json(lib.operator_dir(session) / "converged.json",
                           {**converged, "confirmed_by": args.backend} if cross_check else
                           {"backend": args.backend, "run": run.name if run else None,
                            "case": _inspect_mod.case_digest(session), "final_rel": newton.get("final_rel")})
            add_history_to_report(Path(extra["report"]), history,
                                  contacts_table(session, held_regions(session, None, declared.get("contacts")),
                                                 declared.get("contacts")),
                                  {**brief_status(lib.operator_dir(session)), "solver_note": solver_note(session),
                                   "thin_gaps": lib.read_json(lib.operator_dir(session) / "thin_gaps.json"),
                                   "web_image": web_image_credit(session),
                                   "web_search": web_search_line(session),
                                   "per_part": (per_part_said(session) if (declared.get("material") or {}).get("mode")
                                                == "parts" else None),
                                   **thin_declaration(session, declared, summary)})
            save_stop(session, "stop_solve.json", {"solve": solve, "body": extra.get("body"), "loads": extra.get("loads")})
            extra["warnings"] = summary.get("warnings")
            far = far_off_case_note(extra["prediction_check"].get("agreement"))
            if far:
                extra["warnings"] = [far] + list(extra["warnings"] or [])
        value = {
            "ok": ok, "session_id": args.session_id, "backend": args.backend,
            "cross_check": cross_check,
            "run": run.name if run else None, "returncode": returncode,
            "newton": lib.newton_summary(info.get("newton") or []),
            "elapsed_s": round(time.time() - started, 1),
            "gpu": {**gpu_report, "index": gpu.get("index"), "override": gpu.get("override")},
            "log": str(log_file),
            **({"two_depths": coarse_note} if coarse_note else {}),
            "note": ("out-of-graph solve: the workflow's settings card and state are unchanged; "
                     "judge it with inspect_session.py, which reads the newest run"),
            **extra,
        }
        if not ok:
            value["error"] = (info.get("failures") or [output.strip().splitlines()[-1:]])[-1]
            if cross_check:
                value["result_stands"] = (
                    f"the converged {converged.get('backend')} solve ({converged.get('run')}) is the "
                    f"result; {args.backend} did not converge on this case (its error above): say so "
                    "in the judgement as a caveat, and close the session with finish")
        lib.append_jsonl(lib.operator_dir(session) / "driver_log.jsonl", {
            "time": time.time(), "command": "solve-backend", "backend": args.backend,
            "ok": ok, "run": value["run"], "gpu": value["gpu"]})
        lib.append_jsonl(lib.operator_dir(session) / "gpu_log.jsonl", {
            "time": time.time(), "kind": "solve-backend", "action": args.backend,
            "workers": [], "ok": ok, **value["gpu"]})
        print(json.dumps(lib.relative_paths(value), indent=1, default=str))


# ------------------------------------------------------------------- run --

# How many times the runner lets a plan try each retried stage of a session.
# Past these, a case is not going to work by another attempt of the same kind
