RUN_LIMITS = {"generation": 2, "drawing": 3, "hunyuan": 2, "cad": 3, "web_image": 2, "upload": 3, "regions": 4,
              "revisions": 4, "segmentation": 3, "materials": 3, "solve": 5, "cad_revisions": 2, "repaints": 2}
