class PlanError(ValueError):
    pass


# Stages whose step is served from the tool cache when sent again unchanged:
# the same answer gives the same body, so a resend is not another attempt.
CACHED_STAGES = ("generation", "cad", "upload", "drawing", "hunyuan")


def attempt_stage(kind: str | None, answer: Any, card: dict[str, Any] | None = None) -> str | None:
    """The limited stage an answer to this card spends, whichever command sends it.  ``card``: the
    card it answers, which tells a repaint (a painting already on it) from the first paint."""
    if not isinstance(answer, dict):
        return None
    action = answer.get("action")
    if action == "texture_surface" and kind in ("material_input", "geometry_texture"):
        return (REPAINTS if (card or {}).get("textured_surface") and not answer.get("per_part_colours")
                else None)
    if kind == "geometry_input":
        if action == "draw_image":
            return "drawing"
        if answer.get("generator") == "hunyuan3d" and not answer.get("revise_prompt"):
            return "hunyuan"     # an image (a drawing or the user's) given to Hunyuan3D
        if answer.get("revise_prompt") or answer.get("use_drawn_image") \
                or WEB_DIR in str(answer.get("asset_path") or "").replace("\\", "/") \
                or DRAW_DIR in str(answer.get("asset_path") or ""):
            return None          # a revision is free; a drawing or a web search was counted when made
        if answer.get("asset_kind") == "surface":
            return "upload"
        return "cad" if answer.get("generator") in CAD_GENERATORS else "generation"
    if kind == "bc_input":
        return {"preview_regions": "regions", "revise_regions": "revisions"}.get(action)
    # (a preview whose only change is the segmentation is counted as "segmentation" by the
    # runner, which knows the words were unchanged)
    if kind == "material_input":
        return "materials" if action == "infer_parts" else None
    if kind == "shape_opt_settings":
        return None if action == "finish" else "solve"
    return None


def _attempt_digest(stage: str, answer: dict[str, Any]) -> str:
    """What makes two attempts the same: the answer, and an uploaded file's bytes."""
    import hashlib
    payload = dict(answer)
    path = payload.get("asset_path")
    if path and Path(str(path)).is_file():
        payload["asset_sha256"] = hashlib.sha256(Path(str(path)).read_bytes()).hexdigest()
    return stage + ":" + hashlib.sha256(_normalized(payload).encode("utf-8")).hexdigest()[:16]


def attempt_identity(stage: str | None, answer: dict[str, Any], plan: dict[str, Any]) -> dict[str, Any]:
    """What makes an attempt itself: the answer, and for a body made from a drawing the drawing's
    words and seed, which the answer sent ('use the drawn image') does not carry."""
    geometry = plan.get("geometry") or {}
    if stage == "hunyuan" and geometry.get("draw"):
        return {**answer, "drawing": [str(geometry.get("description") or "").strip(), geometry.get("image_seed", 0)]}
    return answer


def charge_attempt(session: Path, stage: str, answer: dict[str, Any]) -> dict[str, Any]:
    """Count one attempt of ``stage`` in the session, for ``run``, ``answer`` and
    ``solve-backend`` alike.

    Returns ``counted`` (False for an unchanged resend of a cached stage, which
    returns the same result for free), ``over`` (past the stage's limit: do not
    send), and the session's ``counts``.
    """
    op = lib.operator_dir(session)
    counts = lib.read_json(op / "run_counts.json", {}) or {}
    seen = lib.read_json(op / "attempt_digests.json", []) or []
    digest = _attempt_digest(stage, answer)
    if stage in CACHED_STAGES and digest in seen:
        return {"counted": False, "over": False, "counts": counts}
    counts[stage] = counts.get(stage, 0) + 1
    lib.write_json(op / "run_counts.json", counts)
    if stage in CACHED_STAGES:
        lib.write_json(op / "attempt_digests.json", seen + [digest])
    return {"counted": True, "over": counts[stage] > RUN_LIMITS[stage], "counts": counts}


def refund_attempt(session: Path, stage: str, answer: dict[str, Any]) -> None:
    """Take back an attempt that was never run (no idle GPU came free)."""
    op = lib.operator_dir(session)
    counts = lib.read_json(op / "run_counts.json", {}) or {}
    counts[stage] = max(counts.get(stage, 0) - 1, 0)
    lib.write_json(op / "run_counts.json", counts)
    seen = lib.read_json(op / "attempt_digests.json", []) or []
    digest = _attempt_digest(stage, answer)
    if digest in seen:
        seen.remove(digest)
        lib.write_json(op / "attempt_digests.json", seen)


def not_run(result: dict[str, Any]) -> bool:
    """True for a step the GPU guard refused before anything ran."""
    return not result.get("ok") and "gpus" in result and "card" not in result


# The routes to a body, generated first.  The brief narrows them to the ones that can make this
# body and are enough for it (plan.geometry_routes); the runner takes the generated ones in this
# order and never one the plan left out.  `built` is the fallback after GENERATED_BUDGET generated
# bodies, or every listed generated route, and first only by ``built_first_ok``: 7 of 10 runs' bodies were
# blank builds chosen up front because the skill said generators "do not control member
# thicknesses", and the figures lost the objects' look.  The ladder this replaced made every run spend
# each route to its limit before a simplified body: 1363 s of five runs' 4836 s went
# to routes that could not have made the object.
# A licensed web photograph is the last route before `built` (the user's rule, 2026-10-11; removed
# that morning in 4437c57, restored that evening): `built` is refused until it was tried, unless it
# found no usable photograph (web_image_done).  Its body has its own budget (WEB_BODIES), outside
# GENERATED_BUDGET.
GEOMETRY_ROUTES = ("triposg_text", "drawing", "hunyuan3d", "cadcoder", "web_image", "built")
BUILT_FIRST = re.compile(r"^\W*why not generated\W*:\s*(\S.{9,})$", re.I | re.M)
# The generated bodies a session tries before `built` needs no argument: four runs spent
# 4-7 failed generated attempts before building (about half of their added cost).
GENERATED_BUDGET = 2
THIN_WALL_OF_EXTENT = 0.02   # ... or one whose real thinnest member is under 1/50 of the largest extent: a thin sheet,
# closed shell or open lattice, which the generators fill solid (a controlled comparison of 2026-10-11)
FREE_FORM_ROUTES = ("triposg_text", "drawing", "hunyuan3d", "web_image")
ROUTE_STAGE = {"built": "upload", "cadcoder": "cad", "triposg_text": "generation", "drawing": "drawing",
               "hunyuan3d": "hunyuan", "web_image": "web_image"}
WEB_BODIES = 1                 # bodies generated from a web photograph (its refinements are no new body)
STAGE_ROUTE = {stage: route for route, stage in ROUTE_STAGE.items()}
# The free-form steps.  An attempt once left behind is not re-run unchanged (its body, cached or
# not, was already judged not the object); an untried step, or a changed attempt within its limit,
# may follow a later step that fell short (until 2026-10-11 any return was refused, against
# routes.md's "add the next route that could make the body").
ROUTE_ORDER = ("generation", "drawing", "hunyuan", "web_image")
ROUTE_SENT = "route_answers.json"      # each free-form attempt sent, by its identity ("draw|" a drawing alone)
DRAW_DIR = "/inputs/sdxl/"     # the drawings, and the largest object cut out of one (drawing_crop)
WEB_DIR = "/inputs/web/"       # where the runner keeps the photographs it found, per query


def declared_routes(session: Path) -> list[str] | None:
    """plan.geometry_routes as the newest run recorded it (None before one declared it)."""
    routes = lib.read_json(lib.operator_dir(session) / "geometry_routes.json")
    return list(routes) if isinstance(routes, list) else None


def route_tried(session: Path, route: str, counts: dict[str, Any] | None = None) -> bool:
    """Whether a route has had an attempt (a photograph search that showed nothing usable counts)."""
    counts = counts if counts is not None else (lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {})
    if route == "web_image" and web_image_done(session):
        return True
    return counts.get(ROUTE_STAGE[route], 0) > 0


GENERATED_ROUTES = ("triposg_text", "drawing", "hunyuan3d", "cadcoder")    # a body generated from words


def routes_problem(routes: Any, session: Path | None = None, generated: bool = True) -> str | None:
    """plan.geometry_routes: a list of known routes (the order is the runner's, ``canonical_routes``),
    with a generated route among them unless the brief argues a built body first (``built_first_ok``):
    the web photograph is no generated attempt, and a list of it and `built` alone reached a built
    body with no generated one (review of 2026-10-11).  ``generated`` False: the user gave the file."""
    if not isinstance(routes, list) or not routes or not all(isinstance(r, str) for r in routes):
        return ("plan.geometry_routes is the list of routes the brief judged able to make this body, from "
                f"{list(GEOMETRY_ROUTES)}")
    unknown = [r for r in routes if r not in GEOMETRY_ROUTES]
    if unknown:
        return f"plan.geometry_routes: {unknown} are not routes; the routes are {list(GEOMETRY_ROUTES)}"
    if (generated and not any(r in GENERATED_ROUTES for r in routes)
            and not (session is not None and built_first_ok(session))):
        return (f"plan.geometry_routes lists no generated route ({list(GENERATED_ROUTES)}): a generated body "
                "comes first, a built one first only with the brief's 'Why not generated:' line for a real "
                f"thinnest member under {THIN_WALL_OF_EXTENT:.0%} of the largest Real extent or a load path of "
                "one member with a Real section shape (objectives/routes.md §3.4)")
    return None


def canonical_routes(routes: list[str], session: Path | None = None) -> list[str]:
    """The listed routes in the runner's order, never refused for theirs: each once, the generated
    ones first in GEOMETRY_ROUTES order, then the web photograph, `built` last, or the photograph
    and `built` first when ``built_first_ok``, wherever the list put `built` (until 2026-10-12 only
    a list starting with it: one that argued built first and listed it last was sorted generated
    first, and the photograph the brief let it take was then refused as out of turn)."""
    out = sorted(dict.fromkeys(r for r in routes if r in GEOMETRY_ROUTES), key=GEOMETRY_ROUTES.index)
    if "drawing" in out and "triposg_text" not in out:
        # one TripoSG text attempt comes before the drawing: about 4 s and no drawing step, it gave a
        # recognisable body on 3 of 7 objects in a comparison of 2026-10-11, and was almost never tried
        out = ["triposg_text"] + out
    if "built" in out and "web_image" not in out:
        out.insert(out.index("built"), "web_image")       # a web photograph before any hand-built body
    if "built" in out and session is not None and built_first_ok(session):
        out = ["web_image", "built"] + [r for r in out if r not in ("web_image", "built")]
    return out


def built_first_ok(session: Path) -> bool:
    """Whether the brief argues a built body first: its 'Why not generated:' line, and either a
    real thinnest member under THIN_WALL_OF_EXTENT of the largest Real extent (a size a generated
    surface cannot reach), or a load path of one prismatic member, its Real section a shape (one
    section along the member).  Checked on the brief's own Real lines, not on the line's words; "at
    most 4 members" admitted most simple bodies (review of 2026-10-11)."""
    operator = lib.operator_dir(session)
    try:
        text = (operator / "brief.md").read_text(encoding="utf-8")
    except OSError:
        return False
    if not BUILT_FIRST.search(text):
        return False
    members, thin, extents = brief_members(operator) or {}, real_member(operator), real_extents(operator)
    section = real_section(operator) or {}
    return (bool(thin and extents and thin < THIN_WALL_OF_EXTENT * max(extents))
            or (len(members) == 1 and bool(section.get("shape"))))


def generated_bodies(session: Path) -> int:
    """The generated bodies the session sent: free-form bodies (ROUTE_SENT, drawings alone, an
    image's finer extractions, Hunyuan3D's rung on an image with a body, and the web photograph's
    body left out) and CAD generations."""
    sent = lib.read_json(lib.operator_dir(session) / ROUTE_SENT, []) or []
    counts = lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {}
    return sum(not str(k).startswith(("draw|", "refine|", "rung|", "web|")) for k in sent) + int(counts.get("cad", 0) or 0)


def web_photo_problem(session: Path) -> str | None:
    """A built body before a web photograph was tried: after the generated budget and with the
    brief's 'Why not generated:' line alike, unless the search found no usable photograph or
    reached no source, or every photograph shown was turned down (web_image_done).  `blank` runs
    that one search itself (``blank_web_search``) rather than refusing and waiting for a run."""
    if web_image_done(session) or web_body_made(session):
        return None
    return ("a built body comes after a web photograph was tried: `blank` runs the one search itself (the "
            "words of plan.geometry.web_image {\"query\": ...}, else the description's first clause); the "
            "photographs it shows are picked or turned down in plan.geometry.web_image (objectives/routes.md §3.4)")


def built_body_problem(session: Path, plan: dict[str, Any]) -> str | None:
    """A built body (`blank`) about to be sent before a web photograph was tried
    (``web_photo_problem``), or before GENERATED_BUDGET generated bodies and before every listed
    generated route was tried, without the brief's argument (``built_first_ok``)."""
    if geometry_provenance(plan.get("geometry")) != "built":
        return None
    web = web_photo_problem(session)
    if web:
        return web
    if generated_bodies(session) >= GENERATED_BUDGET:
        return None
    routes = declared_routes(session) or list(plan.get("geometry_routes") or [])
    counts = lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {}
    # the photograph is no generated route: counted here, it let a list of `built` alone (which
    # canonical_routes makes ["web_image", "built"]) reach a built body with no generated attempt
    ready = [r for r in routes if r in GENERATED_ROUTES and (r != "hunyuan3d" or hunyuan_ready())]
    untried = [r for r in ready if not route_tried(session, r, counts)]
    if (ready and not untried) or built_first_ok(session):
        return None
    return (f"a built body comes after {GENERATED_BUDGET} generated bodies ({generated_bodies(session)} so far; "
            + (f"{untried} untried" if ready else "no ready generated route listed") + "), or first with the brief's "
            f"'Why not generated:' line for a real thinnest member under {THIN_WALL_OF_EXTENT:.0%} of the largest "
            "Real extent or a load path of one member with a Real section shape (objectives/routes.md §3.4)")


def hunyuan_ready() -> bool:
    try:
        from src.hunyuan3d_wrapper.availability import hunyuan3d_status
        return bool(hunyuan3d_status().ready)
    except Exception:
        return False


def route_step(kind: str | None, answer: Any, generator: str | None = None) -> str | None:
    """Which step of the free-form route a geometry answer takes, cached or not.  ``generator`` is
    the plan's: the drawing Hunyuan3D is given (drawn again, or served from the cache) is part of
    the Hunyuan3D step."""
    if kind != "geometry_input" or not isinstance(answer, dict) or answer.get("revise_prompt"):
        return None
    if answer.get("action") == "draw_image":
        return "hunyuan" if generator == "hunyuan3d" else "drawing"
    if answer.get("generator") == "hunyuan3d":
        return "hunyuan"
    if WEB_DIR in str(answer.get("asset_path") or "").replace("\\", "/"):
        return "web_image"             # a picked photograph, cut out, for TripoSG
    if DRAW_DIR in str(answer.get("asset_path") or ""):
        return "drawing"               # a drawing's largest object (drawing_crop) for TripoSG
    if answer.get("asset_kind") == "surface" or answer.get("generator") in CAD_GENERATORS:
        return None
    return "drawing" if answer.get("use_drawn_image") else "generation"


# A thin member is a warning, never a refusal (2026-10-11): 145 of 190 bodies run before
# were `blank` builds, because a rule that refused every generated body with a real member under
# 4.2 leaves at depth 8 fired for almost every object and its stand-ins were crude.  A body with a
# member under RESOLVED_LEAVES is accepted with its numbers said; the agent keeps it, deepens, or
# builds a thicker stand-in by choice, and the report carries the numbers as a resolution caveat.
THIN_WAYS = ("the body stands, and the report carries the thin member as a resolution caveat; or, by choice, "
             "depth 8 (\"settings\": {\"remesh_octree_depth\": 8}), which halves the leaf: a member under 1 leaf at "
             "depth 7 stays under 2 there, still a caveat")


def body_digest(session: Path) -> str | None:
    """The body at hand by its content: a rewind or a restored copy of a body is the same body."""
    import hashlib
    source = body_source(session)
    try:
        return hashlib.sha256(source.read_bytes()).hexdigest()[:16] if source is not None else None
    except OSError:
        return None


def generated_body(session: Path) -> bool:
    """Whether the body at hand is a free-form generation (a built or uploaded surface, or a CAD
    part, is not)."""
    state = lib.read_json(session / "session.json", {}) or {}
    generator = (state.get("generation") or {}).get("generator")
    return (body_source(session) is not None and state.get("geometry_mode") != "surface"
            and generator not in CAD_GENERATORS)


def route_order_problem(session: Path, kind: str | None, answer: Any,
                        generator: str | None = None, plan: dict[str, Any] | None = None) -> str | None:
    """A free-form step the brief's routes leave out, or taken before the routes listed ahead of
    it were tried, or an earlier attempt re-run unchanged after the session moved past it, is
    refused; any other step is recorded (ROUTE_SENT).  Thin members refuse no step (THIN_WAYS)."""
    step = route_step(kind, answer, generator)
    if (step is None and kind == "geometry_input" and isinstance(answer, dict)
            and answer.get("generator") in CAD_GENERATORS and generated_bodies(session) >= GENERATED_BUDGET
            and (answer.get("revise_prompt") or _attempt_digest("cad", answer) not in (
                lib.read_json(lib.operator_dir(session) / "attempt_digests.json", []) or []))):
        # a CAD body counts in the same budget (it was outside it until 2026-10-11); a prompt revision
        # for one past the budget is refused at once, not after it was spent
        note_route_refused(session, "cadcoder", "the generated budget was spent")
        return budget_spent(session)
    if step is None:
        return None
    counts = lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {}
    routes = declared_routes(session)
    route = STAGE_ROUTE[step]
    if routes is not None and route not in routes:
        return (f"{route} is not among plan.geometry_routes {routes}: add it (any untried route may be added, "
                "with the brief's reason) or build the body (objectives/routes.md §3.4)")
    if routes is not None and not (step == "web_image" and generated_bodies(session) >= GENERATED_BUDGET):
        refused = routes_refused(session)
        untried = [r for r in routes[:routes.index(route)]
                   if r in FREE_FORM_ROUTES and not route_tried(session, r, counts) and r not in refused]
        if untried:
            return (f"{route} comes after {untried} in plan.geometry_routes, untried: take the simpler "
                    "routes first (a listed route stays listed once an attempt was sent)")
    identity = route_identity(kind, answer, generator, plan, session)
    sent = lib.read_json(lib.operator_dir(session) / ROUTE_SENT, []) or []
    if identity.startswith("refine|"):
        # the same image a body was made from, extracted finer: refined before any new image or route
        return refinement_problem(session, answer, plan, identity)
    if identity.startswith("rung|"):
        # Hunyuan3D from an image TripoSG made a body from: its ladder's rung (c), once per image,
        # outside GENERATED_BUDGET, a drawing and a web photograph alike (review of 2026-10-11)
        prefix = "|".join(identity.split("|")[:2]) + "|"
        if identity not in sent and any(str(k).startswith(prefix) for k in sent):
            return ("Hunyuan3D from this image was its ladder's last rung, taken once: "
                    f"{route_next('hunyuan', routes) or 'the next listed route'} (geometry.md, Writing the description)")
        return None
    if identity.startswith("web|"):
        # the photograph's own budget, outside GENERATED_BUDGET; Hunyuan3D from it once it made a body is rung (c)
        made = [k for k in sent if str(k).startswith("web|web_image:")]
        if step == "web_image" and identity not in sent and len(made) >= WEB_BODIES:
            return (f"{WEB_BODIES} body was generated from a web photograph, its budget: refine it (geometry.md, "
                    "Writing the description), Hunyuan3D from the same photograph, or build the body (`blank`)")
        return None
    later = [s for s in ROUTE_ORDER[ROUTE_ORDER.index(step) + 1:] if counts.get(s, 0)]
    if later and identity in sent:
        return (f"the route to the body has moved on to {later[-1]}: this {step} attempt was made before and its "
                "body judged; it is not re-run unchanged. An untried route, or this one with new words or a new "
                "seed within its limit, may follow (objectives/routes.md §3.4)")
    if (step == "generation" and identity not in sent and counts.get("generation", 0)
            and not seed_retry(session, answer)):
        # TripoSG text is tried once (about 4 s, no drawing; a recognisable body on 3 of 7 objects in a
        # comparison of 2026-10-11, short words as good as long); again only with a new seed after it
        # returned no watertight surface, which made no body (seed_retry)
        return ("TripoSG text is tried once, again only with a new seed when it returned no watertight "
                f"surface: the next step is {route_next('generation', routes) or 'the drawing'} "
                "(objectives/routes.md §3.4)")
    if (identity not in sent and not identity.startswith("draw|")
            and generated_bodies(session) >= GENERATED_BUDGET):
        note_route_refused(session, route, "the generated budget was spent")
        return budget_spent(session)
    return None


# A move past a recognisable generated body or drawing names the check it failed (the review of
# 2026-10-12: 4 runs of 10 turned down a recognisable drawing or body for one missing sub-member,
# and the built body made instead lacked the same member, or was cruder).  The runner records the
# drawing or free-form body its own checks passed (STANDING); a plan whose geometry moves past it
# carries plan.geometry.reject: "<the check>", one line, which must be one of REJECT_CHECKS, a
# missing member only when it is a primary one (the Real section's member, or one a run row
# enters).  Any other missing or merged member is accepted and declared.
STANDING = "standing_attempt.json"
REJECTED = "rejections.json"
REJECT_CHECKS = (
    ("the wrong object", r"wrong object|not the object|another object|different object|recogni[sz]"),
    ("several objects", r"several objects|two objects|more than one|multiple objects|\d+ objects"),
    ("not the whole object", r"not the whole|only part|partial|cropped|cut off|truncated|incomplete object"),
    ("a broken cut-out", r"cut-?out"),
)
MISSING_WORDS = r"missing|absent|lacks|lacking|without|dropped|merged|fused|not attached|detached|broken|no "


# A support's member is primary like the load's (a body's wheels fused into a
# blob, and a reject naming the support was refused as a non-primary member): the member each held
# contact sits on (``hold_member``), else the contact's own "member".


def primary_members(session: Path) -> list[str]:
    """The members a body is rejected for lacking: the Real section's member, each member a row
    of the run state enters, and each member the run state's contacts hold (the contact's
    "member")."""
    table, _ = use_table(lib.operator_dir(session))
    out: list[str] = []
    if table:
        out += [table["member"]] if table.get("member") else []
        out += [table["entry"][k] for k in table["cases"].get(table.get("run"), []) if k in (table.get("entry") or {})]
        for name, contact in (table.get("contacts") or {}).items():
            member = hold_member(table, name) or (contact or {}).get("member")
            out += [member] if member else []
    else:
        try:
            size = brief_sections((lib.operator_dir(session) / "brief.md").read_text(encoding="utf-8")).get(
                "size and material", "")
        except OSError:
            size = ""
        out += [m for m in [real_section_member_in(size)] if m]
    return list(dict.fromkeys(out))


def split_reject(plan: dict[str, Any]) -> tuple[dict[str, Any], str]:
    """The plan without geometry.reject (no card takes it, and editing it is no geometry change),
    and its one line."""
    geometry = plan.get("geometry")
    if not isinstance(geometry, dict) or "reject" not in geometry:
        return plan, ""
    said = " ".join(str(geometry.get("reject") or "").split())
    return {**plan, "geometry": {k: v for k, v in geometry.items() if k != "reject"}}, said


def _standing_kept(standing: dict[str, Any], geometry: dict[str, Any]) -> bool:
    """Whether the plan's geometry still takes the standing attempt: the same drawing (any
    generator, any crop), or the same geometry for a body."""
    if standing.get("kind") == "drawing":
        return bool(geometry.get("draw")) and [str(geometry.get("description") or "").strip(),
                                               int(geometry.get("image_seed", 0) or 0)] == standing.get("drawing")
    return same_plan_value(standing.get("geometry"), geometry)


def reject_problem(session: Path, said: str) -> str | None:
    """Why a reject line names no check that a recognisable attempt may fail, or None."""
    text = said.lower()
    if any(re.search(pattern, text) for _, pattern in REJECT_CHECKS):
        return None
    primary = primary_members(session)
    words = {_singular(w) for w in re.findall(r"[a-z0-9]+", text)}

    def named(member: str) -> bool:
        # every word of the member's name (a head word alone names a neighbour of the same kind)
        own = [_singular(w) for w in re.findall(r"[a-z0-9]+", member.lower())]
        return bool(own) and (all(w in words for w in own) or _singular("".join(own)) in _compact(text))

    if re.search(MISSING_WORDS, text) and any(named(m) for m in primary):
        return None
    if base_slab_kept(session) and re.search(r"\bslab|\bbase\b|swallow", text) and re.search(MISSING_WORDS, text):
        return None            # the supports fused into the flat base the geometry stop flagged
    named = primary or "the Real section's member, the member a run row enters"
    return (f"plan.geometry.reject {said!r} names none of the checks a recognisable body or drawing is rejected "
            f"for: {', '.join(c for c, _ in REJECT_CHECKS)}, or a missing primary member ({named}). Another member "
            "missing or merged is accepted: keep "
            "the attempt (put plan.geometry back) and declare the member in body_simplification, absent or a "
            "stand-in (visual_checks.md §1)")


# A ladder step (geometry.md, TripoSG's extraction depths) needs no reject check: the same image and
# seed extracted finer, or Hunyuan3D from the same image, is the first fix for a poor body and stays on
# the image, so a line naming the poor generation is enough.  One body had its
# 6/9 and Hunyuan3D rungs refused for want of a check (its wheels fused), and its body was accepted
# with the wheels declared absent.
POOR_GENERATION = (r"missing|absent|lack|dropped|merged|fused|fuse|blob|stub|fragment|shred|broken|detached|"
                   r"not attached|lost|collapsed|melted|torn|mangled|garbled")


def ladder_step(standing: dict[str, Any], geometry: dict[str, Any]) -> bool:
    """Whether ``geometry`` is the standing TripoSG body's next rung on the same image: the same seed
    at a refined depth pair, or Hunyuan3D."""
    if standing.get("kind") != "body":
        return False
    before = standing.get("geometry")
    try:
        before = json.loads(before) if isinstance(before, str) else before
    except ValueError:
        return False
    if not isinstance(before, dict) or before.get("generator") not in (None, "triposg"):
        return False
    image = plan_image_key({"geometry": before})
    if image is None or plan_image_key({"geometry": geometry}) != image:
        return False
    if geometry.get("generator") == "hunyuan3d":
        return True
    seed = lambda g: (g.get("generation_settings") or {}).get("seed", 0) or 0
    return (geometry.get("generator") in (None, "triposg") and seed(geometry) == seed(before)
            and extraction_depths(geometry) in REFINED_DEPTHS
            and extraction_depths(geometry) != extraction_depths(before))


def move_on_problem(session: Path, plan: dict[str, Any], said: str) -> str | None:
    """A plan that moves past the drawing or generated body the runner's checks passed, without a
    reject line that names the check it failed (or with the line said of the previous one); a
    ladder step on the same image (``ladder_step``) with a line naming the poor generation.  A
    move refused for want of a check records the route it would have taken (ROUTES_REFUSED)."""
    standing = lib.read_json(lib.operator_dir(session) / STANDING, None)
    geometry = plan.get("geometry") if isinstance(plan.get("geometry"), dict) else {}
    if not isinstance(standing, dict) or _standing_kept(standing, geometry):
        return None
    what = "drawing" if standing.get("kind") == "drawing" else "generated body"
    ladder = ladder_step(standing, geometry)
    if not said:
        return (f"the {what} shown passed the runner's checks: moving past it takes plan.geometry.reject: "
                "\"<the check it failed>\", one line (the wrong object, several objects, not the whole object, a "
                "broken cut-out, a missing primary member"
                + ("; for this rung on the same image, the poor generation it fixes: a member fused, missing or "
                   "broken, fragments" if ladder else "")
                + "); a recognisable one with another member missing or "
                "merged is accepted and the member declared (visual_checks.md §1). Nothing was sent")
    if ladder and re.search(POOR_GENERATION, said.lower()):
        return None
    rejected = lib.read_json(lib.operator_dir(session) / REJECTED, []) or []
    if rejected and rejected[-1].get("reject") == said:
        return (f"plan.geometry.reject {said!r} was said of the previous attempt: say the check this {what} "
                "failed. Nothing was sent")
    wrong = reject_problem(session, said)
    if wrong and ladder:
        return (f"plan.geometry.reject {said!r}: this rung on the same image takes the poor generation it fixes "
                "(a member fused, missing or broken, fragments), or a check of visual_checks.md §1. Nothing was sent")
    if wrong:
        route = geometry_route(geometry)
        if route:
            note_route_refused(session, route, f"the body stood (reject {said!r}: {wrong.split('. ')[0]})")
    return wrong


# The routes the runner refused to take, with why: the budget spent, or a move past a standing body
# for no check it failed (the body is then kept and declared).  Such a route counts as taken for the
# simplified body (``body_simplification_problem``) and the verdict names it; the route list itself
# never shrinks once an attempt was sent (``kept_routes``), so no plan edit passes the gate.
ROUTES_REFUSED = "routes_refused.json"


def routes_refused(session: Path) -> dict[str, str]:
    value = lib.read_json(lib.operator_dir(session) / ROUTES_REFUSED, {}) or {}
    return value if isinstance(value, dict) else {}


def note_route_refused(session: Path, route: str, why: str) -> None:
    known = routes_refused(session)
    if route in GEOMETRY_ROUTES and route not in known:
        lib.write_json(lib.operator_dir(session) / ROUTES_REFUSED, {**known, route: why})


def geometry_route(geometry: Any) -> str | None:
    """The route (GEOMETRY_ROUTES) a plan's geometry entry takes, None for a user's file."""
    source = geometry_provenance(geometry)
    if source in (None, "upload"):
        return None
    if source in CAD_GENERATORS:
        return "cadcoder" if source == "cadcoder" else None
    if source in ("built", "hunyuan3d"):
        return source
    if geometry.get("web_image") or WEB_DIR in str(geometry.get("asset_path") or "").replace("\\", "/"):
        return "web_image"
    if geometry.get("draw") or DRAW_DIR in str(geometry.get("asset_path") or ""):
        return "drawing"
    return None if geometry.get("asset_kind") == "image" else "triposg_text"


def kept_routes(session: Path, routes: list[str]) -> tuple[list[str], list[str]]:
    """The routes to enforce from a plan's list, and the ones it dropped that stay: once any route
    attempt was sent, a listed route is never taken off (one run passed the
    simplified-body gate by deleting an untried route from the list)."""
    before = declared_routes(session) or []
    counts = lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {}
    sent = (lib.read_json(lib.operator_dir(session) / ROUTE_SENT, []) or []) or any(
        counts.get(stage, 0) for stage in ROUTE_STAGE.values())
    dropped = [r for r in before if r not in routes] if sent else []
    return canonical_routes(list(routes) + dropped, session), dropped


def record_move_on(session: Path, plan: dict[str, Any], said: str) -> None:
    """After the geometry card was answered: a move past the standing attempt is recorded with its
    reject line (the report's), and the standing attempt is gone."""
    path = lib.operator_dir(session) / STANDING
    standing = lib.read_json(path, None)
    if not isinstance(standing, dict):
        return
    geometry = plan.get("geometry") if isinstance(plan.get("geometry"), dict) else {}
    if _standing_kept(standing, geometry):
        if standing.get("kind") == "drawing":
            path.unlink(missing_ok=True)       # generated from: the body is judged next
        return
    rejected = lib.read_json(lib.operator_dir(session) / REJECTED, []) or []
    lib.write_json(lib.operator_dir(session) / REJECTED,
                   rejected + [{"kind": standing.get("kind"), "reject": said, "time": time.time()}])
    path.unlink(missing_ok=True)


def record_standing(session: Path, stop: str, value: dict[str, Any], geometry: dict[str, Any] | None) -> None:
    """At a drawing or geometry stop: the attempt shown, when the runner's own checks passed it (a
    drawing of one object; a free-form body with no error, one component and G4 within the rule),
    else nothing stands."""
    path = lib.operator_dir(session) / STANDING
    geometry = {k: v for k, v in (geometry or {}).items() if k != "reject"}
    passed = False
    record: dict[str, Any] = {}
    if stop == "drawing":
        drawn = value.get("drawing") if isinstance(value.get("drawing"), dict) else {}
        passed = (value.get("ok") is not False and not value.get("api_error") and bool(value.get("look_at"))
                  and isinstance(drawn.get("objects"), int) and drawn["objects"] <= 1)
        record = {"kind": "drawing", "drawing": [str(geometry.get("description") or "").strip(),
                                                 int(geometry.get("image_seed", 0) or 0)]}
    elif stop == "geometry":
        shown = value.get("geometry") if isinstance(value.get("geometry"), dict) else {}
        g4 = (value.get("planned_resolution") or {}).get("g4") if isinstance(value.get("planned_resolution"), dict) else None
        passed = (generated_body(session) and value.get("ok") is not False and not value.get("error")
                  and (shown.get("components") or 1) == 1 and shown.get("watertight", True) is not False
                  and g4 in (None, "within the rule"))
        record = {"kind": "body", "geometry": _normalized(geometry), "body": body_digest(session)}
    if passed:
        lib.write_json(path, {**record, "time": time.time()})
    else:
        path.unlink(missing_ok=True)


def budget_spent(session: Path) -> str:
    """What follows GENERATED_BUDGET generated bodies: the web photograph until it was tried, then
    the built body."""
    return (f"{GENERATED_BUDGET} generated bodies were tried, the budget: "
            + ("build the body (`blank`, \"built\" in plan.geometry_routes" if web_photo_problem(session) is None
               else "a web photograph (plan.geometry.web_image {\"query\": \"<the object's noun phrase>\"}), then "
                    "the built body (`blank`") + "; objectives/routes.md §3.4)")


NO_SURFACE = "no_surface.json"     # the newest generation that returned no watertight surface


def _without_seed(answer: Any) -> tuple[str, Any]:
    """A generation answer apart from its seed, and the seed."""
    answer = dict(answer) if isinstance(answer, dict) else {}
    settings = dict(answer.get("generation_settings") or {})
    seed = settings.pop("seed", 0)
    return _normalized({**answer, "generation_settings": settings}), seed


def note_no_surface(session: Path, kind: str | None, answer: Any, error: str | None) -> None:
    """A generation the generator turned down for want of a watertight surface: no body was made,
    so the same answer with one new seed may follow (``seed_retry``).  ``retried`` marks a record
    that is itself that seed change, which is not changed again."""
    if kind != "geometry_input" or not isinstance(answer, dict) or "watertight" not in str(error or "").lower():
        return
    path = lib.operator_dir(session) / NO_SURFACE
    last = lib.read_json(path, {}) or {}
    retried = bool(last.get("answer")) and _without_seed(last["answer"])[0] == _without_seed(answer)[0]
    lib.write_json(path, {"answer": answer, "retried": retried, "time": time.time()})


def seed_retry(session: Path, answer: Any) -> bool:
    """Whether ``answer`` is the one seed change a generation that returned no watertight surface
    is allowed: the same answer with another seed, once.  TripoSG text did so on 1 of 7 objects
    in a comparison of 2026-10-11, and a finer extraction (depth 8 or 9) does so more often."""
    last = lib.read_json(lib.operator_dir(session) / NO_SURFACE, {}) or {}
    if not last.get("answer") or last.get("retried"):
        return False
    (before, old), (now, new) = _without_seed(last["answer"]), _without_seed(answer)
    return before == now and old != new


# The refinement ladder for a body TripoSG made poorly from an image that passed its stop: the same
# image and seed extracted finer, before any new image or route.  Measured on 8 inputs at init/depth
# 4/7, 4/8, 5/8 and 6/9 (2026-10-11): 6/9 recovered thin parts (slender members, small closed
# loops, a tall body's outline) at 5-20 s and about 9 GB; 5/8 was better on one lattice that 6/9 collapsed to a line; 4/8
# was the worst (bodies collapsed), so the first grid rises with the last (init = depth - 3).  Text
# mode degenerates at 5/8 and 6/9 and stays at 4/7.  A refinement is the same attempt refined, no
# new body for GENERATED_BUDGET, nor is Hunyuan3D from the same image (rung (c), once per image).
REFINED_DEPTHS = ((6, 9), (5, 8))
REFINEMENTS = 2                        # per image
REFINE_SENT = "refinements.json"       # {image key: [refinement identities sent]}
IMAGE_BODIES = "image_bodies.json"     # the image keys TripoSG made a body from at 4/7
# Free VRAM (with our own workers counted as room) the extraction needs, by octree_depth, image mode:
# about 9 GB at depth 9 and 5 GB at depth 8 (25 GB at depth 9 was seen only in text mode).
EXTRACTION_MIB = {8: 5_000, 9: 10_000}
# The faces a depth-8 or -9 TripoSG extraction is capped at (generation_settings.faces; the generator
# decimates the one watertight body it keeps, and keeps the body whole when decimation would open it).
# A 6/9 body of 1.39 M faces ran PartField out of GPU memory three times in one run;
# capped at 300k it stayed watertight with its volume within 0.03 % (21 s on the CPU).
FINE_FACES = 300_000


def extraction_depths(answer: Any) -> tuple[int, int]:
    """TripoSG's (init_octree_depth, octree_depth) an answer asks for, the defaults 4 and 7."""
    settings = (answer.get("generation_settings") or {}) if isinstance(answer, dict) else {}
    return int(settings.get("init_octree_depth", 4) or 4), int(settings.get("octree_depth", 7) or 7)


def image_key(answer: Any, plan: dict[str, Any] | None) -> str | None:
    """The image a TripoSG body is generated from: a drawing by its words, seed and crop, any other
    image by its path; None for text, a drawing alone, or another generator."""
    import hashlib
    if (not isinstance(answer, dict) or answer.get("action") == "draw_image" or answer.get("revise_prompt")
            or answer.get("generator") not in (None, "triposg")):
        return None
    geometry = ((plan or {}).get("geometry") or {}) if isinstance(plan, dict) else {}
    if answer.get("use_drawn_image") or DRAW_DIR in str(answer.get("asset_path") or ""):
        key = _normalized([str(geometry.get("description") or "").strip(),
                           int(geometry.get("image_seed", 0) or 0), geometry.get("drawing_crop")])
    elif answer.get("asset_kind") == "image" and answer.get("asset_path"):
        key = str(Path(str(answer["asset_path"])).resolve())     # as the plan wrote it or the lint resolved it
    else:
        return None
    return hashlib.sha256(key.encode()).hexdigest()[:10]


def refinement_problem(session: Path, answer: Any, plan: dict[str, Any] | None, identity: str) -> str | None:
    """A finer extraction of an image a body was made from: allowed REFINEMENTS times per image (a
    seed change after no watertight surface not counted), past GENERATED_BUDGET, and recorded."""
    key = identity.split("|")[1]
    path = lib.operator_dir(session) / REFINE_SENT
    sent = lib.read_json(path, {}) or {}
    tried = list(sent.get(key) or [])
    if identity in tried:
        return None                    # a resend of the same refinement
    if key in mass_blocked_images(session):
        return MASS_NO_LADDER + mass_next_said(session, plan)
    if len([k for k in tried if not k.startswith("seed|")]) >= REFINEMENTS and not seed_retry(session, answer):
        return (f"this image was extracted finer {REFINEMENTS} times, the ladder's limit: Hunyuan3D from the same "
                "image (\"generator\": \"hunyuan3d\", once, no new body), else the next listed route (geometry.md, "
                "Writing the description)")
    lib.write_json(path, {**sent, key: tried + [("seed|" + identity) if seed_retry(session, answer) else identity]})
    return None


def refine_hint(session: Path, plan: dict[str, Any]) -> str | None:
    """At the geometry stop of a TripoSG body made from an image: the ladder's next rung, the first
    fix for a poor body from an image that passed its stop (a new image or route only after it)."""
    geometry = plan.get("geometry") or {}
    if geometry.get("generator") not in (None, "triposg"):
        return None
    answer = ({"use_drawn_image": True} if geometry.get("draw")
              else {"asset_kind": geometry.get("asset_kind"), "asset_path": geometry.get("asset_path")})
    key = image_key(answer, plan)
    if key is None:
        return None
    if key in mass_blocked_images(session):
        return MASS_NO_LADDER + mass_next_said(session, plan)
    tried = [k for k in (lib.read_json(lib.operator_dir(session) / REFINE_SENT, {}) or {}).get(key) or []
             if not k.startswith("seed|")]
    depths = extraction_depths(geometry)
    rungs = [d for d in REFINED_DEPTHS if d != depths][:max(REFINEMENTS - len(tried), 0)]
    later = (f"generation_settings init_octree_depth {rungs[0][0]}, octree_depth {rungs[0][1]}"
             + (f", then {rungs[1][0]}/{rungs[1][1]}" if len(rungs) > 1 else "") + ", then " if rungs else "")
    return ("a poor body from this image (fragments, a member missing or broken, a thin part lost) is refined "
            f"first, the same image and seed, geometry.reject naming the fault: {later}Hunyuan3D from the same image (once, no new body); a new image "
            "or route only after (geometry.md, Writing the description)")


# A generated body over MASS_OVER_REAL x the Real mass (G4) is another structure, and no finer extraction
# of the same image thins it: the refinement ladder is for poor shape (fragments, a member missing or
# broken), not mass.  One run accepted an 11.5 x body with the drawing route
# untried, and others spent 6/9 and 5/8 extractions on bodies 8-10 x too heavy.  The runner records the
# image such a body came from, skips its ladder (Hunyuan3D from it only while untried), and refuses to
# accept the body while a generated route or the web photograph remains.
MASS_FAILED = "mass_failed.json"       # [{"digest", "image", "source", "mass_over_real"}] of generated bodies
MASS_NO_LADDER = ("a G4 mass failure (the body over 5 x the Real mass) is no resolution problem: a finer depth "
                  "does not thin it, so this image's refinement ladder is skipped: ")


def mass_failed_images(session: Path) -> set[str]:
    """The images a generated body over MASS_OVER_REAL x the Real mass was made from."""
    return {str(r.get("image")) for r in lib.read_json(lib.operator_dir(session) / MASS_FAILED, []) or []
            if isinstance(r, dict) and r.get("image")}


# The image's newest mass ratio, as the geometry stop measured it: a rescale (or a corrected Real mass)
# can bring a body of a failed image under MASS_OVER_REAL, and its ladder then opens again.  Before
# that, a mass failure closed the image's ladder for the whole session.
MASS_NOW = "mass_now.json"             # {image key: the newest mass_over_real of a body from it, "density": {key: how}}


def mass_blocked_images(session: Path) -> set[str]:
    """The images whose ladder is closed: a body from them failed on mass, and the newest body from
    them is still over MASS_OVER_REAL x the Real mass."""
    now = lib.read_json(lib.operator_dir(session) / MASS_NOW, {}) or {}
    return {key for key in mass_failed_images(session)
            if not isinstance(now.get(key), (int, float)) or now[key] > MASS_OVER_REAL}


def plan_image_key(plan: dict[str, Any]) -> str | None:
    """The image the plan's geometry generates from (a drawing or an image asset), whatever its generator."""
    geometry = plan.get("geometry") or {}
    answer = ({"use_drawn_image": True} if geometry.get("draw")
              else {"asset_kind": geometry.get("asset_kind"), "asset_path": geometry.get("asset_path")})
    return image_key(answer, {**plan, "geometry": {**geometry, "generator": None}})


def mass_next_route(session: Path, plan: dict[str, Any], image: str | None = None) -> str | None:
    """The route after a generated body failed G4 on mass, while one remains: Hunyuan3D from the
    same image while Hunyuan3D is untried, an untried listed generated route within the budget, then
    the web photograph until it was tried; None when only `built` is left."""
    counts = lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {}
    routes = declared_routes(session) or canonical_routes(list(plan.get("geometry_routes") or []), session)
    source = body_provenance(session)
    if (image and source == "triposg" and not counts.get("hunyuan") and "hunyuan3d" in routes
            and hunyuan_ready()):
        return "Hunyuan3D from the same image (\"generator\": \"hunyuan3d\", the same words and image_seed)"
    if generated_bodies(session) < GENERATED_BUDGET:
        for route in routes:
            if (route in GENERATED_ROUTES and (route != "hunyuan3d" or hunyuan_ready())
                    and not route_tried(session, route, counts)):
                return ROUTE_WORDS[route]
    if web_photo_problem(session) is not None:
        return ROUTE_WORDS["web_image"]
    return None


def mass_next_said(session: Path, plan: dict[str, Any]) -> str:
    """The step after a mass failure, in words."""
    image = next((str(r.get("image")) for r in reversed(lib.read_json(lib.operator_dir(session) / MASS_FAILED, [])
                                                         or []) if isinstance(r, dict)), None)
    nxt = mass_next_route(session, plan, image)
    return (f"the next route: {nxt}" if nxt else "the built body (`blank`, at the brief's Real dimensions)") + \
        " (geometry.md, Writing the description)"


def record_mass_failure(session: Path, plan: dict[str, Any], ratio: Any, density: Any = None) -> None:
    """At the geometry stop: a generated body over MASS_OVER_REAL x the Real mass, by its digest and the
    image it came from (a body from text has none); and every measured ratio of a body from an image
    as that image's newest (MASS_NOW), with the density it was priced at (``mass_over_real_from``)."""
    if not isinstance(ratio, (int, float)):
        return
    source = body_provenance(session)
    if source not in ("triposg", "hunyuan3d", *CAD_GENERATORS):
        return
    key = plan_image_key(plan) if source in ("triposg", "hunyuan3d") else None
    if key:
        now = lib.operator_dir(session) / MASS_NOW
        known = lib.read_json(now, {}) or {}
        lib.write_json(now, {**known, key: ratio, "density": {**(known.get("density") or {}), key: density}})
    if ratio <= MASS_OVER_REAL:
        return
    path = lib.operator_dir(session) / MASS_FAILED
    record = lib.read_json(path, []) or []
    digest = body_digest(session)
    if any(isinstance(r, dict) and r.get("digest") == digest for r in record):
        return
    lib.write_json(path, record + [{"digest": digest, "image": key, "source": source,
                                    "mass_over_real": ratio, "density": density, "time": time.time()}])


def mass_route_problem(session: Path, plan: dict[str, Any], resolution: dict[str, Any] | None) -> str | None:
    """A generated body over MASS_OVER_REAL x the Real mass is not accepted while a generated route or
    the web photograph remains (``mass_next_route``): refused on leaving the geometry stop, and said
    there as its error.  Past them it is accepted, and the verdict is G4's "could not be run"."""
    ratio = (resolution or {}).get("mass_over_real")
    if not isinstance(ratio, (int, float)) or ratio <= MASS_OVER_REAL:
        return None
    if body_provenance(session) not in ("triposg", "hunyuan3d", *CAD_GENERATORS) or thickened_stand_in(session, resolution):
        return None            # a thickened thin real member is a marked stand-in, not another structure
    record = lib.read_json(lib.operator_dir(session) / MASS_FAILED, []) or []
    digest = body_digest(session)
    image = next((r.get("image") for r in record if isinstance(r, dict) and r.get("digest") == digest), None)
    nxt = mass_next_route(session, plan, image)
    if not nxt:
        return None
    revisable = (body_provenance(session) in ("triposg", "hunyuan3d") and not extents_revision(session)[0]
                 and mass_outlier(session, resolution))
    priced = (resolution or {}).get("mass_over_real_from")
    return (f"G4 mass: the body is {ratio:g} x the Real mass (over {MASS_OVER_REAL:g}"
            + (f"; density {priced}" if priced else "") + "), another structure, and is not "
            f"accepted while a route remains: try the next route, {nxt}. A finer depth does not thin it (no "
            "refinement ladder for mass)" + (revision_said(session, resolution) if revisable else ""))


def hunyuan_rung_key(session: Path | None, answer: Any, plan: dict[str, Any] | None) -> str | None:
    """The image a Hunyuan3D answer generates from, when TripoSG already made a body from it
    (IMAGE_BODIES, so it passed its stop): Hunyuan3D from it is that image's ladder rung (c), not a
    new body.  A drawing is matched by its words and seed, cropped or not."""
    if session is None or not isinstance(answer, dict):
        return None
    made = lib.read_json(lib.operator_dir(session) / IMAGE_BODIES, []) or []
    geometry = ((plan or {}).get("geometry") or {}) if isinstance(plan, dict) else {}
    as_triposg = {k: v for k, v in answer.items() if k != "generator"}
    for crop in dict.fromkeys((geometry.get("drawing_crop"), None, "largest")):
        key = image_key(as_triposg, {**(plan or {}), "geometry": {**geometry, "drawing_crop": crop}})
        if key in made:
            return key
    return None


def route_identity(kind: str | None, answer: Any, generator: str | None = None,
                   plan: dict[str, Any] | None = None, session: Path | None = None) -> str | None:
    """A free-form attempt's identity (``route_step``): its answer, and the drawing's words and seed
    for a body from a drawing; "draw|" before a drawing alone (no body); "refine|<image>|" before a
    finer extraction of an image the session made a body from (the same attempt refined, no new body)."""
    step = route_step(kind, answer, generator)
    if step is None:
        return None
    geometry = ((plan or {}).get("geometry") or {}) if isinstance(plan, dict) else {}
    drawing = ([str(geometry.get("description") or "").strip(), geometry.get("image_seed", 0)]
               if step != "generation" else None)
    identity = _attempt_digest(step, {**answer, "drawing": drawing})
    if answer.get("action") == "draw_image":
        return "draw|" + identity
    rung = hunyuan_rung_key(session, answer, plan) if step == "hunyuan" else None
    if rung:
        return f"rung|{rung}|{identity}"
    key = image_key(answer, plan) if session is not None and extraction_depths(answer)[1] > 7 else None
    if key and key in (lib.read_json(lib.operator_dir(session) / IMAGE_BODIES, []) or []):
        return f"refine|{key}|{identity}"
    if WEB_DIR in str(answer.get("asset_path") or "").replace("\\", "/"):
        return "web|" + identity        # the web photograph's own budget (WEB_BODIES)
    return identity


def record_route(session: Path, kind: str | None, answer: Any, generator: str | None = None,
                 plan: dict[str, Any] | None = None) -> None:
    """A free-form attempt recorded once it ran (a step the GPU guard refused never is), and the
    image a TripoSG body was made from (IMAGE_BODIES), which a finer extraction may then refine."""
    identity = route_identity(kind, answer, generator, plan, session)
    if identity is None:
        return
    path = lib.operator_dir(session) / ROUTE_SENT
    sent = lib.read_json(path, []) or []
    if identity not in sent:
        lib.write_json(path, sent + [identity])
    key = image_key(answer, plan) if generator in (None, "triposg") else None
    images = lib.read_json(lib.operator_dir(session) / IMAGE_BODIES, []) or []
    if key and key not in images:
        lib.write_json(lib.operator_dir(session) / IMAGE_BODIES, images + [key])


ROUTE_WORDS = {"cadcoder": "CAD-Coder (geometry.generator \"cadcoder\", revise_prompt true)",
               "triposg_text": "a TripoSG text generation",
               "drawing": "an SDXL drawing (geometry.draw true, image_seed)",
               "hunyuan3d": "Hunyuan3D from the drawing (geometry.generator \"hunyuan3d\")",
               "web_image": "a licensed web photograph (geometry.web_image {\"query\": \"<the object's noun phrase>\"})"}


def route_next(stage: str, routes: list[str] | None = None) -> str | None:
    """The step a route's limit (or a turned-down step) leads to: the next route the brief
    listed, else an untried route the brief adds, or the built body."""
    simplified = ("the simplified body: the load path built with blank (\"built\" added to plan.geometry_routes; "
                  "a member left out in plan.body_simplification {\"absent\": [...]}, objectives/routes.md §3.4)")
    if stage not in STAGE_ROUTE or stage == "upload":
        return None
    route = STAGE_ROUTE[stage]
    if routes is not None and route in routes:
        later = [r for r in routes[routes.index(route) + 1:] if r != "hunyuan3d" or hunyuan_ready()]
        if later and later[0] in ROUTE_WORDS:
            return f"the next route plan.geometry_routes lists, {ROUTE_WORDS[later[0]]}"
        return ("every route plan.geometry_routes lists has been tried: an untried route the brief adds "
                "to the list with its reason, or " + simplified)
    if stage == "cad":
        return ("an untried generated route the brief adds, a built body when it reduces to one section, or "
                + simplified)
    later = [r for r in FREE_FORM_ROUTES[FREE_FORM_ROUTES.index(route) + 1:] if r != "hunyuan3d" or hunyuan_ready()]
    return (f"{ROUTE_WORDS[later[0]]} when the brief expects it to make the body, or {simplified}"
            if later else simplified)


FRESH_DRAWING_FOR_HUNYUAN = (
    "a drawing that fails a drawing check (not the whole object, not only one, a member missing) is "
    "generated from by no route: TripoSG and Hunyuan3D both take it as it is and carry its fault. A fresh "
    "drawing made for Hunyuan3D (\"generator\": \"hunyuan3d\" with new words or image_seed) is Hunyuan3D's "
    "own attempt, not the drawing route's, when plan.geometry_routes lists hunyuan3d; else the next listed route")


def last_drawing_note(session: Path, plan: dict[str, Any]) -> str | None:
    """At the drawing stop of the drawing route's last drawing: what a failed one leads to.  In one
    run an agent judged its last drawing wrong (a cut-out through a wall)
    and, the drawing limit spent, generated from it with TripoSG and then Hunyuan3D, each body
    carrying the same fault."""
    if (plan.get("geometry") or {}).get("generator") == "hunyuan3d":
        return None             # a drawing made for Hunyuan3D: its own limit, its own attempts
    counts = lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {}
    if counts.get("drawing", 0) < RUN_LIMITS["drawing"]:
        return None
    return (f"the drawing route's last drawing ({RUN_LIMITS['drawing']} of {RUN_LIMITS['drawing']}): when it "
            "passes, run on; " + FRESH_DRAWING_FOR_HUNYUAN)


def cad_revision_stage(answer: Any) -> str | None:
    """The budget a CAD prompt revision spends (CAD_REVISIONS); None for any other answer."""
    return (CAD_REVISIONS if isinstance(answer, dict) and answer.get("revise_prompt")
            and answer.get("generator") in CAD_GENERATORS else None)


def restart_cad_revisions(session: Path) -> dict[str, Any]:
    """A counted CAD generation: the next one has its whole revision budget again."""
    path = lib.operator_dir(session) / "run_counts.json"
    counts = lib.read_json(path, {}) or {}
    if CAD_REVISIONS in counts:
        counts.pop(CAD_REVISIONS)
        lib.write_json(path, counts)
    return counts


def on_cad_route(session: Path, plan: dict[str, Any] | None = None) -> bool:
    """Whether the session is on a CAD generator's route: a CAD generator makes the current body
    (the workflow's generation settings, the body not an upload) or the plan's geometry names one.
    ``plan`` is the plan as the last run declared it when none is given."""
    if plan is None:
        plan = lib.read_json(lib.operator_dir(session) / "declared.json", {}) or {}
    if ((plan.get("geometry") or {}) if isinstance(plan, dict) else {}).get("generator") in CAD_GENERATORS:
        return True
    state = lib.read_json(session / "session.json", {}) or {}
    return (state.get("geometry_mode") != "surface"
            and (state.get("generation") or {}).get("generator") in CAD_GENERATORS)


def attempts_left(session: Path, counts: dict[str, Any], plan: dict[str, Any] | None = None) -> dict[str, int]:
    """What each retried stage has left.  The CAD revision budget is shown only on a CAD route: off
    it no step can spend it, and a budget printed at every stop reads as one to use."""
    left = {k: max(v - counts.get(k, 0), 0) for k, v in RUN_LIMITS.items()}
    if not on_cad_route(session, plan):
        left.pop(CAD_REVISIONS, None)
    if plan is not None and not plan_paints(plan):
        left.pop(REPAINTS, None)        # nothing the painter paints: no budget to show
    return left


def limit_message(stage: str, counts: dict[str, Any], routes: list[str] | None = None) -> str:
    if stage == REPAINTS:
        return (f"the body was painted again {RUN_LIMITS[REPAINTS]} times after its first painting, the limit "
                "(about 30 s each): put plan.texture back to the words and seed of the painting the card shows, "
                "which is then adopted, or drop plan.texture (a grey body). The painter spreads one reference "
                "over every face and places no colour by part: with a per-part material, "
                "plan.texture {\"per_part_colours\": true} gives each part a flat colour (geometry.md, Texture)")
    if stage == CAD_REVISIONS:
        return (f"CAD prompt revised {RUN_LIMITS[CAD_REVISIONS]} times since the last CAD generation, the "
                "budget before each one: generate from the revision the card shows (run again with "
                "geometry.description as it was revised from), or leave the route: "
                + (route_next("cad", routes) or "the next listed route"))
    nxt = route_next(stage, routes)
    if nxt and stage == "drawing":
        return (f"{stage} attempted {counts.get(stage, 0) - 1} times, the limit. The next step of the "
                f"route: {nxt}; an earlier attempt is not re-run unchanged; " + FRESH_DRAWING_FOR_HUNYUAN)
    if nxt:
        return (f"{stage} attempted {counts.get(stage, 0) - 1} times, the limit. The next step of the "
                f"route: {nxt}; an earlier attempt is not re-run unchanged")
    return (f"{stage} attempted {counts.get(stage, 0) - 1} times, the limit; write the "
            "failure report with what was tried")


def note_revision(session: Path, kind: str | None, answer: Any, card_after: Any) -> None:
    """Record a completed prompt revision: the text it was made from and what it returned.

    The card shows only the revised text, so without this record a plan edited
    at the ``revision`` stop could not be told from one that accepted it.
    """
    if kind != "geometry_input" or not isinstance(answer, dict) or not answer.get("revise_prompt"):
        return
    if not isinstance(card_after, dict) or card_after.get("kind") != "geometry_input" \
            or card_after.get("api_error"):
        return                   # a failed revision leaves nothing to generate from
    lib.write_json(lib.operator_dir(session) / "run_revision.json", {
        "source": str(answer.get("description") or "").strip(),
        "generator": answer.get("generator") or "triposg",
        "revised": str(card_after.get("description") or "").strip()})


# The case brief the agent writes before the plan: its reasoning about the
# real object, which the stops are judged against.  The runner only checks
# that it exists and carries the five headings with something under each;
# the content is the agent's.
BRIEF_HEADINGS = ("Use", "Contacts", "Load", "Size and material")   # a Prediction section is optional


def brief_sections(text: str) -> dict[str, str]:
    """The brief's sections by lower-cased heading."""
    import re
    found = {}
    for block in re.split(r"^#+\s*", text, flags=re.M)[1:]:
        title, _, body = block.partition("\n")
        found[title.strip().lower()] = body.strip()
    return found


def _safely(fn, *args) -> Any:
    """``fn(*args)``, or None when it raises: a report line that fails to read says nothing."""
    try:
        return fn(*args)
    except Exception:
        return None


def brief_status(operator: Path, snapshot: bool = True) -> dict[str, Any]:
    """The brief as the stops report it: its predictions, and whether it changed.

    Two snapshots.  The first call with ``snapshot`` (a body is built, or a run reaches a stop with
    a body; a drawing or revision stop comes before any body, so its brief warnings can still be
    answered in the brief) keeps the brief as it stood before any body existed: its real mass,
    member and section and its contacts are read from that one.  The first solve keeps it again (``snapshot_brief_at_solve``): a section
    rewritten after a result can be seen shows up as ``changed_since_first``, and edits made
    before the first solve are the brief being written, not changes.  A "Prediction (generated)"
    section is reported beside the original rather than counted as a change.
    """
    import hashlib
    path = operator / "brief.md"
    # Snapshots live beside operator/, outside the one folder the skill lets
    # the agent write, so a later edit of the brief cannot also edit its record.
    snapshots = operator.parent / "brief_snapshots"
    first, solved = snapshots / "brief.first.md", snapshots / "brief.solve.md"
    generated_first = snapshots / "prediction_generated.first.txt"
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return {"present": False}
    snapshots.mkdir(exist_ok=True)
    initial = snapshots / "brief_initial.md"
    if not initial.exists():
        # the brief at the first run, before any stop's numbers were shown: edits of its real
        # lines before the body are reported against it (pre_body_edits)
        initial.write_text(text, encoding="utf-8")
    if not first.exists() and snapshot:
        first.write_text(text, encoding="utf-8")
    sections = brief_sections(text)
    generated = next((v for k, v in sections.items()
                      if is_generated_heading(k)), None)
    changed, generated_changed = [], False
    if solved.exists():
        original = brief_sections(solved.read_text(encoding="utf-8"))
        changed = sorted(h for h in (*BRIEF_HEADINGS, "Prediction")
                         if sections.get(h.lower(), "") != original.get(h.lower(), ""))
        if generated is not None:
            if not generated_first.exists():
                generated_first.write_text(generated, encoding="utf-8")
            generated_changed = generated_first.read_text(encoding="utf-8") != generated
    size = sections.get("size and material", "")
    size_first = (brief_sections(first.read_text(encoding="utf-8")).get("size and material", "")
                  if first.exists() else size)
    real_edited = [name for name, read in (("Real mass", real_mass_in), ("Real thinnest member", real_member_in),
                                           ("Real section", real_section_in))
                   if read(size) != read(size_first)]
    return {"present": True,
            "prediction": sections.get("prediction"),
            "changes": sections.get("brief changes"),
            "prediction_generated": generated,
            "changed_since_first": changed,
            "prediction_generated_changed": generated_changed,
            "real_lines_edited": real_edited,
            "real_lines_edited_before_body": [e["text"] for e in pre_body_edits(operator)],
            "extents_revised": _safely(extents_revised_said, operator.parent),
            "real_line_unlocked": _safely(real_line_unlocked_said, operator),
            "digest": hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]}


def is_generated_heading(title: str) -> bool:
    """A brief heading (lower case) that is the generated prediction's: "prediction (generated)",
    with or without the space, or another "prediction (...)" variant."""
    import re
    return ((re.match(r"prediction\s*\(", title) is not None and "revised" not in title)
            or title == "prediction generated")


REAL_LINES = (("Real mass", lambda t: real_mass_in(t)), ("Real thinnest member", lambda t: real_member_in(t)),
              ("Real section", lambda t: real_section_in(t)))


def _size_of(path: Path) -> str | None:
    try:
        return brief_sections(path.read_text(encoding="utf-8")).get("size and material", "")
    except OSError:
        return None


def record_member_warning(operator: Path) -> None:
    """The member warning was shown before any body: the brief's real member may then move to a
    member of its stated section (pre_body_edits allows that edit, and states it)."""
    snapshots = operator.parent / "brief_snapshots"
    size = _size_of(operator / "brief.md")
    if size is None:
        return
    snapshots.mkdir(exist_ok=True)
    path = snapshots / "member_warning.json"
    if not path.exists():
        lib.write_json(path, {"member_m": real_member_in(size), "section": real_section_in(size)})


def member_warning_new(operator: Path) -> bool:
    """Whether the member warning is new for the brief's real lines as they stand: said once per
    member and section (one run was shown the same warning at six stops)."""
    size = _size_of(operator / "brief.md")
    if size is None:
        return False
    lines = {"member_m": real_member_in(size), "section": real_section_in(size)}
    path = operator.parent / "brief_snapshots" / "member_warning_said.json"
    if lib.read_json(path, None) == lines:
        return False
    path.parent.mkdir(exist_ok=True)
    lib.write_json(path, lines)
    return True


# A Real thinnest member raised after the runner's member warning drops the thin-member caveat: taken
# only with the brief's reason, and listed in the verdict (one run raised 0.012 to 0.04 m and
# its resolution check went from 10 to 33 leaves, unsaid).
MEMBER_WHY = re.compile(r"^\W*thinnest member why\s*:\s*(\S.{4,})$", re.I | re.M)


def pre_body_edits(operator: Path) -> list[dict[str, Any]]:
    """The real lines changed between the brief at the first run (``brief_initial.md``) and the
    brief the body was made against (``brief.first.md``): the brief being written, allowed and
    stated.  The Real lines freeze when the first body is made, not at the first run: the case's
    statics and plausibility are checked before any body (``early_case_problem``) so that the brief
    can still be corrected, and an audit met an edit made before any body kept out as an
    edit after it."""
    snapshots = operator.parent / "brief_snapshots"
    before, after = _size_of(snapshots / "brief_initial.md"), _size_of(snapshots / "brief.first.md")
    if before is None or after is None:
        return []
    warned = lib.read_json(snapshots / "member_warning.json", None)
    try:
        why = MEMBER_WHY.search((snapshots / "brief.first.md").read_text(encoding="utf-8"))
    except OSError:
        why = None
    out = []
    for name, read in REAL_LINES:
        old, new = read(before), read(after)
        if old == new:
            continue
        fmt = (lambda v: json.dumps(v) if isinstance(v, dict) else f"{v:g}" if isinstance(v, (int, float)) else str(v))
        raised = (name == "Real thinnest member" and isinstance(warned, dict) and isinstance(old, (int, float))
                  and isinstance(new, (int, float)) and new > old and warned.get("member_m") == old)
        if raised and not why:
            # raised after the member warning with no reason: not taken (the thin member's caveat stays)
            out.append({"line": name, "from": old, "to": new, "allowed": False, "warned": True,
                        "text": f"{name}: {fmt(old)} -> {fmt(new)} after the runner's member warning, without a "
                                f"line 'Thinnest member why: <reason>': not taken, the runner keeps {fmt(old)}"})
            continue
        out.append({"line": name, "from": old, "to": new, "allowed": True,
                    **({"warned": True, "why": why.group(1).strip()} if raised else {}),
                    "text": f"{name}: {fmt(old)} -> {fmt(new)} before the body (allowed, stated"
                            + (f"; raised after the runner's member warning: {why.group(1).strip()}" if raised else "")
                            + ")"})
    return out


def _real_sources(operator: Path) -> tuple[Path, ...]:
    """Where the runner reads the brief's real lines: the body snapshot, or the first run's brief
    when a real line was changed before the body other than as the member warning allows."""
    snapshots = operator.parent / "brief_snapshots"
    if any(not e["allowed"] for e in pre_body_edits(operator)):
        return (snapshots / "brief_initial.md", operator / "brief.md")
    return (snapshots / "brief.first.md", operator / "brief.md")


# The brief's Real lines are frozen once a body exists (the review of 2026-10-12: agents edited the
# Real thinnest member after the body to get past a rule).  The runner already read them from the
# body's snapshot; an edit is now refused, not only reported.  'Real extents revised:' is the one
# revision allowed (extents_revision).
REAL_LINE = re.compile(r"^\W*real\b(?!\s+(?:extents|mass)\s+revised)[^:\n]*:.*$", re.I | re.M)


def _real_lines(text: str) -> list[str]:
    size = brief_sections(text).get("size and material", "")
    return [" ".join(m.group(0).split()) for m in REAL_LINE.finditer(size)]


# A plausibility or equilibrium refusal after the body names the one Real line its correction needs,
# and unlocks it once (an audit: the freeze made such a refusal unanswerable).  The edit is
# taken into the body's snapshot, recorded, and stated in the report.
REAL_UNLOCKED = "real_unlocked.json"      # {"line": <label>, "taken": None | {"from", "to"}}


def _real_label(line: str) -> str:
    """'Real section (member): …' -> 'real section'."""
    return re.sub(r"\([^()]*\)", "", re.sub(r"^\W*", "", line).split(":", 1)[0]).strip().lower()


def unlock_real_line(operator: Path, label: str) -> bool:
    """The Real line ``label`` may change once (False when an unlock was given already)."""
    path = operator.parent / "brief_snapshots" / REAL_UNLOCKED
    if path.exists():
        return False
    path.parent.mkdir(exist_ok=True)
    lib.write_json(path, {"line": label, "taken": None})
    return True


def _take_unlocked(operator: Path, gone: list[str], added: list[str]) -> bool:
    """The one unlocked Real line's edit, written into the snapshots (the body's and the first run's)."""
    snapshots = operator.parent / "brief_snapshots"
    record = lib.read_json(snapshots / REAL_UNLOCKED, None)
    if (not isinstance(record, dict) or record.get("taken") is not None or len(gone) != 1 or len(added) != 1
            or {_real_label(gone[0]), _real_label(added[0])} != {record.get("line")}):
        return False
    try:
        now = (operator / "brief.md").read_text(encoding="utf-8")
    except OSError:
        return False
    new_raw = next((m.group(0) for m in REAL_LINE.finditer(now) if " ".join(m.group(0).split()) == added[0]), None)
    if new_raw is None:
        return False
    for name in ("brief.first.md", "brief_initial.md"):
        path = snapshots / name
        try:
            text = path.read_text(encoding="utf-8")
        except OSError:
            continue
        old_raw = next((m.group(0) for m in REAL_LINE.finditer(text) if " ".join(m.group(0).split()) == gone[0]), None)
        if old_raw is not None:
            path.write_text(text.replace(old_raw, new_raw, 1), encoding="utf-8")
    lib.write_json(snapshots / REAL_UNLOCKED, {**record, "taken": {"from": gone[0], "to": added[0]}})
    return True


def real_line_unlocked_said(operator: Path) -> str | None:
    taken = (lib.read_json(operator.parent / "brief_snapshots" / REAL_UNLOCKED, {}) or {}).get("taken")
    return (f"{taken['from']} -> {taken['to']} after the body, unlocked once by a plausibility or equilibrium "
            "refusal") if taken else None


def real_lines_frozen_problem(operator: Path) -> str | None:
    """The Real lines changed since the body's snapshot (``brief.first.md``): refused, but for the one
    line a refusal after the body unlocked (``unlock_real_line``)."""
    first = operator.parent / "brief_snapshots" / "brief.first.md"
    try:
        before, now = _real_lines(first.read_text(encoding="utf-8")), _real_lines(
            (operator / "brief.md").read_text(encoding="utf-8"))
    except OSError:
        return None
    if before == now:
        return None
    gone, added = [l for l in before if l not in now], [l for l in now if l not in before]
    if _take_unlocked(operator, gone, added):
        return None
    return ("the brief's Real lines are frozen since the first body was made: put back "
            + (f"{gone}" if gone else "nothing removed") + (f", and take out {added}" if added else "")
            + ". The one revision allowed is a line 'Real extents revised: <a> x <b> x <c> m, <reason>' (with "
            "'Real mass revised: <n> kg, <source>' when a refusal offers it) (objectives/routes.md §3.4). Nothing was sent")


def snapshot_brief_at_solve(operator: Path) -> None:
    """The brief as it stood when the first solve was sent: later edits are changes."""
    snapshots = operator.parent / "brief_snapshots"
    solved = snapshots / "brief.solve.md"
    try:
        text = (operator / "brief.md").read_text(encoding="utf-8")
    except OSError:
        return
    snapshots.mkdir(exist_ok=True)
    if not solved.exists():
        solved.write_text(text, encoding="utf-8")
        generated = next((v for k, v in brief_sections(text).items()
                          if is_generated_heading(k)), None)
        if generated is not None:
            (snapshots / "prediction_generated.first.txt").write_text(generated, encoding="utf-8")


# ------------------------------------------------------- the brief's JSON lines --
# The gates read the brief's numbers and names from its JSON lines, never its prose: the Use
# table (one row per action of the use), the Contacts JSON (each contact's
# transmission, hold kind and held length), the Load path, the Real section's member and the
# Real extents.  Each is parsed with json.JSONDecoder and type-checked where it is read.
HOLD_KINDS = ("grip", "rest", "hang", "fastening", "socket", "worn")
HELD_OVER = ("grip", "socket", "worn")       # held over a length: one family for the kind match
USE_UNITS = ("N", "N m")
USE_STATES = ("working", "handling", "assembly", "storage")       # the use's states


def _json_objects(text: str) -> list[dict[str, Any]]:
    """The top-level JSON objects written in ``text``, in order."""
    decoder, out, k, text = json.JSONDecoder(), [], 0, text or ""
    while True:
        k = text.find("{", k)
        if k < 0:
            return out
        try:
            value, end = decoder.raw_decode(text, k)
        except ValueError:
            k += 1
            continue
        if isinstance(value, dict):
            out.append(value)
        k = end


def _json_after(text: str, label: str) -> dict[str, Any] | None:
    """The JSON object right after '<label>:' in ``text`` (the last such line)."""
    found = None
    for match in re.finditer(rf"{label}\s*:\s*(?=\{{)", text or "", flags=re.I):
        try:
            value, _ = json.JSONDecoder().raw_decode(text, match.end())
        except ValueError:
            continue
        if isinstance(value, dict):
            found = value
    return found


def use_table_in(text: str) -> dict[str, Any] | None:
    """The Use section's 'Use table: {...}' line, as written (use_gate checks it)."""
    return _json_after(text, "use table")


def contacts_v2_in(text: str) -> dict[str, dict[str, Any]] | None:
    """The Contacts section's JSON object: each contact's {"transmits", "kind", "over_m"}.  The
    first form, {"<contact>": "force only"}, reads with kind "unknown" (the kind checks skip it)."""
    for value in _json_objects(text):
        out: dict[str, dict[str, Any]] = {}
        for name, entry in value.items():
            if isinstance(entry, str) and entry in TRANSMITS:
                out[str(name)] = {"transmits": entry, "kind": "unknown", "over_m": None}
            elif isinstance(entry, dict) and entry.get("transmits") in TRANSMITS:
                over = entry.get("over_m")
                out[str(name)] = {"transmits": entry["transmits"], "kind": str(entry.get("kind") or "unknown"),
                                  "over_m": float(over) if isinstance(over, (int, float))
                                  and not isinstance(over, bool) and over > 0 else None,
                                  **({"member": str(entry["member"])} if isinstance(entry.get("member"), str) else {})}
            else:
                out = {}
                break
        if out:
            return out
    return None


def contacts_json_problems(text: str) -> list[str]:
    """What is wrong with the Contacts JSON when ``contacts_v2_in`` reads none: each malformed
    entry by name, and why.  [] when it reads, or when the section has no JSON object at all (the
    brief's own checks name a missing line).  One malformed entry used to read as no contacts at
    all, and the agent was told its holds were "not contacts of the Contacts JSON ([])"."""
    if contacts_v2_in(text) is not None:
        return []
    objects = [v for v in _json_objects(text) if v]
    if not objects:
        return []
    out = []
    for name, entry in objects[0].items():
        if isinstance(entry, str) and entry in TRANSMITS:
            continue
        if not isinstance(entry, dict):
            out.append(f"Contacts JSON entry {name!r} is {json.dumps(entry)[:80]}: an object "
                       '{"transmits": ..., "kind": ..., "over_m": ...}')
            continue
        if entry.get("transmits") not in TRANSMITS:
            out.append(f"Contacts JSON entry {name!r}: \"transmits\" is {json.dumps(entry.get('transmits'))}, not one of "
                       f"{list(TRANSMITS)} (written exactly, nothing added)")
        if entry.get("kind") is not None and entry.get("kind") not in HOLD_KINDS:
            out.append(f"Contacts JSON entry {name!r}: \"kind\" is {json.dumps(entry.get('kind'))}, not one of "
                       f"{list(HOLD_KINDS)}")
        over = entry.get("over_m")
        if over is not None and not (isinstance(over, (int, float)) and not isinstance(over, bool) and over > 0):
            out.append(f"Contacts JSON entry {name!r}: \"over_m\" is {json.dumps(over)}, not a length in metres over 0")
    return out or ["the Contacts JSON reads no contact: " + json.dumps(objects[0])[:120]]


def real_section_member_in(text: str) -> str | None:
    """The member the brief's 'Real section (<member>): ...' line names."""
    match = re.search(r"real section\s*\(([^()]+)\)\s*:", text or "", flags=re.I)
    return match.group(1).strip() if match else None


def real_extents_in(text: str) -> list[float] | None:
    """The brief's 'Real extents: <a> x <b> x <c> m', in metres, in the use frame."""
    number = r"([0-9][0-9.eE+-]*)"
    match = re.search(rf"real extents:\s*{number}\s*(?:m\s*)?[x×]\s*{number}\s*(?:m\s*)?[x×]\s*{number}\s*m\b",
                      text or "", flags=re.I)
    try:
        values = [float(v) for v in match.groups()] if match else None
    except ValueError:
        return None
    return values if values and min(values) > 0 else None


def brief_missing(path: Path) -> str | None:
    """Why the brief at ``path`` does not count as written (its first problem), or None when it does."""
    problems = brief_problems(path)
    return problems[0] if problems else None


def brief_problems(path: Path) -> list[str]:
    """Every reason the brief at ``path`` does not count as written, each named once."""
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return ["missing"]
    found = brief_sections(text)
    out = []
    for heading in BRIEF_HEADINGS:
        body = found.get(heading.lower())
        if body is None:
            out.append(f"without a '{heading}' heading")
        elif len(body) < 20:
            out.append(f"empty under '{heading}'")
    if real_mass_in(found.get("size and material", "")) is None:
        out.append("without a line 'Real mass: <number> kg' under 'Size and material'")
    import re
    if "use" in found and use_table_in(found.get("use", "")) is None:
        out.append("without its 'Use table: {...}' JSON line at the end of the Use section (objectives/brief.md "
                   "§2, Use)")
    size = found.get("size and material", "")
    if not re.search(r"real thinnest member:\s*[0-9]", size, flags=re.I):
        out.append("without a line 'Real thinnest member: <number> m' under 'Size and material'")
    section = real_section_in(size)
    if section is None:
        out.append("without a line 'Real section (<Load path member>): " + SECTION_SHAPES + "' under 'Size and "
                   "material' (the real governing member's section, the one its thinnest member is part of)")
        return out
    member = real_member_in(size)
    if section.get("shape"):
        return out          # the runner computed I and A from the shape: nothing to bound
    # Bounds every section obeys, whatever its shape: its second moment cannot exceed its whole
    # area at the extreme fibres, and a wall this thin spanning this depth has at least that area.
    depth, inertia, area = section["depth_m"], section["I_m4"], section["A_m2"]
    # beside the brief's snapshots, outside the folder the agent writes
    record_path = (path.parent.parent / "brief_snapshots" if path.parent.name == "operator"
                   else path.parent) / "section_refused.json"
    if inertia > area * depth ** 2 / 4 * 1.001:
        # The numbers that conflict and what would agree, so the inconsistent one is found rather
        # than I lowered to pass (one run: depth 0.118 m beside an I taken about
        # the 0.178 m side, and "I estimated at 4.5e-5").
        lib.write_json(record_path, {"depth_m": depth, "I_m4": inertia, "A_m2": area})
        out.append(f"Real section: I {inertia:.4g} m4 exceeds A x (depth/2)^2 = {area * depth ** 2 / 4:.4g} "
                   f"(A {area:.4g} m2, depth {depth:.4g} m), which no section reaches. With this A and I the "
                   f"depth is at least 2 x sqrt(I/A) = {2 * (inertia / area) ** 0.5:.4g} m; with this depth and "
                   f"A, I is at most {area * depth ** 2 / 4:.4g} (a solid rectangle A d^2/12 = "
                   f"{area * depth ** 2 / 12:.4g}, a thin-walled box about A d^2/6 = {area * depth ** 2 / 6:.4g}). "
                   "The depth is the section's full extent in the direction it bends, the one I is taken "
                   "about: find which number is wrong and recompute it from the section's shape")
    else:
        refused = lib.read_json(record_path) if record_path.exists() else None
        if (refused and inertia < refused["I_m4"] and abs(depth - refused["depth_m"]) <= 0.01 * depth
                and abs(area - refused["A_m2"]) <= 0.01 * area and not section_computed(size, inertia)):
            out.append(f"Real section: I was lowered from {refused['I_m4']:.4g} to {inertia:.4g} m4 with the "
                       "depth and A unchanged after the bound refused it: show I's computation under the Real "
                       "section line (the formula of the section's shape with its dimensions, which the runner "
                       "evaluates: it must give the stated I within 5 %), or "
                       "correct the depth or A that conflicted")
    if member and section["A_m2"] < 0.75 * section["depth_m"] * min(member, section["depth_m"]):
        out.append(f"Real section: A {section['A_m2']:.4g} m2 is less than a wall of the real thinnest member "
                   f"({member} m) across the depth ({section['depth_m']} m) holds: recompute it")
    return out


PRE_BODY_STOPS = ("plan", "revision", "drawing", "web_image")   # stops a run reaches before any body exists
SOLID_SECTION_SHAPE = 0.1    # I / (A depth^2) under this: a solid section (rectangle 1/12, disc 1/16);
#                              thin walls (tube 1/8, box 1/6, I-beam up to 1/4) read above it
FAR_THINNER = 0.5            # a stated member under half the solid section's thinnest dimension


def brief_member_warning(operator: Path) -> str | None:
    """The brief's Real thinnest member is the member of the Real section the load passes
    through.  A solid Real section (``SOLID_SECTION_SHAPE``) has no wall thinner than about
    min(depth, A / depth); a stated member far under that is another, unloaded part (two runs:
    a rim and a side wall), which forces the section stand-in.  A warning."""
    try:
        size = brief_sections((operator / "brief.md").read_text(encoding="utf-8")).get("size and material", "")
    except OSError:
        return None
    member, section = real_member_in(size), real_section_in(size)
    if not member or not section:
        return None
    shape = section["I_m4"] / (section["A_m2"] * section["depth_m"] ** 2)
    thinnest = min(section["depth_m"], section["A_m2"] / section["depth_m"])
    if shape >= SOLID_SECTION_SHAPE or member >= FAR_THINNER * thinnest:
        return None
    return (f"brief: Real thinnest member {member:g} m is far thinner than its Real section suggests (a solid "
            f"section, I/(A depth^2) = {shape:.3g}, about {thinnest:.3g} m at its thinnest): the Real thinnest "
            "member is the thinnest member the load passes through, part of the Real section's member; a "
            "thinner part that carries no load is plan.thin_off_load_path, not this line. Correct the brief "
            "now, before a body exists (the real lines are kept as they stand then); a raised member is taken only "
            "with a line 'Thinnest member why: <reason>' and is listed in the verdict")


# ------------------------------------------------------------- the instruction --
# The user's instruction, stored by `start` (no API call: the use anchor, a second reading of the
# use by a specialist call at `start`, was removed on 2026-10-11; the operator skill makes no API
# call of its own).  The checks read it only to tell a size the instruction states ("given").
INSTRUCTION = "instruction.json"
LEGACY_INSTRUCTION = "use_anchor.json"    # where a session from before 2026-10-11 stored the instruction


def store_instruction(session: Path, instruction: str, given: str | None = None) -> dict[str, Any]:
    """The instruction as `start` received it: beside the brief's snapshots (outside the folder
    the agent writes) and in operator/ for the agent to read."""
    record: dict[str, Any] = {"instruction": instruction, "time": time.time()}
    if given is not None and given != instruction:
        record["instruction_given"] = given
    operator = lib.operator_dir(session)
    operator.mkdir(parents=True, exist_ok=True)
    lib.write_json(operator / INSTRUCTION, record)
    (session / "brief_snapshots").mkdir(exist_ok=True)
    lib.write_json(session / "brief_snapshots" / INSTRUCTION, record)
    return record


def stored_instruction(operator: Path) -> str:
    """The user's instruction `start` stored ("" without one)."""
    for name in (INSTRUCTION, LEGACY_INSTRUCTION):
        record = lib.read_json(operator.parent / "brief_snapshots" / name, None)
        if isinstance(record, dict) and record.get("instruction"):
            return str(record["instruction"])
    return ""


# ------------------------------------------------------------------- G1: use --
# The Use table (objectives/brief.md §2, Use): one row per action of the use, each with its state,
# size, unit, source, direction, the Load path member it enters and the contacts holding the object
# meanwhile; ``run`` names the state the solve applies.  Every action of a state acts together (a
# state is the case: agents split a push and a press that always act together into two cases, and
# the hold of the one left out went with it).
#
# The runner derives each row's effect at each Load path member (``runner_effects``): a force
# times its lever, the distance from its entry to the hold, taken as the largest Real extent unless
# the row gives ``lever_m``; a twist as it is; at every member from the one it enters to the end of
# the Load path (the members are listed from the loads to the holds).  Agents wrote these numbers
# by hand until 2026-10-11, which doubled the tokens of a run (48 brief edits against 13) and invited
# the lever and zero-effect rules that policed them; a per-row "effect" is now ignored.  The states
# are compared member by member (``use_coverage``): where another state exceeds the run by more
# than a third, the run is refused unless the table declares that member uncovered with the
# workflow limit that keeps it out, which the report prints and which makes the verdict a
# simplified case.  The Real section's member is read for G3's stress, with the levers measured on
# the regions once they exist (``region_levers``).
COVERAGE_SHARE = 0.75
COVERAGE = "coverage.json"
# The limits a member may be left uncovered for: what the workflow cannot apply in a linear static
# solve, never "small" or "another time" (the reasons runs dropped loads for).
WORKFLOW_LIMITS = ("pressure inside a closed cavity", "contact between separate bodies", "large deflection",
                   "dynamic or impact", "temperature")
# The limits whose state a static stand-in can still carry: a declaration of one says why it does not.
APPROXIMATED_LIMITS = {"dynamic or impact": "an inertial approximation (the row's weight x a stated dynamic factor, "
                                            "or an acceleration on the body)",
                       "contact between separate bodies": "a reaction approximation (the separate body's force "
                                                          "applied as a load on its contact face)"}
UNCOVERED_FORM = ('the Use table\'s "uncovered" is {"<Load path member>": {"limit": "<one of '
                  + " | ".join(WORKFLOW_LIMITS) + '>", "why": "<what of that limit acts there>"}}')
DYNAMIC_FACTOR_CAP = 3.0    # an H row sized "x a stated dynamic factor": its top times at most this
ACTION_KINDS = ("applied", "weight", "environment")
AS_ROW = re.compile(r"as\s+(\S+)")    # a Use table row's "source": "as A1" (structured data, not prose)
USE_TABLE_FORM = ('Use table: {"actions": {"A1": {"load": "<name>", "state": "working" | "handling" | "assembly" | '
                  '"storage", "kind": "applied" | "weight" | "environment", "size": <n>, "unit": "N" | "N m", '
                  '"source": "H<k> top" | "<m> kg x g x <factor>" | "derived: <formula>" | "given" | "as A<k>", '
                  '"direction": [x, y, z], "enters": "<Load path member>", "held": ["<contact>", ...]}}, '
                  '"run": "<state>"}')
EFFECT_UNIT = "N m"         # every runner effect is a moment: a force times its lever, a twist as it is


def human_rows() -> dict[str, dict[str, Any]]:
    """cae_practice.md's Human actions table by id ("H1", ...): each row's range and unit, and
    whether its top is times a stated dynamic factor."""
    try:
        text = (SKILL_DIR / "references" / "cae_practice.md").read_text(encoding="utf-8")
    except OSError:
        return {}
    out = {}
    for line in text.splitlines():
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) < 3 or not re.fullmatch(r"H\d+", cells[0]):
            continue
        found = re.search(r"(\d+(?:\.\d+)?)\s*[–-]\s*(\d+(?:\.\d+)?)\s*(N m|N)\b", cells[2])
        if found:
            out[cells[0]] = {"low": float(found.group(1)), "high": float(found.group(2)), "unit": found.group(3),
                             "dynamic": "dynamic factor" in cells[2], "action": cells[1]}
    return out


def _number(value: Any) -> float | None:
    return float(value) if isinstance(value, (int, float)) and not isinstance(value, bool) else None


def _member_of(name: Any, members: dict[str, str]) -> str | None:
    """The Load path member ``name`` is, by its words (case, spacing and plural endings aside)."""
    keys = {_member_key(m): m for m in members}
    return keys.get(_member_key(str(name))) if isinstance(name, str) else None


def _row_state(key: str, row: Any, actions: Any = None) -> str | None:
    """A row's own "state"."""
    return row.get("state") if isinstance(row, dict) and row.get("state") in USE_STATES else None


def _table_text(operator: Path, text: str | None = None) -> tuple[dict[str, Any] | None, str]:
    try:
        text = text if text is not None else (operator / "brief.md").read_text(encoding="utf-8")
    except OSError:
        return None, ""
    return use_table_in(brief_sections(text).get("use", "")), text


def run_held(operator: Path, text: str | None = None) -> tuple[str | None, set[str] | None]:
    """The Use table's run state and the contacts its rows hold, read straight from the brief (no
    contacts read, so the contacts reader can use it): (None, None) without a table."""
    table, _ = _table_text(operator, text)
    if not isinstance(table, dict) or not isinstance(table.get("actions"), dict):
        return None, None
    run = table.get("run")
    if run not in USE_STATES:
        return None, None
    held = {h for k, row in table["actions"].items() if _row_state(k, row) == run and isinstance(row, dict)
            for h in (row.get("held") or []) if isinstance(h, str)}
    return run, held


def run_contacts_of(contacts: dict[str, dict[str, Any]] | None,
                    held: set[str] | None) -> dict[str, dict[str, Any]] | None:
    """The contacts the run state's rows hold (by their words): the only contacts the checks and
    plan.contacts key on; the other states keep their holds in the Use table's "held" alone."""
    if not contacts or not held:
        return contacts
    keys = {_name_key(h) for h in held}
    return {k: v for k, v in contacts.items() if _name_key(k) in keys}


def use_table(operator: Path, brief: Path | None = None) -> tuple[dict[str, Any] | None, list[str]]:
    """The brief's Use table checked whole: (the table read, every problem).  None and the problem
    without a table.  ``brief``: another copy of the brief to read (the solve snapshot, for the
    verdict); the contacts are then that copy's, else the ones frozen at the body
    (``brief_contacts_v2``)."""
    try:
        text = (brief or operator / "brief.md").read_text(encoding="utf-8")
    except OSError:
        return None, []
    sections = brief_sections(text)
    table = use_table_in(sections.get("use", ""))
    if not isinstance(table, dict) or not isinstance(table.get("actions"), dict) or not table["actions"]:
        return None, [f"the Use section ends with one line {USE_TABLE_FORM}: a row for every action of the use's "
                      "working, handling and assembly states that loads the object (objectives/brief.md §2, Use)"]
    size = sections.get("size and material", "")
    members = load_path_in(size) or {}
    rows, out = table["actions"], []
    malformed = contacts_json_problems(sections.get("contacts", ""))
    out += malformed
    if brief is None:
        contacts = brief_contacts_v2(operator) or {}
        out += contacts_frozen_problems(operator)
    else:
        contacts = run_contacts_of(contacts_v2_in(sections.get("contacts", "")), run_held(operator, text)[1]) or {}
    run = table.get("run")
    if not isinstance(run, str) or run not in USE_STATES:
        out.append(f"the Use table's \"run\" is {json.dumps(run)[:80]}: the state the solve applies, one of "
                   f"{list(USE_STATES)} (every action of that state acts together)")
        run = None
    instruction = stored_instruction(operator)
    if not members:
        out.append("the Use table's members are the Load path's: add the line " + LOAD_PATH_FORM
                   + " under Size and material")
    star = real_section_member_in(size)
    if star is None:
        out.append("the Real section line names its member, 'Real section (<Load path member>): ...': the member the "
                   "stress is read at")
    elif members and _member_of(star, members) is None:
        out.append(f"the Real section's member {star!r} is not a member of the Load path {list(members)}")
    extents = real_extents_in(size)
    if extents is None:
        out.append("without a line 'Real extents: <a> x <b> x <c> m' under Size and material (the real object's "
                   "extents in the use frame)")
    humans = human_rows()
    sizes: dict[str, tuple[float, Any]] = {}
    state_of: dict[str, str] = {}
    zero: set[str] = set()
    entry: dict[str, str] = {}
    levers: dict[str, float] = {}
    filled_sizes: dict[str, float] = {}
    for key, row in rows.items():
        where = f"Use table row {key}"
        if not isinstance(row, dict):
            out.append(f"{where} is an object: {USE_TABLE_FORM}")
            continue
        if row.get("state") not in USE_STATES or row.get("kind") not in ACTION_KINDS:
            out.append(f"{where}: \"state\" ({' | '.join(USE_STATES)}) and \"kind\" ({' | '.join(ACTION_KINDS)})")
            if row.get("state") not in USE_STATES:
                continue
        state_of[key] = row["state"]
        source = str(row.get("source") or "").strip()
        same = AS_ROW.fullmatch(source)
        if same:
            # A minor action sized as another row: its size, unit and source are that row's.
            base = rows.get(same.group(1))
            base_source = str(base.get("source") or "").strip() if isinstance(base, dict) else ""
            if same.group(1) == key or not isinstance(base, dict) or not base_source or AS_ROW.fullmatch(base_source):
                out.append(f"{where}: \"source\": \"as <row>\" names another row of this table that gives its own "
                           "size and source")
                continue
            base_size = _number(base.get("size"))
            if base_size is None and sized_by_source(base_source, humans):
                base_size = sized_by_source(base_source, humans)[0]       # the size the runner fills there
            given_size = _number(row.get("size"))
            if row.get("size") is not None and (given_size is None or base_size is None
                                                or abs(given_size - base_size) > 1e-9 * max(abs(base_size), 1.0)):
                out.append(f"{where}: sized \"as {same.group(1)}\", it leaves \"size\" out or gives "
                           f"{same.group(1)}'s, " + (f"{base_size:.6g}" if base_size is not None else "none yet"))
            # left out, the size is filled from the source below as the base row's is
            row = {**row, "size": base.get("size") if row.get("size") is None else base_size,
                   "unit": row.get("unit") or base.get("unit"), "source": base_source}
            source = base_source
        in_run = state_of[key] == run
        filled = sized_by_source(source, humans)
        if TIPPING_CAP_SOURCE.fullmatch(source):
            # the cap the runner computed at the tipping refusal (tipping_excess), never the agent's number
            cap = ((lib.read_json(operator / TIPPING_CAPS, {}) or {}).get(key) or {}).get("cap")
            filled = (float(cap), "N") if isinstance(cap, (int, float)) and cap > 0 else None
            if filled is None:
                out.append(f"{where}: \"source\": \"tipping cap\" is the cap the runner computed for this row at a "
                           "tipping refusal, and it computed none for it")
        if filled is not None:
            computed, unit_from = filled
            given = _number(row.get("size"))
            if given is None:
                # the runner's own arithmetic: a weight's mass x g x factor, a Human actions row's value
                row = {**row, "size": computed, "unit": row.get("unit") or unit_from}
                filled_sizes[key] = computed
            elif ((WEIGHT_SOURCE.match(source) or DERIVED_SOURCE.match(source)) and computed > 0
                  and abs(given / computed - 1) > 0.02):
                out.append(f"{where}: \"size\" {given:g} is not its source {source!r} = {computed:.4g} "
                           f"{unit_from or row.get('unit') or ''}: leave \"size\" out and the runner computes it")
        size_ = _number(row.get("size"))
        if size_ == 0 and row.get("kind") == "environment":
            # heat, humidity, light: an action of the surroundings that is no force is a row of size
            # 0, whose effect is 0 everywhere; it needs no hold and no binding
            zero.add(key)
            continue
        if DERIVED_SOURCE.match(source) and filled is None:
            out.append(f"{where}: \"source\" {source!r} is a derivation the runner cannot evaluate: write it as one "
                       f"arithmetic expression of numbers, each with its units ({DERIVED_UNIT_WORDS}), \"g\" for "
                       "gravity, and leave \"size\" out: the runner computes it")
        elif DERIVED_SOURCE.match(source):
            untraced = derivation_problem(source)
            if untraced:
                out.append(f"{where}: \"source\" {source!r} {untraced}")
        held = row.get("held")
        if held is not None and (not isinstance(held, list) or not all(isinstance(h, str) for h in held)):
            out.append(f"{where}: \"held\" is a list of the contacts that hold the object meanwhile")
        elif in_run and not held:
            out.append(f"{where}: \"held\" names the contacts of the Contacts JSON that hold the object while the "
                       "run state acts (at least one)")
        if size_ is None or size_ <= 0:
            out.append(f"{where}: \"size\" is a number over 0 (0 only for an action of the surroundings that is no "
                       "force), or left out where the source fixes it (\"<m> kg x g x <factor>\", \"H<k> top\", "
                       "\"derived: <formula>\")")
        if row.get("unit") not in USE_UNITS:
            out.append(f"{where}: \"unit\" is \"N\" or \"N m\"")
        if not source:
            out.append(f"{where}: \"source\" names where the size comes from: a Human actions row of cae_practice.md "
                       "(\"H<k> top\" or \"H<k> middle\"), a weight (\"<m> kg x g x <factor>\"), \"derived: "
                       "<formula>\", \"given\", or \"as <row>\" (a minor action sized as another row)")
        if source.lower().startswith("given") and size_ is not None and instruction and not given_in(size_, instruction):
            out.append(f"{where}: \"source\": \"given\", but the user's instruction states no {size_:g} (nor that "
                       f"in kg x g or in kN; it states {_numbers(instruction) or 'no number'}): a size from elsewhere "
                       "is a Human actions row, a weight or \"derived: <formula>\"")
        if size_ is not None and size_ > 0 and row.get("unit") in USE_UNITS:
            sizes[key] = (size_, row.get("unit"))
        human = re.match(r"(H\d+)\b", source)
        if human and size_ is not None:
            band = humans.get(human.group(1))
            factored = HUMAN_SOURCE.match(source)
            if band is None:
                out.append(f"{where}: {human.group(1)} is not a row of cae_practice.md's Human actions ({sorted(humans)})")
            elif factored and factored.group(3) and not band["dynamic"]:
                # a factor the row cannot take was dropped without a word until 2026-10-11
                out.append(f"{where}: \"source\" {source!r} gives a factor, and {human.group(1)} takes no dynamic "
                           f"factor (cae_practice.md, Human actions): write \"{human.group(1)} "
                           f"{factored.group(2).lower()}\", or a weight or \"derived: <formula>\" for a shock")
            else:
                top = band["high"] * (DYNAMIC_FACTOR_CAP if band["dynamic"] else 1.0)
                if row.get("unit") != band["unit"] or not band["low"] * 0.99 <= size_ <= top * 1.01:
                    out.append(f"{where}: {size_:g} {row.get('unit')} is outside {human.group(1)}'s range, "
                               f"{band['low']:g}-{band['high']:g} {band['unit']}"
                               + (f" (x a stated dynamic factor, at most {DYNAMIC_FACTOR_CAP:g})" if band["dynamic"] else ""))
        if varies_problem(row):
            out.append(f"{where}: {varies_problem(row)}")
        enters = _member_of(row.get("enters"), members) if members else None
        if members and enters is None:
            out.append(f"{where}: \"enters\" {row.get('enters')!r} is not a member of the Load path {list(members)}")
        elif enters is not None:
            entry[key] = enters
        lever = _number(row.get("lever_m"))
        if lever is not None and lever >= 0:
            # the agent's one optional number, the fallback before the regions exist (0: the load sits
            # at its own hold, the one way to a lever of 0); never longer than the object (a lever
            # outside it is no lever of this object)
            levers[key] = min(lever, max(extents)) if extents else lever
    cases: dict[str, list[str]] = {}
    for key, state in state_of.items():
        cases.setdefault(state, []).append(key)
    if run is not None and run not in cases:
        out.append(f"\"run\" {run!r} is no state of the Use table's rows ({list(cases)})")
    table_out = {"rows": rows, "cases": cases, "run": run, "members": members,
                 "member": _member_of(star, members) if star and members else None, "state_of": state_of,
                 "contacts": contacts, "sizes": sizes, "contacts_malformed": bool(malformed),
                 "zero": zero, "extents": extents, "entry": entry, "levers": levers, "filled": filled_sizes}
    table_out["paths"], table_out["default_levers"] = row_paths(table_out)
    # A stated lever_m under the geometric default is taken only with its "lever_why": a small one on
    # another state's row cleared a coverage refusal (review of 2026-10-11).  Set aside, said, never refused.
    table_out["levers_set_aside"] = []
    for key in list(levers):
        row = rows.get(key) if isinstance(rows.get(key), dict) else {}
        default = table_out["default_levers"].get(key)
        if default is not None and state_of.get(key) != run and levers[key] < default and not str(row.get("lever_why") or "").strip():
            table_out["levers_set_aside"].append(
                f"{key}: lever_m {levers.pop(key):g} m under the default {default:.3g} m without \"lever_why\": "
                "the default is used")
    table_out["effects"] = runner_effects(table_out)
    declared = table.get("uncovered") if isinstance(table.get("uncovered"), dict) else {}
    if "uncovered" in table and (not isinstance(table.get("uncovered"), dict) or not all(
            isinstance(v, dict) and v.get("limit") in WORKFLOW_LIMITS and str(v.get("why") or "").strip()
            for v in declared.values())):
        out.append(UNCOVERED_FORM)
    stray = [m for m in declared if members and _member_of(m, members) is None]
    if stray:
        out.append(f"the Use table's \"uncovered\" names {stray}, not members of the Load path {list(members)}")
    # The limit is one the rows loading that member meet: a twist (N m) is applied as a couple of
    # tangential tractions, never "contact" or "pressure"; "temperature" is an action of the
    # surroundings (one run left its governing state out under a limit its rows did not have).
    effects = table_out["effects"]
    for m, v in declared.items():
        member = _member_of(m, members) if members else None
        if member is None or not isinstance(v, dict):
            continue
        loading = [k for k in effects if state_of.get(k) != run and effects[k].get(member, 0) > 0]
        if not loading:
            continue
        top = max(loading, key=lambda k: effects[k].get(member, 0))
        unit = (sizes.get(top) or (None, row_unit(rows[top])))[1]
        kind = rows[top].get("kind")
        h = re.match(r"(H\d+)\b", str(rows[top].get("source") or ""))
        dynamic = bool(rows[top].get("dynamic")) or kind == "environment" or bool(h and humans.get(h.group(1), {}).get("dynamic"))
        limit, said = v.get("limit"), None
        if limit in ("contact between separate bodies", "pressure inside a closed cavity") and unit == "N m":
            said = (f"its dominant row {top} is a twist: a torque about an axis is applied as a couple of tangential "
                    "tractions on opposite faces, which the workflow runs")
        elif (limit == "contact between separate bodies" and member == table_out["member"]
              and not separate_body_on(table_out, sections, rows[top], member)):
            # The Real section's member may be declared (its governing load not applied), but only for a
            # contact that is one (review of 2026-10-11).
            said = (f"it is the Real section's member, and no separate body touches it there: its dominant row {top} "
                    "is held by no rest or hang on it, and the Contacts JSON has no contact on it")
        elif limit == "temperature" and kind != "environment":
            said = f"its dominant row {top} is no action of the surroundings"
        elif limit == "dynamic or impact" and not dynamic:
            said = (f"its dominant row {top} is neither an action of the surroundings nor marked dynamic (\"dynamic\": "
                    "true, or a Human actions row x a dynamic factor)")
        elif limit == "large deflection" and not large_deflection(operator, extents):
            said = (f"the runner's deflection over length is not over {DEFLECTION_OVER_LENGTH:g} for the declared "
                    "prediction")
        elif limit in APPROXIMATED_LIMITS and not str(v.get("no_approximation") or "").strip():
            # the review of 2026-10-12: a governing state left uncovered that a static stand-in could run
            said = (f"the workflow can apply {APPROXIMATED_LIMITS[limit]}: run that state so, or add \"no_approximation\": "
                    "\"<why it does not apply here>\", one line")
        if said:
            out.append(f"the Use table's \"uncovered\" gives {m!r} the limit {limit!r}, and {said}")
    # The Real section's member may be declared too: its governing load then cannot be applied, and the
    # verdict says so (a refusal here left a governing load no exit, review of 2026-10-11).
    table_out["declared_uncovered"] = {_member_of(m, members): f"{v.get('limit')}: {v.get('why')}"
                                       for m, v in declared.items()
                                       if members and _member_of(m, members) and isinstance(v, dict)}
    return table_out, out


# A size the source fixes is the runner's to compute: a weight's "<m> kg x g x <factor>", a Human
# actions row's "H<k> top | middle | bottom" (times a stated dynamic factor for a row that takes one).
WEIGHT_SOURCE = re.compile(r"([0-9]+(?:\.[0-9]+)?(?:e[-+]?[0-9]+)?)\s*kg\s*(?:x|×|\*)\s*g"
                           r"(?:\s*(?:x|×|\*)\s*([0-9]+(?:\.[0-9]+)?))?", re.I)
HUMAN_SOURCE = re.compile(r"(H\d+)\s+(top|middle|bottom)(?:\s*(?:with|x|×|\*)\s*(?:a\s+)?(?:dynamic\s+)?"
                          r"(?:factor\s*(?:of\s*)?)?([0-9]+(?:\.[0-9]+)?))?", re.I)


# A derivation is the runner's arithmetic too: "derived: <formula>" in numbers and their units, which
# the runner evaluates (until 2026-10-11 the agent computed its size by hand beside it).  Each unit
# word after a number multiplies it into SI; "g" alone is standard gravity.
DERIVED_SOURCE = re.compile(r"derived:\s*(.*)", re.I | re.S)
DERIVED_UNITS = {"mm": 1e-3, "cm": 1e-2, "m": 1.0, "km": 1e3, "mm2": 1e-6, "cm2": 1e-4, "m2": 1.0,
                 "mm3": 1e-9, "cm3": 1e-6, "m3": 1.0, "l": 1e-3, "kg": 1.0, "t": 1e3, "n": 1.0, "kn": 1e3,
                 "pa": 1.0, "kpa": 1e3, "mpa": 1e6, "bar": 1e5, "s": 1.0, "s2": 1.0, "rad": 1.0, "%": 0.01,
                 "h": 3600.0, "min": 60.0}
DERIVED_UNIT_WORDS = ("mm, cm, m, km, mm2, cm2, m2, mm3, cm3, m3, l, kg, t, N, kN, Pa, kPa, MPa, bar, s, h, min, "
                      "rad, % (and compounds: kg/m3, m/s2, N/mm2, km/h)")


def derived_value(source: str) -> float | None:
    """The value of a "derived: <formula>" source, or None when it is no formula the runner reads:
    one arithmetic expression of numbers (x, ×, *, /, +, -, ^ or **, parentheses, a leading minus),
    each number followed by its units (DERIVED_UNITS, SI after the factor; a unit after "/" divides,
    as kg/m3 or km/h) and "g" for standard gravity.  A bare number is its own value."""
    import ast
    import operator as op
    found = DERIVED_SOURCE.match((source or "").strip())
    if not found:
        return None
    text = found.group(1).replace("²", "2").replace("³", "3").replace("−", "-").replace("**", "^")
    # Each number with its units is one bracketed term "(n*f)", so a unit after "/" divides the term
    # it belongs to, not the next number ("100 N / 2 mm2" was 5e-05 until 2026-10-11).
    tokens = [t for t in re.findall(r"\d+(?:\.\d*)?(?:[eE][-+]?\d+)?|\.\d+|[A-Za-z%]+\d?|[x×·*/+\-^()]|\s+", text)
              if not t.isspace()]
    parts: list[str] = []
    previous, term = "op", 0

    def is_unit(word: str) -> bool:
        return word.lower() in DERIVED_UNITS and not re.fullmatch(r"[\d.].*", word)
    k = 0
    while k < len(tokens):
        word = tokens[k]
        if re.fullmatch(r"[\d.].*", word):
            parts.append(word)
            term, previous = len(parts) - 1, "value"
        elif word in ("x", "×", "·", "*"):
            parts.append("*")
            previous = "op"
        elif word == "/" and previous == "unit" and k + 1 < len(tokens) and is_unit(tokens[k + 1]):
            k += 1                                  # a compound unit's denominator: kg/m3, km/h
            parts[term:] = [f"({''.join(parts[term:])}/{DERIVED_UNITS[tokens[k].lower()]!r})"]
            previous = "unit"
        elif word == ")":
            depth, start = 0, len(parts)
            for start in range(len(parts) - 1, -1, -1):
                depth += {")": 1, "(": -1}.get(parts[start], 0)
                if parts[start] == "(" and depth == -1:
                    break
            parts.append(")")
            term, previous = start, "value"
        elif word in "/+-^(":
            parts.append("**" if word == "^" else word)
            previous = "op"
        elif previous == "op" and word == "g":
            parts.append("9.80665")
            term, previous = len(parts) - 1, "value"
        elif previous in ("value", "unit") and is_unit(word):
            parts[term:] = [f"({''.join(parts[term:])}*{DERIVED_UNITS[word.lower()]!r})"]
            previous = "unit"
        else:
            return None
        k += 1
    ops = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul, ast.Div: op.truediv, ast.Pow: op.pow}

    def value(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return float(node.value)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd)):
            return -value(node.operand) if isinstance(node.op, ast.USub) else value(node.operand)
        if isinstance(node, ast.BinOp) and type(node.op) in ops:
            return ops[type(node.op)](value(node.left), value(node.right))
        raise ValueError(node)
    try:
        return value(ast.parse("".join(parts), mode="eval").body)
    except (SyntaxError, ValueError, ZeroDivisionError, OverflowError, TypeError):
        return None


# A derivation shows its formula (the review of 2026-10-12: refused "given" sizes relabelled "derived:
# 60 N"): at least two quantities ("g" counts) joined by an operation.  Which numbers it uses is not
# judged here (outside constants, densities and pressures, are fair); a cut after the body is caught by
# rows_lowered_since_body.
def derivation_problem(source: str) -> str | None:
    """What a "derived: <formula>" source lacks to be a derivation, or None."""
    formula = (DERIVED_SOURCE.match((source or "").strip()) or [None, ""])[1]
    numbers = re.findall(r"\d+(?:\.\d+)?(?:[eE][-+]?\d+)?|\.\d+", formula)
    quantities = len(numbers) + len(re.findall(r"(?<![A-Za-z])g(?![A-Za-z])", formula))
    if quantities >= 2 and re.search(r"[x×·*/+^]|(?<=\S)\s-\s", formula):
        return None
    return ("is a bare number, no derivation: \"derived\" shows the formula, two or more quantities with their "
            "units joined by x, /, + or - (\"g\" counts); else source the row from a Human actions row, a weight, "
            "or \"given\" when the instruction states it")


def sized_by_source(source: str, humans: dict[str, dict[str, Any]]) -> tuple[float, str | None] | None:
    """(size, unit) a row's source fixes, or None: a weight, mass x g x its factor; a Human actions
    row, its top, middle or bottom (times a stated factor, at most DYNAMIC_FACTOR_CAP, for a row
    that takes one); a derivation, its formula's value (``derived_value``; the row states the unit)."""
    if DERIVED_SOURCE.match((source or "").strip()):
        value = derived_value(source)
        return (value, None) if value is not None else None
    weight = WEIGHT_SOURCE.match((source or "").strip())      # the source itself, never a step of a derivation
    if weight and not (source or "").strip()[weight.end():].strip(" ,;").startswith(("/", "x", "×", "*", "+", "-")):
        return float(weight.group(1)) * 9.80665 * float(weight.group(2) or 1.0), "N"
    human = HUMAN_SOURCE.match((source or "").strip())
    band = humans.get(human.group(1).upper()) if human else None
    if not band:
        return None
    value = {"top": band["high"], "bottom": band["low"],
             "middle": (band["low"] + band["high"]) / 2}[human.group(2).lower()]
    if human.group(3) and band["dynamic"]:
        value *= min(float(human.group(3)), DYNAMIC_FACTOR_CAP)
    return value, band["unit"]


def separate_body_on(table: dict[str, Any], sections: dict[str, str], row: dict[str, Any], member: str) -> bool:
    """Whether a separate body touches ``member`` where ``row`` acts: a rest or hang of the run holding
    the row on it, or a contact of the brief's Contacts JSON (any state) on the member the row enters,
    a load passed through contact by a body that is no hold (review of 2026-10-11)."""
    contacts = table.get("contacts") or {}
    if any(hold_member(table, h) == member and (contacts.get(h) or {}).get("kind") in ("rest", "hang")
           for h in row.get("held") or [] if isinstance(h, str)):
        return True
    every = {**(contacts_v2_in(sections.get("contacts", "")) or {}), **contacts}
    whole = {**table, "contacts": every}
    return (_member_of(row.get("enters"), table.get("members") or {}) == member
            and any(hold_member(whole, c) == member for c in every))


def hold_member(table: dict[str, Any], name: str) -> str | None:
    """The Load path member a hold sits on: its contact's ``member``, else the member its name
    names whole (a contact named after the member it holds), else one whose head word it shares
    when only one does."""
    members = list(table.get("members") or {})
    contacts = table.get("contacts") or {}
    entry = contacts.get(name) or next((v for k, v in contacts.items() if _name_key(k) == _name_key(name)), None)
    if entry and entry.get("member"):
        found = _member_of(entry["member"], table.get("members") or {})
        if found:
            return found
    named = [m for m in members if _named_in(m, name)]
    if named:
        return max(named, key=lambda m: len(_member_key(m)))
    shared = [m for m in members if _members_match(name, m)]
    return shared[0] if len(shared) == 1 else None


SAME_MEMBER_STEP = 0.5      # a row held on the member it enters: half a member step from its hold


def row_paths(table: dict[str, Any]) -> tuple[dict[str, list[str]], dict[str, float]]:
    """Each row's path and default lever, from its ``enters`` and ``held`` alone, whatever the Load
    path's list order: the members between its entry and each of its holds (both ends included).
    The lever is the largest Real extent times the nearest hold's distance along the path over the
    path's length (equal members assumed), and a row that enters the member it is held on is half a
    member step from its hold, never 0: a one-member load path gave every force row 0 while a twist
    kept its N m, and naming a hold on the entry member cleared any coverage (review of
    2026-10-11).  Without a hold on the path, every member and half the largest extent.  Only a row's
    explicit ``lever_m`` (0: it sits at its hold) stands before the regions; once they exist the
    measured arm replaces both (``region_levers``)."""
    members = list(table.get("members") or {})
    reach = max(table.get("extents") or [0.0])
    paths, levers = {}, {}
    for key, row in (table.get("rows") or {}).items():
        if not isinstance(row, dict):
            continue
        entry = table.get("entry", {}).get(key)
        holds = [m for m in (hold_member(table, h) for h in row.get("held") or [] if isinstance(h, str)) if m]
        if entry not in members or not holds:
            paths[key], levers[key] = members, reach / 2
            continue
        e = members.index(entry)
        spans = [members.index(h) for h in holds]
        paths[key] = [m for k, m in enumerate(members) if any(min(e, h) <= k <= max(e, h) for h in spans)]
        nearest = max(min(abs(e - h) for h in spans), SAME_MEMBER_STEP)
        levers[key] = reach * nearest / max(len(members) - 1, 1)
    return paths, levers


def row_lever(table: dict[str, Any], key: str) -> float:
    """A row's lever before the regions exist: its ``lever_m``, else its default (``row_paths``)."""
    given = table.get("levers", {}).get(key)
    if given is not None:
        return float(given)
    default = table.get("default_levers", {}).get(key)
    return float(default if default is not None else max(table.get("extents") or [0.0]) / 2)


def loaded_members(table: dict[str, Any], key: str) -> list[str]:
    """The Load path members a row loads: its path from its entry to its holds (``row_paths``)."""
    paths = table.get("paths") or {}
    return list(paths.get(key) or table.get("members") or {})


def runner_effects(table: dict[str, Any], levers: dict[str, float] | None = None) -> dict[str, dict[str, float]]:
    """Each row's effect at each Load path member on its path (``loaded_members``), in N m: a force
    times its lever (``levers``, measured on the regions, else ``row_lever``), a twist as it is.
    The effect is the same at every member it loads (the moment at the hold bounds the moment
    along the path); a size-0 row loads nothing."""
    out: dict[str, dict[str, float]] = {}
    for key, (size, unit) in (table.get("sizes") or {}).items():
        if key in table.get("zero", ()):
            continue
        lever = (levers or {}).get(key)
        moment = size if unit == "N m" else size * (lever if lever is not None else row_lever(table, key))
        out[key] = {m: moment for m in loaded_members(table, key)}
    return out


def large_deflection(operator: Path, extents: list[float] | None) -> bool:
    """Whether the declared brief case's deflection over the largest Real extent is past
    DEFLECTION_OVER_LENGTH (the plan the last run declared; read without the Use table, which
    asks it)."""
    declared = lib.read_json(operator / "declared.json", {}) or {}
    prediction = declared.get("prediction") or {}
    case = prediction
    deflection = _number(case.get("max_displacement"))
    if not deflection or not extents:
        return False
    unit = (declared.get("scale") or {}).get("unit_system") or "SI (m-kg-s)"
    return deflection * LENGTH_TO_M.get(unit, 1.0) / max(extents) > DEFLECTION_OVER_LENGTH


def row_unit(row: Any) -> Any:
    return row.get("unit") if isinstance(row, dict) else None


def given_in(size: float, instruction: str) -> bool:
    """Whether the user's instruction states ``size``: a number in it, as written, in kg x g, or in
    kN (within 1 %)."""
    return any(n > 0 and abs(size / (n * f) - 1) <= 0.01
               for n in _numbers(instruction) for f in (1.0, 9.80665, 1000.0, 9806.65))


def case_effects(table: dict[str, Any]) -> dict[str, dict[str, float]]:
    """Each state's effect at each Load path member: the sum of its rows' runner effects there."""
    members = table["members"]
    effects = table.get("effects") or runner_effects(table)
    out: dict[str, dict[str, float]] = {}
    for name, labels in table["cases"].items():
        total: dict[str, float] = {m: 0.0 for m in members}
        for a in labels:
            for m, v in (effects.get(a) or {}).items():
                if m in total:
                    total[m] += float(v)
        out[name] = total
    return out


def use_coverage(operator: Path, brief: Path | None = None) -> dict[str, Any] | None:
    """The states compared member by member on the runner's effects, written to
    operator/coverage.json: ``uncovered``, every Load path member where another state exceeds the run
    state by more than a third, each with the table's declared reason (or None); at the Real
    section's member, the run's effect and the largest state's.  None without a Use table whose run
    state has rows.  ``brief``: read that copy (the solve snapshot), and write nothing.

    Every state is compared on ONE lever source: the arms measured on the regions when they cover
    every force row of every state, else the Load path's defaults (``row_lever``) for all.  The
    regions measure the run rows alone, and mixing the two (until 2026-10-11) refused at the
    regions approval a run whose measured arm was about 0 (a load along the member) against
    another state's default lever, with no exit that worked.  A force whose arm is under
    NEAR_ZERO_ARM of the largest Real extent (or a stated ``lever_m`` 0) acts directly, as F / A:
    with one in the comparison the states are compared on the runner's stress at the Real section
    (M (d/2) / I + F / A, the Real section taken for every member), not on the moment alone."""
    table, problems = use_table(operator, brief)
    if table is None or table.get("run") not in table["cases"] or not table["members"]:
        return None
    measured, notes = measured_levers(operator.parent, table)
    forces = [k for k, (_, unit) in (table.get("sizes") or {}).items() if unit == "N" and k not in table.get("zero", ())]
    if measured and all(k in measured for k in forces):
        levers, source = {k: measured[k] for k in forces}, "the regions"
    else:
        levers, source = {k: row_lever(table, k) for k in forces}, "the Load path"
        notes = [n.replace("which the runner uses", "used once the regions measure every state's rows") for n in notes]
    table = {**table, "effects": runner_effects(table, levers)}
    effects = case_effects(table)
    run, star = table["run"], table["member"]
    reach = max(table.get("extents") or [0.0])
    direct = [k for k in forces if levers[k] <= NEAR_ZERO_ARM * reach]
    section = real_section(operator) if direct else None
    basis, unit = effects, EFFECT_UNIT
    if section:
        basis, unit = {}, "MPa"
        for c, e in effects.items():
            pushed = {m: sum(table["sizes"][k][0] for k in direct if table["state_of"].get(k) == c
                             and m in loaded_members(table, k)) for m in e}
            basis[c] = {m: (v * section["depth_m"] / 2 / section["I_m4"] + pushed[m] / section["A_m2"]) / 1e6
                        for m, v in e.items()}
    out: dict[str, Any] = {"run": run, "member": star, "unit": unit, "levers": source,
                           "cases": {c: {m: round(v, 6) for m, v in e.items()} for c, e in effects.items()},
                           "uncovered": {}}
    if section:
        out["stress_MPa"] = {c: {m: round(v, 6) for m, v in e.items()} for c, e in basis.items()}
        out["direct"] = direct
    if star is not None:
        governing = max(basis, key=lambda c: basis[c][star])
        out.update({"run_effect": basis[run][star], "governing": governing,
                    "governing_effect": basis[governing][star]})
    for m in table["members"]:
        top = max(basis, key=lambda c: basis[c][m])
        if basis[top][m] > 0 and basis[top][m] > basis[run][m] / COVERAGE_SHARE:
            out["uncovered"][m] = {"case": top, "effect": round(basis[top][m], 6),
                                   "run": round(basis[run][m], 6), "unit": unit,
                                   "declared": table["declared_uncovered"].get(m)}
    notes = notes + list(table.get("levers_set_aside") or [])
    if notes:
        out["lever_notes"] = notes
    if brief is None:
        lib.write_json(operator / COVERAGE, out)
    return out


LEVER_OFF = 2.0      # a row's lever_m more than this x off its measured arm is said
# A force acts directly (F / A, no bend) when its arm is under 2 % of the largest Real extent, or,
# measured, under 2 % of its distance to the hold (its line passes through the hold).
NEAR_ZERO_ARM = 0.02


def measured_levers(session: Path, table: dict[str, Any]) -> tuple[dict[str, float], list[str]]:
    """The run rows' arms measured on the regions (``region_levers``), once they exist (0 for a line
    through the hold, NEAR_ZERO_ARM), and a note for each ``lever_m`` the measure puts more than
    LEVER_OFF x off (the measured arm is used)."""
    if not (session / "boundary_conditions" / "resolved.json").exists():
        return {}, []
    try:
        measured = {k: 0.0 if v["arm_m"] <= NEAR_ZERO_ARM * v["lever_m"] else v["arm_m"]
                    for k, v in region_levers(session).items()}
    except Exception:          # a measure that fails leaves the defaults
        return {}, []
    notes = []
    for key, arm in measured.items():
        given = (table.get("levers") or {}).get(key)
        if given and (arm <= 0 or not 1 / LEVER_OFF <= given / max(arm, 1e-12) <= LEVER_OFF):
            notes.append(f"{key}: lever_m {given:g} m against the regions' {arm:.3g} m, which the runner uses")
    return measured, notes


def hold_kind_problems(table: dict[str, Any]) -> list[str]:
    """The contacts the agent declares, checked against themselves: each of a known kind; a grip,
    socket or worn contact transmits force and moment and states the length it holds
    (``over_m``); a rest or a hang transmits force only; every contact a run row holds is one of
    the Contacts JSON."""
    contacts, rows = table["contacts"], table["rows"]
    run_rows = [a for a in table["cases"].get(table["run"]) or [] if a in rows]
    out = []
    for name, entry in contacts.items():
        kind = entry["kind"]
        if kind not in HOLD_KINDS:
            out.append(f"contact {name!r}: \"kind\" is one of {list(HOLD_KINDS)} (objectives/brief.md §2, Contacts)")
        elif kind in HELD_OVER and (entry["transmits"] != "force and moment" or not entry["over_m"]):
            out.append(f"contact {name!r} ({kind}): transmits \"force and moment\", with \"over_m\", the length it "
                       "holds along the member")
        elif kind in ("rest", "hang") and entry["transmits"] != "force only":
            out.append(f"contact {name!r} ({kind}): transmits \"force only\" (held on its normal component(s), or its "
                       "reaction from statics)")
    if not contacts and table.get("contacts_malformed"):
        return out           # the malformed entries are named by use_table; nothing reads as a contact
    for a in run_rows:
        row = rows[a] if isinstance(rows[a], dict) else {}
        held = [h for h in row.get("held") or [] if isinstance(h, str)]
        strange = [h for h in held if not (contacts.get(h) or next(
            (v for k, v in contacts.items() if _name_key(k) == _name_key(h)), None))]
        if strange:
            out.append(f"Use table row {a}: held {strange} are not contacts of the brief's Contacts JSON "
                       f"({sorted(contacts)}): the run state is held by its contacts")
    return out


def hold_family(kind: Any) -> Any:
    """Grip, socket and worn are one family: each holds a length of the member."""
    return "grip, socket or worn" if kind in HELD_OVER else kind


@gate_refusal('use gate', 'list')
def use_gate(operator: Path) -> list[str]:
    """G1, before anything is spent (every run, and `blank`): the brief's Use table, its contacts,
    and the coverage of the other states by the run state on the runner's effects (or the member
    declared uncovered).  Every problem at once."""
    table, out = use_table(operator)
    if table is None:
        return out
    # The tiers at once where each can be read: the table's own problems, the contacts, and the
    # coverage only when the table parses whole.
    parses = not out
    kinds = hold_kind_problems(table)
    out = out + kinds
    unfreeze_contacts(operator, named_contacts("; ".join(kinds)))
    if not parses:
        return out
    coverage = use_coverage(operator)
    if not coverage:
        return out
    # One message per state over the run, every member it exceeds it at named with both numbers.
    by_case: dict[str, list[str]] = {}
    for m, u in coverage["uncovered"].items():
        if not u["declared"]:
            by_case.setdefault(u["case"], []).append(f"{u['effect']:.4g} {u['unit']} at {m!r} against {u['run']:.4g}")
    basis = ("stress at the Real section (M (d/2) / I + F / A: a force at its hold acts as F / A)"
             if coverage.get("unit") == "MPa" else "effects (a force times its lever, a twist as it is)")
    for case, said in by_case.items():
        out.append(f"state {case!r} exceeds the run state {coverage['run']!r} by more than a third on the runner's "
                   f"{basis}, levers from {coverage['levers']}: {'; '.join(said)}. " + coverage_exits(case))
    out += coverage_held(operator, coverage, table, by_case)
    return out


COVERAGE_REFUSED = "coverage_refused.json"   # the members a coverage refusal named, until it is resolved


def coverage_exits(case: str) -> str:
    """The two exits of a coverage refusal, each one edit."""
    return (f"Run {case!r} (the Use table's \"run\"; a pressure that varies over a face is bands bound to one row "
            "with \"varies\", objectives/regions.md §3.3), or, when a workflow limit keeps its load out, declare "
            "each such member in the Use table's \"uncovered\": {\"<member>\": {\"limit\": \"<one of "
            + " | ".join(WORKFLOW_LIMITS) + ">\", \"why\": \"...\"}} and the verdict is 'the governing load "
            "cannot be applied; a secondary case was run: …' (objectives/brief.md §2, Use)")


def _row_content(row: dict[str, Any]) -> dict[str, Any]:
    """What a Use table row is apart from its name: its state, the member it enters, its holds, its size."""
    held = row.get("held")
    return {"state": row.get("state"), "enters": row.get("enters"),
            "held": sorted(map(str, held)) if isinstance(held, (list, tuple)) else held, "size": _number(row.get("size"))}


def _same_row(recorded: dict[str, Any] | None, row: dict[str, Any]) -> bool:
    """A recorded row found again under another name: the same state and member, and its holds or
    its size (a corrected size, or holds, may change with the name; not both)."""
    if not recorded or recorded.get("state") != row.get("state") or recorded.get("enters") != row.get("enters"):
        return False
    return recorded.get("held") == row.get("held") or recorded.get("size") == row.get("size")


def coverage_held(operator: Path, coverage: dict[str, Any], table: dict[str, Any],
                  by_case: dict[str, list[str]]) -> list[str]:
    """A coverage refusal is not cleared by moving the Real section off the member it was at, or by
    declaring members it did not name uncovered: an agent cleared one so,
    and the governing load was never applied.  Its exits (the refused state run, the named members
    declared; a row's wrong size corrected) clear it.  Records the refusal (COVERAGE_REFUSED) and
    returns what still holds."""
    path = operator / COVERAGE_REFUSED
    record = lib.read_json(path, {}) or {}
    if by_case:
        named = {m for m, u in coverage["uncovered"].items() if not u["declared"]}
        cases = {u["case"] for m, u in coverage["uncovered"].items() if m in named}
        if not record:
            record = {"members": [], "cases": [], "member": coverage.get("member"),
                      "declared": sorted(table.get("declared_uncovered") or {})}
        record["members"] = sorted(set(record["members"]) | named)
        record["cases"] = sorted(set(record["cases"]) | cases)
        # the dominant row at each named member: deleted rather than corrected, it is no exit
        effects = table.get("effects") or {}
        record["rows"] = sorted(set(record.get("rows") or []) | {
            max((k for k in effects if table["state_of"].get(k) == coverage["uncovered"][m]["case"]),
                key=lambda k: effects[k].get(m, 0), default=None) for m in named} - {None})
        rows = table.get("rows") or {}
        record["row_content"] = {**(record.get("row_content") or {}), **{
            k: _row_content(rows[k]) for k in record["rows"] if isinstance(rows.get(k), dict)}}
        lib.write_json(path, record)
        return []
    if not record:
        return []
    if coverage.get("run") in record.get("cases", []):
        path.unlink(missing_ok=True)          # the governing state is run
        return []
    others = sorted(set(table.get("declared_uncovered") or {}) - set(record.get("declared") or [])
                    - set(record.get("members") or []))
    moved = record.get("member") and coverage.get("member") != record.get("member")
    if set(record.get("members") or []) <= set(table.get("declared_uncovered") or {}) and not moved:
        path.unlink(missing_ok=True)          # its exit: the named members declared
        return []
    # the governing row taken out of the table: the record stays (review of 2026-10-11).  Checked
    # after the declared exit, and a row renamed while it was corrected is found by its content.
    rows = table.get("rows") or {}
    kept = [_row_content(r) for r in rows.values() if isinstance(r, dict)]
    deleted = [k for k in record.get("rows") or [] if k not in rows and not any(
        _same_row((record.get("row_content") or {}).get(k), c) for c in kept)] if "rows" in table else []
    if deleted:
        return [f"the coverage refusal of {record.get('cases')} at {record.get('members')} is not resolved: row(s) "
                f"{deleted} it rested on were removed from the Use table; an action of the use stays a row. "
                + coverage_exits(record.get("cases", ["<state>"])[0])]
    if not others and not moved:
        # a corrected row cleared it: the record goes, so a later move of the Real section is free
        path.unlink(missing_ok=True)
        return []
    said = []
    if moved:
        said.append(f"the Real section moved from {record['member']!r} to {coverage.get('member')!r}")
    if others:
        said.append(f"{others}, which it did not name, declared uncovered")
    return [f"the coverage refusal of {record.get('cases')} at {record.get('members')} is not resolved: "
            + " and ".join(said) + "; neither is an exit (put them back). "
            + coverage_exits(record.get("cases", ["<state>"])[0])]


def table_report(operator: Path) -> dict[str, Any] | None:
    """What the report prints of the Use table: each row's state, size and source, and the states."""
    table, _ = use_table(operator)
    if not table:
        return None
    rows = table.get("rows") or {}
    sizes = table.get("sizes") or {}
    return {"rows": {k: {**{f: r.get(f) for f in ("load", "state", "size", "unit", "source", "enters")},
                         **({"size": sizes[k][0], "unit": sizes[k][1]} if k in sizes else {})}
                     for k, r in rows.items() if isinstance(r, dict)},
            "cases": table["cases"], "run": table["run"]}


# The Real section as a shape and its dimensions, from which the runner computes I and A: the agent
# computed I by hand until 2026-10-11 (and met the bound and the "I lowered" checks that policed it).
# The depth is the extent in the direction the member bends; the "<d> m deep, I .. m4, A .. m2" form
# is still read.
SECTION_SHAPES = ("rectangle <width> x <depth> m | round <diameter> m | tube <diameter> x <wall> m | "
                  "box <width> x <depth> x <wall> m")


def section_of_shape(shape: str, dims: list[float]) -> dict[str, float] | None:
    """{"depth_m", "I_m4", "A_m2", "shape"} of a rectangle (width, depth), a round bar (diameter), a
    tube (diameter, wall) or a box (width, depth, wall), bent about the axis across its depth."""
    import math
    shape = shape.lower()
    try:
        if shape in ("rectangle", "rect", "plate", "bar") and len(dims) >= 2:
            w, d = dims[:2]
            out = (d, w * d ** 3 / 12, w * d)
        elif shape in ("round", "rod", "disc", "circle") and len(dims) >= 1:
            d = dims[0]
            out = (d, math.pi * d ** 4 / 64, math.pi * d ** 2 / 4)
        elif shape in ("tube", "pipe") and len(dims) >= 2:
            d, t = dims[:2]
            inner = max(d - 2 * t, 0.0)
            out = (d, math.pi * (d ** 4 - inner ** 4) / 64, math.pi * (d ** 2 - inner ** 2) / 4)
        elif shape in ("box", "hollow") and len(dims) >= 3:
            w, d, t = dims[:3]
            wi, di = max(w - 2 * t, 0.0), max(d - 2 * t, 0.0)
            out = (d, (w * d ** 3 - wi * di ** 3) / 12, w * d - wi * di)
        else:
            return None
    except (TypeError, ValueError):
        return None
    if min(out) <= 0:
        return None
    return {"depth_m": out[0], "I_m4": out[1], "A_m2": out[2], "shape": shape}


def section_dims_in(text: str) -> tuple[str, list[float]] | None:
    """(shape, dimensions) of a brief's shaped Real section line ('Real section (<member>): <shape>
    <a> x <b> m'), or None."""
    number = r"([0-9][0-9.eE+-]*)"
    shaped = re.search(rf"real section(?:\s*\([^()]*\))?:\s*([a-z]+)\s+{number}(?:\s*m)?"
                       rf"(?:\s*[x×]\s*{number}(?:\s*m)?)?(?:\s*[x×]\s*{number}(?:\s*m)?)?", text or "", flags=re.I)
    if shaped is None:
        return None
    try:
        return shaped.group(1), [float(v) for v in shaped.groups()[1:] if v is not None]
    except ValueError:
        return None


def section_thinnest(shape: str, dims: list[float]) -> float | None:
    """The thinnest wall of a shaped section: a rectangle's smaller side, a round bar's diameter, a
    tube's or a box's wall (SECTION_SHAPES' last number)."""
    shape = shape.lower()
    if shape in ("round", "rod", "disc", "circle") and dims:
        return dims[0]
    if shape in ("rectangle", "rect", "plate", "bar") and len(dims) >= 2:
        return min(dims[:2])
    if shape in ("tube", "pipe") and len(dims) >= 2:
        return dims[1]
    if shape in ("box", "hollow") and len(dims) >= 3:
        return dims[2]
    return None


def real_section_in(text: str) -> dict[str, float] | None:
    """The real governing member's section from a brief's Real section line: a shape and its
    dimensions (SECTION_SHAPES; the runner computes I and A), or '<depth> m deep, I <n> m4, A <n> m2'."""
    import re
    number = r"([0-9][0-9.eE+-]*)"
    match = re.search(rf"real section(?:\s*\([^()]*\))?:\s*{number}\s*m\s+deep\s*,\s*I\s*=?\s*{number}\s*m\^?[4⁴]\s*,\s*"
                      rf"A\s*=?\s*{number}\s*m\^?[2²]", text or "", flags=re.I)
    if match is None:
        shaped = section_dims_in(text)
        return section_of_shape(*shaped) if shaped else None
    try:
        values = [float(v) for v in match.groups()]
    except ValueError:
        return None
    if not values or min(values) <= 0:
        return None
    return {"depth_m": values[0], "I_m4": values[1], "A_m2": values[2]}


def _arithmetic_values(text: str) -> list[float]:
    """The values of the arithmetic expressions written in ``text`` (numbers with ×, x, *, ·, /,
    +, -, ^, ², ³, ⁴ and parentheses; length units stripped), each with at least one operation:
    a bare number is not a computation."""
    import ast
    import operator as op
    import re
    s = re.sub(r"(?<=[\d\s)])(?:mm|cm|m)(?:\^?[234]|[²³⁴])?(?![A-Za-z])", " ", text or "")
    s = s.replace("²", "^2").replace("³", "^3").replace("⁴", "^4").replace("−", "-")
    s = re.sub(r"(?<=[\d)])\s*[x×·]\s*(?=[\d(])", "*", s)
    s = s.replace("^", "**")
    s = re.sub(r"(?<=[\d)])\s+(?=[\d(])", " | ", s)      # two numbers side by side: two expressions
    ops ={ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul, ast.Div: op.truediv, ast.Pow: op.pow}

    def value(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return float(node.value)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd)):
            v = value(node.operand)
            return -v if isinstance(node.op, ast.USub) else v
        if isinstance(node, ast.BinOp) and type(node.op) in ops:
            return ops[type(node.op)](value(node.left), value(node.right))
        raise ValueError(node)
    out = []
    for run in re.findall(r"[\d.()+\-*/eE ]*\d[\d.()+\-*/eE ]*", s):
        # unmatched parentheses (a bracket opened before the run, closed in it) are dropped
        keep, stack = list(run), []
        for k, ch in enumerate(run):
            if ch == "(":
                stack.append(k)
            elif ch == ")":
                if stack:
                    stack.pop()
                else:
                    keep[k] = " "
        for k in stack:
            keep[k] = " "
        expr = "".join(keep).strip().lstrip("eE+*/ ").rstrip("eE+-*/ ").strip()      # a leading minus kept
        try:
            tree = ast.parse(expr, mode="eval").body
            if isinstance(tree, ast.BinOp) or any(isinstance(n, ast.BinOp) for n in ast.walk(tree)):
                out.append(value(tree))
        except (SyntaxError, ValueError, ZeroDivisionError, OverflowError, TypeError):
            continue
    return out


def section_computed(text: str, inertia: float | None = None) -> bool:
    """Whether the Real section line, with the lines that continue it (indented or bulleted below
    it, or in brackets on it), computes I: an arithmetic expression written there evaluates to
    the stated I within 5 % (a shape's formula with its dimensions), not a bare or estimated value."""
    import re
    lines = (text or "").splitlines()
    start = next((k for k, ln in enumerate(lines) if re.search(r"real section(?:\s*\([^()]*\))?:", ln, flags=re.I)),
                 None)
    if start is None:
        return False
    if inertia is None:
        inertia = (real_section_in(lines[start]) or {}).get("I_m4")
    if not inertia:
        return False
    block = [lines[start]]
    for ln in lines[start + 1:]:
        stripped = ln.strip()
        if not stripped or re.match(r"real\s", stripped, flags=re.I):
            break
        if not ln[:1].isspace() and re.match(r"([-*]\s|#)", stripped):
            break
        block.append(ln)
    return any(abs(v - inertia) <= 0.05 * abs(inertia) for v in _arithmetic_values(" ".join(block)))


def real_member_in(text: str) -> float | None:
    import re
    match = re.search(r"real thinnest member:\s*([0-9][0-9.eE+-]*)\s*m\b", text or "", flags=re.I)
    try:
        return float(match.group(1)) if match else None
    except ValueError:
        return None


def real_mass_in(section: str) -> float | None:
    """The real object's mass from a brief's 'Real mass: <number> kg' line."""
    import re
    match = re.search(r"real mass:\s*([0-9][0-9.eE+-]*)\s*kg\b", section or "", flags=re.I)
    try:
        return float(match.group(1)) if match else None
    except ValueError:
        return None


def real_member(operator: Path) -> float | None:
    """The real object's thinnest load-path member, from the brief's 'Real thinnest member:
    <number> m' line as it stood before any body existed (its snapshot)."""
    for path in _real_sources(operator):
        try:
            section = brief_sections(path.read_text(encoding="utf-8")).get("size and material", "")
        except OSError:
            continue
        if real_member_in(section) is not None:
            return real_member_in(section)
    return None


UP_IN_USE = re.compile(r"up in use:\s*(?:the\s+)?(longest|shortest)\s+extent\s+(vertical|horizontal)", re.I)
SAME_EXTENT = 0.02        # extents within 2 % of each other are one (a round flange, a square plate)
# plan.body_up: the signed body axis that points up in use, the agent's one statement of how the
# body came out (+y, upright, when left out).  Each use-frame axis goes to (body axis, sign) by the
# smallest rotation that takes the use's up (+y) there (a half turn about x for -y).  Until
# 2026-10-11 the runner guessed the turn from the extents' ranks (no sign, near-equal extents
# swapped) and read down from values.acceleration, which the agent was told to turn by hand: a
# turned acceleration then left the rows unturned, an unturned one the gravity.
BODY_UP = ("+x", "-x", "+y", "-y", "+z", "-z")
_TURNS = {"+y": ((0, 1), (1, 1), (2, 1)), "-y": ((0, 1), (1, -1), (2, -1)),
          "+x": ((1, -1), (0, 1), (2, 1)), "-x": ((1, 1), (0, -1), (2, 1)),
          "+z": ((0, 1), (2, 1), (1, -1)), "-z": ((0, 1), (2, -1), (1, 1))}


def body_orientation(session: Path, plan: dict[str, Any], resolution: dict[str, Any]
                     ) -> tuple[dict[str, Any] | None, str | None]:
    """The body's axes against the brief's 'Up in use: the <longest|shortest> extent
    <vertical|horizontal>' line, with up the plan's ``body_up`` (+y without one).

    The workflow cannot turn a body (``up_axis`` only names the axis the extent is measured
    along): a body that came out turned keeps the brief's physics; the agent states which body
    axis is the use's up and the runner turns the rows and the acceleration (``use_to_body``).
    In one run a body that came out with its axis vertical had its load moved
    to another face and a support invented, where turning the load direction kept the case."""
    extents = resolution.get("physical_extents")
    if not extents or len(extents) != 3:
        return None, None
    up = plan.get("body_up") if plan.get("body_up") in BODY_UP else "+y"
    up_axis = "xyz".index(up[1])
    out: dict[str, Any] = {"extents_m": dict(zip("xyz", extents)), "up": up, "use_to_body": axes_said(up)}
    try:
        match = UP_IN_USE.search((lib.operator_dir(session) / "brief.md").read_text(encoding="utf-8"))
    except OSError:
        match = None
    if not match:
        return out, None
    which, way = match.group(1).lower(), match.group(2).lower()
    pick = max(extents) if which == "longest" else min(extents)
    axes = [k for k in range(3) if abs(extents[k] - pick) <= SAME_EXTENT * pick]
    vertical = up_axis in axes and (way == "vertical" or len(axes) == 1)
    out["brief"] = f"{which} extent {way}"
    out["agrees"] = vertical if way == "vertical" else not vertical
    if out["agrees"]:
        return out, None
    names = "/".join("xyz"[k] for k in axes)
    ups = [f"{sign}{'xyz'[k]}" for k in range(3) if (k in axes) == (way == "vertical") for sign in "+-"]
    # the brief's line that the body as it stands (up +y) agrees with: the line to fix when views.png
    # shows the body upright as the real object stands
    vertical_now = extents[up_axis]
    line = ("Up in use: the longest extent vertical" if vertical_now >= max(extents) * (1 - SAME_EXTENT) else
            "Up in use: the shortest extent vertical" if vertical_now <= min(extents) * (1 + SAME_EXTENT) else
            f"Up in use: the {'shortest' if which == 'longest' else 'longest'} extent horizontal")
    return out, (f"the body's {which} extent ({names}) is {'horizontal' if way == 'vertical' else 'vertical'} with "
                 f"up {up}, the brief's 'Up in use' {way}: if views.png shows the body upright as the real object "
                 f"stands, fix the brief's line to '{line}'; else state plan.body_up (one of "
                 f"{', '.join(f'{u}: {axes_said(u)}' for u in ups)}; the runner turns the Use table rows and the "
                 "acceleration, objectives/size.md §3.1)")


# A generated body that came out tilted: its base plane off the up axis by more than
# TILT_DEG, for a body the use stands on rests.  The workflow's scale step cannot rotate a body
# (scale-surface takes an axis and an extent only), so it is warned at the geometry stop and listed
# in the verdict (TILT_RECORD), never refused.
TILT_DEG = 10.0
TILT_RECORD = "body_tilt.json"
TILT_BAND = 0.05      # the lowest faces: a vertex within this share of the height above the lowest point


def body_tilt(session: Path, plan: dict[str, Any]) -> float | None:
    """The angle (degrees) between the up axis (``body_up``, +y without one) and the area-weighted
    mean normal of the lowest faces that look down (a vertex within TILT_BAND of the height above the
    lowest point, within 45 degrees of down), or None without such faces: the base or feet the body
    stands on, not every face that looks down (an overhang's underside read as tilt)."""
    import numpy as np
    mesh = _generated_mesh(session)
    if mesh is None or not len(mesh.faces):
        return None
    down = -np.asarray(turned_direction([0.0, 1.0, 0.0], use_to_body(session, plan)), dtype=float)
    normals, areas = np.asarray(mesh.face_normals, dtype=float), np.asarray(mesh.area_faces, dtype=float)
    heights = -np.asarray(mesh.vertices, dtype=float) @ down
    lowest = heights[np.asarray(mesh.faces)].min(axis=1) <= heights.min() + TILT_BAND * float(np.ptp(heights))
    base = lowest & (normals @ down > np.cos(np.radians(45.0)))
    if not base.any():
        return None
    mean = (normals[base] * areas[base, None]).sum(axis=0)
    return float(np.degrees(np.arccos(np.clip(mean @ down / (np.linalg.norm(mean) or 1.0), -1.0, 1.0))))


def tilt_warning(session: Path, plan: dict[str, Any]) -> str | None:
    """A body the use stands on a rest whose base is over TILT_DEG off the up axis: said, and
    recorded for the verdict."""
    contacts = brief_contacts_v2(lib.operator_dir(session)) or {}
    if (not any((c or {}).get("kind") == "rest" for c in contacts.values())
            or body_provenance(session) in ("built", "upload")):
        return None
    tilt = body_tilt(session, plan)
    path = lib.operator_dir(session) / TILT_RECORD
    if tilt is None or tilt <= TILT_DEG:
        if path.exists():
            path.unlink()
        return None
    lib.write_json(path, {"deg": round(tilt, 1), "body": body_digest(session)})
    return (f"the body's base is {tilt:.0f} degrees off its up axis (over {TILT_DEG:g}): the workflow cannot rotate a "
            "body, so a tilted generated body is generated again or the next route taken; kept, the verdict lists it")


# A flat base the generator added under a body the brief stands on several supports (a generated
# body with a plank fused under it, the shadow under the cut-out read as solid, swallowed the lower
# halves of the wheels; the body passed and the hold was narrowed onto the wheels).  The base is the
# largest connected patch of faces looking down (within SLAB_DEG of down) at the lowest level (each
# vertex within SLAB_BAND of the height above the lowest point), against the footprint (the convex hull
# of the body seen from above).  Measured on 31 bodies on discrete rests:
# a fused base plank 0.16 of the footprint, spanning 0.92 of its length; every other body at most
# 0.09, feet and other point supports 0.002-0.04.  A genuine flat base (a body standing on a plate, 0.94) is
# never measured: the check runs only for supports the brief makes several (``discrete_rests``).
SLAB_BAND = 0.05
SLAB_DEG = 20.0
SLAB_SHARE = 0.12       # the patch's area over the footprint's, at least
SLAB_SPAN = 0.5         # ... and its extent over the footprint's along the footprint's longer axis, at least
SLAB_RECORD = "base_slab.json"
SLAB_SAID = ("a flat base under the body that the brief's supports do not have (the supports merged into it), "
             "kept as generated")


def discrete_rests(contacts: dict[str, Any] | None) -> list[str]:
    """The brief's rest contacts when they are several supports: two or more rests, or a rest named in
    the plural ("support rests", "feet"), or one named after a plural member's single item ("leg rest"
    on "legs"); else [] (one support, as a base on a plate)."""
    rests = {k: c for k, c in (contacts or {}).items() if (c or {}).get("kind") == "rest"}
    if len(rests) > 1:
        return sorted(rests)

    def several(name: str, member: str) -> bool:
        words = [_singular(w) for w in _name_key(name).split("_") if w]
        return _plural(name) or (bool(member) and _plural(member)
                                 and _singular(_name_key(member).split("_")[-1]) in words)
    return [k for k, c in rests.items() if several(k, str((c or {}).get("member") or ""))]


def base_slab(mesh, up) -> dict[str, Any] | None:
    """The largest flat patch looking down at the body's lowest level, against the footprint:
    {"share", "span"}, None without one."""
    import numpy as np
    from scipy.sparse import coo_matrix
    from scipy.sparse.csgraph import connected_components
    from scipy.spatial import ConvexHull
    up = np.asarray(up, dtype=float) / np.linalg.norm(up)
    vertices, faces = np.asarray(mesh.vertices, dtype=float), np.asarray(mesh.faces)
    if not len(faces):
        return None
    heights = vertices @ up
    normals, areas = np.asarray(mesh.face_normals, dtype=float), np.asarray(mesh.area_faces, dtype=float)
    low = heights[faces].max(axis=1) <= heights.min() + SLAB_BAND * float(np.ptp(heights))
    down = low & (normals @ -up >= np.cos(np.radians(SLAB_DEG)))
    if not down.any():
        return None
    side = np.cross(up, [1.0, 0.0, 0.0] if abs(up[0]) < 0.9 else [0.0, 1.0, 0.0])
    side /= np.linalg.norm(side)
    plane = np.c_[vertices @ side, vertices @ np.cross(up, side)]
    footprint = float(ConvexHull(plane).volume)
    pairs = np.asarray(mesh.face_adjacency)
    pairs = pairs[down[pairs[:, 0]] & down[pairs[:, 1]]]
    graph = coo_matrix((np.ones(len(pairs)), (pairs[:, 0], pairs[:, 1])), shape=(len(faces), len(faces)))
    labels = connected_components(graph, directed=False)[1]
    chosen = np.flatnonzero(down)
    projected = areas[chosen] * (normals[chosen] @ -up)
    totals = np.bincount(labels[chosen], weights=projected)
    best = int(np.argmax(totals))
    centred = plane - plane.mean(axis=0)
    axis = np.linalg.eigh(np.cov(centred.T))[1][:, -1]          # the footprint's longer axis
    patch = centred[faces[chosen[labels[chosen] == best]].ravel()] @ axis
    return {"share": round(float(totals[best]) / max(footprint, 1e-30), 3),
            "span": round(float(np.ptp(patch)) / max(float(np.ptp(centred @ axis)), 1e-30), 2)}


def base_slab_warning(session: Path, plan: dict[str, Any]) -> str | None:
    """A generated body with a flat base its brief's several supports do not have (``base_slab``):
    said at the geometry stop, in words beside the views, and recorded so a body kept with it is a
    marked simplification (``runner_simplifications``)."""
    path = lib.operator_dir(session) / SLAB_RECORD
    rests = discrete_rests(brief_contacts_v2(lib.operator_dir(session)))
    digest = body_digest(session)
    if not rests or body_provenance(session) in ("built", "upload") or digest is None:
        if path.exists():
            path.unlink()
        return None
    known = lib.read_json(path, {}) or {}
    if known.get("body") == digest and known.get("up") == plan.get("body_up") and "share" in known:
        found = known if known.get("flagged") else None
    else:
        mesh = _generated_mesh(session)
        measured = base_slab(mesh, turned_direction([0.0, 1.0, 0.0], use_to_body(session, plan))) \
            if mesh is not None else None
        found = measured if measured and measured["share"] >= SLAB_SHARE and measured["span"] >= SLAB_SPAN else None
        lib.write_json(path, {"body": digest, "up": plan.get("body_up"), "share": (measured or {}).get("share", 0.0),
                              "span": (measured or {}).get("span", 0.0), "flagged": bool(found), "rests": rests})
    if not found:
        return None
    contacts = brief_contacts_v2(lib.operator_dir(session)) or {}
    members = sorted({str((contacts.get(r) or {}).get("member") or r) for r in rests})
    return (f"a flat base under the body that the brief's supports do not have; it may have swallowed the supports "
            f"({', '.join(members)}): one flat downward patch at the lowest level covers {found['share']:.0%} of the "
            f"footprint and {found['span']:.0%} of its length, where the brief stands the body on {', '.join(rests)}. "
            "Supports fused into a base are a fused primary member: refine first, the ladder on this image and then "
            "the listed routes (plan.geometry.reject \"the <supports> fused into a flat base\"); this body is "
            f"accepted only after them, as a marked simplification ({SLAB_SAID}; the verdict "
            f"'{VERDICT_SIMPLIFIED}')")


def slab_next_step(session: Path, plan: dict[str, Any]) -> str | None:
    """The step a body flagged with a flat base (``base_slab_kept``) still takes before it is accepted:
    the refine ladder's rungs on its image (6/9, 5/8, then Hunyuan3D from the same image), then a
    listed route untried within the generated budget (a route the runner refused counts as taken);
    None when every one was tried."""
    counts = lib.read_json(lib.operator_dir(session) / "run_counts.json", {}) or {}
    source = body_provenance(session)
    image = plan_image_key(plan) if source in ("triposg", "hunyuan3d") else None
    if image and source == "triposg" and image not in mass_blocked_images(session):
        tried = [k for k in (lib.read_json(lib.operator_dir(session) / REFINE_SENT, {}) or {}).get(image) or []
                 if not k.startswith("seed|")]
        depths = extraction_depths(plan.get("geometry") or {})
        rungs = [d for d in REFINED_DEPTHS if d != depths][:max(REFINEMENTS - len(tried), 0)]
        if rungs:
            return (f"the same image and seed at generation_settings init_octree_depth {rungs[0][0]}, octree_depth "
                    f"{rungs[0][1]}")
    if image and source == "triposg" and not counts.get("hunyuan") and hunyuan_ready():
        return "Hunyuan3D from the same image (\"generator\": \"hunyuan3d\", the same words and image_seed)"
    routes = declared_routes(session) or canonical_routes(list(plan.get("geometry_routes") or []), session)
    refused = routes_refused(session)
    for route in routes:
        if route == "built" or route in refused or route_tried(session, route, counts):
            continue
        if route in GENERATED_ROUTES and (generated_bodies(session) >= GENERATED_BUDGET
                                          or (route == "hunyuan3d" and not hunyuan_ready())):
            continue
        if route in ROUTE_WORDS:
            return ROUTE_WORDS[route]
    return None


def slab_route_problem(session: Path, plan: dict[str, Any]) -> str | None:
    """A body the geometry stop flagged with a flat base is refused on leaving the stop while a ladder
    rung or a listed route remains (``slab_next_step``): its swallowed supports are a fused primary
    member.  Past them it is accepted, a marked simplification (``runner_simplifications``)."""
    if not base_slab_kept(session):
        return None
    step = slab_next_step(session, plan)
    return (f"the body's flat base may have swallowed the brief's supports (a fused primary member): it is not "
            f"accepted while a refinement or a listed route remains: refine first, {step}, with plan.geometry.reject "
            "naming the supports fused into the base") if step else None


def base_slab_kept(session: Path) -> bool:
    """Whether the body at hand is the one the geometry stop flagged with a flat base."""
    known = lib.read_json(lib.operator_dir(session) / SLAB_RECORD, {}) or {}
    return bool(known.get("flagged")) and known.get("body") == body_digest(session)


def axes_said(up: str) -> str:
    """The use-frame axes in the body's frame for a body_up, printed so no axis is mapped by hand."""
    return ", ".join(f"use {'xyz'[k]} -> body {'-' if sign < 0 else '+'}{'xyz'[axis]}"
                     for k, (axis, sign) in enumerate(_TURNS[up]))


def body_up_problem(plan: dict[str, Any], regions: list[dict[str, Any]],
                    contacts: dict[str, dict[str, Any]]) -> str | None:
    """A stated body_up whose down puts every rest's held face looking up: the rests would hang, so
    the sign is wrong (review of 2026-10-11)."""
    import numpy as np
    up = plan.get("body_up")
    if up not in BODY_UP or up == "+y":
        return None
    down = np.asarray(turned_direction([0.0, -1.0, 0.0], use_to_body(None, plan)))
    names = region_contacts(plan.get("contacts"))
    faces = [np.asarray(r.get("mean_normal") or [0, 0, 0], dtype=float) for r in regions
             if r.get("category") == "dirichlet"
             and (contacts.get((names.get(r.get("name")) or {}).get("contact")) or {}).get("kind") == "rest"]
    faces = [f / np.linalg.norm(f) for f in faces if np.linalg.norm(f) > 0]
    if not faces or not all(float(f @ down) <= -STANDS_ON for f in faces):
        return None
    other = ("-" if up[0] == "+" else "+") + up[1]
    return (f"plan.body_up {up} puts the rests' faces looking up, so they would hang: the use's up is likely "
            f"{other} ({axes_said(other)})")


def use_to_body(session: Path | None, plan: dict[str, Any]) -> tuple[tuple[int, int], ...] | None:
    """The turn from the use frame (+y up) into the body's: for each use axis, the body axis it
    goes to and its sign, from the plan's ``body_up`` (``_TURNS``); None for an upright body."""
    up = plan.get("body_up") if isinstance(plan, dict) else None
    return _TURNS[up] if up in BODY_UP and up != "+y" else None


def turned_direction(vector: list[float], turn: tuple[tuple[int, int], ...] | None) -> list[float]:
    """A use-frame vector in the body's frame (``use_to_body``)."""
    if not turn:
        return [float(c) for c in vector]
    out = [0.0, 0.0, 0.0]
    for use_axis, (body_axis, sign) in enumerate(turn):
        out[body_axis] = sign * float(vector[use_axis])
    return out


def body_vector(plan: dict[str, Any], key: str = "acceleration") -> Any:
    """plan.values' acceleration (or body_force), written in the use frame, in the body's frame:
    what the solve, the statics and the tipping check take."""
    vector = (plan.get("values") or {}).get(key)
    if not isinstance(vector, list) or len(vector) != 3 or any(_number(c) is None for c in vector):
        return vector
    return turned_direction(vector, use_to_body(None, plan))


def real_section(operator: Path) -> dict[str, float] | None:
    """The real governing member's section as the brief stated it before any body existed."""
    for path in _real_sources(operator):
        try:
            section = brief_sections(path.read_text(encoding="utf-8")).get("size and material", "")
        except OSError:
            continue
        if real_section_in(section) is not None:
            return real_section_in(section)
    return None


def real_mass(operator: Path) -> float | None:
    """The real mass as the brief stated it at the first run (its snapshot), else as it stands; the
    one revision's (``extents_revision``) once taken."""
    revised = revised_mass(operator)
    if revised:
        return revised
    for path in _real_sources(operator):
        try:
            value = real_mass_in(brief_sections(path.read_text(encoding="utf-8")).get("size and material", ""))
        except OSError:
            continue
        if value:
            return value
    return None


def merge_patch(target: Any, patch: Any) -> Any:
    """RFC 7396 JSON merge patch: an object merges key by key (null removes the key), anything
    else replaces the target whole."""
    if not isinstance(patch, dict):
        return patch
    out = dict(target) if isinstance(target, dict) else {}
    for key, value in patch.items():
        if value is None:
            out.pop(key, None)
        else:
            out[key] = merge_patch(out.get(key), value)
    return out


def patched_plan(path: Path, patch_text: str, session: Path | None = None) -> dict[str, Any]:
    """``run --patch``: the plan on disk with a merge patch applied, checked as a plan; nothing
    is written here (the run writes it back once it is checked)."""
    try:
        patch = json.loads(patch_text)
    except ValueError as exc:
        raise PlanError(f"--patch is not JSON ({exc}); plan.json is unchanged. The patch goes in single quotes, "
                        "so an apostrophe inside it is written \\u0027 (the JSON escape)")
    if not isinstance(patch, dict):
        raise PlanError("--patch is a JSON object, an RFC 7396 merge patch of plan.json (null removes a "
                        "key); plan.json is unchanged")
    try:
        current = json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise PlanError(f"cannot read the plan {path}: {exc}")
    plan = merge_patch(current, patch)
    try:
        return check_plan(plan, session)
    except PlanError as exc:
        raise PlanError(f"the patched plan is refused, and plan.json is unchanged: {exc}")


def json_layout(text: str) -> dict[str, Any] | None:
    """The ``json.dumps`` arguments that reproduce ``text`` exactly (indent, separators, escaping,
    the final newline), or None when the file was laid out by hand (one object inline among
    indented ones): ``run --patch`` writes the plan back in its own layout, so an Edit of a line
    the agent wrote still finds it (one run: the patch re-indented plan.json
    and the next Edit missed)."""
    try:
        value = json.loads(text)
    except ValueError:
        return None
    body, tail = text.rstrip("\n"), text[len(text.rstrip("\n")):]
    for indent in (None, 1, 2, 4, 3, "\t"):
        for separators in ((", ", ": "), (",", ":"), (",", ": ")):
            if indent is not None and separators[0] == ", ":
                continue
            for ascii_only in (False, True):
                kwargs = {"indent": indent, "separators": separators, "ensure_ascii": ascii_only}
                if json.dumps(value, **kwargs) == body:
                    return {**kwargs, "tail": tail}
    return None


PATCH_REWROTE = ("plan.json was rewritten by --patch: keep changing the plan with --patch, or Read plan.json "
                 "before a Write or Edit (one from an earlier Read fails as modified since read)")
PATCHED = "plan_patched.json"     # the session's plan has been written by --patch (PATCH_REWROTE said)


def patched_text(path: Path, plan: dict[str, Any]) -> tuple[str, str | None]:
    """The patched plan as written back: in the file's own layout, or, when that cannot be
    reproduced, one indent per level and the note the stop prints."""
    try:
        layout = json_layout(Path(path).read_text(encoding="utf-8"))
    except OSError:
        layout = None
    if layout is None:
        return json.dumps(plan, indent=1, ensure_ascii=False) + "\n", PATCH_REWROTE
    tail = layout.pop("tail")
    return json.dumps(plan, **layout) + tail, None


# A batch that runs one instruction several times for different bodies (realizations) sets
# FEM_OPERATOR_SEED: every generation seed the plan leaves at 0 or unset (the geometry's
# generation_settings.seed, its image_seed when it draws, the texture's texture_seed) becomes that
# number, written into plan.json, so two runs of the same words generate two bodies.  A seed the plan
# already sets to another number is the agent's own (a retry) and is kept.  Nothing else changes.
SEED_ENV = "FEM_OPERATOR_SEED"
# The generators take a geometry seed of 0-100 only (models.py GenerationSettings.seed; the plan
# lint refuses more), so a larger batch seed is folded into 1-100 there: with the default base 100,
# run k of a realization batch gets geometry seed k.  Seeds 101 and 102 were once
# refused at the lint and the agent set 100 by hand.  The image and texture seeds take any number.
GEOMETRY_SEED_MAX = 100


def geometry_seed(seed: int) -> int:
    return seed if seed <= GEOMETRY_SEED_MAX else (seed - 1) % GEOMETRY_SEED_MAX + 1


def batch_seed() -> int | None:
    value = os.environ.get(SEED_ENV, "").strip()
    try:
        seed = int(value)
    except ValueError:
        return None
    return seed if 0 < seed < 2 ** 31 else None


def with_batch_seed(plan: dict[str, Any], seed: int | None) -> tuple[dict[str, Any], list[str]]:
    """``plan`` with its 0 or unset generation seeds set to ``seed`` and the keys changed."""
    if not seed:
        return plan, []
    out, changed = copy.deepcopy(plan), []
    geometry = out.get("geometry")
    if isinstance(geometry, dict) and not geometry.get("asset_path"):
        settings = geometry.get("generation_settings")
        if isinstance(settings, dict) and not settings.get("seed"):
            settings["seed"] = geometry_seed(seed)
            changed.append("geometry.generation_settings.seed")
        drawing = geometry.get("draw") is True or "image_seed" in geometry \
            or str(geometry.get("generator") or "").lower() == "hunyuan3d"
        if drawing and not geometry.get("image_seed"):
            geometry["image_seed"] = seed
            changed.append("geometry.image_seed")
    texture = out.get("texture")
    if isinstance(texture, dict) and texture and not texture.get("texture_seed"):
        texture["texture_seed"] = seed
        changed.append("texture.texture_seed")
    return (out, changed) if changed else (plan, [])


def load_plan(path: Path, session: Path | None = None) -> dict[str, Any]:
    try:
        plan = json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise PlanError(f"cannot read the plan {path}: {exc}")
    return check_plan(plan, session)


# A free-form description is the object in a few words.  A controlled comparison (2026-10-11, long
# against short prompts over two seeds) found: past about 20 words the drawing prompt overflows the
# drawing model's 77 tokens and cuts the workflow's own style suffix; a negated noun gets drawn; and
# mesh words ("solid", "watertight", "hollow, empty inside") never change what the generators build.
# The tokens are counted by CLIP's own byte-pair encoding, read from a local copy of its vocabulary
# (no network, no tokenizer package: neither `tokenizers` nor `transformers` is in mechfoundry-agents);
# it matched transformers' CLIPTokenizer on 306 of 306 strings (2026-10-11).  Without the files the
# count is estimated, one per word, digit or punctuation run plus one per word over 10 letters: on
# 3000 prompts of 15-20-word descriptions it refused none that fit (the style exactly 32) and passed
# 54 of 66 that did not, by a few tokens (the earlier 1.3 per word plus a margin of 4 refused
# descriptions whose real prompt was 69 and 74 of 77).
CLIP_TOKENS = 77
CLIP_VOCAB = ("src/dependency/TripoSG/pretrained_weights/TripoSG-scribble/tokenizer",
              "src/dependency/Hunyuan3D-2.1/pretrained_weights/hf_cache/hub/"
              "models--stabilityai--stable-diffusion-xl-base-1.0/snapshots/*/tokenizer")
CLIP_SPLIT = re.compile(r"'s|'t|'re|'ve|'m|'ll|'d|[^\W\d_]+|\d|(?:[^\w\s]|_)+", re.I)
NEGATION = re.compile(r"\b(?:no|not|without|never|none)\b", re.I)
MESH_WORDS = re.compile(r"\bwatertight\b|\bempty inside\b|\bsolid\b(?=\s*(?:[,.;]|$|body\b|object\b|piece\b))|"
                        r"\bhollow\b(?=\s*(?:[,.;]|$))", re.I)
# View and pose words: the workflow's style frames every drawing, and a view asked for in the words
# fights it (a side view drew a flat elevation; review of 2026-10-11).
VIEW_WORDS = re.compile(r"\b(?:seen|viewed|shown|photographed)\s+from\b|"
                        r"\b(?:side|front|top|rear|back|bottom|end|plan|three[- ]quarters?|isometric|aerial|"
                        r"perspective|profile|elevation)\s+views?\b", re.I)


@functools.lru_cache(maxsize=1)
def clip_merges() -> dict[tuple[str, str], int] | None:
    """CLIP's BPE merge ranks from the first local vocabulary found, or None."""
    for pattern in CLIP_VOCAB:
        for folder in sorted(lib.REPO_ROOT.glob(pattern)):
            try:
                lines = (folder / "merges.txt").read_text(encoding="utf-8").split("\n")[1:49152 - 256 - 2 + 1]
            except OSError:
                continue
            return {tuple(m.split()): i for i, m in enumerate(lines) if len(m.split()) == 2}
    return None


@functools.lru_cache(maxsize=1)
def _clip_bytes() -> dict[int, str]:
    """CLIP's byte-to-character table (GPT-2's), for a word outside ASCII."""
    kept = list(range(33, 127)) + list(range(161, 173)) + list(range(174, 256))
    chars = kept[:] + [256 + n for n in range(256 - len(kept))]
    return dict(zip(kept + [b for b in range(256) if b not in kept], map(chr, chars)))


def _clip_bpe(word: str, ranks: dict[tuple[str, str], int]) -> int:
    parts = tuple(word[:-1]) + (word[-1] + "</w>",)
    while len(parts) > 1:
        best = min(zip(parts, parts[1:]), key=lambda p: ranks.get(p, 1 << 30))
        if best not in ranks:
            break
        merged, i = [], 0
        while i < len(parts):
            if i < len(parts) - 1 and (parts[i], parts[i + 1]) == best:
                merged.append(parts[i] + parts[i + 1])
                i += 2
            else:
                merged.append(parts[i])
                i += 1
        parts = tuple(merged)
    return len(parts)


def clip_tokens(text: str) -> tuple[int, bool]:
    """The drawing model's tokens for ``text`` with its start and end marks, and whether they were
    counted (True) or estimated (False, no local vocabulary)."""
    words = CLIP_SPLIT.findall(" ".join(str(text or "").split()).lower())
    ranks = clip_merges()
    if ranks is None:
        return sum(1 + (len(w) > 10 and w.isalpha()) for w in words) + 2, False
    table = _clip_bytes()
    return sum(_clip_bpe("".join(table[b] for b in w.encode("utf-8")), ranks) for w in words) + 2, True


def drawing_style() -> str:
    """The style the workflow appends to every drawing prompt (draw_image.STYLE), read from its file."""
    try:
        import ast
        path = SKILL_DIR.parents[2] / "hunyuan3d_wrapper" / "draw_image.py"
        for node in ast.parse(path.read_text(encoding="utf-8")).body:
            if isinstance(node, ast.Assign) and any(getattr(t, "id", None) == "STYLE" for t in node.targets):
                return str(ast.literal_eval(node.value))
    except (OSError, SyntaxError, ValueError):
        pass
    return "a single object, the whole object in frame, three-quarter view from slightly above, centered, plain " \
           "white background, soft even lighting, product photo"


def description_problem(geometry: dict[str, Any], instruction: str = "") -> str | None:
    """A free-form description (TripoSG text, a drawing) with a negation or mesh words, or a drawing
    description that overflows the drawing model's tokens with the style appended: one message,
    before anything is spent.  A view phrase the user's ``instruction`` itself contains is part of
    the object's name there, and is kept."""
    words = str(geometry.get("description") or "").strip()
    if not words or geometry.get("generator") in CAD_GENERATORS or geometry.get("asset_kind") == "surface":
        return None
    named = " ".join(str(instruction or "").lower().split())

    def in_instruction(m: re.Match) -> bool:
        # the exact phrase, as whole words: "... from" with the words it names ("from the <word>"),
        # so a phrase that only shares its first words with the instruction's is not exempt
        tail = re.match(r"\s+(?:(?:the|a|an)\s+)?[\w-]+", words[m.end():]) if m.group(0).lower().endswith("from") else None
        phrase = " ".join((m.group(0) + (tail.group(0) if tail else "")).lower().split())
        return bool(re.search(r"(?<![\w-])" + re.escape(phrase) + r"(?![\w-])", named))
    found = list(dict.fromkeys(m.group(0) for pattern in (NEGATION, MESH_WORDS, VIEW_WORDS)
                               for m in pattern.finditer(words)
                               if not (pattern is VIEW_WORDS and in_instruction(m))))
    # the prompt the workflow draws from: the description, ", " and its style (draw_image.draw)
    tokens, counted = clip_tokens(f"{words}, {drawing_style()}") if geometry.get("draw") else (0, True)
    long = tokens > CLIP_TOKENS
    if not found and not long:
        return None
    return ("plan.geometry.description: " + (f"drop {found} (a negated part gets drawn; mesh words change nothing; "
                                               "the workflow's style sets the view)"
                                               if found else "")
            + ("; " if found and long else "")
            + (f"the drawing prompt with the workflow's style appended is {tokens} of the drawing model's "
               f"{CLIP_TOKENS} tokens{'' if counted else ' (estimated)'}: it overflows" if long else "")
            + ": at most about 20 words, '<material> <object>, <2-3 defining shape features>' (geometry.md, Writing "
              "the description)")


def check_plan(plan: Any, session: Path | None = None) -> dict[str, Any]:
    """The plan's own checks, before anything is sent, every problem in one refusal (a plan refused
    one field at a time cost a run each, 2026-10-11).  ``session``: the texture's wording is
    checked only when it is new to that session (texture_is_new)."""
    if not isinstance(plan, dict):
        raise PlanError("the plan is a JSON object")
    problems: list[str] = []

    def check(fn, *args) -> None:
        try:
            fn(*args)
        except PlanError as exc:
            problems.append(str(exc))

    gone = [FIELDS_GONE[k] for k in plan if k in FIELDS_GONE]
    gone += [FIELDS_GONE[f"body_simplification.{k}"] for k in (plan.get("body_simplification") or {})
             if isinstance(plan.get("body_simplification"), dict) and f"body_simplification.{k}" in FIELDS_GONE]
    for group in ("contacts", "loads"):
        entries = plan.get(group) if isinstance(plan.get(group), dict) else {}
        gone += sorted({FIELDS_GONE[f"{group}.{k}"] for entry in entries.values() if isinstance(entry, dict)
                        for k in entry if f"{group}.{k}" in FIELDS_GONE})
    problems += gone
    unknown = sorted(set(plan) - set(PLAN_KEYS) - {"notes"} - set(FIELDS_GONE))
    if unknown:
        problems.append(f"unknown plan keys {unknown}; the keys are {list(PLAN_KEYS)}")
    for key in ("geometry", "scale", "material"):
        if not isinstance(plan.get(key), dict):
            problems.append(f"the plan needs {key!r} as an object")
    geometry = plan.get("geometry") if isinstance(plan.get("geometry"), dict) else {}
    said = description_problem(geometry, stored_instruction(lib.operator_dir(session)) if session is not None else "")
    if said:
        problems.append(said)
    web = geometry.get("web_image")
    if web is not None and (not isinstance(web, dict) or not str(web.get("query") or "").strip()
                            or set(web) - {"query", "pick", "why"} or re.search(r"https?:|www\.|/", str(web.get("query")))):
        # query words only: the runner alone searches, and never fetches a URL the agent wrote
        problems.append('plan.geometry.web_image is {"query": "<the object\'s noun phrase>"} (words, never a URL) '
                        'and, after the web_image stop, "pick": "<a candidate id>", or "none" with '
                        '"why": "<id>: <the check it failed>; ..."')
    if web is not None and (geometry.get("draw") or geometry.get("asset_path")):
        problems.append("plan.geometry.web_image is the image: leave draw and asset_path out")
    if "drawing_crop" in geometry and (geometry["drawing_crop"] != "largest" or not geometry.get("draw")):
        problems.append('plan.geometry.drawing_crop is "largest", beside "draw": true: the drawing\'s '
                        "largest object alone, which the drawing stop cuts out when it reads several")
    path = str(geometry.get("asset_path") or "")
    if "inputs/web/" in path.replace("\\", "/"):
        problems.append("plan.geometry.asset_path cannot name a web photograph: it is used only through "
                        'plan.geometry.web_image {"query": ..., "pick": "<id>"}, which counts and credits it')
    if path and (Path(path).is_absolute() or path.startswith("~")):
        problems.append("plan.geometry.asset_path is written relative to the repository root, as `blank` "
                        "prints it (output/fem_workflow_operator/<SID>/operator/…), not as an absolute path")
    if not str(plan.get("regions", "")).strip():
        problems.append("the plan needs 'regions': the supports and loads in words")
    if "body_up" in plan and plan["body_up"] not in BODY_UP:
        problems.append(f"plan.body_up is the body axis that points up in use, one of {list(BODY_UP)} (+y, an "
                        "upright body, when left out)")
    if not isinstance(plan.get("values"), dict):
        problems.append("the plan needs 'values' (dirichlet_values, acceleration; the loads come from the Use table)")
    if isinstance(plan.get("material"), dict):
        check(_check_material, plan["material"])
    for name, contact in (plan.get("contacts") or {}).items() if isinstance(plan.get("contacts"), dict) else ():
        if (not isinstance(contact, dict) or contact.get("transmits") not in TRANSMITS
                or not isinstance(contact.get("regions", []), list)
                or not isinstance(contact.get("pieces", 1), int)):
            problems.append(f"plan.contacts.{name} is {{\"transmits\": {' | '.join(map(json.dumps, TRANSMITS))}, "
                            "\"regions\": [<support regions, once previewed>]}, keyed by the brief's "
                            "contact (optional: \"simplified_to\", \"pieces\": <n> with \"pieces_why\": "
                            "\"<the brief's reason>\")")
            continue
        target, transmits = contact.get("simplified_to"), contact.get("transmits")
        if target not in (None, *SIMPLIFICATIONS):
            problems.append(f"plan.contacts.{name}.simplified_to is one of {list(SIMPLIFICATIONS)}")
        elif target and SIMPLIFIES[target] != transmits:
            problems.append(f"plan.contacts.{name}: simplified_to {target!r} idealises a contact that "
                            f"transmits {SIMPLIFIES[target]!r}, not {transmits!r}")
    hold = plan.get("reference_hold")
    if hold is not None and (not isinstance(hold, dict) or not isinstance(hold.get("regions", []), list)):
        problems.append("plan.reference_hold is {\"regions\": [<the support region at an end beyond "
                        "every reaction, once previewed>]}")
    users_file = bool(path) and "/operator/" not in "/" + path.replace("\\", "/")
    if "geometry_routes" not in plan and not users_file:
        problems.append("the plan needs 'geometry_routes': the routes the brief judged able to make this "
                        f"body and enough for it, generated first, from {list(GEOMETRY_ROUTES)} "
                        "(objectives/routes.md §3.4)")
    said = routes_problem(plan["geometry_routes"], session, generated=not users_file) \
        if "geometry_routes" in plan else None
    if said:
        problems.append(said)
    body = plan.get("body_simplification")
    if body is not None and (not isinstance(body, dict) or set(body) - {"kept", "left_out", "absent"} - {
            k.split(".", 1)[1] for k in FIELDS_GONE if k.startswith("body_simplification.")}
                             or not isinstance(body.get("absent", {}), (dict, list))):
        problems.append("plan.body_simplification is {\"absent\": [\"<Load path member>\", ...] (or "
                        "{\"<member>\": \"minor\" | \"major\"}), \"left_out\": <what the real body adds, optional>}: "
                        "every Load path member not absent is kept")
    if "thin_off_load_path" in plan and not str(plan.get("thin_off_load_path") or "").strip():
        problems.append("plan.thin_off_load_path is the sentence that names the thin part and why it "
                        "carries none of the load")
    if "bonded_gaps" in plan and not str(plan.get("bonded_gaps") or "").strip():
        problems.append("plan.bonded_gaps is the sentence that says which parts the solve joins across "
                        "a gap under a leaf, and why that leaves the case")
    from src.agents_wrapper.fem_workflow.models import SelectorSpec
    for name, selector in (plan.get("region_revisions") or {}).items() if isinstance(plan.get("region_revisions"), dict) else ():
        try:
            SelectorSpec.model_validate(selector)
        except ValueError as exc:
            problems.append(f"plan.region_revisions.{name} is not a selector: {str(exc)[:200]}")
    if texture_is_new(session, plan.get("texture")):
        check(_check_texture, plan.get("texture"), (plan.get("material") or {}).get("mode") == "parts"
              if isinstance(plan.get("material"), dict) else False)
    values = plan.get("values") if isinstance(plan.get("values"), dict) else {}
    if "load" in values:
        check(_check_load, values["load"], "values.load")
    for name, value in (values.get("neumann_values") or {}).items():
        check(_check_load, value, f"values.neumann_values.{name}")
    said = load_reduction_problem(session, plan.get("load_reduction"), plan)
    if said:
        problems.append(said)
    if problems:
        raise PlanError("; ".join(dict.fromkeys(problems)))
    return normalize_absent(plan)


def _check_material(material: dict[str, Any]) -> None:
    """Uniform values, or ``mode: parts`` with the words the part stage values from."""
    mode = material.get("mode", "uniform")
    if mode == "uniform":
        return
    if mode != "parts":
        raise PlanError("plan.material.mode is 'uniform' (the default) or 'parts'; VoMP is "
                        "not a plan material (materials.md: a comparison only)")
    if not str(material.get("description", "")).strip():
        raise PlanError("plan.material.mode 'parts' needs 'description': what each part is "
                        "made of, in the words the brief uses for its parts")
    for part in material.get("parts") or []:
        if not isinstance(part, dict) or "id" not in part:
            raise PlanError(f"each plan.material.parts entry needs an 'id' and the values to "
                            f"change: {json.dumps(part)[:80]}")


def _check_load(value: Any, label: str) -> None:
    """A load is a traction vector or a force total; anything else is a silent zero."""
    def vector(v):
        return (isinstance(v, (list, tuple)) and len(v) == 3
                and all(isinstance(c, (int, float)) and not isinstance(c, bool) for c in v))
    if vector(value) or (isinstance(value, dict) and set(value) == {"force"} and vector(value["force"])):
        return
    raise PlanError(f"{label} must be a traction [tx, ty, tz] (force per area, in stress "
                    f"units) or a total {{\"force\": [fx, fy, fz]}}; got {json.dumps(value)[:80]}")


# The paint's wording rule (geometry.md, Texture), checked with the plan, before anything is
# painted.  In 10 runs every plan's texture_prompt was written
# at plan time, before the rule was read at the texture stop; the first paint failed in 5 of 10
# runs (13 repaints, 631 s of painting, 16 % of the wall time).  These checks refuse 9 of the 10
# first prompts (9-23 words; 4 with two or more colours), the 5 that failed among them, and pass
# every accepted repaint (3-5 words, one colour).  The painter draws one reference and spreads
# its body colour over every face, so more words only add places and lights it cannot keep.
# Per-part materials name one colour per part, a clause each.
TEXTURE_WORDS_MAX = 8
# Colour words, generic; a hyphenated compound ("reddish-brown") is one colour.
TEXTURE_COLOURS = frozenset((
    "red orange yellow green blue purple violet pink brown black white grey gray beige tan cream "
    "creamy ivory gold golden silver teal cyan turquoise navy maroon olive khaki crimson scarlet "
    "magenta lime charcoal ochre amber burgundy indigo lavender mustard rust reddish orangish "
    "yellowish greenish bluish purplish pinkish brownish blackish whitish greyish grayish").split())
TEXTURE_RULE = (
    'plan.texture is {"texture_prompt": "<colour> <material>", "texture_seed": <integer, 0 by default>}: '
    "the material and one mid or light colour in a few words, a finish word at most. A body generated "
    "from an image (a drawing or a web photograph) is painted from that image, which the runner adds; "
    "the words then only keep the material and the plain colour a failed paint falls back to. From "
    "words alone the painter spreads one body colour over every face, so lighting, gloss, wear and colours tied to places "
    "(edges, holes, one face) come back as a darker, mottled or two-tone body, and dark or glossy "
    'words paint near-black. Per-part materials ("mode": "parts") name one colour per part: '
    '"<colour> <material> <part>, <colour> <material> <part>", which the painter does not place by part; '
    '{"per_part_colours": true} colours each part flat instead. A face painted flat grey is a failed '
    "view: change texture_seed (geometry.md, Texture)")


# The basic hue words.  Two of them side by side are two colours ("red white steel") unless they
# blend into one: a grey of a hue ("blue grey", "grey green") or two hues next to each other on the
# colour wheel ("blue green", "red brown").  Any other colour word before a colour is its modifier
# ("olive green", "charcoal grey", "golden brown", "creamy white", "rust red", "silver grey"), one
# colour with it.
TEXTURE_BASIC_HUES = frozenset("red orange yellow green blue purple violet pink brown black white grey".split())
TEXTURE_NEIGHBOUR_HUES = frozenset(frozenset(pair.split("-")) for pair in (
    "red-orange orange-yellow yellow-green green-blue blue-purple blue-violet purple-violet "
    "purple-red violet-red red-pink pink-purple red-brown orange-brown yellow-brown").split())
# Shade words: not a material or a part, so a side of only these and a colour ("mid grey") is a
# colour, not a part (texture_parts).
TEXTURE_SHADES = frozenset("light dark pale mid medium deep bright muted soft warm cool".split())


def _is_colour(token: str) -> bool:
    return any(p in TEXTURE_COLOURS for p in token.split("-"))


def _one_colour(before: str, word: str) -> bool:
    """Whether colour word ``word`` right after colour word ``before`` names the same colour."""
    if before not in TEXTURE_BASIC_HUES:
        return word in TEXTURE_COLOURS                      # a modifier: olive green, rust red
    if word not in TEXTURE_BASIC_HUES:
        return False
    if "grey" in (before, word):                            # blue grey, grey green; not black grey
        return not {before, word} & {"black", "white"} and before != word
    return frozenset((before, word)) in TEXTURE_NEIGHBOUR_HUES


def texture_colours(clause: str) -> tuple[int, list[str]]:
    """(words, colours) of one clause.  A colour is a run of colour words that blend into one: a
    modifier and its hue ("olive green", "golden brown", "rust red"), a hue's grey ("blue grey"),
    neighbouring hues ("blue green") or a hyphenated compound ("reddish-brown").  Two basic hues side
    by side ("red white steel") are two colours, and so are colours apart: a word between them
    ("grey steel, brown wood"), a comma or slash ("red, white", "black/white") or a joining "and",
    "with" or "&" ("red and white", "red-and-white").  The same colour said twice is one."""
    text = re.sub(r"-(and|with)-", r" \1 ", clause.lower()).replace("&", " and ")
    tokens = re.findall(r"[a-z]+(?:-[a-z]+)*|[,/;]", text)
    words = [t for t in tokens if t not in ",/;"]
    colours, current, last = [], [], None
    for token in tokens:
        if token in ",/;" or not _is_colour(token):
            if current:
                colours.append(" ".join(current))
            current, last = [], None
            continue
        for word in token.split("-"):                       # blue-grey: blue, then grey
            word = "grey" if word == "gray" else word
            if word not in TEXTURE_COLOURS:
                continue
            if last is not None and not _one_colour(last, word):
                colours.append(" ".join(current))
                current = []
            current.append(word)
            last = word
    if current:
        colours.append(" ".join(current))
    return len(words), sorted(set(colours))


def texture_parts(words: str) -> list[str]:
    """Per-part materials' clauses: split on commas and semicolons, and on "and" / "with" between
    two parts ("grey steel plate and brown wood rail", "grey steel plate and brown rail"), each
    "<colour> <material> <part>" with a word besides its colour and shade.  A side with none is a
    colour joined to the next ("red and white steel plate", "mid grey and blue steel frame"), kept
    with it so it counts as two."""
    def plain(piece: str) -> int:
        return sum(not _is_colour(t) and t not in TEXTURE_SHADES
                   for t in re.findall(r"[a-z]+(?:-[a-z]+)*", piece.lower()))
    out = []
    for clause in re.split(r"[,;]", words):
        pieces = re.split(r"\s+(and|with)\s+", clause)
        merged: list[str] = []
        for k in range(0, len(pieces), 2):
            piece = pieces[k]
            if merged and (plain(piece) < 1 or plain(merged[-1]) < 1):
                merged[-1] = f"{merged[-1]} {pieces[k - 1]} {piece}"
            else:
                merged.append(piece)
        out += merged
    return out


def _check_texture(texture: Any, parts: bool) -> None:
    """plan.texture's words: at most TEXTURE_WORDS_MAX words and one colour (texture_colours; per
    part in parts mode, texture_parts), and a whole-number seed or none."""
    if texture is None:
        return
    if isinstance(texture, dict) and "per_part_colours" in texture:
        _check_part_colours(texture, parts)
        return
    if not isinstance(texture, dict) or not (str(texture.get("texture_prompt") or "").strip()
                                             or texture.get("texture_image")):
        raise PlanError(TEXTURE_RULE)
    seed = texture.get("texture_seed")
    seed = 0 if seed is None else seed
    if isinstance(seed, bool) or not isinstance(seed, int) or not 0 <= seed < 2 ** 32:
        raise PlanError(f"plan.texture.texture_seed is a whole number from 0: {TEXTURE_RULE}")
    words = str(texture.get("texture_prompt") or "").lower()
    for clause in (texture_parts(words) if parts else [words]):
        count, colours = texture_colours(clause)
        if count > TEXTURE_WORDS_MAX or len(colours) > 1:
            found = f"{count} words" + (f", colours {colours}" if len(colours) > 1 else "")
            raise PlanError(f"plan.texture.texture_prompt has {found}{' in one part' if parts else ''}; {TEXTURE_RULE}")


PART_COLOURS_RULE = (
    'plan.texture {"per_part_colours": true} colours each part of a per-part material ("mode": "parts") '
    "flat, in its material's colour (parts of one material share it); {\"per_part_colours\": {\"<part id>\": "
    "\"<colour words>\"}} names a part's colour (one colour, a shade word at most, e.g. \"light brown\"), the "
    "rest in their montage colour. It stands alone in plan.texture: no texture_prompt beside it (geometry.md, "
    "Texture)")


# per_part_colours true: each part in its material's colour.  It once took the part montage's
# colours, which are the segmentation's debug colours: in one run one handle of
# one material came out in two colours, and two runs spent a turn naming every part's colour by
# hand.  A part's material is read from its values (E, density), named by the description's words
# where they say which of the fitting materials it is; parts whose values lie within
# PART_SAME_MATERIAL of each other are one material (the vision valuation scatters one material's
# values by a few per cent) and share a colour.  The table is ordered so that the first material
# whose ranges fit is the likelier one, and its density ranges keep the families apart where the
# moduli overlap (glass 2200-2600 kg/m3 against aluminium 2600-2950; magnesium before the
# composites, which only their words choose there).
# (name, E range in Pa, density range in kg/m3, words that name it, colour words when the
# description gives none; None: the description's colour, else the calm palette)
METAL_WORDS = ("metal", "metallic", "alloy")
MATERIAL_COLOURS = (
    ("foam", (1e3, 5e7), (10, 400), ("foam", "sponge", "padding", "cushion"), "light grey"),
    ("rubber", (1e5, 2e8), (800, 2000), ("rubber", "elastomer", "silicone", "neoprene", "latex", "tpe"),
     "rubber"),
    ("plastic", (1e8, 1e10), (800, 2200), ("plastic", "polymer", "nylon", "abs", "polypropylene", "polyethylene",
                                           "hdpe", "ldpe", "pvc", "acrylic", "polycarbonate", "resin", "pet", "pom",
                                           "acetal", "polystyrene", "ptfe", "pla"), None),
    ("wood", (4e9, 2.5e10), (250, 1200), ("wood", "wooden", "timber", "oak", "pine", "beech", "birch", "maple",
                                          "walnut", "ash", "bamboo", "plywood", "mahogany", "spruce", "hardwood",
                                          "softwood", "cork"), "wood"),
    ("magnesium", (4e10, 4.8e10), (1700, 1900), ("magnesium",) + METAL_WORDS, "silver"),
    ("aluminium", (6e10, 8e10), (2600, 2950), ("aluminium", "aluminum") + METAL_WORDS, "aluminium"),
    ("glass", (4.5e10, 9e10), (2200, 2600), ("glass",), "light cyan"),
    ("composite", (2e10, 2.5e11), (1400, 2100), ("carbon", "fibre", "fiber", "composite", "cfrp", "gfrp",
                                                 "fibreglass", "fiberglass"), "charcoal"),
    ("concrete", (1.5e10, 6e10), (1800, 2800), ("concrete", "stone", "granite", "marble", "brick", "mortar",
                                                "cement", "terracotta", "clay"), "concrete"),
    ("ceramic", (5e10, 4.5e11), (2000, 4200), ("ceramic", "porcelain", "stoneware", "earthenware", "alumina"),
     "ceramic"),
    ("titanium", (1e11, 1.3e11), (4300, 4700), ("titanium",) + METAL_WORDS, "titanium"),
    ("copper alloy", (8e10, 1.45e11), (8100, 9000), ("copper", "brass", "bronze") + METAL_WORDS, "brass"),
    ("cast iron", (8e10, 1.8e11), (6800, 7400), ("iron",) + METAL_WORDS, "iron"),
    ("steel", (1.8e11, 2.2e11), (7500, 8100), ("steel", "stainless", "chrome", "iron") + METAL_WORDS, "steel"),
)
# Calm, distinct colours for a material the table does not know (or a plastic its words give no colour).
PART_PALETTE = ("teal", "ochre", "olive", "light blue", "beige", "violet", "khaki", "turquoise")
PART_SAME_MATERIAL = 0.10      # values within 10 % of each other are one material


def _readable_colour(words: str | None) -> bool:
    """Whether the workflow's colour reader (plain_colour) reads ``words`` as a colour, not its
    mid-grey default: "timber" or "nylon" would otherwise colour a part grey."""
    if not words:
        return False
    try:
        from src.hunyuan3d_wrapper.surface import plain_colour
    except Exception:          # the reader not importable: trust the table's own words
        return True
    return not plain_colour(words)[1].startswith("mid grey")


def part_material_colours(parts: list[dict[str, Any]], *texts: str) -> dict[str, str]:
    """{"<part id>": "<colour words>"}: each part in its material's colour (MATERIAL_COLOURS), from
    its E and density and the words of ``texts`` (the material description, a texture prompt) that
    name which fitting material it is and, when they do, its colour.  Parts of one material (values
    within PART_SAME_MATERIAL) share a colour; a material the table does not know takes the next
    colour of a calm palette."""
    clauses = [c.strip().lower() for text in texts if text for c in texture_parts(str(text)) if c.strip()]
    groups: list[tuple[float, float, list[int]]] = []
    for part in sorted(parts, key=lambda q: int(q.get("id", 0))):
        try:
            modulus, density = float(part["youngs_modulus"]), float(part["density"])
        except (KeyError, TypeError, ValueError):
            continue
        same = next((g for g in groups if abs(modulus - g[0]) <= PART_SAME_MATERIAL * g[0]
                     and abs(density - g[1]) <= PART_SAME_MATERIAL * g[1]), None)
        if same is None:
            groups.append((modulus, density, [int(part["id"])]))
        else:
            same[2].append(int(part["id"]))
    out, used, palette = {}, set(), iter(PART_PALETTE)
    for modulus, density, ids in groups:
        fitting = [m for m in MATERIAL_COLOURS
                   if m[1][0] <= modulus <= m[1][1] and m[2][0] <= density <= m[2][1]]
        chosen, clause = (fitting[0] if fitting else None), None
        for material in fitting:                    # the description says which fitting material it is
            named = next((c for c in clauses if set(re.findall(r"[a-z]+", c)) & set(material[3])), None)
            if named is not None:
                chosen, clause = material, named
                break
        words = None
        if clause is not None:
            colours = texture_colours(clause)[1]
            tokens = re.findall(r"[a-z]+", clause)
            if colours:
                first = colours[0]
                index = next((k for k, t in enumerate(tokens) if t == first.split()[0]), None)
                shade = tokens[index - 1] if index and tokens[index - 1] in TEXTURE_SHADES else None
                words = f"{shade} {first}" if shade else first
            else:
                # the material's own word when the colour reader knows it ("pine", "brass"), else
                # the family's colour ("timber" and "plywood" are wood, "stainless" is steel)
                words = next((t for t in tokens if t in chosen[3] and _readable_colour(t)), None)
        if not _readable_colour(words):
            words = chosen[4] if chosen is not None else None
        if words is None:
            words = next((c for c in palette if c not in used), "grey")
        if words in used and len(words.split()) == 1:
            # another material (values over 10 % apart) already took these words: a shade keeps them apart
            words = f"light {words}" if f"light {words}" not in used else f"dark {words}"
        used.add(words)
        for i in ids:
            out[str(i)] = words
    return out


def resolved_part_colours(plan: dict[str, Any], card: dict[str, Any] | None = None) -> Any:
    """plan.texture.per_part_colours as sent: true read as each part's material colour, from the
    parts the card has valued (with the plan's corrections), else the plan's own parts; true as it
    is while no part has values (the workflow then takes the montage colours)."""
    wanted = per_part_colours(plan)
    if wanted is not True:
        return wanted
    material = plan.get("material") or {}
    parts = {int(p["id"]): dict(p) for p in (card or {}).get("material_parts") or [] if "id" in p}
    for edit in material.get("parts") or []:
        if isinstance(edit, dict) and "id" in edit:
            parts[int(edit["id"])] = {**parts.get(int(edit["id"]), {}), **edit}
    colours = part_material_colours(list(parts.values()), str(material.get("texture_prompt") or ""),
                                    str(material.get("description") or ""))
    return colours or True


def _check_part_colours(texture: dict[str, Any], parts: bool) -> None:
    """plan.texture.per_part_colours: only with a per-part material, alone in plan.texture, true or
    part ids to colour words of one colour each."""
    wanted = texture.get("per_part_colours")
    if not parts:
        raise PlanError("plan.texture.per_part_colours colours the parts a per-part material is valued on: "
                        'it needs plan.material.mode "parts". ' + PART_COLOURS_RULE)
    if set(texture) - {"per_part_colours"}:
        raise PlanError(f"plan.texture has {sorted(set(texture) - {'per_part_colours'})} beside "
                        "per_part_colours. " + PART_COLOURS_RULE)
    if wanted is True:
        return
    if not isinstance(wanted, dict) or not wanted:
        raise PlanError(PART_COLOURS_RULE)
    for key, words in wanted.items():
        if not str(key).strip().isdigit():
            raise PlanError(f"plan.texture.per_part_colours key {key!r} is no part id. " + PART_COLOURS_RULE)
        count, colours = texture_colours(str(words).lower())
        if count > 3 or len(colours) != 1:
            raise PlanError(f"plan.texture.per_part_colours[{key!r}] {words!r} is not one colour in a few "
                            "words. " + PART_COLOURS_RULE)


DARK_TEXTURE_WORDS = re.compile(r"\b(dark\w*|polished|gloss\w*)\b", re.I)
TEXTURE_WORDS_SAID = "texture_words_said.json"


def texture_words_note(session: Path | None, texture: Any) -> str | None:
    """Before the session's first paint, words that paint near-black (dark, polished, glossy):
    said once per wording, never refused.  Only before it: several runs
    repainted good paints because a rule about these words read as one about the
    paint that came back."""
    if session is None or not isinstance(texture, dict):
        return None
    operator = lib.operator_dir(session)
    if ((lib.read_json(operator / "run_sent.json", {}) or {}).get("texture") is not None
            or (lib.read_json(operator / PAINT_AHEAD, {}) or {}).get("answer")):
        return None
    words = str(texture.get("texture_prompt") or "")
    found = sorted({w.lower() for w in DARK_TEXTURE_WORDS.findall(words)})
    if not found or (lib.read_json(operator / TEXTURE_WORDS_SAID, {}) or {}).get("words") == words:
        return None
    lib.write_json(operator / TEXTURE_WORDS_SAID, {"words": words})
    return (f"plan.texture names {found}, which paint near-black: before the first paint, write a mid or light "
            "shade (geometry.md, Texture). Said once, not a refusal")


def texture_is_new(session: Path | None, texture: Any) -> bool:
    """Whether plan.texture is new to this session: not the texture already sent to its card nor
    the one painted ahead.  Only a new one is checked, so a session resumed under a later rule is not
    refused on every run for words it has already painted."""
    if session is None or texture is None:
        return True
    operator = lib.operator_dir(session)
    sent = (lib.read_json(operator / "run_sent.json", {}) or {}).get("texture")
    if sent is not None and same_plan_value(sent, texture):
        return False
    painted = dict((lib.read_json(operator / PAINT_AHEAD, {}) or {}).get("answer") or {})
    painted.pop("action", None)
    return not (painted and isinstance(texture, dict)
                and same_plan_value(_normalized(painted), {k: v for k, v in texture.items() if v is not None}))


# The plan sections the runner sends, each at its card, in the order the cards
# come.  A section changed after its card was answered means a rewind to that
# card: the edited description regenerates, the edited words preview again.
SECTION_CARDS = (("geometry", "geometry_input"), ("texture", "material_input"),
                 ("scale", "geometry_physics"), ("segmentation", "bc_input"),
                 ("regions", "bc_input"), ("values", "bc_values"), ("use_table", "bc_values"),
                 ("body_up", "bc_values"), ("load_reduction", "bc_values"),
                 ("material", "material_input"))
CARD_ORDER = ("geometry_input", "geometry_texture", "geometry_physics", "bc_input",
              "bc_values", "material_input", "shape_opt_settings")


def _normalized(value: Any) -> str:
    return json.dumps(value, sort_keys=True, default=str)


PLAN_DIGITS = 6       # plan numbers compared to 6 significant digits (statics prints 3 decimals)


def _canonical(value: Any) -> Any:
    """A plan value with its numbers compared as numbers: -0.0 is 0, 0 is 0.0, and a float's digits
    past the sixth significant one are rounding; integers, integral floats (as integers) and booleans
    compare exactly (a boolean is tagged, so true is not 1).  A text comparison read statics' reaction [-0.0, F, 0.0], as
    the runner applied it, and the plan's [0, F, 0] as a changed plan.values: every run of one
    session rewound to the values card and repainted (5 runs, 30-45 s each)."""
    if isinstance(value, bool):
        return ("bool", value)
    if value is None or isinstance(value, str):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            return value
        if value.is_integer() and abs(value) < 2 ** 53:
            return int(value)               # 1234567.0 is the integer 1234567, compared exactly
        return float(f"{value:.{PLAN_DIGITS}g}") + 0.0
    if isinstance(value, dict):
        return {str(k): _canonical(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_canonical(v) for v in value]
    return value


def same_plan_value(sent_text: str | None, value: Any) -> bool:
    """Whether a section sent (its ``_normalized`` text) holds the plan's value, numbers compared
    as numbers (``_canonical``)."""
    if sent_text is None:
        return False
    try:
        before = json.loads(sent_text)
    except ValueError:
        return sent_text == _normalized(value)
    return _canonical(before) == _canonical(json.loads(_normalized(value)))


def statics_filled(session: Path) -> tuple[dict[str, Any], list[str]]:
    """The reactions statics gave at the last values card, {region: force_N}, and the regions
    the runner applied them to over the plan's own values (``applied`` in operator/statics.json)."""
    record = lib.read_json(lib.operator_dir(session) / "statics.json", {}) or {}
    derived = {r["region"]: r["force_N"] for r in record.get("reactions") or []
               if isinstance(r, dict) and r.get("region") and r.get("force_N") is not None}
    # the Use table's forces the runner put on load regions (use_table_values) are its own too: a
    # run after them read the plan without them as a values change, rewound and repainted each time
    table = (lib.read_json(lib.operator_dir(session) / TABLE_VALUES, {}) or {}).get("forces") or {}
    return {**table, **derived}, list(table) + [str(r) for r in record.get("applied") or []]


def with_statics(values: Any, derived: dict[str, Any], applied: list[str] | None = None) -> Any:
    """The plan's values as the runner sends them once statics' reactions are in: each derived
    reaction on its region where the plan has none, and where the runner applied it over the
    plan's (``applied``)."""
    if not isinstance(values, dict) or not derived:
        return values
    neumann = dict(values.get("neumann_values") or {})
    for region, force in derived.items():
        if region not in neumann or region in (applied or ()):
            neumann[region] = {"force": force}
    return {**values, "neumann_values": neumann}


def changed_sections(plan: dict[str, Any], sent: dict[str, str], kind: str,
                     derived: dict[str, Any] | None = None,
                     applied: list[str] | None = None) -> list[tuple[str, str]]:
    """(section, card) pairs already sent whose plan value differs, before ``kind``.

    ``derived`` (``statics_filled``) are the reactions the runner itself put into plan.values at
    the values card: the values sent then carry them, the plan does not, and that difference is
    the runner's own, never a plan change.  Compared as the plan alone, it rewound one
    run to the values card and repainted at four texture stops in a row (about
    45 s), until the agent copied statics' reactions into the plan."""
    position = CARD_ORDER.index(kind) if kind in CARD_ORDER else len(CARD_ORDER)

    def same(section: str) -> bool:
        if same_plan_value(sent[section], plan.get(section)):
            return True
        return bool(section == "values" and derived
                    and same_plan_value(sent[section], with_statics(plan.get(section), derived, applied)))
    return [(section, card) for section, card in SECTION_CARDS
            if CARD_ORDER.index(card) < position and section in sent and not same(section)]


def plan_settings(plan: dict[str, Any]) -> dict[str, Any]:
    """The solve's settings: every field, from the class defaults, then the plan's entries.

    float64 is pinned although ShapeOptSettings now defaults to it (kept so a plan's
    settings never depend on that default).  Keys the settings no longer have are
    dropped: the model ignores them, and the card's defaults never carry them, so
    kept they would read as a change after every solve (an old plan's
    reinit_n_iters, removed as never used).  A retired sdf_bc_fix_method "graft" is read
    as "mask" here, as the model reads it, for the same reason.
    """
    from src.agents_wrapper.fem_workflow.models import ShapeOptSettings
    known = ShapeOptSettings.model_fields
    settings = {k: v for k, v in (plan.get("settings") or {}).items() if k in known}
    if "sdf_bc_fix_method" in settings:
        settings["sdf_bc_fix_method"] = ShapeOptSettings.retire_graft(settings["sdf_bc_fix_method"])
    return {**ShapeOptSettings().model_dump(mode="json"), "use_mixed_precision": True, **settings}


def _settings_changed(plan_settings: dict[str, Any], defaults: dict[str, Any]) -> list[str]:
    return sorted(k for k, v in plan_settings.items() if defaults.get(k) != v)


# A segmentation that ran out of GPU memory fails the same way when sent again unchanged: one run
# sent it three times (once after stopping workers, once with another method) on a 1.16 M
# face body.  The runner records the body and settings and refuses that resend before it is spent.
SEGMENTATION_OOM = "segmentation_oom.json"


def out_of_memory(error: Any) -> bool:
    text = str(error or "").lower()
    return "out of memory" in text or "outofmemory" in text


def _segmentation_key(session: Path, answer: Any) -> str | None:
    if not isinstance(answer, dict) or answer.get("action") != "preview_segmentation":
        return None
    return _normalized([body_digest(session), answer.get("segmentation") or {}])


def record_segmentation_oom(session: Path, answer: Any) -> None:
    key = _segmentation_key(session, answer)
    if key is None:
        return
    record = lib.read_json(lib.operator_dir(session) / SEGMENTATION_OOM, []) or []
    if key not in record:
        lib.write_json(lib.operator_dir(session) / SEGMENTATION_OOM, record + [key])


def segmentation_oom_problem(session: Path, answer: Any) -> str | None:
    """The same segmentation of the same body as one that ran out of GPU memory: refused unsent."""
    key = _segmentation_key(session, answer)
    if key is None or key not in (lib.read_json(lib.operator_dir(session) / SEGMENTATION_OOM, []) or []):
        return None
    faces = None
    try:
        mesh = _generated_mesh(session)
        faces = len(mesh.faces) if mesh is not None else None
    except Exception:
        pass
    return ("this segmentation ran out of GPU memory on this body" + (f" ({faces} faces)" if faces else "")
            + " and is not sent again unchanged: make the body smaller (a TripoSG body at depth 8 or 9 is capped "
            f"at {FINE_FACES} faces when generated again; or the coarser extraction), or change plan.segmentation "
            "(fewer num_clusters, or method shape_diameter)")


# The regions are previewed only on a body the geometry stop accepted: one whose run on from that stop
# passed its checks (G4, the load path, the mass rule, the gaps).  One run previewed regions
# on a body it then rejected.  The acceptance is recorded by the body's digest.
ACCEPTED_BODY = "accepted_body.json"
PREVIEW_ACTIONS = ("preview_segmentation", "preview_regions", "revise_regions")


def accept_body(session: Path) -> None:
    lib.write_json(lib.operator_dir(session) / ACCEPTED_BODY, {"digest": body_digest(session), "time": time.time()})


def body_lock_problem(session: Path, answer: Any) -> str | None:
    """A regions preview on a body the geometry stop has not accepted (ACCEPTED_BODY)."""
    if not isinstance(answer, dict) or answer.get("action") not in PREVIEW_ACTIONS:
        return None
    digest = body_digest(session)
    if digest is None or (lib.read_json(lib.operator_dir(session) / ACCEPTED_BODY, {}) or {}).get("digest") == digest:
        return None
    return ("the regions are previewed only on a body the geometry stop accepted: run on from the geometry stop "
            "(its checks pass) before any preview")


def preview_stage(session: Path, plan: dict[str, Any]) -> str | None:
    """The limit a region preview spends: the same words as the last preview on another
    segmentation are a re-segmentation, with its own limit, so getting the parts a load, a
    support or a material needs does not spend the region previews."""
    last = lib.read_json(lib.operator_dir(session) / "last_preview.json", {}) or {}
    words = str(plan.get("regions") or "").strip()
    segmentation = _normalized(plan.get("segmentation") or {})
    if last and last.get("words") == words and last.get("segmentation") != segmentation:
        return "segmentation"
    return "regions"


def split_problem(drawing: Any) -> None:
    """A drawing whose cut-out reads as several objects is never generated from whole, by any
    route: its largest object (drawing_crop "largest") or a new drawing.  Until 2026-10-11 it was
    refused once and then taken unchanged, and two runs generated from drawings of
    several or the wrong objects that way; one object whose silhouette splits (a U or H shape)
    is drawn again rather than let a split drawing through."""
    if not drawing or not Path(str(drawing)).exists():
        return
    counted = drawing_objects(drawing) or {}
    if (counted.get("objects") or 0) < 2:
        return
    raise PlanError(f"the drawing reads as {counted['objects']} objects and is not generated from whole: its "
                    "largest one (geometry.drawing_crop \"largest\") when that is the whole object, else draw "
                    "again (new words or image_seed; geometry.md, SDXL drawing)")


def plan_answer(kind: str, card: dict[str, Any], plan: dict[str, Any],
                revision: dict[str, Any] | None = None
                ) -> tuple[dict[str, Any] | None, str | None, str | None]:
    """The answer the plan gives this card: (answer, counted stage, stop after it).

    ``None`` as the answer means the session is complete (the settings card
    after a solve the plan does not change).  ``revision`` is the last prompt
    revision the runner saw complete (``note_revision``): the text it was made
    from, the generator, and the text it returned.
    """
    if kind == "geometry_input":
        geometry = dict(plan["geometry"])
        draw = bool(geometry.pop("draw", False))
        seed = geometry.pop("image_seed", 0)
        crop = geometry.pop("drawing_crop", None)
        description = str(geometry.get("description") or "").strip()
        # The card's drawing is reused only when it was drawn from these words
        # and this seed; new words or a new seed draw again.
        drawn = (card.get("drawn_image") and
                 str(card.get("drawn_image_prompt") or "").strip() == description and
                 int(card.get("image_seed") or 0) == int(seed))
        if draw and not drawn:
            # Drawn, then shown at the drawing stop before anything is generated from it.  A
            # drawing made for Hunyuan3D is one of Hunyuan3D's attempts, counted now, rejected or
            # not (hunyuan_charge makes the body generated from it that same attempt): counted
            # only at generation, one run drew three for a limit of two.
            return ({"action": "draw_image", "description": description, "image_seed": seed},
                    "hunyuan" if geometry.get("generator") == "hunyuan3d" else "drawing", "drawing")
        if draw:
            # Generating from the drawing is the drawing's own attempt, counted
            # when it was drawn: it does not spend a text generation.  Hunyuan3D
            # from the same drawing is its own step of the ladder, with its own limit.
            geometry.pop("revise_prompt", None)
            stage = "hunyuan" if geometry.get("generator") == "hunyuan3d" else None
            if crop:
                # The drawing's largest object alone, cut out at the drawing stop (several objects
                # drawn): the same drawing's attempt, generated from one object.
                cut = largest_object_path(card["drawn_image"])
                if not cut.exists():
                    raise PlanError("geometry.drawing_crop \"largest\": the drawing stop cut out no "
                                    "largest object (the drawing reads as one); leave drawing_crop out")
                return ({**geometry, "asset_path": str(cut), "asset_kind": "image"}, stage, "geometry")
            split_problem(card.get("drawn_image"))
            return ({**geometry, "use_drawn_image": True}, stage, "geometry")
        if geometry.get("generator") == "hunyuan3d" and geometry.get("asset_kind") != "image":
            raise PlanError("Hunyuan3D takes an image: the drawing (geometry.draw true, with its "
                            "words and image_seed) or the user's (asset_path, asset_kind 'image')")
        # Each route has its own attempts: a built or uploaded body is not a
        # text generation, and neither is a CAD generation.
        cad = geometry.get("generator") in CAD_GENERATORS
        stage = ("upload" if geometry.get("asset_kind") == "surface"
                 else "cad" if cad else "hunyuan" if geometry.get("generator") == "hunyuan3d"
                 # a picked web photograph was counted when it was searched for
                 else None if WEB_DIR in str(geometry.get("asset_path") or "").replace("\\", "/")
                 else "generation")
        if geometry.get("revise_prompt"):
            # A revision is keyed to the text it was made from, as a drawing is
            # keyed to its words and seed: the card's revised text is generated
            # from only while the plan still holds the words it revised.  An
            # edited description is revised again, never replaced by the old
            # revision.
            shown = str(card.get("description") or "").strip()
            rev = revision or {}
            if (str(rev.get("source") or "").strip() == description
                    and rev.get("generator") == (geometry.get("generator") or "triposg")
                    and rev.get("revised") and shown == str(rev["revised"]).strip()):
                return ({**geometry, "description": shown, "revise_prompt": False},
                        stage, "geometry")
            # A CAD revision is read before it is generated from: a revision can
            # drop a feature or a dimension.
            return (geometry, None, "revision" if cad else None)
        return (geometry, stage, "geometry")
    if kind == "geometry_texture":
        # Painted at the material card instead, once the geometry is final (texture_answer): a
        # paint here was thrown away by every later regeneration, and took 77-90 s cold.
        return ({"action": "skip_texture"}, None, None)
    if kind == "geometry_physics":
        return ({"action": "apply_scaling", **plan["scale"]}, None, None)
    if kind == "bc_input":
        wanted = str(plan["regions"]).strip()
        segmentation = plan.get("segmentation") or {}
        shown = dict(card.get("segmentation") or {})
        same_segmentation = all(shown.get(k) == v for k, v in segmentation.items())
        if not card.get("has_segmentation") or not same_segmentation:
            # Segment and name the parts first (again, after a change of segmentation):
            # the region synthesizer then maps a part named in the words to a segment
            # instead of guessing.
            answer = {"action": "preview_segmentation"}
            if segmentation:
                answer["segmentation"] = segmentation
            return (answer, None, None)
        if str(card.get("description") or "").strip() == wanted and same_segmentation:
            if card.get("preview_error"):
                raise PlanError(f"the preview of these words failed ({card['preview_error']}); "
                                "correct the synthesized selector in plan.region_revisions, or "
                                "reword plan.regions (boundary_conditions.md §2)")
            if card.get("has_regions") and not card.get("api_error"):
                return ({"action": "approve_regions"}, None, None)
        answer = {"action": "preview_regions", "description": wanted}
        if segmentation:
            answer["segmentation"] = segmentation
        return (answer, "regions", "regions")
    if kind == "bc_values":
        values = plan["values"]
        answer = {"action": "apply_values"}
        given = values.get("dirichlet_values") or {}
        named = values.get("neumann_values") or {}
        supports = [item["name"] for item in card.get("dirichlet") or []]
        loads = [item["name"] for item in card.get("neumann") or []]
        # A named value that matches no region would otherwise fall back to the
        # default (a full clamp, the shared load) without a word, undoing the
        # brief's contact line: refuse, and show the names the preview made.
        unknown = [n for n in given if n not in supports] + [n for n in named if n not in loads]
        if unknown:
            raise PlanError(f"plan.values names {unknown}, which are not regions of this preview: "
                            f"the supports are {supports} and the loads {loads}; use those names")
        unbound = [n for n in supports if n not in region_contacts(plan.get("contacts"))
                   and n not in ((plan.get("reference_hold") or {}).get("regions") or [])]
        if unbound:
            raise PlanError(f"support regions {unbound} are in no contact's regions: list each in "
                            "plan.contacts.<brief contact>.regions")
        answer["dirichlet_values"] = {
            item["name"]: given.get(item["name"]) or {"components": [0, 1, 2], "value": 0.0}
            for item in card.get("dirichlet") or []}
        neumann = {}
        for item in card.get("neumann") or []:
            value = named.get(item["name"], values.get("load"))
            if value is None:
                raise PlanError(f"plan.values gives no load for region {item['name']!r}: add "
                                "'load' (applied to every load region) or neumann_values")
            neumann[item["name"]] = value
        answer["neumann_values"] = neumann
        for key in ("acceleration", "body_force"):
            if key in values:
                answer[key] = body_vector(plan, key)       # the use frame's, turned with plan.body_up
        reduction = plan.get("load_reduction")
        if isinstance(reduction, (int, float)) and not isinstance(reduction, bool) and 0 < reduction < 1:
            # the runner's offered fraction (load_reduction_offer, checked by check_plan): every load as
            # the solver's own load scale scales them, prescribed displacements with them
            answer["neumann_values"] = {k: _scaled_load(v, float(reduction)) for k, v in neumann.items()}
            for key in ("acceleration", "body_force"):
                if key in answer:
                    answer[key] = _scaled_load(answer[key], float(reduction))
            answer["dirichlet_values"] = {k: (_scaled_load(v, float(reduction)) if isinstance(v, dict) else v)
                                          for k, v in answer["dirichlet_values"].items()}
        return (answer, None, None)
    if kind == "material_input":
        material = dict(plan["material"])
        texture = plan.get("texture")
        if (texture and card.get("surface_has_colour") is False
                and not (card.get("textured_surface") and texture_matches(card, texture, plan))):
            # The regions are approved, so the geometry is final: painted now (again, for new
            # words or seed), then shown at the texture stop before the material is applied.  A
            # body that arrived coloured (Hunyuan3D) is not repainted.  A paint after the first on
            # this body is a repaint, counted; a flat colour per part is not.
            if texture.get("per_part_colours"):
                return ({"action": "texture_surface", "per_part_colours": resolved_part_colours(plan, card)},
                        None, "texture")
            return ({"action": "texture_surface", **texture},
                    REPAINTS if card.get("textured_surface") else None, "texture")
        if material.get("mode") == "parts":
            return _parts_answer(card, plan, material)
        material.pop("mode", None)
        material.pop("uniform_why", None)          # the runner's (uniform_materials_problem), no card's
        if material.get("action") == "infer_material":
            if card.get("material_mode") == "vomp" or card.get("material_artifact"):
                raise PlanError("the inference read this description as a spatial (VoMP) material, which "
                                "is no plan material: give youngs_modulus, poisson_ratio and density in "
                                "plan.material, or mode 'parts' (materials.md)")
            words = str(material.get("material_description") or "").strip()
            if card.get("youngs_modulus") is None or str(card.get("material_description") or "").strip() != words:
                # Inferred, then shown at the materials stop before the solve uses the values.
                return (material, None, "materials")
        material.pop("action", None)
        material.pop("material_description", None)
        return ({"material_mode": "uniform", **material}, None, None)
    if kind == "shape_opt_settings":
        # Every field, from the class defaults: the card's "defaults" are the
        # session's current values, so a setting tried once would otherwise stay
        # on after the plan dropped it (a beta cap outlived its line in the plan).
        settings = plan_settings(plan)
        defaults = card.get("defaults") or {}
        if card.get("solve_error"):
            if not _settings_changed(settings, defaults):
                raise PlanError("the last solve failed with these settings; change "
                                "plan.settings (troubleshooting.md), or report the failure")
            return (settings, "solve", "solve")
        if card.get("solve_complete"):
            if _settings_changed(settings, defaults):
                return (settings, "solve", "solve")
            return (None, None, None)
        return (settings, "solve", "solve")
    raise PlanError(f"the plan does not cover the {kind!r} card")


def texture_matches(card: dict[str, Any], texture: dict[str, Any], plan: dict[str, Any] | None = None) -> bool:
    """Whether the card's painting was made from the plan's texture words (and seed, when given),
    or, for per_part_colours, is the flat colouring by part asked for (true: the parts' material
    colours as they read now, so parts valued after a first colouring are coloured again)."""
    fallback = card.get("texture_fallback") or {}
    if texture.get("per_part_colours") or fallback.get("kind") == "part_colours":
        asked = (resolved_part_colours(plan, card) if plan is not None and texture.get("per_part_colours") is True
                 else texture.get("per_part_colours"))
        return fallback.get("kind") == "part_colours" and fallback.get("asked") == asked
    if "texture_prompt" in texture and (str(card.get("texture_prompt") or "").strip()
                                        != str(texture.get("texture_prompt") or "").strip()):
        return False
    if "texture_seed" in texture and card.get("texture_seed") != texture.get("texture_seed"):
        return False
    return True


def texture_not_applied(session: Path, card: dict[str, Any], plan: dict[str, Any]) -> dict[str, Any] | None:
    """Why a planned painting did not happen, said at the geometry stop: the workflow offers the
    texture card only for a colourless surface with the painter installed, so a body that arrived
    coloured (a generation asked for colour) passes it by, and so does any body without the painter."""
    if not plan.get("texture") or card.get("kind") == "geometry_texture" \
            or "texture" in (lib.read_json(lib.operator_dir(session) / "run_sent.json", {}) or {}):
        return None
    source = body_source(session)
    try:
        from src.agents_wrapper.fem_workflow.graph import _surface_has_colour
        coloured = _surface_has_colour(str(source)) if source else None
    except Exception:
        coloured = None
    if coloured:
        return {"applied": False, "note": (
            "the body arrived coloured by its generator (plan.geometry.generation_settings.texture: true): "
            "plan.texture was not applied, and the workflow paints only a colourless surface")}
    return {"applied": False, "note": "the painter is not available here: plan.texture was not applied"}


def drawing_charge(session: Path, plan: dict[str, Any], answer: Any, stage: str | None) -> str | None:
    """A drawing made for Hunyuan3D is charged to Hunyuan3D's generation, not to the drawings; if
    TripoSG then generates from that same drawing, the drawing is charged there, once."""
    if not isinstance(answer, dict):
        return stage
    geometry = plan.get("geometry") or {}
    key = [str(geometry.get("description") or "").strip(), int(geometry.get("image_seed", 0) or 0)]
    path = lib.operator_dir(session) / "uncharged_drawings.json"
    uncharged = lib.read_json(path, []) or []
    if answer.get("action") == "draw_image" and stage is None and key not in uncharged:
        lib.write_json(path, uncharged + [key])
    elif ((answer.get("use_drawn_image") or DRAW_DIR in str(answer.get("asset_path") or ""))
          and stage is None and key in uncharged):
        lib.write_json(path, [k for k in uncharged if k != key])
        return "drawing"
    return stage


def drawing_accepted(session: Path, plan: dict[str, Any], answer: Any) -> bool:
    """Whether a body was generated from this drawing (its words and seed) before: the drawing
    stop showed it and the run on accepted it.  Recorded when a body is generated from a drawing;
    asked when the same drawing comes back from the cache, which then needs no second look (one
    run: going back to a drawing already used cost a drawing stop)."""
    if not isinstance(answer, dict):
        return False
    geometry = plan.get("geometry") or {}
    # the crop is part of what was accepted: another drawing_crop is looked at again
    key = [str(geometry.get("description") or "").strip(), int(geometry.get("image_seed", 0) or 0),
           geometry.get("drawing_crop")]
    path = lib.operator_dir(session) / "accepted_drawings.json"
    accepted = lib.read_json(path, []) or []
    if answer.get("use_drawn_image") or DRAW_DIR in str(answer.get("asset_path") or ""):
        if key not in accepted:
            lib.write_json(path, accepted + [key])
        return True
    return answer.get("action") == "draw_image" and key in accepted


def hunyuan_charge(session: Path, plan: dict[str, Any], answer: Any, stage: str | None) -> str | None:
    """A drawing made for Hunyuan3D was counted as a Hunyuan3D attempt when it was drawn; the first
    body generated from it is that same attempt, not another.  A drawing Hunyuan3D takes over
    from the drawing route (the words and seed kept) is counted when Hunyuan3D generates from it."""
    if stage != "hunyuan" or not isinstance(answer, dict):
        return stage
    geometry = plan.get("geometry") or {}
    key = [str(geometry.get("description") or "").strip(), int(geometry.get("image_seed", 0) or 0)]
    path = lib.operator_dir(session) / "hunyuan_drawings.json"
    drawn = lib.read_json(path, []) or []
    if answer.get("action") == "draw_image":
        if key not in drawn:
            lib.write_json(path, drawn + [key])
        return stage
    if (answer.get("use_drawn_image") or DRAW_DIR in str(answer.get("asset_path") or "")) and key in drawn:
        lib.write_json(path, [k for k in drawn if k != key])
        return None
    return stage


def _relative(path: Path) -> str:
    try:
        return str(Path(path).resolve().relative_to(lib.REPO_ROOT))
    except ValueError:
        return str(path)


WEB_RECORD = "web_image.json"     # the session's searches, and whether the photograph route is done


def web_folder(session: Path, query: str) -> Path:
    """Where the photographs found for one query live: inputs/web/<digest of the words>/<id>/."""
    import hashlib
    return session / "inputs" / "web" / hashlib.sha256(query.strip().lower().encode()).hexdigest()[:10]


def web_image_done(session: Path) -> bool:
    """True once the photograph route needs nothing more before a built body: the search found no
    usable photograph (or reached no source), or every photograph shown was turned down."""
    record = lib.read_json(lib.operator_dir(session) / WEB_RECORD, {}) or {}
    return bool(record.get("no_usable_photo") or record.get("rejected"))


def web_body_made(session: Path) -> bool:
    """Whether a body was generated from a picked web photograph (its one body, WEB_BODIES)."""
    sent = lib.read_json(lib.operator_dir(session) / ROUTE_SENT, []) or []
    return any(str(k).startswith("web|web_image:") for k in sent)


def web_image_credit(session: Path) -> dict[str, Any] | None:
    """The attribution of the photograph the session's body was generated from, or None when the
    newest generation came from anything else (the driver log's newest generating answer)."""
    try:
        lines = (lib.operator_dir(session) / "driver_log.jsonl").read_text(encoding="utf-8").splitlines()
    except OSError:
        return None
    for line in reversed(lines):
        try:
            entry = json.loads(line)
        except ValueError:
            continue
        answer = entry.get("answer")
        if entry.get("kind") != "geometry_input" or not isinstance(answer, dict) or not entry.get("ok") \
                or answer.get("action") == "draw_image" or answer.get("revise_prompt"):
            continue
        if WEB_DIR in str(answer.get("asset_path") or "").replace("\\", "/"):
            return lib.read_json(Path(answer["asset_path"]).parent / "attribution.json")
        return None
    return None


def web_montage(candidates: list[dict[str, Any]], target: Path) -> Path | None:
    """The shown photographs' thumbnails side by side, each labelled with its id: one small picture
    for the stop (three 1024-pixel reads were the drawing stop's cost before drawing_pair)."""
    from PIL import Image, ImageDraw
    thumbs = []
    for c in candidates:
        try:
            thumbs.append((c["id"], Image.open(lib.REPO_ROOT / c["thumb"]).convert("RGB")))
        except (OSError, KeyError, ValueError):
            continue
    if not thumbs:
        return None
    height = max(t.height for _, t in thumbs) + 22
    sheet = Image.new("RGB", (sum(t.width for _, t in thumbs) + 8 * (len(thumbs) - 1), height), "white")
    draw, x = ImageDraw.Draw(sheet), 0
    for name, thumb in thumbs:
        sheet.paste(thumb, (x, 22))
        draw.text((x + 4, 4), name, fill=(0, 0, 0))
        x += thumb.width + 8
    target.parent.mkdir(parents=True, exist_ok=True)
    sheet.save(target)
    return target


class WebProcessingFailed(RuntimeError):
    """The photographs could not be processed for a reason a run again would meet again (no
    compute interpreter, no CUDA, RMBG-1.4 missing offline, a timeout): unlike no idle GPU, the
    search is spent and no usable photograph is recorded, so the body may be built."""


def find_web_images(args, session: Path, output_root: Path, compute_env: str, query: str) -> dict[str, Any]:
    """Search the licensed sources for ``query`` (web_images.py: the only code that reaches the
    web), download the candidates with their attribution, then in the compute env on a GPU find the
    named object (Grounding DINO, when cached), crop it, cut it out as a drawing is and pre-screen
    it; at most web_images.SHOW survivors are shown.  Written to the query's candidates.json."""
    import subprocess
    import web_images
    import inspect_session
    ledger = output_root / "web_requests.json"
    folder = web_folder(session, query)
    fetched = lib.read_json(folder / "fetched.json")
    if fetched is None:
        # searched and downloaded once: a run again after no idle GPU reuses these files
        result = web_images.search(query, ledger)
        shown, failed = [], []
        for candidate in result["candidates"]:
            try:
                record = web_images.download(candidate, folder / candidate["id"], ledger)
                shown.append({**record, "original": str(record["original"])})
            except Exception as exc:
                failed.append({"id": candidate["id"], "error": f"{type(exc).__name__}: {str(exc)[:120]}"})
        folder.mkdir(parents=True, exist_ok=True)
        lib.write_json(folder / "fetched.json", {"result": result, "shown": shown, "failed": failed})
    else:
        result, shown, failed = fetched["result"], fetched["shown"], fetched["failed"]
    note = None
    if shown:
        select_gpu(args, output_root, True, [], compute_env)        # NoIdleGPU: nothing processed
        python = inspect_session.compute_interpreter(compute_env)
        if python is None:
            raise WebProcessingFailed(f"no interpreter of the compute env {compute_env}")
        pairs = [p for c in shown for p in (c["original"], str(Path(c["original"]).parent))]
        try:
            done = subprocess.run([python, str(Path(__file__).resolve().parent / "web_images.py"), "process",
                                   "--phrase", query, *pairs], capture_output=True, text=True, timeout=900,
                                  cwd=lib.REPO_ROOT, env={**os.environ, "HF_HUB_OFFLINE": "1"})
        except (OSError, subprocess.TimeoutExpired) as exc:
            raise WebProcessingFailed(f"{type(exc).__name__}: {str(exc)[:160]}")
        if done.returncode:
            tail = [line for line in (done.stderr or done.stdout or "").splitlines() if line.strip()]
            raise WebProcessingFailed((tail[-1] if tail else f"exit code {done.returncode}")[-200:])
        # the last JSON line: a library may print before it
        lines = [line for line in done.stdout.splitlines() if line.strip().startswith("{")]
        try:
            note = json.loads(lines[-1]).get("note") if lines else None
        except ValueError:
            note = None
    candidates, dropped = [], []
    for c in shown:
        where = Path(c["original"]).parent
        screened = lib.read_json(where / "screen.json") or {"reasons": ["not processed"]}
        if screened.get("reasons"):
            dropped.append({"id": c["id"], "why": "; ".join(screened["reasons"])})
            continue
        candidates.append({"id": c["id"], "title": c["title"], "author": c["author"], "licence": c["licence"],
                           "source": c["source"], "source_url": c["source_url"],
                           "licence_checked_at_source": c.get("licence_checked_at_source", True),
                           "image": _relative(where / "cut.png"), "thumb": _relative(where / "thumb.png")})
    candidates = candidates[:web_images.SHOW]
    reached = any("error" not in s for s in result["sources"])
    found = {"query": query, "found": len(result["candidates"]), "candidates": candidates,
             **({"dropped": dropped} if dropped else {}), **({"failed": failed} if failed else {}),
             **({"note": note} if note else {}), **({} if reached else {"unreachable": True}),
             "sources": result["sources"]}
    montage = web_montage(candidates, folder / "shown.png") if candidates else None
    if montage:
        found["montage"] = _relative(montage)
    folder.mkdir(parents=True, exist_ok=True)
    lib.write_json(folder / "candidates.json", found)
    return found


def web_image_route(args, session: Path, output_root: Path, compute_env: str,
                    plan: dict[str, Any]) -> dict[str, Any]:
    """The web-photograph step, before the geometry card is answered: ``{"stop": ..., "extra": ...}``
    to stop, or ``{"plan": ...}`` with the picked photograph's cut-out as the geometry's image.  One
    search a session; a second, with other words, only when the first returned nothing.  No usable
    photograph (none found or survived the pre-screen, or no source reached) is recorded, and the
    body may then be built (web_photo_problem)."""
    geometry = dict(plan["geometry"])
    web = geometry.pop("web_image")
    query, pick = str(web["query"]).strip(), web.get("pick")
    folder = web_folder(session, query)
    found = lib.read_json(folder / "candidates.json")
    path = lib.operator_dir(session) / WEB_RECORD
    record = lib.read_json(path, {}) or {}
    searches = list(record.get("searches") or [])
    if found is None:
        order = route_order_problem(session, "geometry_input", {"asset_path": WEB_DIR, "asset_kind": "image"},
                                    plan=plan)
        if order:
            return {"stop": "error", "extra": {"error": order}}
        if any(s.get("found") for s in searches) or len(searches) >= RUN_LIMITS["web_image"]:
            return {"stop": "error", "extra": {"error": (
                "one web search a session; a second, with other words, only when the first returned nothing: "
                f"pick from {searches[-1]['query']!r} (its words in plan.geometry.web_image.query), or build the "
                "body (objectives/routes.md §3.4)")}}
        off = web_query_problem(session, plan, query)
        if off:
            return {"stop": "error", "extra": {"error": off}}
        charged = charge_attempt(session, "web_image", {"query": query.lower()})
        if charged["over"]:
            return {"stop": "limit", "extra": {"error": limit_message("web_image", charged["counts"],
                                                                      declared_routes(session))}}
        try:
            found = find_web_images(args, session, output_root, compute_env, query)
        except NoIdleGPU as exc:
            # nothing was shown: the search is not spent, and a run again reuses the downloads
            refund_attempt(session, "web_image", {"query": query.lower()})
            return {"stop": "error", "extra": {"error": f"the photographs could not be processed ({exc}); "
                                                        "run again"}}
        except Exception as exc:
            # a failure a run again would meet again (no CUDA, no interpreter, RMBG-1.4 missing
            # offline, a timeout): the search is spent and the body may be built (review of 2026-10-11)
            why = f"processing failed: {str(exc).strip()[:160] or type(exc).__name__}"
            record.update(searches=searches + [{"query": query, "shown": 0, "failed": why}], no_usable_photo=why)
            lib.write_json(path, record)
            return {"stop": "web_image", "extra": {"web_image": {
                "query": query, "no_usable_photo": why, "next": "no usable photograph: build the body now (`blank`)"}}}
        searches.append({"query": query, "found": found["found"], "shown": len(found["candidates"]),
                         **({"unreachable": True} if found.get("unreachable") else {})})
        record["searches"] = searches
        if not found["candidates"]:
            record["no_usable_photo"] = ("no source reached" if found.get("unreachable") else
                                         "none found" if not found["found"] else "none passed the pre-screen")
        lib.write_json(path, record)
        pick = None                     # a pick is made from what this search showed
    shown = {k: found[k] for k in ("query", "candidates", "dropped", "note", "unreachable") if k in found}
    if pick is None:
        if not found["candidates"]:
            again = (not found["found"] and not found.get("unreachable")
                     and len(searches) < RUN_LIMITS["web_image"])
            return {"stop": "web_image", "extra": {"web_image": {**shown, "no_usable_photo": True, "next": (
                "no usable photograph: build the body now (`blank`)"
                + (", or one search with other words (this one returned nothing)" if again else ""))}}}
        return {"stop": "web_image", "extra": {"web_image": shown, "look_at": [found["montage"]]
                                               if found.get("montage") else [c["thumb"] for c in found["candidates"]]}}
    if pick == "none":
        why = str(web.get("why") or "").strip()
        unsaid = turned_down_problem([c["id"] for c in found["candidates"]], why)
        if unsaid:
            return {"stop": "error", "extra": {"error": unsaid}}
        lib.write_json(path, {**record, "rejected": sorted(set(record.get("rejected", [])) | {query}),
                              "turned_down": {**(record.get("turned_down") or {}), query: why}})
        return {"stop": "web_image", "extra": {"web_image": {
            "query": query, "turned_down": why, "next": "every photograph turned down: build the body (`blank`)"}}}
    chosen = next((c for c in found["candidates"] if c["id"] == pick), None)
    if chosen is None:
        return {"stop": "error", "extra": {"error": f"plan.geometry.web_image.pick {pick!r} is none of the "
                                                    f"candidates {[c['id'] for c in found['candidates']]} or \"none\""}}
    if (record.get("picked") or {}).get("id") != pick:
        lib.write_json(path, {**record, "picked": {"query": query, "id": pick}})
    geometry.update({"asset_path": str(lib.REPO_ROOT / chosen["image"]), "asset_kind": "image"})
    return {"plan": {**plan, "geometry": geometry}}


# Words that say nothing of which object a photograph shows: a query of these alone (or of words
# the case never used) found nothing and so unlocked the built body (review of 2026-10-11).
QUERY_FILLER = frozenset(
    "the and with for from its one two three four five six into onto over under each per about that this "
    "which who what how any all some photo photograph picture image object real view whole single "
    "simulate simulation analyse analyze run fea test stress load loads loaded case".split())
WEB_CHECKS = (("whole", "one whole object"), ("itself", "the object itself"), ("cut", "a complete cut-out"),
              ("person", "no person"), ("people", "no person"), ("print", "the object itself"),
              ("scene", "the object itself"), ("several", "one whole object"), ("partial", "one whole object"))


def _content_words(text: str) -> set[str]:
    """A text's content words, a plural's stem included."""
    words = {w for w in re.findall(r"[a-z]+", str(text or "").lower()) if len(w) > 2 and w not in QUERY_FILLER}
    return (words | {w[:-1] for w in words if len(w) > 3 and w.endswith("s")}
            | {w[:-2] for w in words if len(w) > 4 and w.endswith("es")})


def web_query_problem(session: Path, plan: dict[str, Any], query: str) -> str | None:
    """A search whose words share no content word with the plan's description or the user's
    instruction (the object's own noun) is refused before it is spent."""
    case = _content_words((plan.get("geometry") or {}).get("description")) | _content_words(
        stored_instruction(lib.operator_dir(session)))
    if _content_words(query) & case:
        return None
    return (f"plan.geometry.web_image.query {query!r} names no word of plan.geometry.description or the "
            "instruction: the query is the object's noun phrase, its head noun among those words "
            "(objectives/routes.md §3.4)")


def turned_down_problem(ids: list[str], why: str) -> str | None:
    """``"pick": "none"`` with a ``why`` that names the check the photographs failed: one reason shared
    by all of them ("none shows the whole object alone"), or each shown photograph's id and its check."""
    if not ids:
        return None
    if not any(i in why for i in ids) and any(word in why.lower() for word, _ in WEB_CHECKS):
        return None                    # one reason for every photograph shown
    at = sorted((why.find(i), i) for i in ids if i in why)
    named = {i for _, i in at}
    failed = [i for k, (start, i) in enumerate(at)
              if not any(word in why[start:at[k + 1][0] if k + 1 < len(at) else None].lower()
                         for word, _ in WEB_CHECKS)]
    missing = [i for i in ids if i not in named] + failed
    if not missing:
        return None
    return ('"pick": "none" comes with "why": the check the photographs failed (one whole object, the object '
            "itself, a complete cut-out, no person), one reason for all (\"none shows the whole object alone\") or "
            f"per id; not said for {missing} (objectives/routes.md §3.4)")


def web_search_line(session: Path) -> str | None:
    """The run report's line for the photograph route: each query and its outcome."""
    record = lib.read_json(lib.operator_dir(session) / WEB_RECORD, {}) or {}
    if not record.get("searches"):
        return None
    picked, down = record.get("picked") or {}, record.get("turned_down") or {}
    parts = []
    for s in record["searches"]:
        q = s.get("query")
        outcome = (f"picked {picked['id']}" if picked.get("query") == q else
                   f"turned down: {down[q]}" if q in down else
                   s.get("failed") or ("no source reached" if s.get("unreachable") else
                                       "none found" if not s.get("found") else
                                       f"{s.get('shown', 0)} shown" + ("" if s.get("shown") else
                                                                        ", none passed the pre-screen")))
        parts.append(f"{q!r}: {outcome}")
    return "; ".join(parts)


def drawn_from_plan(card: dict[str, Any], plan: dict[str, Any]) -> bool:
    """Whether the card's drawing was drawn from the plan's words and seed."""
    geometry = plan.get("geometry") or {}
    return bool(geometry.get("draw") and card.get("drawn_image")
                and str(card.get("drawn_image_prompt") or "").strip() == str(geometry.get("description") or "").strip()
                and int(card.get("image_seed") or 0) == int(geometry.get("image_seed", 0)))


def fresh_images(rendered: dict[str, Any]) -> tuple[list[str], str | None]:
    """The pictures this render wrote, and its error if it failed (never an older file)."""
    if not rendered.get("ok", False) and not rendered.get("images"):
        return [], str(rendered.get("error") or "the render failed")[:300]
    return list(rendered.get("images") or []), None


def _inspect(session: Path, output_root: Path, *command: str) -> dict[str, Any]:
    """Run the inspector as a subprocess (render re-executes under the compute env)."""
    import subprocess
    script = Path(__file__).resolve().parent / "inspect_session.py"
    result = subprocess.run(
        [sys.executable, str(script), "--output-root", str(output_root), *command],
        capture_output=True, text=True, timeout=600, cwd=lib.REPO_ROOT)
    text = result.stdout
    start = text.find("{")
    try:
        return json.loads(text[start:]) if start >= 0 else {"ok": False}
    except ValueError:
        return {"ok": False, "error": (result.stderr or text)[-500:]}


def _parts_answer(card: dict[str, Any], plan: dict[str, Any],
                  material: dict[str, Any]) -> tuple[dict[str, Any] | None, str | None, str | None]:
    """The per-part material, one card answer at a time.

    A bare surface is painted first (the part stage reads colour), then the
    parts are valued, which is the ``materials`` stop: the agent looks at the
    montage.  Corrections listed in the plan are applied next, with the same
    stop so the final table is seen; then the field is approved.  Painting
    and the corrections are not attempts; valuing the parts is.
    """
    current = {int(p["id"]): p for p in card.get("material_parts") or []}
    # Filled from the brief (with_brief_parts): the valuation runs on, and the stop comes after the
    # brief's values are applied, so the final table is seen at the one materials stop.
    filled = bool(material.get("_from_brief"))
    if current and str(card.get("material_description") or "").strip() != str(material["description"]).strip():
        # The parts were valued from other words: value them again, and stop on the new values.
        return ({"action": "infer_parts", "material_description": material["description"]},
                "materials", None if filled else "materials")
    if not current:
        if card.get("surface_has_colour") is False and not card.get("textured_surface"):
            if not material.get("texture_prompt"):
                # Each part one flat colour, in seconds: the painter places no colour by part (a
                # minute of GPU, 2026-10-10), and the values come from the brief.
                return ({"action": "texture_surface", "per_part_colours": True}, None, None)
            return ({"action": "texture_surface", "texture_prompt": material["texture_prompt"]}, None, None)
        return ({"action": "infer_parts", "material_description": material["description"]},
                "materials", None if filled else "materials")
    edits = [dict(p) for p in material.get("parts") or []]
    pending = [p for p in edits if int(p["id"]) in current
               and any(current[int(p["id"])].get(k) != v for k, v in p.items() if k != "id")]
    if filled and card.get("material_inferred"):
        # just valued: the brief's values applied (the card's own when they agree), then the stop
        return ({"action": "apply_parts", "parts": pending or [{"id": i} for i in sorted(current)]},
                None, "materials")
    if pending:
        return ({"action": "apply_parts", "parts": pending}, None, "materials")
    return ({"material_mode": "parts"}, None, None)


DRAWING_SPECK = 0.05       # a foreground piece under this share of the largest is a speck


def drawing_objects(path: Any, side: int = 256) -> dict[str, Any] | None:
    """How many separate objects a drawing shows: the connected pieces of its cut-out's alpha mask
    (the drawing comes back cut out from its background), ignoring specks under 5 % of the largest
    piece.  More than one is often several objects or viewpoints, which the generator would build as
    one body, but one object can read so too (a U or H silhouette, a leg cut free from the
    background): the count is shown at the stop and decides nothing.  None for an image with no
    alpha channel."""
    import numpy as np
    from PIL import Image
    if not path:
        return None
    try:
        image = Image.open(path)
    except (OSError, ValueError):
        return None
    if "A" not in image.getbands():
        return None
    alpha = image.getchannel("A")
    full = np.asarray(alpha) > 127
    scale = side / max(alpha.size)
    if scale < 1:
        alpha = alpha.resize((max(1, round(alpha.size[0] * scale)), max(1, round(alpha.size[1] * scale))),
                             Image.NEAREST)
    out = mask_pieces(np.asarray(alpha) > 127)
    if out["objects"] == 1:
        pair = side_by_side(full)
        if pair:
            out = {**out, "objects": 2, "side_by_side": pair}
    return out


TOUCHING_VALLEY = 0.3      # columns at the split hold under this share of the fuller side's peak
TOUCHING_DIP = 0.3         # and the top edge there drops this share of the height below the tops


def side_by_side(mask) -> dict[str, Any] | None:
    """Two figures side by side whose parts touch (one alpha piece): the deepest valley in the
    count of foreground pixels per column, with a quarter or more of the foreground on each side,
    where the top edge dips well below both tops, and the two sides of similar area.  Measured on
    the drawings the sessions hold: a pair of touching standing views read 0.25 and 0.37; the
    single objects nearest to it read 0.36 / 0.34 and 0.13 / 0.19 (valley / dip)."""
    import numpy as np
    rows = np.nonzero(mask.any(axis=1))[0]
    if not len(rows):
        return None
    top, height = rows.min(), rows.max() - rows.min() + 1
    cols = mask.sum(axis=0).astype(float)
    smooth = np.convolve(cols, np.ones(9) / 9, mode="same")
    xs = np.nonzero(cols)[0]
    total = cols.sum()
    edge = np.where(mask.any(axis=0), mask.argmax(axis=0), mask.shape[0])
    best = None
    for x in range(int(xs.min()) + 1, int(xs.max())):
        share = cols[:x].sum() / total
        if not 0.25 <= share <= 0.75:
            continue
        peak = min(smooth[:x].max(), smooth[x:].max())
        valley = smooth[x] / peak if peak else 1.0
        if best is None or valley < best[1]:
            best = (x, valley, share)
    if best is None:
        return None
    x, valley, share = best
    dip = (edge[max(x - 4, 0):x + 5].min() - top) / height
    balance = min(share, 1 - share) / max(share, 1 - share)
    if valley <= TOUCHING_VALLEY and dip >= TOUCHING_DIP and balance >= 0.5:
        return {"split_x_px": int(x), "valley": round(float(valley), 3), "top_dip": round(float(dip), 3)}
    return None


def largest_object_path(drawing: Any) -> Path:
    """Where the drawing stop puts the drawing's largest object alone (``drawing_crop``)."""
    path = Path(str(drawing))
    return path.with_name(path.stem + "_largest.png")


def drawing_pair(raw: Any, cut: Any, out_dir: Path,
                 cut_label: str = "cut-out (what the body is generated from)") -> Path | None:
    """The drawing as SDXL made it and its cut-out side by side, labelled, in one image of one
    drawing's pixel count (two 1024 x 1024 pictures were two image reads at every drawing stop;
    a picture's tokens go as its pixels).  The cut-out sits on a light checker, so what the
    background removal dropped shows.  None when either is missing (the stop lists what exists)."""
    from PIL import Image, ImageDraw
    try:
        left, right = Image.open(raw).convert("RGBA"), Image.open(cut).convert("RGBA")
    except (OSError, ValueError, TypeError, AttributeError):
        return None
    width, height = left.size
    side = max(1, int(round((width * height / 2) ** 0.5)))     # two panels, one picture's pixels
    band = max(14, side // 24)
    panels = []
    for image in (left, right):
        image = image.copy()
        image.thumbnail((side, side))
        tile = max(8, side // 32)
        board = Image.new("RGBA", (side, side), (255, 255, 255, 255))
        paint = ImageDraw.Draw(board)
        for y in range(0, side, tile):
            for x in range(0, side, tile):
                if (x // tile + y // tile) % 2:
                    paint.rectangle([x, y, x + tile - 1, y + tile - 1], fill=(222, 222, 222, 255))
        board.alpha_composite(image, ((side - image.size[0]) // 2, (side - image.size[1]) // 2))
        panels.append(board)
    sheet = Image.new("RGB", (2 * side, side + band), (255, 255, 255))
    write = ImageDraw.Draw(sheet)
    for k, (panel, label) in enumerate(zip(panels, ("drawing (as SDXL drew it)", cut_label))):
        sheet.paste(panel.convert("RGB"), (k * side, band))
        write.text((k * side + 6, 2), label, fill=(0, 0, 0))
    write.line([(side, band), (side, side + band)], fill=(120, 120, 120), width=2)
    out_dir.mkdir(parents=True, exist_ok=True)
    target = out_dir / f"drawing_{Path(str(cut)).stem}.png"
    sheet.save(target)
    return target


def downscaled(path: Any, out: Path, size: tuple[int, int] = (1000, 700)) -> Path | None:
    """A copy of a picture shrunk to fit ``size`` (aspect kept), for a look that needs no more
    pixels; None when the picture cannot be read."""
    from PIL import Image
    try:
        image = Image.open(path)
        image.load()
    except (OSError, ValueError, TypeError, AttributeError):
        return None
    if image.size[0] <= size[0] and image.size[1] <= size[1]:
        return Path(str(path))
    image.thumbnail(size, Image.LANCZOS)
    out.parent.mkdir(parents=True, exist_ok=True)
    image.save(out)
    return out


def cut_largest_object(drawing: Any, counted: dict[str, Any]) -> Path | None:
    """The drawing's largest object alone, on a transparent square, for a drawing that reads as
    several objects (separate pieces of its cut-out, or two touching figures side by side):
    the other objects' pixels are made transparent.  SDXL draws objects that come in pairs (a
    pair of gloves) as two, which the generator would build as one body; a redraw costs a
    drawing, the cut-out none.  None when the drawing reads as one object or has no alpha."""
    import numpy as np
    from PIL import Image
    if (counted.get("objects") or 0) < 2:
        return None
    try:
        image = Image.open(drawing).convert("RGBA")
    except (OSError, ValueError):
        return None
    rgba = np.asarray(image).copy()
    solid = rgba[..., 3] > 127
    if counted.get("side_by_side"):
        # one piece, two figures: keep the side of the valley with more of the body
        split = int(counted["side_by_side"]["split_x_px"])
        keep = np.zeros_like(solid)
        left, right = solid[:, :split].sum(), solid[:, split:].sum()
        if left >= right:
            keep[:, :split] = solid[:, :split]
        else:
            keep[:, split:] = solid[:, split:]
    else:
        # separate pieces: label on the full mask, keep the largest
        labels = np.zeros(solid.shape, dtype=np.int32)
        sizes = []
        for y0, x0 in zip(*np.nonzero(solid)):
            if labels[y0, x0]:
                continue
            label = len(sizes) + 1
            labels[y0, x0] = label
            stack, count = [(y0, x0)], 0
            while stack:
                y, x = stack.pop()
                count += 1
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < solid.shape[0] and 0 <= nx < solid.shape[1] \
                            and solid[ny, nx] and not labels[ny, nx]:
                        labels[ny, nx] = label
                        stack.append((ny, nx))
            sizes.append(count)
        keep = labels == (int(np.argmax(sizes)) + 1)
    if not keep.any():
        return None
    rgba[..., 3] = np.where(keep, rgba[..., 3], 0)
    ys, xs = np.nonzero(keep)
    y0, y1, x0, x1 = ys.min(), ys.max() + 1, xs.min(), xs.max() + 1
    side = int(max(y1 - y0, x1 - x0) * 1.15)            # the object, centred, with a margin
    square = np.zeros((side, side, 4), dtype=np.uint8)
    oy, ox = (side - (y1 - y0)) // 2, (side - (x1 - x0)) // 2
    square[oy:oy + (y1 - y0), ox:ox + (x1 - x0)] = rgba[y0:y1, x0:x1]
    out = largest_object_path(drawing)
    Image.fromarray(square).save(out)
    return out


def mask_pieces(mask) -> dict[str, Any]:
    """The 4-connected pieces of a boolean mask: how many are larger than a speck, and their sizes."""
    import numpy as np
    labels = np.zeros(mask.shape, dtype=np.int32)
    sizes, boxes = [], []
    height, width = mask.shape
    for y0, x0 in zip(*np.nonzero(mask)):
        if labels[y0, x0]:
            continue
        label = len(sizes) + 1
        labels[y0, x0] = label
        stack, count = [(y0, x0)], 0
        lo, hi = [y0, x0], [y0, x0]
        while stack:
            y, x = stack.pop()
            count += 1
            lo, hi = [min(lo[0], y), min(lo[1], x)], [max(hi[0], y), max(hi[1], x)]
            for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                if 0 <= ny < height and 0 <= nx < width and mask[ny, nx] and not labels[ny, nx]:
                    labels[ny, nx] = label
                    stack.append((ny, nx))
        sizes.append(count)
        boxes.append([int(lo[1]), int(lo[0]), int(hi[1]), int(hi[0])])
    largest = max(sizes) if sizes else 0
    keep = [k for k, n in enumerate(sizes) if n >= DRAWING_SPECK * largest] if largest else []
    return {"objects": len(keep), "pieces_px": sorted((sizes[k] for k in keep), reverse=True),
            "boxes_xyxy": [boxes[k] for k in keep], "specks": len(sizes) - len(keep)}


def generated_extents(session: Path) -> list[float] | None:
    """The generated (or uploaded) surface's bounding-box extents, before scaling."""
    mesh = _generated_mesh(session)
    return None if mesh is None else [float(e) for e in mesh.extents]


def thin_gaps(mesh, leaf: float, samples: int = 30000) -> dict:
    """Where the body's surface faces another part of it across air thinner than a leaf.

    Surface samples, each with its outward normal; a pair a leaf or less apart whose normals
    face each other (cosine under -0.7) with the other point ahead of this one along its normal
    is a gap the octree fills: the two sides are bonded at the resolution the body is solved at.
    Returns the share of the surface on such a gap, the gap widths and where they are.
    """
    return _facing_pairs(mesh, leaf, leaf, samples, across="air")


_THIN_WALLS: dict[tuple, dict] = {}   # one measurement per body and leaf in a runner process


# G4's member measure (``g4_member_ratio``): the thinnest wall measured straight through, within a
# reach of G4_REACH x the brief's real thinnest member, on G4_WALL_SHARE of the surface or more.
# The voxel p10 over the whole volume read an exact 2 mm plate on a 1 m body at 3.12 x and a 20 mm
# bar on a bulky block at 14.8 x; a reach of 2 leaves saw no over-thick member at all, and a 1 %
# share read a 7 mm plate past its real 2 mm tab (0.2 % of the surface) at 3.5 x (reviews of
# 2026-10-11).  No wall within the reach: the voxel ratio stands.
G4_REACH = 3.5
G4_WALL_SHARE = 0.001


def g4_member_ratio(mesh, leaf: float, real_thin: float, voxel_ratio: float | None = None,
                    samples: int = 4000) -> tuple[float | None, str | None]:
    """(the body's thinnest load-path wall over the real thinnest member, where it was read):
    "wall" when walls are found within G4_REACH x the real member on G4_WALL_SHARE of the surface,
    else "voxel" (``voxel_ratio``, None without one)."""
    import numpy as np
    reach = min(max(G4_REACH * real_thin, RESOLVED_LEAVES * leaf), 0.25 * float(max(mesh.extents)))   # bounded cost
    # A reading over the rule is taken again with five times the samples, by the same share rule,
    # and the denser reading stands: a member near G4_WALL_SHARE that the first sampling missed is
    # found, and one under it is not.  The second pass took the 4th-smallest gap of its samples and
    # the smaller of the two readings, which passed a member far under the share (review of 2026-10-11).
    reading = None
    for count in (samples, 5 * samples):
        read = _facing_pairs(mesh, leaf, reach, count, across="material", arrays=True)
        gaps = np.sort(np.asarray(read["gap"])[np.asarray(read["found"])])
        k = max(int(np.ceil(G4_WALL_SHARE * len(read["gap"]))), 1)
        reading = round(float(gaps[k - 1]) / real_thin, 2) if len(gaps) >= k else None
        if reading is not None and reading <= MEMBER_OVER_REAL:
            break
    if reading is not None:
        return reading, "wall"
    return (voxel_ratio, "voxel") if voxel_ratio is not None else (None, None)


def thin_walls(mesh, leaf: float, samples: int = 12000) -> dict:
    """Where the body is a wall thinner than RESOLVED_LEAVES: the surface's back face lies behind it,
    across material, closer than that.

    The voxel thickness (``member_thickness``) cannot see a part under about two of its voxels
    (1/80 of the body), which is under two leaves at depth 8: the thinnest parts escape it.  The
    surface pairs have no such floor.  Returns the share of the surface on such a wall."""
    import hashlib
    key = (hashlib.sha256(mesh.vertices.tobytes() + mesh.faces.tobytes()).hexdigest(), round(leaf, 9), samples)
    if key not in _THIN_WALLS:
        _THIN_WALLS[key] = _facing_pairs(mesh, leaf, RESOLVED_LEAVES * leaf, samples, across="material")
    return _THIN_WALLS[key]


def _facing_pairs(mesh, leaf: float, reach: float, samples: int, across: str, arrays: bool = False) -> dict:
    """Surface samples whose outward normals oppose another sample's within ``reach``: across
    air (the other point ahead along the normal) or across material (behind it).  ``arrays``
    returns the per-sample readings instead of the summary (``thin_volume_outside_holds``)."""
    import numpy as np
    import trimesh

    points, faces = trimesh.sample.sample_surface(mesh, samples, seed=0)
    points = np.asarray(points, dtype=float)
    normals = np.asarray(mesh.face_normals[faces], dtype=float)
    sign = 1.0 if across == "air" else -1.0
    cells = np.floor((points - points.min(axis=0)) / reach).astype(np.int64)
    span = cells.max(axis=0) + 3
    key = lambda c: ((c[:, 0] + 1) * span[1] + (c[:, 1] + 1)) * span[2] + (c[:, 2] + 1)
    own = key(cells)
    order = np.argsort(own)
    sorted_keys = own[order]
    gap = np.full(len(points), np.inf)
    best = np.full(len(points), np.inf)      # the nearest offset from the normal line found behind each point
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            for dz in (-1, 0, 1):
                target = key(cells + np.array([dx, dy, dz]))
                start = np.searchsorted(sorted_keys, target, side="left")
                stop = np.searchsorted(sorted_keys, target, side="right")
                counts = stop - start
                if not counts.any():
                    continue
                i = np.repeat(np.arange(len(points)), counts)
                j = order[np.concatenate([np.arange(a, b) for a, b in zip(start, stop) if b > a])]
                d = points[j] - points[i]
                ahead = sign * np.einsum("ij,ij->i", d, normals[i])
                cosine = np.einsum("ij,ij->i", normals[j], normals[i])
                close = np.einsum("ij,ij->i", d, d) <= reach * reach
                if across == "air":
                    ok = (cosine < -0.7) & close & (ahead > 0.1 * leaf)
                    if ok.any():
                        np.minimum.at(gap, i[ok], ahead[ok])
                    continue
                # A wall's thickness at a point is the distance to the opposite face straight behind
                # it: the facing sample (normals within 14 degrees of opposite) nearest the line
                # along its normal, not the shortest of many.  Across a round section the shortest
                # pairs are chords off the diameter and read it thin, and inside a hollow section, or between
                # faceted faces, pairs off to the side read a tilted face's plane short.
                ok = (cosine < -0.97) & close & (ahead > 0.1 * leaf)
                if not ok.any():
                    continue
                lateral = np.sqrt(np.maximum(np.einsum("ij,ij->i", d, d) - ahead ** 2, 0.0))
                ii, cc, aa = i[ok], lateral[ok], ahead[ok]
                first = np.lexsort((cc, ii))
                ii, cc, aa = ii[first], cc[first], aa[first]
                keep = np.r_[True, ii[1:] != ii[:-1]]
                ii, cc, aa = ii[keep], cc[keep], aa[keep]
                better = cc < best[ii]
                best[ii[better]], gap[ii[better]] = cc[better], aa[better]
    found = np.isfinite(gap)
    if arrays:
        return {"faces": np.asarray(faces), "gap": gap, "best": best, "found": found,
                "area_per_sample": float(mesh.area) / len(points),
                "spacing": float(np.sqrt(float(mesh.area) / len(points)))}
    out = {"share_of_surface": round(float(found.mean()), 4), "leaf_m": round(leaf, 5)}
    if found.any():
        out["width_m"] = [round(float(v), 5) for v in np.percentile(gap[found], [10, 50])]
        # The thinnest wall that covers a hundredth of the surface: which walls are counted as thin
        # changes with the depth, a percentile over them would too; this reading does not.
        ordered = np.sort(gap[found])
        k = int(np.ceil(THIN_WALL_SHARE * len(gap))) - 1
        out["thinnest_over_1pct_m"] = round(float(ordered[k]), 5) if 0 <= k < len(ordered) else None
        out["where"] = [[round(float(v), 4) for v in points[found].min(axis=0)],
                        [round(float(v), 4) for v in points[found].max(axis=0)]]
        if across == "material" and not (mesh.is_watertight and abs(float(mesh.volume)) > 0):
            # said, not left out: a missing share would read as a measure from before it existed
            out["volume_share"] = None
        elif across == "material":
            # The thin walls' share of the volume: each sample stands for area/samples of surface
            # and half the wall behind it (both faces of a wall are sampled).  A thin part has much
            # surface for its volume, so the surface share overstates a fin: a 4 mm lip 60 mm deep
            # along a 40 mm bar reads 55 % of the surface and 16 % of the volume.
            # Only walls whose opposite face lies straight behind (offset under the sample spacing):
            # the nearest facing sample of a point beside a re-entrant corner is the other part's
            # face, off to the side, and would count a thick member beside a fin as thin.
            spacing = float(np.sqrt(float(mesh.area) / len(points)))
            behind = found & (best <= spacing)
            thin_volume = float(gap[behind].sum()) * float(mesh.area) / len(points) / 2.0
            out["volume_share"] = round(min(thin_volume / abs(float(mesh.volume)), 1.0), 4)
    return out


def body_source(session: Path) -> Path | None:
    """The surface the session's body is now: the upload when the geometry card's mode is a
    surface, the generated mesh otherwise.  A generation left on disk by a switch to a built
    body is not the body."""
    geometry = session / "geometry"
    mode = (lib.read_json(session / "session.json", {}) or {}).get("geometry_mode")
    order = ("original.glb", "generated.glb") if mode == "surface" else ("generated.glb", "original.glb")
    return next((geometry / name for name in order if (geometry / name).exists()), None)


def _physical_mesh(session: Path):
    import trimesh
    path = session / "geometry" / "physical.glb"
    return trimesh.load(path, force="mesh", process=False) if path.exists() else None


def _generated_mesh(session: Path):
    import trimesh
    source = body_source(session)
    if source is None:
        return None
    return trimesh.load(source, force="mesh", process=False)


def fill_fraction(session: Path) -> float | None:
    """Mesh volume over its bounding-box volume: how much of the box is material.

    A solid chunky object fills 0.3-0.7 of its box; a hollow box or shell with
    walls a leaf thick fills under about 0.15, which the six views cannot show.
    """
    mesh = _generated_mesh(session)
    if mesh is None or not mesh.is_watertight:
        return None
    box = float(mesh.extents[0] * mesh.extents[1] * mesh.extents[2])
    return round(abs(float(mesh.volume)) / box, 3) if box > 0 else None


def resolved_plan(session: Path, plan: dict[str, Any]) -> dict[str, Any]:
    """The plan with ``scale.up_axis: "longest"`` replaced by the generated mesh's longest axis.

    TripoSG puts the object's front at +z, so a long body's length lands on x
    from some prompts and on z from others; "longest" says the extent is the
    long dimension, whichever that came out as.
    """
    scale = plan.get("scale") or {}
    if scale.get("up_axis") != "longest":
        return plan
    extents = generated_extents(session)
    if extents is None:
        return plan
    axis = "xyz"[max(range(3), key=lambda i: extents[i])]
    return {**plan, "scale": {**scale, "up_axis": axis}}


# The version of the measures planned_resolution records: an entry cached under another version is
# measured again (G4's wall reading and the principal extents changed what an old entry holds).
MEASURE_VERSION = 4          # 4: G4's mass at the parts' densities, the solved volume


def planned_resolution(session: Path, plan: dict[str, Any]) -> dict[str, Any] | None:
    """``_planned_resolution``, cached in ``operator/planned_resolution.json``.

    It is a pure function of the body file, the plan's scale, depth and density and the brief's
    real mass and member, and cost 1.3 s (0.9 s in a warm process) at each of the one to three
    calls a runner command made -- the gates, the statics, both geometry-stop checks, judge.
    """
    source = body_source(session)
    if source is None:
        return _planned_resolution(session, plan)
    try:
        stat = Path(source).stat()
    except OSError:
        return _planned_resolution(session, plan)
    operator = lib.operator_dir(session)
    key = _normalized({"measures": MEASURE_VERSION, "body": [str(source), stat.st_size, stat.st_mtime_ns],
                       "scale": plan.get("scale"),
                       "depth": (plan.get("settings") or {}).get("remesh_octree_depth", 7),
                       "density": [plan_density(session, plan)[0], g4_density(session, plan)[0]],
                       "real": [real_mass(operator), real_member(operator)]})
    path = operator / "planned_resolution.json"
    cache = lib.read_json(path, {}) or {}
    walls = (cache.get(key) or {}).get("thin_walls") or {}
    if key in cache and not ((walls.get("share_of_surface") or 0) > 0 and "volume_share" not in walls):
        # (an entry measured before the thin walls' volume share existed is measured again)
        return json.loads(json.dumps(cache[key]))     # a copy: callers may add to it
    out = _planned_resolution(session, plan)
    if out is not None:
        entries = list(cache.items())[-7:] + [(key, out)]
        lib.write_json(path, dict(entries))
    return json.loads(json.dumps(out)) if out is not None else None


def _planned_resolution(session: Path, plan: dict[str, Any]) -> dict[str, Any] | None:
    """The leaf size the plan's scale gives this geometry, before it is scaled.

    The octree cube is 1.92 x the largest physical extent, split 2^depth ways;
    the scale is uniform, so the largest extent follows from the planned one
    along ``up_axis`` and the generated mesh's proportions.
    """
    plan = resolved_plan(session, plan)
    scale = plan.get("scale") or {}
    axis = "xyz".find(str(scale.get("up_axis", "")))
    extent = scale.get("physical_extent")
    extents = generated_extents(session)
    if axis < 0 or not extent or extents is None:
        return None
    factor = float(extent) / float(extents[axis])
    physical = [float(e) * factor for e in extents]
    depth = int((plan.get("settings") or {}).get("remesh_octree_depth", 7))
    h = 1.92 * max(physical) / 2 ** depth
    out = {"physical_extents": [round(e, 4) for e in physical], "depth": depth,
           "leaf_size_h": round(h, 5),
           "leaves_across_smallest_extent": round(min(physical) / h, 1),
           "four_leaves": round(4 * h, 4), "fill_fraction": fill_fraction(session)}
    # The generated body's volume and mass at the planned size, so the mass
    # limit (objectives/size.md §3.1) is applied here, where the geometry can still
    # be changed, rather than read off the solve stop.
    mesh = _generated_mesh(session)
    density, density_source = plan_density(session, plan)
    if mesh is not None:
        try:
            # the extents along the body's own principal axes (its oriented bounding box), which the
            # extents check compares: a body lying diagonally in a plane read its axis-aligned box
            # (review of 2026-10-11); the mass is the volume's, as before
            out["principal_extents"] = [round(float(e) * factor, 4) for e in _scale_free(
                session, "principal_extents", lambda: sorted(mesh.bounding_box_oriented.primitive.extents.tolist(),
                                                             reverse=True))]
        except Exception:      # the axis-aligned extents stand
            pass
    if mesh is not None and mesh.is_watertight:
        volume = abs(float(mesh.volume)) * factor ** 3
        out["planned_volume"] = round(volume, 6)
        if density:
            out["planned_mass"] = round(volume * float(density), 4)
            if density_source != "plan":
                out["planned_mass_density"] = f"{density:.4g}, {density_source}"
        try:
            # the body the solve takes: physical.glb, scaled as the workflow scales it (workflow_scale)
            solved = abs(float(mesh.volume)) * workflow_scale(
                mesh.bounds, axis, float(extent), session_octree_depth(session)) ** 3
            out["solved_volume"] = round(solved, 6)
            if density:
                out["solved_mass"] = round(solved * float(density), 4)
        except Exception:      # the planned mass stands for it
            pass
        # G4's mass (and the mass revision's) at the parts' own densities when the brief or the plan
        # gives parts that differ (g4_density); the planned mass stays the solve's density
        g4, g4_from = g4_density(session, plan, density, density_source)
        if g4:
            out["g4_mass"] = round(volume * float(g4), 4)
            out["mass_over_real_from"] = f"{g4:.4g}, {g4_from}"
            real = real_mass(lib.operator_dir(session))
            if real:
                out["mass_over_real"] = round(out["g4_mass"] / real, 2)
        try:
            thin = _scale_free(session, "member_thickness", lambda: member_thickness(mesh))
            if thin:
                out["member_thickness"] = {
                    "thinnest_m": round(thin["p10"] * factor, 5),
                    "median_m": round(thin["p50"] * factor, 5),
                    "voxel_m": round(thin["voxel"] * factor, 5),
                    "note": ("a voxel estimate of the members' size (the thinnest 10 % of the volume), "
                             "to read beside the views; it decides nothing: thinnest_member_leaves is "
                             "the one thin-member measure every check uses")}
        except Exception as exc:  # a hint, never a blocker
            out["member_thickness"] = {"error": str(exc)[:120]}
        real_thin = compared_member(session)
        if real_thin and isinstance(out.get("member_thickness"), dict) and out["member_thickness"].get("thinnest_m"):
            # the voxel estimate's ratio: a built body's own route (body_route), never G4
            out["voxel_member_over_real"] = round(out["member_thickness"]["thinnest_m"] / real_thin, 2)
        try:
            scaled = mesh.copy()
            scaled.apply_scale(factor)
            out["thin_gaps"] = thin_gaps(scaled, h)
            out["thin_walls"] = thin_walls(scaled, h)
            if real_thin:
                ratio, source = _scale_free(session, ("g4", round(factor, 9), round(h, 9), real_thin), lambda: g4_member_ratio(
                    scaled, h, real_thin, out.get("voxel_member_over_real")))
                if ratio is not None:
                    out["member_over_real"], out["member_over_real_from"] = ratio, source
            enough = f"{RESOLVED_LEAVES} or more (no wall thinner)"
            out["thinnest_member_leaves"] = thinnest_leaves(out) or enough
            if depth < DEEPEST_DEPTH:
                # what a solve at the deepest depth will be checked against
                h8 = 1.92 * max(physical) / 2 ** DEEPEST_DEPTH
                out[f"thinnest_member_leaves_at_depth_{DEEPEST_DEPTH}"] = thinnest_leaves(
                    {"thin_walls": thin_walls(scaled, h8)}) or enough
        except Exception as exc:  # a hint, never a blocker
            out["thin_gaps"] = {"error": str(exc)[:120]}
        try:
            out["sections"] = _scale_free(session, ("sections", factor), lambda: planned_sections(mesh, factor))
            out["load_path"] = _scale_free(session, ("load_path", factor), lambda: load_path_numbers(mesh, factor))
        except Exception as exc:  # a hint, never a blocker
            out["sections"] = {"error": str(exc)[:120]}
    return out


# The self-weight a scaled stand-in carries is its solved body's: the volume of physical.glb times
# the density solved.  The scaling once took the planned mass (the generated mesh x extent / its
# extent along the up axis), but the workflow snaps the mesh's bounds to its octree lattice before
# scaling (scale_surface), so physical.glb came out 1 % longer and 3 % heavier, and a figure that
# read the applied body load off physical.glb found it 1.03 x the Real weight (2026-10-12; the rest of
# its 1.55 x was the use's 1.5 g dynamic factor, which the runner applies by design).
def workflow_scale(bounds, axis: int, extent: float, depth: int) -> float:
    """The uniform scale ``workflow_tool.scale_surface`` gives a mesh of these ``bounds``: the bounds
    snapped to the octree lattice (cube OCTREE_CUBE_PAD x the largest extent, 2^depth leaves) and the
    snapped span along ``axis`` made ``extent``.  Kept equal to it by a test."""
    low, high = [float(v) for v in bounds[0]], [float(v) for v in bounds[1]]
    h = OCTREE_CUBE_PAD * max(b - a for a, b in zip(low, high)) / 2 ** int(depth)
    return float(extent) / (round(high[axis] / h) * h - round(low[axis] / h) * h)


OCTREE_CUBE_PAD = 3.84 / 2.0          # workflow_tool.OCTREE_CUBE_PAD


def session_octree_depth(session: Path) -> int:
    """The depth the workflow scales the surface at (the session's, not the plan's remesh depth)."""
    return int((lib.read_json(session / "session.json", {}) or {}).get("octree_depth") or 7)


_SCALE_FREE: dict[Any, Any] = {}


def _scale_free(session: Path, name: Any, compute):
    """A measure of the generated body that the plan's depth does not change, computed once per
    body file in this process.  The geometry stop asks ``_planned_resolution`` twice, for the
    plan's depth and the deepest, and recomputed these each time: 7.7 s of member thickness alone
    on a 744k-face body (2026-10-09).  A copy is returned, as callers may add to it."""
    source = body_source(session)
    try:
        stat = Path(source).stat() if source else None
    except OSError:
        stat = None
    if stat is None:
        return compute()
    key = (str(source), stat.st_size, stat.st_mtime_ns, name)
    if key not in _SCALE_FREE:
        _SCALE_FREE[key] = compute()
    return copy.deepcopy(_SCALE_FREE[key])


def filled_voxels(mesh, cells: int = 160):
    """The body as a filled voxel grid: (solid, pitch, grow, shrink).

    Ray tests need rtree and trimesh's voxel fill needs scipy, neither of which
    the environment carries, so: the surface is sampled into a voxel shell (the
    grid offset half a voxel, so a face at the body's extreme sits on a voxel
    centre like any other), closed by one dilation so the flood fill cannot
    leak, the outside is flood-filled from the border, and the dilation is taken
    off again.  Across a member of thickness t the solid is then t/pitch + 1
    voxels on average: the two shell layers straddle the two faces.  The grid
    is padded by three voxels on every side.
    """
    import numpy as np
    import trimesh

    pitch = float(max(mesh.extents)) / cells
    count = int(min(3_000_000, max(100_000, 8 * float(mesh.area) / pitch ** 2)))
    points, _ = trimesh.sample.sample_surface(mesh, count, seed=0)
    index = np.floor((np.asarray(points) - mesh.bounds[0]) / pitch + 0.5).astype(int)
    shape = np.ceil(mesh.extents / pitch).astype(int) + 1
    index = np.clip(index, 0, shape - 1)
    shell = np.zeros(shape, dtype=bool)
    shell[index[:, 0], index[:, 1], index[:, 2]] = True
    shell = np.pad(shell, 3)

    def neighbours(a, combine):
        # ``combine`` the array with its two neighbours along every axis, wrapping round as
        # np.roll(a, +-1) does, but in place on slices: np.roll copied the whole grid twice per
        # axis, at each of the ~1700 calls a 744k-face body's thickness took (2.4 s, 2026-10-09).
        out = a.copy()
        for axis in range(a.ndim):
            def at(s):
                index = [slice(None)] * a.ndim
                index[axis] = s
                return tuple(index)
            combine(out[at(slice(1, None))], a[at(slice(None, -1))], out=out[at(slice(1, None))])
            combine(out[at(slice(None, -1))], a[at(slice(1, None))], out=out[at(slice(None, -1))])
            combine(out[at(0)], a[at(-1)], out=out[at(0)])      # the wrap: first plane, last plane
            combine(out[at(-1)], a[at(0)], out=out[at(-1)])
        return out

    def grow(a):
        return neighbours(a, np.logical_or)

    def shrink(a):
        return neighbours(a, np.logical_and)

    closed = grow(shell)
    outside = np.zeros(shell.shape, dtype=bool)
    outside[0], outside[-1] = True, True
    outside[:, 0], outside[:, -1] = True, True
    outside[:, :, 0], outside[:, :, -1] = True, True
    outside &= ~closed
    for _ in range(3 * cells):
        grown = grow(outside) & ~closed
        if (grown == outside).all():
            break
        outside = grown
    # The dilation's outer layer touches the outside; the sampled shell does
    # not (every shell voxel's neighbours are in the dilation), so this takes
    # off exactly what the closing added.
    return ~grow(outside), pitch, grow, shrink


def reach_beyond_holds(session: Path) -> dict[str, Any] | None:
    """How far the body reaches beyond the box of its held regions, each way: for a body held at a
    side rather than its base, what it cantilevers from where it is held."""
    import numpy as np
    import trimesh
    resolved = lib.read_json(session / "boundary_conditions" / "resolved.json", {}) or {}
    physical, masks_path = session / "geometry" / "physical.glb", session / "boundary_conditions" / "resolved.npz"
    if not resolved or not physical.exists() or not masks_path.exists():
        return None
    mesh = trimesh.load(physical, force="mesh", process=False)
    masks = np.load(masks_path)
    held = np.zeros(len(mesh.faces), dtype=bool)
    for region in resolved.get("regions", []):
        key = region.get("key")
        if region.get("category") == "dirichlet" and key in masks.files and len(masks[key]) == len(mesh.faces):
            held |= masks[key].astype(bool)
    if not held.any():
        return None
    points = mesh.vertices[mesh.faces[held].reshape(-1)]
    lo, hi = points.min(axis=0), points.max(axis=0)
    blo, bhi = mesh.bounds
    return {f"{sign}{'xyz'[a]}": round(float(max(bhi[a] - hi[a] if sign == "+" else lo[a] - blo[a], 0.0)), 4)
            for a in range(3) for sign in "+-"}


def load_path_numbers(mesh, factor: float) -> dict[str, Any]:
    """The body's load path in numbers, to set beside the brief's object: how many separate members
    a cut across each axis crosses (at a quarter, half and three quarters of the extent), and how
    far the body reaches beyond the footprint it stands on (its lowest 5 % of the height, +y up),
    each way.  A count or a reach the object does not have is another load path."""
    import numpy as np
    crossing = {}
    for a in "xyz":
        rows = cross_sections(mesh, stations=(0.25, 0.5, 0.75), axis=a)["stations"]
        crossing[a] = [len(r["pieces"]) for r in rows]
    v = np.asarray(mesh.vertices, dtype=float) * factor
    low = v[:, 1] <= v[:, 1].min() + 0.05 * np.ptp(v[:, 1])
    lo, hi = v[low][:, [0, 2]].min(axis=0), v[low][:, [0, 2]].max(axis=0)
    reach = {"+x": float(v[:, 0].max() - hi[0]), "-x": float(lo[0] - v[:, 0].min()),
             "+z": float(v[:, 2].max() - hi[1]), "-z": float(lo[1] - v[:, 2].min())}
    return {"members_crossing_cuts": crossing,
            "reach_beyond_base_m": {k: round(max(val, 0.0), 4) for k, val in reach.items()},
            "base_footprint_m": [[round(float(lo[0]), 4), round(float(lo[1]), 4)],
                                 [round(float(hi[0]), 4), round(float(hi[1]), 4)]],
            "note": ("members_crossing_cuts: separate pieces a cut across x, y and z meets at 1/4, 1/2 "
                     "and 3/4 of the extent; reach_beyond_base_m: how far the body reaches beyond the "
                     "footprint of its lowest 5 % (x, z). Set both beside the brief's object: how many "
                     "members carry the load, where it is held, what it cantilevers")}


def planned_sections(mesh, factor: float, axis: str | None = None,
                     stations: tuple[float, ...] | None = None) -> dict[str, Any]:
    """``cross_sections`` in the plan's metres, positions from the body's minimum corner
    (the scaled body's own frame, which the region words use).  ``stations``: fractions of the
    length to cut at (the five default stations when None)."""
    raw = cross_sections(mesh, axis=axis) if stations is None else cross_sections(mesh, stations, axis=axis)
    axis = "xyz".index(raw["axis"])
    across = ["xyz".index(a) for a in raw["across"]]
    low = [float(v) for v in mesh.bounds[0]]
    length = float(mesh.extents[axis]) * factor
    rows = []
    for row in raw["stations"]:
        pieces = []
        for piece in row["pieces"][:6]:
            size = [v * factor for v in piece["size"]]
            pieces.append({
                "area_m2": float(f"{piece['area'] * factor ** 2:.4g}"),
                "centroid_m": [round((piece["centroid"][i] - low[across[i]]) * factor, 4) for i in range(2)],
                # I[0] = ∫(v-v̄)² resists bending about the first across axis, I[1] about the second
                "I_m4": {f"about_{raw['across'][i]}": float(f"{piece['I'][i] * factor ** 4:.4g}")
                         for i in range(2)},
                f"size_m_along_{raw['across'][0]}_{raw['across'][1]}": [round(v, 4) for v in size],
                "length_over_size": [round(length / v, 1) if v > 0 else None for v in size]})
        rows.append({"at_m": round((row["at"] - low[axis]) * factor, 4), "pieces": pieces})
    return {"along": raw["axis"], "across": raw["across"], "length_m": round(length, 4),
            "note": ("the generated body after the plan's scale, cut across its longest axis: per "
                     "piece the exact area, centroid, the second moment of area about each "
                     "centroidal axis named (I_m4.about_y: bending about a y-parallel axis), its "
                     "size along the two axes, and the body's length over each size (under about "
                     "5 the beam formula needs its shear term)"),
            "stations": rows}


def _section_loops(segments):
    """Chain cut segments into closed loops of 2-D points."""
    import numpy as np

    keyed = {}
    scale = float(np.abs(segments).max() or 1.0) * 1e-9
    def key(p):
        return (round(float(p[0]) / scale), round(float(p[1]) / scale))
    starts = {}
    for i, (a, b) in enumerate(segments):
        starts.setdefault(key(a), []).append(i)
    used = np.zeros(len(segments), dtype=bool)
    loops = []
    for first in range(len(segments)):
        if used[first]:
            continue
        loop, i = [], first
        while not used[i]:
            used[i] = True
            loop.append(segments[i][0])
            nxt = [j for j in starts.get(key(segments[i][1]), []) if not used[j]]
            if not nxt:
                break
            i = nxt[0]
        if len(loop) >= 3:
            loops.append(np.asarray(loop))
    return loops


def _polygon_props(points):
    """Signed area, first moments and second moments (about the origin) of a closed polygon."""
    import numpy as np

    u, v = points[:, 0], points[:, 1]
    un, vn = np.roll(u, -1), np.roll(v, -1)
    c = u * vn - un * v
    area = c.sum() / 2.0
    su = ((u + un) * c).sum() / 6.0            # ∫u dA
    sv = ((v + vn) * c).sum() / 6.0            # ∫v dA
    iuu = ((u * u + u * un + un * un) * c).sum() / 12.0   # ∫u² dA
    ivv = ((v * v + v * vn + vn * vn) * c).sum() / 12.0   # ∫v² dA
    iuv = ((u * vn + 2 * u * v + 2 * un * vn + un * v) * c).sum() / 24.0
    return area, su, sv, iuu, ivv, iuv


def cross_sections(mesh, stations=(0.1, 0.3, 0.5, 0.7, 0.9), axis: str | None = None):
    """The body's sections across its longest axis, piece by piece, cut exactly.

    Each station is a plane across the longest axis; the mesh is cut there
    (trimesh's plane intersection, no extra library), the cut segments are
    oriented by their faces' normals (outward to the right, so an outline runs
    counter-clockwise and a hole clockwise) and chained into loops; each outline
    with the holes inside it is a piece.  Green's theorem then gives the exact
    area, centroid and second moments of every piece: the numbers a hand formula
    needs, from the body that came out rather than from its bounding box.
    """
    import numpy as np
    import trimesh

    axis = "xyz".index(axis) if axis in ("x", "y", "z") else int(np.argmax(mesh.extents))
    others = [a for a in range(3) if a != axis]
    rows = []
    for fraction in stations:
        coordinate = float(mesh.bounds[0][axis] + fraction * mesh.extents[axis])
        normal = np.eye(3)[axis]
        origin = np.zeros(3)
        origin[axis] = coordinate
        lines, faces = trimesh.intersections.mesh_plane(mesh, normal, origin, return_faces=True)
        if len(lines) == 0:
            rows.append({"at": coordinate, "pieces": []})
            continue
        seg = np.asarray(lines)[:, :, others]                  # (n, 2, 2) in (u, v)
        outward = np.asarray(mesh.face_normals[faces])[:, others]
        d = seg[:, 1] - seg[:, 0]
        # outward on the right of the direction: d x outward < 0 for a counter-clockwise outline
        flip = (d[:, 0] * outward[:, 1] - d[:, 1] * outward[:, 0]) > 0
        seg[flip] = seg[flip][:, ::-1]
        loops = _section_loops(seg)
        props = [(loop, _polygon_props(loop)) for loop in loops]
        outers = [(loop, p) for loop, p in props if p[0] > 0]
        holes = [(loop, p) for loop, p in props if p[0] < 0]
        pieces = []
        for loop, p in outers:
            total = np.array(p, dtype=float)
            for hole, q in holes:
                if _point_in_polygon(tuple(hole[0]), [tuple(x) for x in loop]):
                    total += np.array(q, dtype=float)
            area, su, sv, iuu, ivv, iuv = total
            if area <= 0:
                continue
            cu, cv = su / area, sv / area
            pieces.append({"area": float(area), "centroid": [float(cu), float(cv)],
                           "I": [float(ivv - area * cv * cv), float(iuu - area * cu * cu)],
                           "size": [float(np.ptp(loop[:, 0])), float(np.ptp(loop[:, 1]))]})
        pieces.sort(key=lambda piece: -piece["area"])
        rows.append({"at": coordinate, "pieces": pieces})
    return {"axis": "xyz"[axis], "across": ["xyz"[a] for a in others], "stations": rows}


def member_thickness(mesh, cells: int = 160) -> dict[str, float] | None:
    """Local thickness of the body's members, from the filled voxel grid.

    The body (``filled_voxels``) is eroded one layer at a time (a city-block
    distance to the surface); along the medial ridge, where that distance is a
    local maximum, it gives the local thickness.  The 10th percentile over the
    body's volume is the thinnest member, which the six views cannot measure
    and the resolution rules need.  Members whose faces are parallel to the axes
    read within a voxel.  City-block distance reads a member whose
    faces are inclined to the axes thick: plates inclined 30-45 degrees read
    1.2-1.8x, the most when only a few voxels thick (1.5x at ten or more).
    """
    import numpy as np

    solid, pitch, grow, shrink = filled_voxels(mesh, cells)
    if solid.sum() < 50:
        return None
    dist = np.zeros(solid.shape, dtype=np.int32)
    current = solid.copy()
    layer = 0
    while current.any() and layer < cells:
        layer += 1
        dist[current] = layer
        current = shrink(current)
    # Local thickness as the diameter of the largest inscribed ball that
    # contains each voxel (Hildebrand): ridge voxels (a local maximum of the
    # distance along some axis) seed balls of their own radius, painted largest
    # first, so the voxels at edges and corners take the thickness of the
    # member behind them instead of their own distance to the nearest face.
    # The centres of the maximal balls are the voxels whose distance is not
    # exceeded by any of their 26 neighbours: the centre line of a bar, the
    # mid-plane of a plate.  (An axis-wise test also takes the diagonal sheets
    # that run into every edge, whose small balls then dominate the low end.)
    highest = dist.copy()
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            for dz in (-1, 0, 1):
                if dx or dy or dz:
                    highest = np.maximum(highest, np.roll(dist, (dx, dy, dz), axis=(0, 1, 2)))
    ridge = solid & (dist >= highest) & (dist >= 2)
    local = np.zeros(solid.shape, dtype=np.float64)
    for radius in sorted(np.unique(dist[ridge]), reverse=True):
        seeds = ridge & (dist == radius)
        # The balls grow r-1 voxels from their centres, so only the box around the centres
        # padded by r is touched: grown there instead of over the whole grid.  They never reach
        # the box's faces, and the solid never touches the grid's, so the result is the same.
        where = np.argwhere(seeds)
        lo = np.maximum(where.min(axis=0) - int(radius), 0)
        hi = np.minimum(where.max(axis=0) + int(radius) + 1, solid.shape)
        box = tuple(slice(a, b) for a, b in zip(lo, hi))
        ball, inside = seeds[box], solid[box]
        for _ in range(int(radius) - 1):
            ball = grow(ball) & inside
        # n voxels across give a ridge distance of (n+1)/2 for odd n and n/2
        # for even n, and the faces lie on average n-1 voxels apart: 2r-2 or
        # 2r-1.  The parity is not known at a voxel, so the mean, 2r-1.5:
        # half a voxel either way, plus the half voxel by which n-1 itself
        # straddles the true thickness, so within a voxel and unbiased.
        part = local[box]
        part[ball & (part == 0)] = (2.0 * radius - 1.5) * pitch
    values = local[solid & (local > 0)]
    if values.size < 50:
        return {"p10": pitch, "p50": pitch, "voxel": pitch, "under_two_voxels": True}
    return {"p10": float(np.percentile(values, 10)), "p50": float(np.percentile(values, 50)),
            "voxel": pitch, "under_two_voxels": False}


def use_table_digest(session: Path, plan: dict[str, Any]) -> dict[str, Any] | None:
    """What the values card reads of the Use table: the run state, its rows' sizes, units and
    directions, and plan.loads.  None without a table of states."""
    try:
        table, _ = use_table(lib.operator_dir(session))
    except Exception:
        return None
    if not table:
        return None
    rows = {a: {k: (table["rows"].get(a) or {}).get(k) for k in ("size", "unit", "direction", "source")}
            for a in table["cases"].get(table["run"]) or [] if isinstance(table["rows"].get(a), dict)}
    return {"run": table["run"], "rows": rows, "loads": plan.get("loads")}


TABLE_VALUES = "table_values.json"     # the forces the runner put on load regions from the Use table
COUPLE_TOLERANCE = 0.10                 # a plan's couple on an N m row's regions within 10 % of its size


def use_table_values(session: Path, plan: dict[str, Any],
                     regions: list[dict[str, Any]]) -> tuple[dict[str, Any], str | None, str | None]:
    """Each load region's force from the Use table: the run rows bound to it (``load_bindings``),
    each at its size along the row's own "direction" when it gives one, else the direction of the
    plan's value for that region (``neumann_values``, or ``load``).  A row bound to several regions
    shares its size among them: a row's size is the total it puts on its regions (a pressure on
    opposite walls is shared, never doubled, which one run met; the two faces
    of a squeeze are a row each, the second "as" the first).  A row in N m (a twist) is not
    applied: the plan's own forces on its regions must make a couple within COUPLE_TOLERANCE of its
    size.  A load region with a value that no row binds is refused.  Returns (the plan with those
    forces, a note, a problem); the forces are recorded (TABLE_VALUES) so the next run reads them
    as the runner's, not a plan change.  A bound row is applied with its size: binding without a
    value (one run bound two rows and applied neither) and the same number
    typed twice are both gone."""
    import numpy as np
    operator = lib.operator_dir(session)
    table, _ = use_table(operator)
    if not table:
        return plan, None, None
    values = dict(plan.get("values") or {})
    named = dict(values.get("neumann_values") or {})
    by_name = {r.get("name"): r for r in regions}
    reactions = set(reaction_regions(plan.get("contacts")))
    loads = {r.get("name") for r in regions if r.get("category") == "neumann"} - reactions
    planned = {row["region"]: np.asarray(row["force_N"], dtype=float) for row in planned_load(plan, regions)}

    axes = use_to_body(session, plan)

    def direction(row: dict[str, Any], region: str):
        own = row.get("direction")
        if isinstance(own, list) and len(own) == 3 and all(_number(c) is not None for c in own):
            own = turned_direction(own, axes)          # the row's use-frame line, in the body's frame
        for value in (own, named.get(region), values.get("load")):
            vector = value.get("force") if isinstance(value, dict) else value
            if isinstance(vector, list) and len(vector) == 3 and all(_number(c) is not None for c in vector):
                size = float(np.linalg.norm(np.asarray(vector, dtype=float)))
                if size > 0:
                    return np.asarray(vector, dtype=float) / size
        return None

    bindings = load_bindings(session, plan, regions)
    totals: dict[str, Any] = {}
    said, missing, wrong = [], [], []
    bound_regions: set[str] = set()
    for label, bound in bindings.items():
        size = (table.get("sizes") or {}).get(label)
        targets = [r for r in bound.get("regions") or [] if r in loads]
        bound_regions |= set(targets)
        if bound.get("state") != "applied" or not size or not targets:
            continue
        row = table["rows"].get(label) or {}
        if size[1] == "N m":
            centres = [np.asarray(by_name[r].get("centroid") or [0, 0, 0], dtype=float) for r in targets]
            middle = np.mean(centres, axis=0)
            axis = row.get("direction")
            if (len(targets) >= 2 and isinstance(axis, list) and len(axis) == 3
                    and all(_number(c) is not None for c in axis) and np.linalg.norm(axis) > 0):
                axis = turned_direction(axis, axes)        # the twist's use-frame axis, in the body's frame
                # The twist about the row's "direction" as a couple of tangential forces the runner
                # computes: each region's force across its arm from the regions' middle, so the
                # agent types no couple (its arithmetic was a refusal round trip, 2026-10-11).
                axis = np.asarray(axis, dtype=float) / np.linalg.norm(axis)
                arms = [(c - middle) - float((c - middle) @ axis) * axis for c in centres]
                if all(np.linalg.norm(a) > 0 for a in arms):
                    for region, arm in zip(targets, arms):
                        tangent = np.cross(axis, arm / np.linalg.norm(arm))
                        totals[region] = totals.get(region, np.zeros(3)) + size[0] / (len(targets) * np.linalg.norm(arm)) * tangent
                    said.append(f"{label} {size[0]:g} N m about {[round(float(c), 3) for c in axis]} as a couple on {targets}")
                    continue
            couple = float(np.linalg.norm(sum(np.cross(c - middle, planned.get(r, np.zeros(3)))
                                              for c, r in zip(centres, targets))))
            if abs(couple - size[0]) > COUPLE_TOLERANCE * size[0]:
                wrong.append(f"{label} is {size[0]:g} N m, and the plan's forces on {targets} make a couple of "
                             f"{couple:.4g} N m about their middle: give the row \"direction\": [x, y, z], the axis "
                             "it twists about, and the runner applies the couple on its regions")
            continue
        units = {}
        for region in targets:
            unit = direction(row, region)
            if unit is None:
                missing.append(region)
            else:
                units[region] = unit
        shares = profile_shares(session, row, [by_name.get(r) or {"name": r} for r in units], axes)
        for region, unit in units.items():
            share = shares[region] if shares else 1.0 / len(units)
            totals[region] = totals.get(region, np.zeros(3)) + size[0] * share * unit
        said.append(f"{label} {size[0]:g} N on {targets}" + (
            " shared by its profile (" + ", ".join(f"{r} {shares[r]:.0%}" for r in units) + ")" if shares else ""))
    loose = sorted(r for r in loads - bound_regions if r in named or values.get("load") is not None) if bindings else []
    if loose:
        wrong.append(f"load regions {loose} have a value in the plan that no row of the run state binds: bind its "
                     "row in plan.loads, or leave the region out of the words")
    if missing:
        wrong.append(f"load regions {sorted(set(missing))} carry Use table rows but no direction: give the row its "
                     "\"direction\": [x, y, z], or plan.values.neumann_values.<region> a vector along it (its size "
                     "is the table's)")
    if wrong:
        return plan, None, "; ".join(wrong)
    forces = {region: [round(float(c), 6) for c in force] for region, force in totals.items()}
    lib.write_json(operator / TABLE_VALUES, {"forces": forces})
    if not forces:
        return plan, None, None
    for region, force in forces.items():
        named[region] = {"force": force}
    values["neumann_values"] = named
    turned = (f"; row directions and the acceleration turned into the body's frame (use x, y, z -> body "
              f"{', '.join(('-' if sign < 0 else '+') + 'xyz'[a] for a, sign in axes)}, plan.body_up "
              f"{plan.get('body_up')})" if axes else "")
    return ({**plan, "values": values}, "loads from the Use table (the plan's values give their direction only): "
            + "; ".join(said) + turned, None)


VARIES_FORM = ('{"along": [x, y, z], "from": <the intensity at the low end>, "to": <at the high end>} '
               '(relative numbers, 0 or more, in the use frame)')


def varies_problem(row: dict[str, Any]) -> str | None:
    """A row's ``varies`` (a pressure that varies linearly across its bands) in its form, or why not."""
    varies = row.get("varies")
    if varies is None:
        return None
    along = varies.get("along") if isinstance(varies, dict) else None
    ends = [_number(varies.get(k)) for k in ("from", "to")] if isinstance(varies, dict) else [None]
    if (not isinstance(along, list) or len(along) != 3 or any(_number(c) is None for c in along)
            or not any(along) or None in ends or min(ends) < 0 or not max(ends) > 0):
        return f"\"varies\" is {VARIES_FORM}"
    return None


def profile_shares(session: Path, row: dict[str, Any], regions: list[dict[str, Any]],
                   turn: tuple[tuple[int, int], ...] | None) -> dict[str, float] | None:
    """Each band's share of a row whose intensity varies linearly (``varies``) along an axis: the
    intensity at the band's centroid, interpolated between the bands' outer bounds along that axis,
    times the band's loaded area, over the sum.  None for a uniform row (equal shares).  The agent
    states the profile; the runner computes each band's value (until 2026-10-11 the agent typed one
    value per band)."""
    import numpy as np
    if varies_problem(row) or not row.get("varies") or len(regions) < 2:
        return None
    varies = row["varies"]
    axis = np.asarray(turned_direction(varies["along"], turn), dtype=float)
    axis /= np.linalg.norm(axis)
    bounds = {r.get("name"): r.get("bounds") for r in
              (lib.read_json(session / "boundary_conditions" / "resolved.json", {}) or {}).get("regions", [])}
    at, reach = {}, []
    for r in regions:
        if not r.get("centroid"):
            return None
        at[r["name"]] = float(np.asarray(r["centroid"], dtype=float) @ axis)
        box = bounds.get(r["name"]) or r.get("bounds")
        if box:
            low, high = np.asarray(box[0], dtype=float), np.asarray(box[1], dtype=float)
            corners = [np.where([(k >> i) & 1 for i in range(3)], high, low) for k in range(8)]
            reach += [float(c @ axis) for c in corners]
        else:
            reach.append(at[r["name"]])
    low, high = min(reach), max(reach)
    if high - low <= 0:
        return None
    start, end = float(varies["from"]), float(varies["to"])
    weights = {name: (start + (end - start) * (p - low) / (high - low))
               * float(next(r for r in regions if r["name"] == name).get("loaded_area")
                       or next(r for r in regions if r["name"] == name).get("area") or 1.0)
               for name, p in at.items()}
    total = sum(weights.values())
    return {name: w / total for name, w in weights.items()} if total > 0 else None


def planned_load(plan: dict[str, Any], regions: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """The force each load region will get from the plan's values, in newtons.

    A traction times the region's loaded area, or the force total as given.
    Shown at the regions stop so a traction typed as a force (5 kPa written as
    5000 N over 17 m2, which is 17 N of load) is seen before the solve.
    """
    values = plan.get("values") or {}
    rows = []
    for region in regions:
        if region.get("category") != "neumann":
            continue
        value = (values.get("neumann_values") or {}).get(region["name"], values.get("load"))
        area = region.get("loaded_area")
        if value is None or area is None:
            continue
        if isinstance(value, dict):
            force = [float(c) for c in value["force"]]
            how = "a force total"
        else:
            force = [float(c) * float(area) for c in value]
            how = f"traction {list(value)} x loaded area {float(area):.4g}"
        rows.append({"region": region["name"], "force_N": [round(c, 3) for c in force],
                     "magnitude_N": round(sum(c * c for c in force) ** 0.5, 3), "from": how})
    return rows


def material_segments_json(session: Path) -> Path | None:
    """The segmentation the per-part material was valued on, chosen as the workflow chooses it
    (graph ``_material_segments``): the regions stage's segments only when they are PartField's or
    a CAD part's own faces (graph ``BC_PART_SEGMENTATIONS``), else the material step's own
    PartField parts under materials/parts.

    The parts table once read the regions stage's segments first whatever their method.  In one
    run those were 8 shape-diameter segments while the material had been
    valued on the material step's own 6 PartField parts: the table gave each part id the
    centroid and area of another segmentation's segment of the same number (parts placed on one
    part that the montage showed on another; area fractions summing to 0.41).

    The graph's own test, replicated: the regions' segments when their method (their metadata's,
    else the session's) is PartField or CAD faces and their stamp (segments.source.json) records
    the current surface's contents; else the material step's segments when theirs does."""
    regions = session / "boundary_conditions" / "segments.json"
    own = session / "materials" / "parts" / "segments.json"
    if _regions_method(session) in ("partfield", "cad_faces") and _segments_match_surface(session, regions):
        return regions
    return own if _segments_match_surface(session, own) else None


def _regions_method(session: Path) -> str | None:
    """The method the regions stage's saved segments were made with (graph ``_bc_segmentation_method``)."""
    metadata = lib.read_json(session / "boundary_conditions" / "segments.json", {}) or {}
    state = lib.read_json(session / "session.json", {}) or {}
    return (metadata.get("method") if isinstance(metadata, dict) else None) or state.get("segmentation_method")


def _segments_match_surface(session: Path, segments_json: Path) -> bool:
    """Whether saved part labels were computed on the session's surface as it is now: their stamp's
    sha256 against the surface's contents (graph ``_segments_current``)."""
    npz = segments_json.with_suffix(".npz")
    stamp = lib.read_json(npz.with_name(npz.stem + ".source.json"), {}) or {}
    surface = _session_surface(session)
    if not (npz.is_file() and segments_json.is_file() and stamp.get("sha256") and surface):
        return False
    try:
        from src.agents_wrapper.fem_workflow.monitor import _digest
        return stamp["sha256"] == _digest(Path(surface))
    except Exception:
        return False


def _segment_table(session: Path) -> dict[int, dict[str, Any]]:
    """Each PartField segment's area fraction and centroid, by id, for the parts table: from the
    segmentation the parts were valued on (``material_segments_json``)."""
    path = material_segments_json(session)
    try:
        data = json.loads(path.read_text(encoding="utf-8")) if path is not None else {}
    except (OSError, ValueError):
        return {}
    return {int(s["id"]): {"area_fraction": round(float(s.get("area_fraction", 0)), 3),
                           "centroid": [round(float(c), 3) for c in s.get("centroid", [])]}
            for s in data.get("segments") or []}


def parts_mean_density(session: Path) -> float | None:
    """The part field's mean density over its occupied voxels, for a mass estimate.

    A per-part material has no single density, so the summary leaves the mass
    out; the 64^3 field's occupied voxels give a volume-weighted mean that,
    times the mesh volume, is the mass the hand check needs.
    """
    root = session / "materials" / "parts" / "field"
    try:
        import numpy as np
        manifest = json.loads((root / "manifest.json").read_text(encoding="utf-8"))
        grid = np.load(root / "material_grid.npy")
        mask = np.load(root / "valid_mask.npy").astype(bool)
        values = grid[..., manifest["channels"].index("density")][mask]
        return float(values.mean()) if values.size else None
    except Exception:
        return None


def plan_density(session: Path | None, plan: dict[str, Any]) -> tuple[float | None, str | None]:
    """The density the planned mass is taken at, and where it came from.

    Uniform: the plan's.  Per-part materials have none of their own, and the planned mass, the mass
    limit and the self-weight scaling of a stand-in once read None for them: in one run
    a stand-in of per-part materials at 2.9 x the real weight was neither scaled nor
    refused.  So, best first: the part field's volume-weighted mean (once the parts are valued); the
    valued parts weighted by their segments' area; before the parts are valued (the geometry stop
    and the regions come first), the mean of the densities the brief writes (each as written, so a
    material named for several members counts more), else of the plan's own parts."""
    material = plan.get("material") or {}
    density = material.get("density")
    if isinstance(density, (int, float)) and not isinstance(density, bool) and density > 0:
        return float(density), "plan"
    if material.get("mode") != "parts" or session is None:
        return None, None
    mean = parts_mean_density(session)
    if mean:
        return mean, "the part field's mean density"
    valued = (lib.read_json(session / "materials" / "parts" / "materials.json", {}) or {}).get("parts") or []
    given = {int(p["id"]): p for p in material.get("parts") or [] if isinstance(p, dict) and "id" in p}
    areas = _segment_table(session)
    weighted = [((given.get(int(p["id"])) or {}).get("density", p.get("density")),
                 (areas.get(int(p["id"])) or {}).get("area_fraction"))
                for p in valued if isinstance(p, dict) and "id" in p]
    weighted = [(float(d), float(a)) for d, a in weighted if isinstance(d, (int, float)) and d > 0 and a]
    if weighted and sum(a for _, a in weighted) > 0:
        return (sum(d * a for d, a in weighted) / sum(a for _, a in weighted),
                "the valued parts' densities weighted by area")
    listed = brief_parts_density(session, plan)
    if listed[0]:
        return listed
    written = brief_densities(lib.operator_dir(session))
    if written:        # kg/m3 in the brief, the plan's units here
        unit = (plan.get("scale") or {}).get("unit_system") or "SI (m-kg-s)"
        factor = _typical_density({"unit_system": unit}) / 1000.0
        return factor * sum(written) / len(written), "the mean of the densities the brief writes"
    own = [float(p["density"]) for p in given.values() if isinstance(p.get("density"), (int, float))
           and p["density"] > 0]
    return (sum(own) / len(own), "the mean of the plan's parts") if own else (None, None)


# G4 priced a body of different real materials at the Governing one alone: one run
# priced a light membrane as the Governing metal, and refused three recognisable bodies at
# 162-7673 x the Real mass.
# Where the brief's Materials by part (or the plan's parts) differ in density, G4's mass, and the
# mass revision's, take the parts' own: the segments matched to the listed parts as the material
# card fills them (brief_part_fills), else, before any segments, the listed parts' plain mean.
PARTS_RHO_APART = 1.05


def brief_parts_density(session: Path, plan: dict[str, Any]) -> tuple[float | None, str | None]:
    """The brief's Materials by part as one density in the plan's units, and how it was mixed."""
    entries = [e for e in brief_part_materials(session) if e.get("rho")]
    if not entries:
        return None, None
    to_si = DENSITY_TO_SI.get((plan.get("scale") or {}).get("unit_system") or "SI (m-kg-s)", 1.0)
    labels, areas = segment_labels(session), _segment_table(session)
    governing = governing_entry(session) if labels else None
    pairs = [((match_part(labels.get(i, ""), entries) or governing or {}).get("rho"), row.get("area_fraction"))
             for i, row in areas.items()] if labels else []
    pairs = [(float(r), float(a)) for r, a in pairs if r and a]
    if pairs:
        return (sum(r * a for r, a in pairs) / sum(a for _, a in pairs) / to_si,
                "the brief's Materials by part matched to the segments, weighted by area")
    return (sum(e["rho"] for e in entries) / len(entries) / to_si,
            "the plain mean of the brief's Materials by part (no segments yet)")


def g4_density(session: Path | None, plan: dict[str, Any], density: float | None = None,
               source: str | None = None) -> tuple[float | None, str | None]:
    """The density G4's mass is taken at: per-part materials' (plan_density); a uniform plan's own,
    unless the brief's Materials by part differ in density (brief_parts_density)."""
    if density is None and source is None:
        density, source = plan_density(session, plan)
    if session is not None and (plan.get("material") or {}).get("mode") != "parts":
        rhos = [e["rho"] for e in brief_part_materials(session) if e.get("rho")]
        if len(rhos) > 1 and max(rhos) > PARTS_RHO_APART * min(rhos):
            mixed = brief_parts_density(session, plan)
            if mixed[0]:
                return mixed
    return density, ("the plan's density" if source == "plan" else source)


def body_and_loads(session: Path, summary: dict[str, Any]) -> dict[str, Any]:
    """The body (extents, volume, mass, leaf size) and the loads of a solved session.

    The same block for the runner's solve stop and for ``solve-backend``, so a
    hand check has the mass whichever way the solve ran.  A per-part material
    has no single density: the mass is then the mesh volume times the field's
    mean density, and the self-weight follows from it.
    """
    geometry = summary.get("geometry") or {}
    material = summary.get("material") or {}
    density = material.get("density")
    volume = geometry.get("physical_volume")
    body = {"physical_extents": geometry.get("physical_extents"), "volume": volume,
            "mass": round(volume * density, 4) if volume and density else None,
            "leaf_size_h": geometry.get("leaf_size_h")}
    loads = summary.get("loads")
    if volume and not density and material.get("mode") == "parts":
        mean = parts_mean_density(session)
        if mean:
            body["mass"] = round(volume * mean, 4)
            body["mass_note"] = ("mesh volume times the part field's mean density "
                                 f"({mean:.0f}); per-part masses follow the area fractions")
            loads = {**(loads or {}), "self_weight_estimate": round(volume * mean * 9.80665, 4)}
    return {"body": body, "loads": loads}


def load_shares(session: Path, plan: dict[str, Any], planned: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Each load's share of the total, self-weight included, while the prediction is open."""
    rows = [{"load": r["region"], "N": r["magnitude_N"]} for r in planned]
    resolution = planned_resolution(session, plan) or {}
    acceleration = (plan.get("values") or {}).get("acceleration") or [0, 0, 0]
    g = sum(float(c) ** 2 for c in acceleration) ** 0.5
    if resolution.get("planned_mass"):
        rows.append({"load": "self-weight" + ("" if g else " (not applied: acceleration 0)"),
                     "N": round(resolution["planned_mass"] * (g or 9.80665), 3)})
    total = sum(r["N"] for r in rows) or 1.0
    return [{**r, "share": round(r["N"] / total, 3)} for r in rows]


def cad_face_summary(session: Path) -> dict[str, Any] | None:
    """The B-rep faces of a CAD-generated body, counted by type.

    A CAD generator can return a clean, watertight, wrong part; the number of
    cylindrical faces (bores, holes, round bosses) and planes is a check of the
    part against the brief's features that the six views do not give.
    """
    import numpy as np

    path = session / "geometry" / "generated.glb.faces.npz"
    source = body_source(session)
    if not path.exists() or (source is not None and source.name != "generated.glb"):
        return None
    try:
        data = np.load(path, allow_pickle=False)
        types = [str(x) for x in data["surface_types"]]
    except Exception:
        return None
    counts: dict[str, int] = {}
    for kind in types:
        counts[kind] = counts.get(kind, 0) + 1
    return {"faces": len(types), "by_type": counts,
            "note": "B-rep faces: each hole or bore is one or two 'cylinder' faces; compare "
                    "with the brief's features"}


def planned_supports(plan: dict[str, Any], regions: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """What each support region will be held in, from the plan's dirichlet_values.

    Printed at the regions stop beside ``planned_load`` so a contact the brief
    released shows up before the values are sent, and a name that matches no
    region is seen here rather than silently clamped.
    """
    given = (plan.get("values") or {}).get("dirichlet_values") or {}
    names = [r.get("name") for r in regions if r.get("category") == "dirichlet"]
    out = [{"name": n, "components": (given.get(n) or {}).get("components", [0, 1, 2]),
            "from": "plan.values.dirichlet_values" if n in given else "default: all components"}
           for n in names]
    for n in given:
        if n not in names:
            out.append({"name": n, "error": "not a support region of this preview; the next run will refuse it"})
    return out


# Partial paint defects, read from the painted surface's vertex colours (CIELAB, D65).
# Measured on 32 paints of ten bodies.
#   Near-black is dark AND grey: L* < 15 with chroma C* < 12.  Lightness alone counted a deep
# maroon underside, a good paint, as 11 % black; with the chroma bound it is 0.5 %.  The paints
# with black patches or a black body: 15 % and 100 % near-black off the resting facings; every
# other paint at most 3 %.  A facing that rests on a held region, or faces straight down (-y:
# the workflow's views are y-up), is listed apart and counts neither for black nor for two tones:
# the painter bakes a shadow under a body.  Unless it is mostly near-black itself (over half of
# its vertices): that is a black base, not a shadow (one such base: 80 % of its facing; the
# darkest shaded underside measured: 12 %), and it counts with the rest.
#   Two tones: the mean L* of the brightest and darkest of the counted axis facings holding 5 % of
# the vertices or more; 44 on the two-tone paints and 33 on the black base, at most 22 on the others.
#   Hue coverage: when the words name one colour of a hue, the share of the surface in that hue's
# band at C* >= 15 (>= 8 when a shade word asks for a pale or dark shade, whose chroma is low).  A
# paint grey all over with the hue only on small parts: 7 % and 30 %; the other paints asked red
# or brown: 55 % to 100 %.  Both paints asked blue came back teal-green (hue near 180, the views
# agree): 0 %, warned.  Each threshold sits between the two groups.
PAINT_DARK_L = 15.0
PAINT_DARK_CHROMA = 12.0
PAINT_DARK_SHARE = 0.05
PAINT_FACING_SPLIT = 30.0
PAINT_FACING_SHARE = 0.05
PAINT_HUE_CHROMA = 15.0
PAINT_HUE_CHROMA_SHADE = 8.0
PAINT_HUE_SHARE = 0.5
# The one hue by facing: a paint whose body is the hue overall (over PAINT_HUE_SHARE) can still
# have a whole side another colour.  One run asked one hue and got it on the
# front only, the back grey: 67 % overall and a lightness split of 5.5, so neither check above
# fired.  A counted facing of at least PAINT_HUE_FACING_SIZE of the surface under
# PAINT_HUE_FACING_SHARE in the hue is that side.  Measured on every paint of the 32
# that passes the overall share: the one-sided paints read 0.20-0.30 on their grey
# side (three seeds of one run), the paints of one hue all round 0.66 or more on every facing.
PAINT_HUE_FACING_SIZE = 0.1
PAINT_HUE_FACING_SHARE = 0.45
PAINT_RESTING_BLACK = 0.5                 # a resting facing over half near-black is a black base
# Words asking for a pale or a dark shade: such a colour has little chroma (a pale pink, a light
# blue, a dark brown are C* 8-15), so the hue band is read from a lower chroma.
PAINT_SHADE_WORDS = ("pale", "light", "pastel", "soft", "muted", "dusty", "dark", "deep")
# Colour words naming no hue a chroma test can find: a colour with one of them is not checked for hue.
PAINT_NEUTRAL_WORDS = ("grey", "gray", "white", "black", "silver", "beige", "cream", "creamy", "ivory", "khaki",
                       "charcoal", "whitish", "greyish", "grayish", "blackish")
# A held region rests on a facing when its area-weighted mean normal lies within about 45
# degrees of that facing's axis.
PAINT_HELD_ALIGNED = 0.7
FACING_NAMES = ("-x", "+x", "-y", "+y", "-z", "+z")
DOWN_FACING = 2                           # -y: the workflow's views are drawn y-up
# A generic colour vocabulary.  A dark colour word asks for dark paint; a dark finish or material
# word does too, unless the prompt names a lighter colour beside it (a light paint on a dark
# material is the colour asked for).  Two hues or more is a paint of several colours: its facings
# may differ on purpose.
DARK_COLOUR_WORDS = ("black", "dark", "deep", "charcoal", "ebony", "graphite", "anthracite", "soot", "coal",
                     "onyx", "obsidian", "jet", "gunmetal", "blackened", "navy", "slate", "espresso", "midnight")
DARK_SHADE_WORDS = ("dark", "deep")       # shades of a hue, not hues
DARK_FINISH_WORDS = ("iron", "walnut", "mahogany", "wenge", "rosewood", "oiled", "smoked")
# Materials that are dark whatever colour word stands beside them: the painter paints them dark (a
# run asked a mid grey carbon fibre, got its near-black weave, was warned
# "near-black" and repainted it an unrealistic light grey).  They ask for dark paint.
DARK_MATERIAL_WORDS = ("carbon", "graphite", "anthracite", "rubber", "bitumen", "asphalt", "tar", "ebony",
                       "obsidian", "soot", "coal")
HUE_WORDS = ("red", "orange", "yellow", "green", "blue", "purple", "violet", "pink", "brown", "white",
             "grey", "gray", "silver", "gold", "golden", "beige", "tan", "cream", "ivory", "teal", "cyan",
             "turquoise", "magenta", "maroon", "olive", "bronze", "copper", "ochre", "amber", "khaki", "lime",
             "crimson", "scarlet", "burgundy")
# Each chromatic hue word's CIELAB hue angle h_ab (degrees), read off the sRGB colour the word
# names, and the half-width of its band (35 unless given).  Blue spans sky blue (235) to pure
# blue (306): a band of 213-323.  The reds end at 54: wood brown sits at 58-67 and must not pass
# for red.  Grey, white, black, silver and the near-neutral words (beige, cream,
# ivory, khaki) are not here: their paints are not checked for hue.
PAINT_HUE_HALF_WIDTH = 35.0
# The reds reach down to about 345 (-15): one run asked red and got a crimson,
# magenta-leaning red (h 0-12 on 91 % of the surface), read as "9 % red" and so as a paint off its hue.
HUE_ANGLES = {"red": (20, 34), "crimson": (15, 25), "scarlet": (40, 15), "maroon": (28, 26),
              "burgundy": (15, 25), "pink": 2,
              "orange": 64, "ochre": 64, "copper": 65, "bronze": 65, "brown": 67, "tan": 78, "amber": 83,
              "gold": 89, "golden": 89, "yellow": 93, "olive": 103, "lime": 122, "green": 142,
              "teal": 196, "turquoise": 185, "cyan": 197, "blue": (268, 55), "navy": 306,
              "violet": 313, "purple": 328, "magenta": 328}
# A pale blue reads cyan to teal at its low chroma: one run asked a light blue
# glass and got a pale teal (h 170-200 on 87 % of the surface, the views a light blue-green glass),
# warned as "1 % blue".  With a light shade word, blue's band reaches down through cyan.
PAINT_LIGHT_SHADE_WORDS = ("pale", "light", "pastel", "soft")
PALE_HUE_BANDS = {"blue": (190.0, 25.0)}


def _lab(rgb: Any) -> tuple[Any, Any, Any]:
    """CIELAB L*, chroma C* and hue angle h (degrees) of sRGB colours in 0..255, D65."""
    import numpy as np
    c = np.asarray(rgb, dtype=float).reshape(-1, 3) / 255.0
    linear = np.where(c <= 0.04045, c / 12.92, ((c + 0.055) / 1.055) ** 2.4)
    xyz = linear @ np.array([[0.4124564, 0.3575761, 0.1804375], [0.2126729, 0.7151522, 0.0721750],
                             [0.0193339, 0.1191920, 0.9503041]]).T / np.array([0.95047, 1.0, 1.08883])
    f = np.where(xyz > 216 / 24389, np.cbrt(xyz), (24389 / 27 * xyz + 16) / 116)
    a, b = 500 * (f[:, 0] - f[:, 1]), 200 * (f[:, 1] - f[:, 2])
    return 116 * f[:, 1] - 16, np.hypot(a, b), np.degrees(np.arctan2(b, a)) % 360


def _painted_mesh(path: str | Path) -> Any:
    """The painted surface as one mesh with vertex colours (a texture sampled at the vertices);
    None for a surface without colours or of one flat colour (unpainted)."""
    import numpy as np
    import trimesh
    try:
        mesh = trimesh.load(str(path), force="mesh", process=False)
        visual = mesh.visual
        if getattr(visual, "kind", None) == "texture":
            visual = visual.to_color()
        rgb = np.asarray(visual.vertex_colors)[:, :3].astype(float)
    except Exception:
        return None
    if not len(rgb) or len(rgb) != len(mesh.vertices) or rgb.std() < 1e-6:
        return None
    mesh.visual = trimesh.visual.ColorVisuals(mesh, vertex_colors=np.asarray(visual.vertex_colors))
    return mesh


def held_facings(session: Path | None) -> list[int]:
    """The axis facings (indices into FACING_NAMES) a held region of the resolved preview rests on:
    its area-weighted mean normal within about 45 degrees of the facing's axis."""
    import numpy as np
    import trimesh
    if session is None:
        return []
    resolved = lib.read_json(session / "boundary_conditions" / "resolved.json", {}) or {}
    masks_path, physical = session / "boundary_conditions" / "resolved.npz", session / "geometry" / "physical.glb"
    if not resolved.get("regions") or not masks_path.exists() or not physical.exists():
        return []
    try:
        mesh = trimesh.load(physical, force="mesh", process=False)
        masks = np.load(masks_path)
    except Exception:
        return []
    out = set()
    for region in resolved["regions"]:
        key = region.get("key")
        if region.get("category") != "dirichlet" or key not in masks.files or len(masks[key]) != len(mesh.faces):
            continue
        faces = masks[key].astype(bool)
        normal = (mesh.face_normals[faces] * mesh.area_faces[faces, None]).sum(axis=0)
        length = float(np.linalg.norm(normal))
        if length <= 0:
            continue
        axis = int(np.argmax(np.abs(normal)))
        if abs(normal[axis]) / length >= PAINT_HELD_ALIGNED:
            out.add(2 * axis + int(normal[axis] > 0))
    return sorted(out)


def paint_stats(path: str | Path, resting: Any = (), hue: Any = None,
                hue_chroma: float = PAINT_HUE_CHROMA) -> dict[str, Any] | None:
    """The painted surface's near-black shares (overall, by facing, and over the counted facings:
    all but the ``resting`` ones and the downward one, a resting facing mostly near-black
    included), its lightness split between the counted facings and, for ``hue`` (bands of
    (centre, half-width) in degrees), the share in those bands at ``hue_chroma`` or more; None for
    a surface without colours.  ``masks`` holds each finding's vertices, for the marked views."""
    import numpy as np
    mesh = _painted_mesh(path)
    if mesh is None:
        return None
    rgb = np.asarray(mesh.visual.vertex_colors)[:, :3].astype(float)
    normal = np.asarray(mesh.vertex_normals)
    lightness, chroma, angle = _lab(rgb)
    axis = np.argmax(np.abs(normal), axis=1)
    facing = 2 * axis + (normal[np.arange(len(normal)), axis] > 0)
    dark = (lightness < PAINT_DARK_L) & (chroma < PAINT_DARK_CHROMA)
    # a resting facing mostly near-black is a black base, not a shadow: it is counted
    black = {k for k in range(6) if (facing == k).any() and dark[facing == k].mean() > PAINT_RESTING_BLACK}
    rest = sorted({DOWN_FACING, *[int(k) for k in resting]} - black)
    moving = ~np.isin(facing, rest)
    by_facing = {FACING_NAMES[k]: round(float(dark[facing == k].mean()), 4) for k in range(6)
                 if (facing == k).mean() >= PAINT_FACING_SHARE}
    means = {k: float(lightness[facing == k].mean()) for k in range(6)
             if (facing == k).mean() >= PAINT_FACING_SHARE and k not in rest}
    out: dict[str, Any] = {
        "dark_share": float(dark.mean()),
        "dark_share_away_from_resting": float(dark[moving].mean()) if moving.any() else 0.0,
        "dark_share_by_facing": by_facing, "resting_facings": [FACING_NAMES[k] for k in rest],
        "facing_split": float(max(means.values()) - min(means.values())) if means else 0.0,
        "lightness_mean": float(lightness.mean()), "lightness_std": float(lightness.std()),
        "masks": {"dark": dark & moving}}
    if means:
        # the counted facing whose lightness is furthest from the counted body's: the second tone
        odd = max(means, key=lambda k: abs(means[k] - float(lightness[moving].mean())))
        out["masks"]["split"] = facing == odd
        out["split_facing"] = FACING_NAMES[odd]
    if hue is not None:
        bands = [hue] if isinstance(hue[0], (int, float)) else list(hue)
        near = np.zeros(len(angle), dtype=bool)
        for centre, half in bands:
            near |= np.abs((angle - centre + 180) % 360 - 180) <= half
        inside = (chroma >= hue_chroma) & near
        out["hue_share"] = float(inside.mean())
        out["masks"]["hue"] = ~inside
        # by large counted facing: a side painted another colour hides in the overall share
        out["hue_share_by_facing"] = {FACING_NAMES[k]: round(float(inside[facing == k].mean()), 4)
                                      for k in range(6) if (facing == k).mean() >= PAINT_HUE_FACING_SIZE
                                      and k not in rest}
        out["masks"]["hue_facing"] = {FACING_NAMES[k]: (facing == k) & ~inside for k in range(6)}
    out["mesh"] = mesh
    return out


def paint_colours(prompt: str | None) -> dict[str, Any]:
    """What a texture prompt asks for: whether it asks for dark paint, whether it names several
    colours, and the one colour's hue bands when it has a hue (``hue``: the colour, its bands of
    (centre, half-width) in degrees and the chroma they are read from; None otherwise).

    Colours are counted as the plan check counts them (texture_colours): a modifier and its hue
    ("navy blue", "olive green"), a hue's grey or two neighbouring hues are one colour, and its
    bands are those of each of its hue words.  A colour with a neutral word ("blue grey") has no
    band to find."""
    import re
    text = str(prompt or "").lower()
    words = set(re.findall(r"[a-z]+", text))
    light_hues = words & set(HUE_WORDS)
    dark = (bool(words & set(DARK_COLOUR_WORDS) | words & set(DARK_MATERIAL_WORDS))
            or bool(words & set(DARK_FINISH_WORDS) and not light_hues))
    _, groups = texture_colours(text)
    hue = None
    if len(groups) == 1:
        parts = [w for t in groups[0].split() for w in t.split("-")]
        bands = [HUE_ANGLES[w] if isinstance(HUE_ANGLES[w], tuple) else (HUE_ANGLES[w], PAINT_HUE_HALF_WIDTH)
                 for w in parts if w in HUE_ANGLES]
        if words & set(PAINT_LIGHT_SHADE_WORDS):
            bands += [PALE_HUE_BANDS[w] for w in parts if w in PALE_HUE_BANDS]
        if bands and not set(parts) & set(PAINT_NEUTRAL_WORDS):
            shade = bool(words & set(PAINT_SHADE_WORDS))
            hue = {"word": groups[0], "bands": [(float(c), float(h)) for c, h in bands],
                   "chroma": PAINT_HUE_CHROMA_SHADE if shade else PAINT_HUE_CHROMA}
    return {"dark": dark, "several": len(groups) >= 2, "hue": hue}


def paint_findings(painted: str | Path | None, prompt: str | None, mode: str | None = None,
                   session: Path | None = None) -> tuple[list[str], dict[str, Any] | None]:
    """What the paint check finds (sentences) and the statistics it found them in, whose
    ``flagged`` mask holds the vertices behind the findings.  A prompt that asks for dark paint,
    alone or among several colours, is not checked for black (the dark share cannot be told from
    the colour asked for); a paint of several colours, or of per-part materials, is not checked for
    two tones or hue (its facings and parts may differ on purpose)."""
    import numpy as np
    if not painted or not Path(painted).exists():
        return [], None
    asked = paint_colours(prompt)
    hue = asked["hue"] if mode != "parts" and not asked["several"] else None
    stats = paint_stats(painted, held_facings(session), hue["bands"] if hue else None,
                        hue["chroma"] if hue else PAINT_HUE_CHROMA)
    if not stats:
        return [], None
    found, flagged = [], np.zeros(len(stats["mesh"].vertices), dtype=bool)
    share = stats["dark_share_away_from_resting"]
    if share > PAINT_DARK_SHARE and not asked["dark"]:
        shown = ", ".join(f"{k} {100 * v:.1f} %" for k, v in stats["dark_share_by_facing"].items()
                          if k not in stats["resting_facings"])
        resting = ", ".join(f"{k} {100 * v:.1f} %" for k, v in stats["dark_share_by_facing"].items()
                            if k in stats["resting_facings"])
        found.append(f"{100 * share:.1f} % of the surface off its resting facings is near-black (L* under "
                     f"{PAINT_DARK_L:g} and chroma C* under {PAINT_DARK_CHROMA:g}: dark grey, not a deep colour; "
                     f"over {100 * PAINT_DARK_SHARE:g} % is a black patch when the colour asked for is not dark); "
                     f"counted, by facing: {shown or 'none'}"
                     + (f"; resting facings (facing down or on a held region, read as shading, not counted): "
                        f"{resting}" if resting else ""))
        flagged |= stats["masks"]["dark"]
    if stats["facing_split"] > PAINT_FACING_SPLIT and not asked["several"] and mode != "parts":
        found.append(f"its facings differ by {stats['facing_split']:.0f} in lightness L* (over "
                     f"{PAINT_FACING_SPLIT:g}: two tones, one side painted unlike another; {stats['split_facing']} "
                     "is the odd one)")
        flagged |= stats["masks"]["split"]
    if hue and stats["hue_share"] < PAINT_HUE_SHARE:
        bands = " or ".join(f"{h:g} degrees of {c:g}" for c, h in hue["bands"])
        found.append(f"{100 * stats['hue_share']:.0f} % of the surface is {hue['word']} (hue within "
                     f"{bands} at chroma C* {hue['chroma']:g} or more; "
                     f"under {100 * PAINT_HUE_SHARE:g} % is a paint whose body is not the colour asked for)")
        flagged |= stats["masks"]["hue"]
    elif hue:
        off = {k: v for k, v in stats["hue_share_by_facing"].items() if v < PAINT_HUE_FACING_SHARE}
        if off:
            found.append(f"{100 * stats['hue_share']:.0f} % of the surface is {hue['word']}, but on its "
                         + ", ".join(f"{k} facing {100 * v:.0f} %" for k, v in off.items())
                         + f" (under {100 * PAINT_HUE_FACING_SHARE:g} % on a facing of {100 * PAINT_HUE_FACING_SIZE:g} "
                         "% of the surface or more: that side is painted another colour)")
            for k in off:
                flagged |= stats["masks"]["hue_facing"][k]
    stats["flagged"] = flagged
    return found, stats


def paint_defect_warning(painted: str | Path | None, prompt: str | None, mode: str | None = None,
                         session: Path | None = None) -> str | None:
    """A warning, never a refusal, when the paint is partly black (a colour asked for that is not
    dark), two-toned between facings, or mostly not the one hue asked for.  It names the numbers
    and sends the agent to the views first; it gives no answer to paste, since a measured paint
    can still be the right one."""
    found, _ = paint_findings(painted, prompt, mode, session)
    return paint_warning_text(found)


def paint_warning_text(found: list[str], marked: str | None = None) -> str | None:
    """The paint check's warning: the numbers, then the views before any repaint.  ``marked``:
    the colour the measured vertices are hatched in, when the marked views were drawn."""
    if not found:
        return None
    where = (f"the measured vertices are hatched in {marked} there" if marked else
             "look at the faces named")
    return ("the paint may be partial: " + "; ".join(found) + f". Look at the painted views first ({where}). "
            "Paint again with a new texture_seed only if the views show the defect on the body itself; "
            "a shadow, a small part or a mark is no reason (a warning only: running on adopts this paint)")


# Hatching for the marked views: the measured vertices striped in a colour far from the paint's.
PAINT_MARKS = (("magenta", (255, 0, 255)), ("green", (25, 215, 25)))
PAINT_HATCH_STRIPES = 40                                    # stripes across the body's largest extent


def mark_paint_views(stats: dict[str, Any] | None, out: Path,
                     compute_env: str = lib.DEFAULT_COMPUTE_ENV) -> str | None:
    """The six painted views again with the vertices behind the paint check's findings hatched
    (diagonal stripes in world space, so they read in every view), drawn by the workflow's own
    render-surface under the compute environment (this one has no matplotlib).  Returns the
    hatch colour's name; None when nothing is flagged or the picture cannot be drawn."""
    import subprocess
    import tempfile
    import numpy as np
    from inspect_session import compute_interpreter
    mesh, flagged = (stats or {}).get("mesh"), (stats or {}).get("flagged")
    if mesh is None or flagged is None or not flagged.any():
        return None
    interpreter = compute_interpreter(compute_env)
    if interpreter is None:
        return None
    marked = mesh.copy()
    rgba = np.asarray(mesh.visual.vertex_colors).copy()
    width = float(np.ptp(mesh.vertices, axis=0).max()) / PAINT_HATCH_STRIPES or 1.0
    stripe = np.floor(np.asarray(mesh.vertices).sum(axis=1) / width).astype(int) % 2 == 0
    _, chroma, angle = _lab(rgba[:, :3])
    coloured = chroma >= PAINT_HUE_CHROMA
    median = float(np.median(angle[coloured])) if coloured.mean() >= 0.25 else None
    near_magenta = median is not None and abs((median - HUE_ANGLES["magenta"] + 180) % 360 - 180) < 60
    name, mark = PAINT_MARKS[1] if near_magenta else PAINT_MARKS[0]
    rgba[flagged & stripe, :3] = mark
    import trimesh
    marked.visual = trimesh.visual.ColorVisuals(marked, vertex_colors=rgba)
    tool = lib.REPO_ROOT / "src" / "agents_wrapper" / "fem_workflow" / "scripts" / "workflow_tool.py"
    with tempfile.TemporaryDirectory() as scratch:
        surface = Path(scratch) / "marked.glb"
        marked.export(surface)
        try:
            done = subprocess.run([interpreter, str(tool), "render-surface", "--surface", str(surface),
                                   "--output", str(out)], capture_output=True, text=True, timeout=60,
                                  env={**os.environ, "MPLBACKEND": "Agg", "MPLCONFIGDIR": scratch})
        except (OSError, subprocess.TimeoutExpired):
            return None
    return name if done.returncode == 0 and Path(out).exists() else None


def _stop_payload(stop: str, session: Path, output_root: Path, card: dict[str, Any],
                  plan: dict[str, Any]) -> dict[str, Any]:
    """What the agent looks at and reads at a stop."""
    import inspect_session
    # web_image: the candidates and their pictures come with the stop itself
    payload: dict[str, Any] = {"why": STOPS[stop]} if stop == "web_image" else {"why": STOPS[stop], "look_at": []}
    member = planned_member(session, plan) if stop in ("plan", "drawing", "revision", "web_image") else None
    if member:
        # before anything is generated: how thick the description must ask the members to be
        payload["real_member"] = member
    if stop in ("web_image", "plan", "triage"):
        return payload
    if stop == "drawing":
        path, raw = card.get("drawn_image"), card.get("drawn_image_raw")
        found = [p for p in (raw, path) if p and Path(p).exists()]
        crop = (plan.get("geometry") or {}).get("drawing_crop") == "largest"
        pair = drawing_pair(raw, path, lib.operator_dir(session),
                            "cut-out (drawing_crop: its largest object alone is generated from)" if crop
                            else "cut-out (what the body is generated from)") if len(found) == 2 else None
        payload["look_at"] = [str(pair)] if pair else found
        counted = drawing_objects(path) or {}
        seed = card.get("image_seed")
        payload["drawing"] = {"words": card.get("drawn_image_prompt"), "image_seed": seed, **counted}
        last = last_drawing_note(session, plan)
        if last:
            payload["drawing"]["last_drawing"] = last
        if (counted.get("objects") or 0) > 1:
            payload["drawing"]["note"] = (
                f"the cut-out reads as {counted['objects']} pieces: several objects or views, or one object "
                "whose silhouette splits (a U or H shape, a part cut free from the background). It is never "
                "generated from whole; new words or a new image_seed draw again")
            cut = cut_largest_object(path, counted) if path else None
            if cut is not None:
                payload["look_at"].append(str(cut))
                payload["drawing"]["largest_object"] = str(cut)
                payload["drawing"]["note"] += (
                    "; largest_object is the largest of them alone: when it is the whole object, "
                    "geometry.drawing_crop \"largest\" generates from it (this drawing's attempt)")
        if card.get("drawn_image_dropped"):
            # Measured by the drawing tool with SDXL's own tokenizer (the card carries it).
            lost = ("words of your description and all of the single-object style after it"
                    if card.get("drawn_image_description_cut") else
                    "the single-object style appended after your description (one whole object, plain "
                    "background, seen from a little above)")
            payload["warnings"] = [
                f"SDXL reads 77 tokens of a drawing's prompt and never read {lost}: "
                f"\"{card['drawn_image_dropped']}\". Shorten the description to about 20 words "
                "(geometry.md) and draw again; this drawing was made without them"]
        if card.get("api_error"):
            payload["api_error"] = card["api_error"]
        return payload
    if stop == "texture":
        views, painted = card.get("texture_views"), card.get("textured_surface")
        if views and Path(views).exists() and (not painted or not Path(painted).exists()
                                               or Path(views).stat().st_mtime >= Path(painted).stat().st_mtime - 1):
            # the six painted views at about 1000 x 700, as the field pictures (one look's pixels)
            small = downscaled(views, lib.operator_dir(session) / "texture_views.png")
            payload["look_at"].append(str(small or views))
        fallback = card.get("texture_fallback") or None
        payload["texture"] = {"texture_prompt": card.get("texture_prompt"), "texture_seed": card.get("texture_seed"),
                              "textured_surface": painted, "texture_reference": card.get("texture_reference"),
                              **({"texture_fallback": fallback} if fallback else {})}
        if card.get("texture_reference") and Path(card["texture_reference"]).exists():
            payload["look_at"].append(card["texture_reference"])
        if fallback and fallback.get("kind") == "part_colours":
            # A flat colour per part, made deterministically: nothing to judge as a painting.
            asked = fallback.get("asked")
            payload["note"] = (f"{fallback.get('note')}"
                               + (f"; per_part_colours true was read as each part's material colour, parts of one "
                                  f"material in one colour: {asked}" if isinstance(asked, dict) and per_part_colours(plan) is True
                                  else "")
                               + ". Look that each part's colour lies on one part; run again to go on to the materials")
            if card.get("api_error"):
                payload["api_error"] = card["api_error"]
            return payload
        if fallback and fallback.get("kind") == "plain_colour":
            # The painter crashed or failed on this surface (the workflow tried the seed and one more):
            # a flat colour stands in, marked.  No other seed or words paint it; the run goes on.
            payload["warnings"] = [
                f"{fallback.get('note')}. Nothing to fix: go on to the materials, never repaint (another "
                "seed or other words do not paint this surface; troubleshooting.md, Paint); the report "
                "says the body was not painted"]
            if card.get("api_error"):
                payload["api_error"] = card["api_error"]
            return payload
        image = painted_from_image(session, painted)
        if image:
            # Painted from the body's own image (with_body_image): its colours are the image's, so the
            # checks that read the words' colour (near-black, two tones, hue) do not apply.
            payload["texture"]["painted_from_image"] = image
            payload["note"] = ("painted from the image the body was generated from (texture_reference): compare "
                               "the views with it, not with the words; the side the image does not show is "
                               "the painter's guess; the painter ignores the words when it has an image, so a "
                               "repaint changes texture_seed, never the words")
            if card.get("api_error"):
                payload["api_error"] = card["api_error"]
            return payload
        try:
            found, stats = paint_findings(painted, card.get("texture_prompt"),
                                          (plan.get("material") or {}).get("mode", "uniform"), session)
        except Exception:      # a hint, never a blocker
            found, stats = [], None
        if found:
            # the same six views with the measured vertices hatched, in place of the plain ones
            import tempfile
            small, colour = None, None
            try:                # a picture, never a blocker: any failure keeps the plain views
                with tempfile.TemporaryDirectory() as scratch:
                    colour = mark_paint_views(stats, Path(scratch) / "marked.png")
                    if colour:
                        target = lib.operator_dir(session) / "texture_views_marked.png"
                        small = downscaled(Path(scratch) / "marked.png", target)
                        if small is not None and Path(small).parent == Path(scratch):     # already small: kept as is
                            small = Path(shutil.copy(small, target))
            except Exception:
                small, colour = None, None
            if small:
                payload["look_at"] = [str(small)] + [p for p in payload["look_at"]
                                                     if Path(p).name != "texture_views.png" and p != views]
            payload["warnings"] = [paint_warning_text(found, colour if small else None)]
        if card.get("api_error"):
            payload["api_error"] = card["api_error"]
        return payload
    if stop == "revision":
        payload["revised_description"] = card.get("description")
        payload["cad_revision"] = card.get("cad_revision")
        if card.get("api_error"):
            payload["api_error"] = card["api_error"]
        return payload
    if stop == "geometry":
        views = session / "geometry" / "views.png"
        source = body_source(session)
        if views.exists() and (source is None or views.stat().st_mtime >= source.stat().st_mtime - 1):
            payload["look_at"].append(str(views))
        elif views.exists():
            payload["render_error"] = "geometry/views.png predates this body: it is not shown"
        revision = lib.read_json(lib.operator_dir(session) / "run_revision.json", {}) or {}
        if (plan.get("geometry") or {}).get("revise_prompt") and revision.get("revised"):
            # The text the body was generated from, when the words were revised first.
            payload["revised_description"] = revision["revised"]
        summary = inspect_session.summarize(
            session, remesh_depth=(plan.get("settings") or {}).get("remesh_octree_depth"), solve=False)
        payload["geometry"] = summary.get("geometry")
        faces = cad_face_summary(session)
        if faces:
            payload["cad_faces"] = faces
            revised = (lib.read_json(lib.operator_dir(session) / "run_revision.json", {}) or {}).get("revised")
            payload["cad_parts"] = cad_parts(revised or "")
            payload["cad_parts_note"] = ("the parts as the revision states them, not as the generated "
                                         "code built them: compare with views.png and connected_solids")
        geometry = plan.get("geometry") or {}
        if geometry.get("draw") or geometry.get("asset_kind") == "image":
            # The picture the body was made from, and how many separate objects it shows.
            source = (card.get("drawn_image") or (lib.read_json(session / "session.json", {}) or {}).get("drawn_image")
                      ) if geometry.get("draw") else geometry.get("asset_path")
            counted = drawing_objects(source) if source else None
            payload["drawing"] = {"path": source, **(counted or {"objects": "not counted (no cut-out alpha)"})}
            refine = refine_hint(session, plan)
            if refine:
                payload["drawing"]["refine"] = refine
        credit = web_image_credit(session)
        if credit:
            # The photograph the body was made from, and its credit for the report and any figure.
            payload["web_image"] = credit
        note = texture_not_applied(session, card, plan)
        if note:
            payload["texture"] = note
        mesh = _generated_mesh(session)
        if mesh is not None:
            merged = mesh.copy()
            merged.merge_vertices()
            payload["connected_solids"] = connected_solids(merged)
        thin_warnings: list[str] = []
        try:
            payload["planned_resolution"] = resolution = planned_resolution(session, plan) or {}
            depth = resolution.get("depth") or DEEPEST_DEPTH
            deep = {**plan, "settings": {**(plan.get("settings") or {}), "remesh_octree_depth": DEEPEST_DEPTH}}
            deep_resolution = (planned_resolution(session, deep) or {}) if depth < DEEPEST_DEPTH else resolution
            limit = thin_member_limit(session, plan, resolution)
            route = body_route(session, plan, resolution)["route"] == "section"
            # The thin-member warning, at the plan's depth and at the deepest: said with its numbers
            # where the body can still change, never refused (THIN_WAYS); the report carries it.
            problem = resolution_warning(session, plan, resolution)
            deepest = resolution_warning(session, deep, deep_resolution) if depth < DEEPEST_DEPTH else problem
            check = problem or f"the thinnest member is {RESOLVED_LEAVES} leaves or more at the plan's depth"
            if depth < DEEPEST_DEPTH:
                check += f"; at depth {DEEPEST_DEPTH}: " + ("under it too" if deepest else "it resolves")
            resolution["resolution_check"] = check
            if limit:
                resolution["real_member"] = {**limit, "note": real_member_note(limit["unresolvable"])}
            if problem:
                thin_warnings.append(problem)
            try:
                governing = governing_unresolved_warning(session, plan, resolution)
            except Exception:  # a hint, never a blocker
                governing = None
            if governing:
                thin_warnings.append(governing)
                if isinstance(resolution.get("real_member"), dict):
                    resolution["real_member"].pop("note", None)      # the warning says it, with its way
            cover = thin_cover_warning(session, plan, resolution)
            if cover:
                thin_warnings.append(cover)
            # G4 and the brief's load path, refused on leaving this stop as well (every problem at once)
            body_wrong = "; ".join(p for p in (body_gate(session, plan, resolution), path_gate(session, plan)) if p)
            if body_wrong:
                payload["ok"] = False
                payload["error"] = body_wrong
                if NO_REGENERATION in body_wrong and isinstance(payload.get("drawing"), dict):
                    payload["drawing"].pop("refine", None)     # a finer depth cannot answer an extents refusal
            if route:
                resolution["section_stand_in"] = section_equivalence(session, plan, resolution)
            # Gaps the solve bonds, at the depth the solve will take (two runs met this
            # only when the regions refused it).
            gaps = thin_gaps_problem(session, plan, resolution, deeper=deep_resolution, record=False)
            if gaps:
                thin_warnings.append("thin gaps: " + gaps)
        except Exception as exc:  # a hint, never a blocker
            payload["planned_resolution"] = {"error": str(exc)[:200]}
        try:
            # inside planned_resolution, which the compact view prints
            payload["planned_resolution"]["orientation"], turned = body_orientation(
                session, plan, payload["planned_resolution"])
        except Exception:  # a hint, never a blocker
            turned = None
        if turned:
            thin_warnings.append(turned)
        try:
            tilted = None if turned else tilt_warning(session, plan)
        except Exception:  # a hint, never a blocker
            tilted = None
        if tilted:
            thin_warnings.append(tilted)
        try:
            slab = base_slab_warning(session, plan)
        except Exception:  # a hint, never a blocker
            slab = None
        if slab:
            thin_warnings.append(slab)
        outside = range_findings(payload.get("planned_resolution"))
        if outside and equivalent_body(session):
            outside = None     # built at the equivalent-stiffness section: marked, exempt (runner_simplifications)
        try:
            filled = thickened_stand_in(session, payload.get("planned_resolution")) if outside else None
        except Exception:      # a measure that fails marks nothing
            filled = None
        if filled:
            thin_warnings.append(f"G4: {outside}, the real {filled['real_wall_m']:g} m member generated "
                                 f"{filled['measured_m']:g} m thick: accepted "
                                 f"from this stop when it is recognisably the object, as a marked {THICKENED_SAID} "
                                 "(self-weight scaled to the Real mass; the verdict says so)")
            outside = None
        if isinstance(payload.get("planned_resolution"), dict):
            # G4 decided here, where the body can still change; the judge only applies it
            payload["planned_resolution"]["g4"] = (f"'{VERDICT_NOT_RUN}' ({outside})" if outside else
                                                   "a marked thickened stand-in" if filled else "within the rule")
        scaled = scale_deviation(session, payload.get("planned_resolution"))
        if scaled:
            thin_warnings.append(scaled + ": taken as a marked simplification (the verdict says so)")
        massive = None
        try:
            resolution = payload.get("planned_resolution") or {}
            if not filled:
                record_mass_failure(session, plan, resolution.get("mass_over_real"),
                                    resolution.get("mass_over_real_from"))
            massive = mass_route_problem(session, plan, resolution)
        except Exception:      # a hint, never a blocker here: the run on refuses it again
            massive = None
        try:
            swallowed = slab_route_problem(session, plan)
        except Exception:      # a hint, never a blocker here: the run on refuses it again
            swallowed = None
        if swallowed:
            # refused on leaving this stop while a rung or route remains (said once, as the error)
            payload["ok"] = False
            payload["error"] = "; ".join(p for p in (payload.get("error"), swallowed) if p)
        if massive:
            # refused on leaving this stop while a route remains (said once, as the error)
            payload["ok"] = False
            payload["error"] = "; ".join(p for p in (payload.get("error"), massive) if p)
            if isinstance(payload.get("drawing"), dict):
                payload["drawing"].pop("refine", None)
        elif isinstance(payload.get("drawing"), dict) and payload["drawing"].get("refine"):
            payload["drawing"]["refine"] = refine_hint(session, plan)     # the ladder skipped after a mass failure
        if outside and not massive:
            thin_warnings.append(f"G4: the body is outside the workflow's range ({outside}): a solve on it is "
                                 f"'{VERDICT_NOT_RUN}', whatever its route; the next listed route, or a body built "
                                 "at the brief's Real dimensions (`blank`), is within it (objectives/routes.md §3.4)"
                                 + (revision_said(session, payload.get("planned_resolution"))
                                    if generated_body(session) and not extents_revision(session)[0]
                                    and mass_outlier(session, payload.get("planned_resolution")) else ""))
        payload["warnings"] = thin_warnings + list(summary.get("warnings") or [])
        return payload
    if stop == "regions":
        try:
            plan = bind_by_name(plan, (lib.read_json(session / "boundary_conditions" / "resolved.json", {})
                                       or {}).get("regions") or [])
        except PlanError:
            pass                       # refused by name when the run reads the plan
        if card.get("preview_error"):
            payload["preview_error"] = card["preview_error"]
        if card.get("api_error"):
            payload["api_error"] = card["api_error"]
        # both pictures from one render process (two cost two interpreter starts and imports)
        images, failed = fresh_images(_inspect(session, output_root, "render", session.name,
                                               "--what", "regions,segments"))
        payload["look_at"].extend(images)
        if failed:
            payload.setdefault("render_error", []).append(f"regions,segments: {failed}")
        summary = inspect_session.summarize(
            session, remesh_depth=(plan.get("settings") or {}).get("remesh_octree_depth"), solve=False)
        payload["segment_description"] = card.get("segment_description")
        payload["regions"] = summary.get("regions")
        payload["planned_load"] = planned_load(plan, summary.get("regions") or [])
        try:
            payload["load_resultants"] = load_resultants(session, payload["planned_load"])
        except Exception as exc:  # a hint, never a blocker
            payload["load_resultants"] = {"error": str(exc)[:160]}
        payload["planned_supports"] = planned_supports(plan, summary.get("regions") or [])
        payload["load_shares"] = load_shares(session, plan, payload["planned_load"])
        try:
            payload["reactions_from_statics"] = statics(session, plan, summary.get("regions") or [],
                                                        payload["planned_load"])
            if payload["reactions_from_statics"] is None and any(
                    (c or {}).get("transmits") == "force only" and not (c or {}).get("simplified_to")
                    for c in (plan.get("contacts") or {}).values()):
                payload["reactions_from_statics"] = {
                    "note": "list each simple support's load region in plan.contacts.<contact>.regions, "
                            "with a value in neumann_values: the next run checks it against statics "
                            "before sending anything, and prints statics' value when it differs"}
        except Exception as exc:  # a hint, never a blocker
            payload["reactions_from_statics"] = {"error": str(exc)[:200]}
        synthesized = lib.read_json(session / "boundary_conditions" / "synthesized.json", {}) or {}
        synthesized_names(session)       # kept, so a revision of a region a reword drops is known stale
        payload["synthesized_selectors"] = {item["name"]: item["selector"] for item in
                                            [*synthesized.get("dirichlet", []), *synthesized.get("neumann", [])]}
        payload["region_revision"] = (lib.read_json(session / "boundary_conditions" / "revision.json", {})
                                      or {}).get("regions")
        payload["revise"] = ("to change one region, put its corrected selector in plan.region_revisions "
                             "(no new synthesis; its own limit); rewording plan.regions re-synthesises "
                             "every region")
        payload["held_regions"] = held_regions(
            session, (plan.get("values") or {}).get("dirichlet_values") or {}, plan.get("contacts"), plan)
        try:
            payload["reach_beyond_holds_m"] = reach_beyond_holds(session)
        except Exception as exc:  # a hint, never a blocker
            payload["reach_beyond_holds_m"] = {"error": str(exc)[:120]}
        payload["warnings"] = list(summary.get("warnings") or [])
        held = held_pieces_warning(payload["held_regions"] or [], plan.get("contacts"), session)
        if held:
            # the approving run refuses it (pieces_problem): said where the plan can still answer it
            payload["warnings"].insert(0, held)
        plural = plural_pieces_warning(payload["held_regions"] or [], plan.get("contacts"), session)
        if plural:     # a warning, said once a body (BODY_ONCE)
            payload["warnings"].append(plural)
        jump = held_pieces_jump(session, str(plan.get("regions") or ""), payload["held_regions"] or [],
                                plan.get("segmentation"))
        if jump:
            payload["warnings"].insert(0, jump)
        floating = body_pieces_problem(session)       # contacts are bound in the approving patch
        if floating:      # the approving run refuses it: said where the region words can still change
            payload["warnings"].insert(0, "pieces, checked now (the approving run refuses it): " + floating)
        try:        # the approving run refuses it: said where the region words can still change
            grip = grip_span_problems(session, plan, payload["held_regions"] or [],
                                      brief_contacts_v2(lib.operator_dir(session)) or {})
        except Exception:  # a hint, never a blocker
            grip = []
        try:        # the approving run refuses it: said where the region words can still change
            grounded = rest_ground_problem(session, plan, payload["held_regions"] or [])
        except Exception:  # a hint, never a blocker
            grounded = None
        if grounded:
            payload["warnings"].insert(0, "rests, checked now (the approving run refuses it): " + grounded)
        for said in (grip and "held length, checked now (the approving run refuses it): " + "; ".join(grip),
                     loads_binding_problem(session, plan, summary.get("regions") or []) if plan.get("loads")
                     else None):
            if said:
                payload["warnings"].insert(0, said)
        try:       # a warning, never a refusal: said where the region words can still change
            entry = entry_member_warning(session, plan, summary.get("regions") or [])
        except Exception:  # a hint, never a blocker
            entry = None
        if entry:
            payload["warnings"].insert(0, entry)
        try:       # a warning, never a refusal
            scale = load_scale_warning(session)
        except Exception:  # a hint, never a blocker
            scale = None
        if scale:
            payload["warnings"].insert(0, scale)
        try:
            tips = tipping_warning(session, plan, summary.get("regions") or [], payload["planned_load"])
        except Exception:  # a hint, never a blocker
            tips = None
        if tips:
            payload["warnings"].insert(0, tips)
        keys = contacts_keys_note(session, plan)
        if keys:
            payload["contacts_keys"] = keys
        coverage = coverage_view(session)
        if coverage:
            payload["coverage"] = coverage
        return payload
    if stop == "materials":
        if card.get("api_error"):
            payload["api_error"] = card["api_error"]
        if (plan.get("material") or {}).get("mode", "uniform") != "parts":
            # A uniform material inferred from words: its values, before the solve uses them (a card
            # may still carry an earlier per-part valuation, which this case does not use).
            payload["material"] = {k: card.get(k) for k in ("youngs_modulus", "poisson_ratio", "density",
                                                             "material_description", "material_inferred")}
            return payload
        montage = card.get("parts_montage")
        if montage and Path(montage).exists():
            payload["look_at"].append(str(montage))
        segments = _segment_table(session)
        filled = (lib.read_json(lib.operator_dir(session) / PART_FILL, {}) or {})
        parts = []
        for part in card.get("material_parts") or []:
            seg = segments.get(int(part["id"]), {})
            said = (filled.get("segments") or {}).get(str(part["id"])) or {}
            parts.append({**{k: part.get(k) for k in ("id", "youngs_modulus", "poisson_ratio", "density")},
                          **({"label": said.get("label"), "material": said.get("material"), "from": said["from"]}
                             if said else {}),
                          "area_fraction": seg.get("area_fraction"),
                          "centroid": seg.get("centroid")})
        payload["parts"] = parts
        if filled.get("unmatched") or filled.get("stand_ins"):
            payload["parts_caveats"] = ([f"segments {filled['unmatched']} not named by the brief's Materials by "
                                         "part: the Governing material (or the valuation's), a caveat"]
                                        if filled.get("unmatched") else []) + list(filled.get("stand_ins") or [])
        by_material: dict[str, list[int]] = {}
        for part in parts:
            by_material.setdefault(f"E {part.get('youngs_modulus')}, rho {part.get('density')}", []).append(part["id"])
        payload["segments_by_material"] = by_material
        method = _regions_method(session)
        payload["parts_segmentation"] = (
            "the regions stage's PartField segments: plan.segmentation.num_clusters changes them"
            if method == "partfield" else
            "the regions stage's CAD faces: one value per B-rep face"
            if method == "cad_faces" else
            "the material step's own PartField, 6 parts: plan.segmentation does not reach them; "
            "segment with method partfield to choose the count")
        payload["soft_parts"] = [p["id"] for p in parts
                                 if isinstance(p.get("youngs_modulus"), (int, float))
                                 and p["youngs_modulus"] < 1e9]
        payload["parts_summary"] = card.get("parts_summary")
        return payload
    if card.get("solve_error"):
        lib.write_json(lib.operator_dir(session) / "solve_failed.json", {"time": time.time()})
        payload["solve_error"] = card["solve_error"]
        payload["solve_log_tail"] = (card.get("solve_log") or "").splitlines()[-12:]
        return payload
    images, failed = fresh_images(_inspect(session, output_root, "render", session.name, "--what", "all"))
    payload["look_at"].extend(images)
    if failed:
        payload["render_error"] = failed
    summary = inspect_session.summarize(session)
    report = inspect_session.write_report(session, summary)
    payload["report"] = str(report)
    payload.update(body_and_loads(session, summary))
    payload["material"] = summary.get("material")
    payload["solve"] = summary.get("solve")
    payload["held_regions"] = held_regions(session, None, plan.get("contacts"))
    payload["relative_to_supports"] = relative_displacement(session, plan)
    payload["prediction_check"] = prediction_check(session, summary.get("solve"), plan.get("prediction"),
                                                   payload["relative_to_supports"])
    declared = {"contacts": plan.get("contacts"), "prediction": plan.get("prediction"),
                "material_mode": (plan.get("material") or {}).get("mode", "uniform"),
                "body_simplification": plan.get("body_simplification"),
                "body_route": body_route(session, plan).get("route")}
    history = record_prediction(session, summary, declared, payload["prediction_check"])
    payload["prediction_check"] = {**(payload["prediction_check"] or {}), "agreement": agreement(history)}
    zero = zero_field(summary)
    if zero:
        # a failed solve, never "below resolution" (an audit)
        payload["solve_error"] = zero
        lib.write_json(lib.operator_dir(session) / ZERO_FIELD, {"run": (summary.get("solve") or {}).get("run"),
                                                                "said": zero})
        record_blocker(session, "a workflow step failed", zero)
    add_history_to_report(report, history, contacts_table(session, payload["held_regions"], plan.get("contacts")),
                          {**brief_status(lib.operator_dir(session)),
                           "thin_gaps": lib.read_json(lib.operator_dir(session) / "thin_gaps.json"),
                           "web_image": web_image_credit(session),
                           "web_search": web_search_line(session),
                           **thin_declaration(session, plan, summary),
                           "per_part": per_part_said(session) if declared["material_mode"] == "parts" else None,
                           "revisions_kept": lib.read_json(lib.operator_dir(session) / "revision_kept.json")})
    if declared["material_mode"] == "parts" and isinstance(payload.get("material"), dict):
        payload["material"] = {**payload["material"], "per_part": per_part_said(session)}
    payload["warnings"] = summary.get("warnings")
    coverage = coverage_view(session)
    if coverage:
        payload["coverage"] = coverage
    far = far_off_case_note(payload["prediction_check"].get("agreement"))
    if far:
        payload["warnings"] = [far] + list(payload["warnings"] or [])
    return payload


def coverage_view(session: Path) -> dict[str, Any] | None:
    """The Use table's coverage as the regions and solve stops print it, compact: at the Real
    section's member the run state's effect and the largest state's (N m, the runner's), and each
    member another state exceeds the run at, one line each.  The whole record is
    operator/coverage.json; the compact view prints it once and then "unchanged" (compact_stop)."""
    operator = lib.operator_dir(session)
    try:
        coverage = use_coverage(operator)
    except Exception:      # a view, never a blocker
        return None
    if not coverage:
        return None
    out: dict[str, Any] = {"run": coverage["run"]}
    if coverage.get("run_effect") is not None:
        out[f"at {coverage['member']}"] = (f"run {coverage['run_effect']:.4g} {coverage['unit']}, largest {coverage['governing']!r} "
                                           f"{coverage['governing_effect']:.4g}")
    if coverage.get("uncovered"):
        out["uncovered"] = {m: f"{u['case']!r} {u['effect']:.4g} vs {u['run']:.4g}"
                               + (f", declared {u['declared'].split(':')[0]}" if u.get("declared") else "")
                            for m, u in coverage["uncovered"].items()}
    return out


def brief_run(value: dict[str, Any]) -> dict[str, Any]:
    """What a stop prints by default: the decision's inputs, not every number.

    The whole payload is in ``operator/last_run.json``; ``--full`` prints it.
    """
    keep = ("ok", "session_id", "stop", "kind", "elapsed_s", "attempts_left", "error", "errors",
            "restored", "answer", "why", "look_at", "planned_resolution", "segment_description",
            "planned_load", "preview_error", "api_error", "solve_error", "solve_log_tail",
            "report", "body", "loads", "warnings", "next", "parts", "soft_parts", "brief",
            "planned_supports", "revised_description", "cad_revision", "cad_faces",
            "held_regions", "prediction_check", "relative_to_supports", "synthesized_selectors",
            "region_revision", "revise", "load_resultants", "cad_parts", "cad_parts_note",
            "connected_solids", "load_shares", "segments_by_material", "parts_segmentation", "parts_caveats",
            "reactions_from_statics", "verdict", "drawing", "web_image", "texture", "material", "reach_beyond_holds_m",
            "render_error", "fallback", "cross_check", "read", "real_member", "coverage",
            # an out-of-graph solve (solve_fallback) prints its numbers at the top level
            "backend", "run", "newton", "checks", "region_displacement", "result_stands", "two_depths")
    out = {k: value[k] for k in keep if k in value}
    # A step's warnings are the only place a preview that kept the previous
    # regions, or a solve that fell back, says so: they stay in the brief form.
    out["steps"] = [{k: s.get(k) for k in ("kind", "action", "ok", "elapsed_s", "notes", "warnings")}
                    for s in value.get("steps", [])]
    step_warnings = [w for s in value.get("steps", []) for w in (s.get("warnings") or [])]
    if step_warnings:
        out["step_warnings"] = step_warnings
    if value.get("regions"):
        out["regions"] = [{k: r.get(k) for k in ("name", "category", "faces", "area_fraction",
                                                  "normal_coherence", "loaded_fraction", "selector")}
                          for r in value["regions"]]
    if value.get("geometry"):
        g = value["geometry"]
        out["geometry"] = {k: g.get(k) for k in ("watertight", "components", "faces", "note")}
    if value.get("solve"):
        s = value["solve"]
        out["solve"] = {k: s.get(k) for k in ("succeeded", "newton", "nodes", "duration_s",
                                              "checks", "region_displacement", "optimization")}
    return out


# ----------------------------------------------------------- what to read --

SKILL_DIR = Path(__file__).resolve().parents[1]
# The reference sections that apply from each stop, named in its ``read`` field (SKILL.md,
# "Reading"): the agent reads these, and nothing else unless a rule names it.  Measured on
# five runs: every agent read SKILL.md and 10-12 references in full by
# call 5 (up to 134 k chars; about 2.5 M of the longest run's 8.8 M input tokens, since every later call re-reads
# them).  Each entry is (file under references/, heading it starts at or None for the whole
# file, why).  A decision taken before an attempt is spent (the route, the drawing's words,
# the region words, the depth, the brief and the plan) is named at the stop *before* that
# spend; an entry that only helps after a failure is named by the error (READ_ON_ERROR).
